window.STUDY = [{"id":"adabi","name":"الشعبة الأدبية — عام","icon":"📖","color":"#FF6B6B","grad":"linear-gradient(135deg,#FF6B6B,#B24592)","desc":"اللغة والتاريخ والجغرافيا والفلسفة — مواد الصف الثالث بأسلوب مبسط","subjects":[{"id":"adabiar","name":"اللغة العربية","icon":"📝","color":"#FF9F43","books":[{"title":"النحو والصرف","icon":"✒️","chapters":[{"title":"الحال والتمييز","read":[{"h":"تعريف الحال وصورها","t":"الحال اسم نكرة منصوب يبيّن هيئة صاحبه وقت حدوث الفعل، ويكون في الغالب جوابًا لسؤال \"كيف؟\". له ثلاث صور: (1) مفردة: \"عاد الجندي منتصرًا\"، (2) جملة اسمية أو فعلية: \"جاء الطالبُ وهو يضحك\"، \"جاء الطالبُ يركضُ\"، (3) شبه جملة (ظرف أو جار ومجرور): \"وقفتُ أمامَ الباب\"، \"رأيت النهرَ في جريانه\"."},{"h":"شروط الحال وصاحبها","t":"الحال تكون دائمًا نكرةً، ويصحّ وقوعها جوابًا لسؤال \"كيف؟\". أما صاحبها فقد يكون فاعلًا أو مفعولًا به أو مبتدأ أو مجرورًا بحرف جر، ولا يصحّ تقديم الحال على عاملها في الغالب. مثال: \"رجع المهاجرُ سعيدًا إلى وطنه\" فصاحب الحال هو الفاعل \"المهاجر\"."},{"h":"التمييز تعريفه وأنواعه","t":"التمييز اسم نكرة منصوب يُذكر لرفع الإبهام عن اسم قبله أو عن جملة قبله. وهو نوعان: (1) تمييز الذات (أو المفرد): يوضح اسمًا مبهمًا قبله، ويكون منقولًا من الفاعل أو المفعول أو نائب الفاعل، مثل \"تصدّق خالدٌ مالًا\" (الأصل: تصدّق مالُ خالد)، (2) تمييز النسبة: يوضح جملة ويكون بعد المصدر أو النسبة أو التعجب أو أفعال الزيادة والنقصان، مثل \"زاد الرجلُ كرمًا\"، \"ما أصدقَه قولًا\"، \"أحمدُ أفضل من زيدٍ علمًا\"."},{"h":"حالات التمييز الإعرابية","t":"التمييز ملحوظ إن جاء منقولًا من فاعل أو مفعول، ومحفوظ إن كان على وزن \"فُعال\" كقوله تعالى \"اشتعل الرأسُ شيبًا\". ويأتي التمييز بعد المقادير (كيل أو ميزان أو مساحة أو عدد) مفردًا منصوبًا مثل \"اشتريتُ رطلًا عسلًا\"، أو مجرورًا بمن إن كان العدد مركّبًا أو معطوفًا أو معقودًا."},{"h":"الفرق بين الحال والتمييز","t":"الحال تبيّن هيئة الفاعل أو المفعول وجوابها \"كيف\"، وتتعدد صورها (مفردة وجملة وشبه جملة) وتطابق صاحبها في العدد والنوع غالبًا. أما التمييز فيبيّن الشيء أو النسبة وجوابه \"من ماذا\"، ويكون مفردًا منصوبًا أو مجرورًا ومنقولًا، ولا يطابق مميَّزه في العدد والنوع. ففي \"عادت الفتاةُ مسرورةً\" الحال مفردة مطابقة، وفي \"عندي عشرون كتابًا\" تمييز مفرد."}],"qs":[{"q":"عاد الجيشُ منتصرًا إلى الوطن. إعراب كلمة \"منتصرًا\":","a":["مفعول به منصوب","حال منصوبة","نعت منصوب","تمييز منصوب"],"c":1,"d":"easy","hint":"اسأل: كيف عاد الجيش؟","expl":"\"منتصرًا\" اسم نكرة يُبيّن هيئة الجيش وقت العودة، وهي جواب \"كيف عاد؟\" لذا هي حال منصوبة. لو كانت مفعولًا به لوقع عليها فعل الفاعل، ولو كانت نعتًا لسبقتها جملة نعتٍ موصوف، ولو كانت تمييزًا لرفعت إبهامًا عن اسم مبهم. نصيحة: اجعل أول اختبار لك للحال سؤال \"كيف؟\"، فإن صلح الجواب فهي حال."},{"q":"شربتُ الماءَ باردًا. كلمة \"باردًا\" إعرابها:","a":["حال منصوبة من الماء","مفعول به منصوب","تمييز منصوب","خبر منصوب"],"c":0,"d":"medium","hint":"بَيّنت هيئة المفعول به الماء","expl":"\"باردًا\" حال منصوبة من المفعول به \"الماء\"؛ لأنها بيّنت هيئته وقت الشرب وجواب \"كيف شربت الماء؟\". وليست مفعولًا به لأن الماء هو المفعول، وليست تمييزًا لأنها لم ترفع إبهامًا عن اسم مبهم. نصيحة: الحال قد تكون من الفاعل وقد تكون من المفعول، فانظر لمن تُنسب الهيئة."},{"q":"ما أجملَ السماءَ لونًا! كلمة \"لونًا\":","a":["حال منصوبة","تمييز منصوب عن جملة سابقة","مفعول به منصوب","نعت منصوب"],"c":1,"d":"hard","hint":"جاءت بعد أسلوب تعجب لإيضاح الجملة","expl":"\"لونًا\" تمييز النسبة؛ لأنها جاءت بعد أسلوب التعجب \"ما أجمل\" لتوضح الجملة وتفسر جهة جمال السماء. ولو كانت حالًا لبيّنت هيئة السماء نفسها، وليست مفعولًا به لأن \"أجمل\" هنا فعل تعجب والسماء مفعول به. نصيحة: التمييز المنقول عن جملة يأتي كثيرًا بعد التعجب والمدح والذم وأفعال الزيادة."},{"q":"في الحقيبة عشرون قلمًا. سبب نصب \"قلمًا\":","a":["لأنه مفعول به","لأنه تمييز ميّز به العدد عشرون","لأنه نعت لعشرون","لأنه حال من الحقيبة"],"c":1,"d":"medium","hint":"الأعداد المفردة من 3 إلى 10 تمييزها جمع مجرور، وما فوقها مفرد منصوب","expl":"العدد \"عشرون\" يدل على مبلغ مبهم، فجاءت \"قلمًا\" مفردةً منصوبةً لرفع الإبهام وتحديد المَعْدود، فهي تمييز ذاتٍ منصوب. عَيِّر الأمر: لو كانت مفعولًا به لأمكن وقوع فعلٍ عليها. نصيحة: الأعداد من 11 إلى 99 مميَّزُها مفرد منصوب، وما دون العشرة مميَّزُها جمع مجرور."},{"q":"جاء الرجلُ وهو يضحك. بيّن نوع الحال في الجملة:","a":["حال مفردة","حال جملة فعلية","حال جملة اسمية","حال شبه جملة"],"c":1,"d":"easy","hint":"توقفت على فعل \"يضحك\"","expl":"الحال هنا جملة فعلية؛ لأنها وقعت جملة تبدأ بفعل مضارع \"يضحك\" مرتبطة بالواو، وفيها ضمير يعود على صاحب الحال \"الرجل\". ولو قيل \"جاء الرجلُ وهو ضاحك\" لجاز أن تكون اسمية. نصيحة: اضبط صورة الحال من أول كلمة في الجملة الواقعة حالًا: فعل ففعلية، واسم فاسمية."},{"q":"خرجت الأمُّ باكيةً على ابنها. صاحب الحال في العبارة:","a":["ابنها","باكية","الأم","خرجت"],"c":2,"d":"medium","hint":"من الذي يوصف بالبكاء؟","expl":"الحال \"باكيةً\" تبيّن هيئة الأم وقت الخروج، فصاحبها هو الفاعل \"الأم\" الذي قامت به الحال. \"خرجت\" هي الفعل العامل، و\"ابنها\" مضاف إليه مجرور. نصيحة: صاحب الحال هو الموصوف بها، ولو فكرت في السؤال \"كيف خرجت الأم؟\" لظهر لك الجواب فورًا."},{"q":"جاءت الفتاةُ مسرورةً. جاءت الحال \"مسرورة\" مؤنثةً؛ لماذا؟","a":["لأن الحال تتبع عاملها","لأن الحال تطابق صاحبها في النوع والعدد غالبًا","لأن التمييز لا يطابق","لأن \"جاءت\" فعل مؤنث"],"c":1,"d":"hard","hint":"قارن: جاء الولدُ مسرورًا","expl":"الحال تطابق صاحبها في التذكير والتأنيث والإفراد والتثنية والجمع غالبًا، فصاحب الحال \"الفتاة\" مؤنثة فجاءت الحال مؤنثة \"مسرورة\". وهذا فرق جوهري بين الحال والتمييز الذي يبقى مفردًا منصوبًا مهما كان مميَّزه. نصيحة: استخدم المطابقة للتفرقة بين الحال والتمييز في الاختبار."}]},{"title":"المنادى","read":[{"h":"تعريف المنادى وأدواته","t":"المنادى اسمٌ يُذكر بعد أداة نداءٍ لتنبيه المخاطب، مثل \"يا محمد\". وأدواته: (يا) لنداء القريب والبعيد، (أيا، هيا) للبعيد، (الهمزة و\"أيْ\") للقريب، و(وا) للندبة. مثال: \"أحمدُ أقبلْ\"، \"وا معتصماه\"."},{"h":"المنادى المفرد العلم والنكرة المقصودة","t":"المنادى المفرد العلم أو النكرة المقصودة يُبنى على الضم في محل نصب، مثل \"يا عليُّ\"، \"يا رجلُ أقبل\" أيها التي يطلق عليها صفةً لتنبيه بعض الناس. وهذان النوعان يعربان: منادى مبني على الضم في محل نصب."},{"h":"المنادى المضاف والشبيه بالمضاف","t":"المنادى المضاف منصوب، مثل \"يا طالبَ العلمِ\"، والمنادى الشبيه بالمضاف (ما أُسند إليه شيء أو وصف بما بعده) منصوب أيضًا مثل \"يا طالبًا العلمَ\". أما النكرة غير المقصودة فمنصوبة مثل \"يا طالبًا اجتهد\" حيث لا يُقصد بها معيَّن."},{"h":"منادى \"أيها\" وما بعدها","t":"في نحو \"يا أيها الطالبُ اجتهد، يا أيتها المؤمنةُ\": \"أي\" منادى مبني على الضم في محل نصب، و\"ها\" للتنبيه حرف مبني لا محل له، وما بعدها (الطالب، المؤمنة) بدل أو نعت مرفوع يتبع لفظها. وجاز بعد \"أيها\" لقصد تنبيه الجنس."},{"h":"الندبة والاستغاثة","t":"الندبة: نداء المتفجَّع عليه أو المستغاث منه بأداة \"وا\"، مثل \"وا مصيبتاه\"، وجاز أن يُنصَب المنادى في الندبة مثل \"وا عبدَ الله\". والاستغاثة: طلب إغاثة لمن وقع في شدة، وتكون بأداة \"يا\" مع \"للكاف\" الموجه \"يا لَلأميرِ المظلوم\"."}],"qs":[{"q":"يا محمدُ اجتهد في دروسك. إعراب \"محمدُ\":","a":["مفعول به منصوب","منادى مبني على الضم في محل نصب","مبتدأ مرفوع","فاعل مرفوع"],"c":1,"d":"easy","hint":"منادى مفرد عَلم","expl":"\"محمد\" منادى مفرد عَلم، فيُبنى على الضم في محل نصب بفعل النداء المحذوف \"أنادي\". لا محل للرفع ولا هو فاعل؛ لأن المنادى اسمٌ بعد أداة نداء. نصيحة: احفظ القاعدة: المفرد العَلم والنكرة المقصودة يُبنيان على الضم دائمًا."},{"q":"يا طالبَ العلمِ اجتهد. إعراب \"طالبَ\":","a":["منادى مبني على الضم","منادى مضاف منصوب","نعت مرفوع","خبر مقدم"],"c":1,"d":"easy","hint":"تأمّل: بعده مضاف إليه \"العلم\"","expl":"المنادى المضاف يُنصَب ولا يُبنى، فـ \"طالبَ\" منصوب لأن العامل فعل النداء المحذوف. فلو كان مفردًا لَبُني على الضم، لكن إضافته منعت البناء. نصيحة: فرِّق: المضاف والشبيه بالمضاف والنكرة غير المقصودة منصوبة، والمفرد العَلم والنكرة المقصودة مبنية."},{"q":"يا طالبًا اجتهدْ ولا تتهاونْ. كلمة \"طالبًا\":","a":["منادى نكرة غير مقصودة منصوب","منادى مقصود مبني على الضم","مفعول لأجله منصوب","تمييز منصوب"],"c":0,"d":"medium","hint":"لا نعرف طالبًا بعينه","expl":"النداء هنا لطالب غير معيّن، فهي نكرة غير مقصودة تُنصَب ولا تُبنى على الضم. ولو قيل \"يا طالبُ\" لكانت نكرة مقصودة تُبنى على الضم للتنبيه على شخص معيّن. نصيحة: انظر هل المتكلم يقصد شخصًا بعينه أم لا لتحدد النوع."},{"q":"يا أيُّها الطالبُ اجتهدْ. ما إعراب \"أيُّ\"؟","a":["منادى مبني على الضم في محل نصب","مبتدأ مرفوع","مضاف إليه","بدل منصوب"],"c":0,"d":"medium","hint":"\"أي\" اسم مبهم يعامل معاملة المفرد","expl":"\"أي\" منادى مبني على الضم في محل نصب، و\"ها\" للتنبيه، والطالب بدلٌ مرفوع أو نعت مرفوع يتبع لفظ \"أي\". لا يصلح الرفع بالابتداء لأن النداء يُعرب المنادى حسب محله. نصيحة: تُعرب \"أيها\" في النداء: \"أي\" منادى مبني على الضم في محل نصب + \"ها\" حرف تنبيه."},{"q":"وا مصيبتاه! ما أسلوب الجملة؟","a":["نداء قريب","ندبة","استغاثة","ترخيم"],"c":1,"d":"easy","hint":"بدأت بـ\"وا\" للتفجع","expl":"الجملة ندبة؛ لأن \"وا\" أداة الندبة للتفجع على المصيبة، والمنادى \"مصيبتاه\" منادى مبني على الضم المقدر في محل نصب مع إشباع هاء السكت. أما الاستغاثة فأداتها \"يا\" مع لام موجهة نحو \"يا لَلناس\". نصيحة: ميّز الأدوات: \"وا\" للندبة، \"يا لِـلمغاث\" للاستغاثة، \"يا\" مع تنبيه للنداء."},{"q":"يا أهلَ القرى أجيبوا الضيفَ. \"أهلَ\" منادى:","a":["مفرد عَلم مبني","مضاف منصوب","شبيه بالمضاف منصوب","نكرة غير مقصودة"],"c":1,"d":"medium","hint":"ما بعد المنادى مضاف إليه","expl":"\"أهل\" مضافٌ إلى \"القرى\"، فجاء المنادى مضافًا منصوبًا؛ لأن المضاف لا يُبنى على الضم. ولو لم يُضف لأمكن أن يُبنى أو يُنصب حسب القصد. نصيحة: علامة المنادى المضاف أن بعده مضافًا إليه محذوفًا تنوينه."},{"q":"يا أيُّها الولدُ العاقلُ لا تكذبْ. ما وظيفة كلمة \"الولد\"؟","a":["عطف بيان","بدل أو نعت مرفوع يتبع لفظ \"أي\"","مفعول به منصوب","منادى ثانٍ"],"c":1,"d":"hard","hint":"بعد \"أيها\" يأتي الاسم معرفة بأل","expl":"كلمة \"الولد\" بعد \"أيها\" تكون بدلًا أو نعتًا مرفوعًا يتبع لفظ \"أي\" في الظاهر، وهي هنا عطف بيان أيضًا. لا يجوز نصبها لأنها تابعة بلفظها لا بالمحل. نصيحة: ابحث عن \"أيها/أيتها\" ثم اجعل ما بعدها بدلًا أو نعتًا مرفوعًا."}]},{"title":"التعجب والمدح والذم","read":[{"h":"التعجب السماعي","t":"التعجب السماعي ألفاظ مسموعة عن العرب وردت على غير قياس، كقولهم: (سبحان الله، لله درُّه، ما أحسنه). وهي تُعرب حسب موقعها ولا تدخلها قواعد التعجب القياسي، فلا يجوز الاشتقاق منها."},{"h":"التعجب القياسي وصيغتاه","t":"للتعجب القياسي صيغتان: (ما أفعله) مثل \"ما أجمل السماءَ\"، و(أفعلْ به) مثل \"أجملْ بالسماءِ\". وكلتاهما تدل على استعظام صفة في المتعجب منه، وعلامتهما أن يكون المتعجب منه مفعولًا به في صيغة \"ما أفعله\" وفاعلًا للجار والمجرور في صيغة \"أفعل به\"."},{"h":"شروط صوغ التعجب القياسي","t":"يشترط في الفعل أن يكون: ثلاثيًا، تامًا، متصرّفًا غير جامد، مثبتًا غير منفي، غير مبني للمجهول، قابلًا للتفاضل، وليس من أفعال الحواس أو الألوان أو العيوب. فمثلًا \"ليس\" و\"كان\" جامدان لا تُصاغ منهما صيغتا التعجب مباشرة، و\"أعمى\" و\"أصفر\" و\"فرح\" لا يصحّ التعجب القياسي منها إلا بالاستعانة بوسيلة غير مباشرة."},{"h":"إعراب صيغتي التعجب","t":"في \"ما أجملَ السماءَ\": \"ما\" نكرة تامة بمعنى شيء مبنية في محل رفع مبتدأ، و\"أجملَ\" فعل ماضٍ للتعجب مبني على الفتح، وفاعله ضمير مستتر وجوبًا، و\"السماءَ\" مفعول به، والجملة الفعلية خبر \"ما\". وفي \"أجملْ بالسماءِ\": \"أجملْ\" فعل ماضٍ للتعجب مبني على الفتح، و\"بالسماءِ\" جار ومجرور في محل رفع فاعل."},{"h":"أفعال المدح والذم","t":"أفعال المدح والذم أفعال جامدة: (نِعْمَ، حبَّذا) للمدح، و(بئس، لا حبذا، ساء) للذم. فاعلها متصدر بأل كقولك \"نعم الرجلُ\"، أو مضاف إلى ما فيه أل كـ\"نعم عملُ الطالبِ\"، أو مضمر مستتر مميز بنكرة مثل \"نعم رجلًا\". ويقدّر مخصوص بالمدح أو الذم مرفوع مبتدأ تُعدّ الجملة خبره."}],"qs":[{"q":"ما أجملَ السماءَ ليلًا! إعراب \"أجملَ\":","a":["فعل أمر مبني","فعل ماضٍ للتعجب مبني على الفتح","فعل مضارع مرفوع","اسم فعل"],"c":1,"d":"easy","hint":"هي صيغة \"ما أفعله\" للتعجب","expl":"في صيغة التعجب \"ما أفعله\" يكون \"أجملَ\" فعلًا ماضيًا للتعجب مبنيًا على الفتح، وفاعله ضمير مستتر، و\"ما\" نكرة تامة مبتدأ. ليس فعل أمر لأن صيغة الأمر لا تُبنى على الفتح المتعمد للتعجب. نصيحة: تعرّف صيغتي التعجب: \"ما أفعله\" و\"أفعلْ به\"."},{"q":"أكرمْ بهذا الطالبِ! ما الصيغة والتعليل؟","a":["أسلوب إنشاء صيغة \"أفعلْ به\" للتعجب","أسلوب أمر ناهي","خبر محض","صيغة تعجب سماعية"],"c":0,"d":"medium","hint":"بعد السكون يأتي جار ومجرور فاعل","expl":"\"أكرمْ بهذا\" صيغة تعجب قياسية \"أفعلْ به\"، فيكون فعل التعجب ماضيًا مبنيًا على الفتح (والسكون لغة)، والجار والمجرور \"بهذا\" في محل رفع فاعل. لا يصح تفسيرها أمرًا لأن المتكلم لم يطلب فعلًا. نصيحة: صيغة \"أفعلْ به\" تَعجُّب، وإذا وردت بمعنى الأمر فبقرينة أخرى."},{"q":"أيُّ الجمل الآتية تعجبٌ قياسي صحيح؟","a":["ما أجملَ هذا المنظرَ","أجملْ بهذا المنظرِ","ما أنضرَ شجرةً عند التعبير عن عيب","أنبِهْ عن القمر"],"c":2,"d":"medium","hint":"\"أنضر\" تُعدّ عيبًا ولا يصح القياس منه","expl":"الجملة الثالثة غير صحيحة؛ لأن \"أنضر\" لونٌ (نضارة بمعنى صفر) وقد وردت الحواس والألوان والعيوب ممتنعة من التعجب القياسي، لذلك سؤال السؤال صحيح بالصيغتين الأوليين. نصيحة: تذكّر أن الصيغتين صحيحتان إذا كان الفعل ثلاثيًا تامًا متصرفًا قابلاً للتفاضل."},{"q":"نِعْمَ الرجلُ عمرو. نوع الجملة وقاعدة الإعراب:","a":["أسلوب ذمّ","أسلوب مدح بفعل جامد نعم","أسلوب تعجب","أسلوب تفضيل"],"c":1,"d":"easy","hint":"سرعة: \"نعم\" تفيد المدح","expl":"\"نعم\" من أفعال المدح الجامدة، وفاعلها \"الرجل\" المتصدر بأل، والمخصوص بالمدح \"عمرو\" مرفوع مبتدأ خبره الجملة. لو قيل \"بئس\" لكانت ذمًّا. نصيحة: المدح: نعم وحبذا، الذم: بئس وساء ولا حبذا، واحفظها في قائمة واحدة."},{"q":"بئسَ خلقًا الكذبُ. إعراب \"خلقًا\":","a":["مفعول به منصوب","تمييز منصوب لفاعل بئس","نعت منصوب","حال منصوبة"],"c":1,"d":"hard","hint":"أفعال الذم والمدح ترتبط بالتمييز","expl":"فاعل \"بئس\" ضمير مستتر، و\"خلقًا\" تمييز منصوب يفسّر الفاعل المضمر، و\"الكذب\" مخصوص بالذم مرفوع مبتدأ. لم تنصب مفعولًا به لأن \"بئس\" فعل لازمة. نصيحة: إذا رأيت فاعلً مضمرًا بعد نعم/بئس فاذكر التمييز المفسر منه."},{"q":"\"حَبَّذا العلمُ\" أيّ من الآتي صحيح؟","a":["حبَّ فعل ماضٍ و\"ذا\" فاعله","حبَّ فعل أمر","ذا مفعول به","حبَّ مدح والكاف حرف جر"],"c":0,"d":"easy","hint":"\"ذا\" اسم إشارة فاعل لحبَ","expl":"\"حبَّذا\" تستوي في المدح: \"حبَّ\" فعل ماضٍ جامد للمدح، و\"ذا\" اسم إشارة فاعل، و\"العلم\" مبتدأ مخصوص بالمدح مؤخر، بمعنى نعم العلم العلمُ. وهي من أفعال المدح المشهورة. نصيحة: \"حَبَّذا\" = مدح، و\"لا حبَّذا\" = ذم، وتُثَبَّت \"ذا\" بلا إذابة."},{"q":"أيُّ الأفعال الآتية يصلح لصوغ التعجب القياسي منه مباشرة؟","a":["استقام","قرأ","أحمرّ","ليست"],"c":1,"d":"hard","hint":"الفعل يجب أن يكون ثلاثيًا تامًا متصرفًا","expl":"\"قرأ\" فعل ثلاثي تام متصرف قابل للتفاضل فيُصاغ منه \"ما أقرأَ\" و\"أقرئْ به\". أما \"استقام\" فغير ثلاثي ويلزم الاستعانة بمصدره، و\"أحمرّ\" لونٌ، و\"ليست\" ناقصة منفية، وكلها لا يصح القياس المباشر منها. نصيحة: التزم بالشروط الأربعة: الثلاثي، التام، المتصرّف، المثبت القابل للتفاضل."}]},{"title":"الاستفهام","read":[{"h":"تعريف الاستفهام وأدواته","t":"الاستفهام طلب معرفة شيء لم يكن معلومًا من قبل. أدواته: الهمزة وهل للتصديق، و(ما، ماذا، من، أي، كم) للتصور، و(كيف، أين، متى، أيان) للبلاغة، و(لماذا، لم، عمَّ) للتعليل. وتكون بعض الأدوات أسماءً معربة أو مبنية حسب موقعها في الجملة."},{"h":"الهمزة وهل","t":"\"هل\" حرف استفهام غير جازم يطلب التصديق بالفعل أو الخبر فقط، ولا تدخل إلا على الجملة المثبتة غالبًا، ولا يصح أن تسبقها \"أم\" لغير التعادل. أما الهمزة فتطلب التصور أو التصديق، وتدخل على المثبت والمنفي، وتُستعمل مع \"أم\" في سؤال التردد كقولك \"أجاء محمدٌ أم عليٌّ؟\"."},{"h":"أسماء الاستفهام","t":"\"من\" لطلب تعيين العاقل: \"من طرق الباب؟\" و\"ما/ماذا\" للسؤال عن غير العاقل، و\"أي\" للسؤال عن أشياء متعددة ويمكن إضافة إلى العاقل أو غيره، و\"كم\" الاستفهامية للسؤال عن العدد (مميزها مفرد منصوب أو مجرور بمن)، و\"كيف\" للسؤال عن الحال، و\"أين\" عن المكان، و\"متى/أيان\" عن الزمان."},{"h":"إعراب أسماء الاستفهام","t":"أسماء الاستفهام تُبنى في موضع الرفع أو النصب أو الجر، مثل \"من\" مبتدأ في \"من عندك؟\"، و\"ماذا\" مفعول به في \"ماذا قرأتَ؟\"، و\"أين\" ظرف مكان منصوب في \"أين توجهتَ؟\". و\"كم\" تتميز بالعامل: \"كم كتابًا قرأتَ؟\" فتُعرب اسم استفهام مفعولًا به."},{"h":"الفروق البلاغية بين الأدوات","t":"كل أداة استفهام تختص بسؤال معين: (متى) للسؤال عن الزمن العام، و(أيان) للسؤال عن وقت داهم قريب الوقوع كيوم القيامة، و(مَن) عن الفاعل العاقل، و(ما) عن الصفة أو غير العاقل، و(أي) تفيد العموم والاشتراك. والاستفهام قد يخرج عن معناه الحقيقي إلى أغراض بلاغية كالإنكار والتقريع والتحقير."}],"qs":[{"q":"هل سافرَ أخوكَ؟ \"هل\" هنا:","a":["اسم استفهام للتصور","حرف استفهام غير جازم للتصديق","فعل ماضٍ","حرف شرط جازم"],"c":1,"d":"easy","hint":"لا يقع بعدها اسم فاعل الأداة","expl":"\"هل\" حرف استفهام غير جازم مبني لا محل له من الإعراب، يطلب التصديق، أي الموافقة على خلافه من نعم أو لا. وليست اسمًا؛ لأن الاسم لا يكون حرفًا ولا يدخل على الجملة. نصيحة: \"هل\" حرف، و(من/ما/متى...) أسماء استفهام."},{"q":"كم كتابًا قرأتَ في العطلة؟ إعراب \"كتابًا\":","a":["تمييز منصوب لكم الاستفهامية","مفعول به منصوب","نعت منصوب","بدل منصوب"],"c":0,"d":"medium","hint":"تمييز \"كم\" مفرد منصوب أو مجرور بمن","expl":"\"كتابًا\" تمييز منصوب لاسم الاستفهام \"كم\"، والمميّز المفرد منصوب يوضح العدد الذي سُئل عنه. لو لحق \"من\" لجاز الجر: \"كم من كتابٍ\". لا نفعله مفعولًا به لأن \"قرأتَ\" منه المفعول. نصيحة: مع \"كم\" الاستفهامية صحّ قاعدة: تمييزها مفرد منصوب."},{"q":"كيف حالُك اليوم؟ إعراب \"كيف\":","a":["خبر مقدم في محل رفع","فاعل مرفوع","ظرف زمان منصوب","مفعول به منصوب"],"c":0,"d":"hard","hint":"وردت للسؤال عن الحال","expl":"\"كيف\" اسم استفهام مبني على الفتح للسؤال عن الحال، وهي هنا خبر مقدم في محل رفع، والمبتدأ المؤخر \"حالك\". فلو سبقتها \"ليست كيفَ حالُك؟\" لاختلف موقعها. نصيحة: \"كيف\" تدل على الحال فتكون كثيرًا خبرًا مقدمًا."},{"q":"أجاء زيدٌ أم عليٌّ؟ هذا الاستفهام:","a":["استفهام عن التصديق","تردُّد بالهمزة بين شيئين","استفهام إنكاري","سؤال عن المكان"],"c":1,"d":"medium","hint":"كلتاهما معلومان ونريد تعيين أحدهما","expl":"الاستفهام هنا استفهام تردد وطلب تعيين؛ فالهمزة تدخل على المثبت مع \"أم\" للسؤال عن أي الاثنين وقع، وليس سؤالًا عن صحة الخبر. \"هل\" لا تدخل على مثل هذا الترتيب. نصيحة: الهمزة تجمع التصديق والتصور، أما \"هل\" فتصديق فقط."},{"q":"أينَ تضعُ كتبَك؟ \"أين\" هنا:","a":["اسم استفهام للسؤال عن المكان ظرف منصوب","حرف استفهام","اسم استفهام للسؤال عن الوقت","فاعل مرفوع"],"c":0,"d":"easy","hint":"وابعه متعلق بوضع","expl":"\"أين\" اسم استفهام مبني للسؤال عن المكان، وهو ظرف مكان منصوب متعلق بفعل \"تضع\". ولو كان حرفًا لم يستوفِ السؤال عنه. نصيحة: \"أين\" مكانية ظرفية، و\"متى\" زمانية، و\"كيف\" حالية."},{"q":"ما الذي أعجبَك في الموضوع؟ إعراب \"ما\":","a":["مفاعيل به وعلامته النصب","مبتدأ في محل رفع","ظرف مكان منصوب","خبر مرفوع"],"c":1,"d":"medium","hint":"جاؤت موصولة بالذي فصارت مبتدأ","expl":"\"ما\" هنا اسم استفهام وقع مبتدأً في محل رفع لأنه تلاها اسم موصول \"الذي\" مرفوع خبره الجملة. ولو قيل \"ماذا أعجبك\" لكانت \"ما\" مفعولًا به أو مبتدأ حسب الوجهين. نصيحة: انظر للعلاقة التي بعد الاسم: مبتدأ أم مفعول به تتحدد بمكان الترتيب."},{"q":"لماذا تأخرتَ عن موعدك؟ الغرض من الاستفهام هنا:","a":["طلَب العِلّة والتعليل","إنكار وتوبيخ","التحقير","التمني"],"c":0,"d":"easy","hint":"أداة \"لماذا\" تفيد السبب","expl":"\"لماذا\" و\"لمَ\" و\"عمَّ\" تطلب علةً وسببًا لحدوث الفعل، فهنا نسأل عن سبب التأخر. الاستفهام قد يقصد به أغراض بلاغية أخرى لكن المطروح المطلوب صريح. نصيحة: احفظ ربط الأدوات بالمعنى: لماذا=علة، أين=مكان، متى=زمان، كيف=حال."}]},{"title":"التوابع والبدل","read":[{"h":"التوابع وتعريفها العام","t":"التوابع أسماء تتبع ما قبلها في الإعراب، وهي أربعة: النعت (الصفة)، العطف (النسق)، التوكيد، والبدل. كل تابع يحمل حركة متبوعه ويعرب مثله تمامًا، ومثال ذلك \"جاء الطالبُ المجتهدُ\"."},{"h":"النعت وأنواعه","t":"النعت يُبين صفة الاسم الموصوف. نعت حقيقي يتبع الموصوف في الإعراب والنوع والعدد والتعريف، مثل \"رأيتُ رجلًا كريمًا\"، ونعت سببي يُفيد منعوتًا قبله مع ما بعده، ويرفع ما بعده فاعلًا ويتأخر عنه، مثل \"هذا رجلٌ كريمٌ خلقُه\"."},{"h":"العطف وحروفه","t":"العطف ربط بين اسم وفعل بحرف، وحروفه: (الواو) للاشتراك، (الفاء) للترتيب مع التعقيب، (ثم) للترتيب مع التراخي، (أو) للتخيير، (حتى) للغاية، (بل، لكن) للإضراب والاستدراك، (أم) للتعيين. والمعطوف يتبع المعطوف عليه في الإعراب فقط لا في النوع والعدد."},{"h":"التوكيد","t":"التوكيد نوعان: لفظي بتكرار اللفظ نفسه كـ\"جاء جاء محمد\"، ومعنوي بألفاظ مخصوصة تدل على ذات المؤكد: (نفس، عين، كل، أجمعون، كلا، كلتا، جميع). اشتراط التوكيد المعنوي أن يكون الضمير متصلًا بالمؤكد كقولك \"فاز اللاعبُ نفسُه\"."},{"h":"البدل وأنواعه","t":"البدل تابع مقصود بالحكم أو بالذات، والمبدل منه مذكور قبله، وأنواعه: (1) بدل كلٌّ من كلٍّ أو بدل مطابق: \"جاء المديرُ أحمدُ\"، (2) بدل بَعض من كل: \"أكلتُ الخبزَ ثلثَه\"، (3) بدل اشتمال: \"أعجبني الفتى خلقُه\"، (4) بدل مباين: (غلط ونسيان وإضراب) مثل \"جاء أخوكَ أبوكَ\"."}],"qs":[{"q":"جاء المديرُ المسؤولُ لتفقد العمل. كلمة \"المسؤول\":","a":["بدل مرفوع","نعت مرفوع يتبع المدير","معطوف مرفوع","توكيد مرفوع"],"c":1,"d":"easy","hint":"تبين صفة المدير","expl":"\"المسؤول\" نعت حقيقي مرفوع يتبع المنعوت \"المدير\" في الإعراب والتنكير (بأل) والتعريف، ولو كان بدلًا لأفرد الحكم على البدل دون المبدل منه. نصيحة: النعت يوضح الموصوف، والبدل يُعيد إحياءه باسم آخر."},{"q":"فازَ المتسابقُ نفسُهُ بالمركز الأول. \"نفسُه\":","a":["بدل مرفوع","نعت مرفوع","توكيد معنوي مرفوع","معطوف مرفوع"],"c":2,"d":"medium","hint":"توكيد بضمير متصل","expl":"\"نفس\" مع ضمير متصل (ه) من ألفاظ التوكيد المعنوي، وهي مرفوعة تابعٌ للمؤكد \"المتسابق\". والدليل أن حذفها لا يخل بمعنى الجملة صلًا بجحنها توكيدًا. نصيحة: ألفاظ التوكيد المعنوي: نفس، عين، كل، أجمعون + ضمير يطابق المؤكد."},{"q":"قرأتُ الكتابَ صفحاتِه الأولى. \"صفحاته\":","a":["بدل بعض من كل منصوب","نعت منصوب","مضاف إليه","معطوف منصوب"],"c":0,"d":"hard","hint":"جزء من الكتاب","expl":"البدل جزء من المبدل منه، فجاء بدل بعض من كل منصوبًا يتبع الكتاب في النصب، و(ها) تعود على الكتاب. لو كانت نعتًا لأوضحت صفة لا جزءًا. نصيحة: حدد علاقة البدل: مطابق (نفس)، بعض من كل، اشتمال (خلق/علم)، مباين (غلط)."},{"q":"أعجبتني الفتاةُ خلقُها الجميلُ. \"خلقُها\":","a":["بدل اشتمال مرفوع","خبر مرفوع","نعت مرفوع","فاعل مرفوع"],"c":0,"d":"medium","hint":"الخلق معنى قائم في الفتاة","expl":"\"خلقُها\" بدل اشتمال مرفوع؛ لأنه من الصفات المعنوية التي تشتمل عليها الفتاة ولا تجزأ عنها، والضمير يعود للمبدل منه \"الفتاة\". وليست خبرًا لأن \"أعجبت\" فعل تام لا هنا مبتدأ، ولا نعتًا. نصيحة: البدل الاشتمالي يأتي بمعنى أدبي ليست جزءًا."},{"q":"حضرَ الصديقُ أحمدُ. \"أحمد\" في الجملة:","a":["بدل مطابق مرفوع","نعت","معطوف","توكيد معنوي"],"c":0,"d":"easy","hint":"نفس الشخص عرف باسمين","expl":"\"أحمد\" بدل مطابق (كل من كل) مرفوع يتبع \"الصديق\"، وهو المقصود بالحضور بعينه. يسقط البدل ويكون الحكم على الأول لو كان نعتًا. نصيحة: البدل المطابق = الاسم يفسّر المقصود: \"المدير الأستاذ محمد\"."},{"q":"أكرمتُ المعلمَ ثم الوالدَ. حرف العطف هنا:","a":["الواو للاشتراك","ثم للترتيب مع التراخي","الفاء للتعقيب","أو للتخيير"],"c":1,"d":"easy","hint":"الإكرام بعد الإكرام بفاصل","expl":"\"ثم\" تفيد الترتيب مع التراخي، أي أن إكرام الوالد جاء بعد إكرام المعلم بفاصل زماني منقول اللفظ. و\"الفاء\" للترتيب المتعاقب فورًا، والواو تجمع بلا ترتيب. نصيحة: الصيد في حروف العطف: الفاء تعقيب، ثم تراخٍ، الواو اشتراك."},{"q":"افْعَلْ الدواءَ كلَّه وليس بعضَه. \"كلَّه\":","a":["توكيد معنوي منصوب","بدل منصوب","مفعول ثانٍ","نعت منصوب"],"c":0,"d":"hard","hint":"توكيد الشمول للدواء","expl":"\"كل\" من ألفاظ التوكيد المعنوي، وهي منصوبة تابعة للمؤكد \"الدواء\"، و(ه) ضمير متصل بالمؤكد زادتها شمولًا. لو قلت \"الدواءَ كله\" بقصد تقسيط جزء لجاز البدل، لكن هنا لم يقصد. نصيحة: تأكد من وجود الضمير العائد على المؤكد مع \"كل نفس عين\"."}]}]},{"title":"البلاغة والأدب","icon":"🖋️","chapters":[{"title":"علم البيان للأدبي","read":[{"h":"التشبيه وأركانه","t":"التشبيه عقد شراكة بين شيئين في صفة واحدة أو أكثر، وأركانه أربعة: المشبه، المشبه به، أداة التشبيه (كأن، كاف، مثل، يشبه)، ووجه الشبه. مثال: \"العلمُ كالنورِ في الهداية\" فالعلم مشبه، والنور مشبه به، والكاف أداة، والهداية وجه الشبه."},{"h":"أنواع التشبيه بحسب الشبه","t":"التشبيه إما مؤكد إذا حذفت أداة التشبيه: \"العلمُ نورٌ\"، أو مجمل إذا حذف وجه الشبه: \"كأن عليًّا بدرٌ\"، أو مفصل إذا ذكر وجه الشبه: \"كأنه البحر وافِدًا بالندى\"، أو بليغ إذا حذفت الأداة ووجه الشبه معًا: \"هو بحرٌ\"."},{"h":"الاستعارة المكنية والتصريحية","t":"الاستعارة تشبيه حُذف أحد طرفيه. المكنية: حذف المشبه به ورمز له بلازمه: \"اعتدى العدوُّ على الحقِّ\" حيث شبه الحق بالإنسان وحذف المشبه به وأبقى لازمه \"العدوان\". والتصريحية: حذف المشبه وصرح بالمشبه به: \"رأيتُ أسدًا في الميدان\" يقصد بها الشجاع."},{"h":"الكناية","t":"الكناية لفظ أُريد به لازم معناه مع جواز إرادة المعنى الأصلي، مثل \"فلانٌ طويلُ النِّجاد\" أي رفيع الشأن، و\"فلانٌ كثيرُ الرماد\" كناية عن الكرم، و\"نظيفُ اليد\" كناية عن الأمانة، و\"طاهرُ الذيل\" عن العفة. وهي أبلغ من التصريح لكونها تترك للذهن أثرًا."},{"h":"المجاز المرسل والاستعارة التصريحية","t":"المجاز المرسل كلمة مستعملة في غير معناها لعلاقة غير المشابهة كالسببية \"(زرعتُ الأرضَ)\" بمعنى بذرت فيها، والمجزئية \"(فليحذرْ الذين يخالفون عن أمره)\" أي جزأ الله. أما الاستعارة فتقوم على علاقة المشابهة فقط. والكناية أعمّ وأشمل لأنها لا تنافي الحقيقة."}],"qs":[{"q":"العلمُ نورٌ. هذه جملة تشتمل على صورة بيانية هي:","a":["استعارة مكنية","تشبيه بليغ حذفت الأداة ووجه الشبه","كناية","مجاز مرسل"],"c":1,"d":"easy","hint":"بلا أداة وبلا وجه شبه","expl":"\"العلم نور\" تشبيه بليغ؛ لأنه حُذفت الأداة (الكاف) ووجه الشبه (الإضاءة في الهداية) فصار بلسان الأبلغين. لو قيل \"كأن العلم نور في الهداية\" لصار مجملًا. نصيحة: التشبيه البليغ علامته: عدم الأداة وعدم وجه الشبه معًا."},{"q":"المعلمُ يبذلُ كالنهرِ في العطاء. الصورة البيانية:","a":["استعارة تصريحية","تشبيه مؤكد بدليل الكاف","كناية","مجاز مرسل"],"c":1,"d":"easy","hint":"وردت فيها أداة التشبيه","expl":"الشبه هنا تشبيه صريح وردت أداة التشبيه \"الكاف\"، فهو تشبيه مؤكد باطلاع الأداة. ولو حذف الأداة لكان بليغًا. نصيحة: الأداة (كأن، الكاف، مثل، يشبه) تجعل الصورة تشبيهًا صريحًا بلا نقاش."},{"q":"غزا الانتقادُ أفكارَ الكاتب بعنفٍ. الصورة في \"الانتقادِ يغزو\":","a":["تشبيه","استعارة مكنية شبه الانتقاد بشخص","استعارة تصريحية","كناية"],"c":0,"d":"medium","hint":"شُبه الانتقاد بإنسان يغزو","expl":"في \"الانتقاد يغزو\" شبه الانتقاد بإنسان محارب يغزو، وبَنى على المحذوف لازم من لوازمه وهو (الغزو)، فهي استعارة مكنية حُذف فيها المشبه به. لو قيل \"الانتقادُ أسدٌ\" لصرحت بالمشبه به. نصيحة: الاستعارة المكنية = حذف المشبه به وإبقاء لازمه؛ والتصريحية = ذكر المشبه به هم شاهدي البروفة."},{"q":"أشرقت شمسُ الحرية فوق العالم. الصورة البيانية:","a":["استعارة تصريحية حذف المشبه \"الحرية\" وذُكر المشبه به \"الشمس\"","تشبيه بليغ","كناية","مجاز مرسل بالعلاقة السببية"],"c":0,"d":"hard","hint":"ذُكر \"الشمس\" صراحة في مكان الحرية","expl":"هنا شبهت الحرية بالشمس، ثم حذف المشبه (الحرية) وصرح بالمشبه به (شمس) مع شيء من لوازمه، فهي استعارة تصريحية. ولو ظهرت الحرية وهي (مشبه) مع الشمس لمتصف بالتكافؤ. نصيحة: تمييز: التصريحية ذكرت المشبه به، والمكنية احتفظت ببعض لوازمه فقط."},{"q":"فلانٌ رفيعُ البناءِ عالي السَّنام. هذه عبارة كناية عن:","a":["الشجاعة","رفعة المكانة والعلو","الكرم","الأمانة"],"c":1,"d":"medium","hint":"بناء عالٍ يرمز لعلو المنزلة","expl":"\"رفيع البناء\" لفظٌ أريد به لازم معناه (رفعة المنزلة والجاه) مع جواز إرادة المعنى الأصلي الطولي، فهو كناية عن الرفعة لا عن ظاهر البناء. لو قصدت شجاعة لاستعملت \"طويل النجاد\". نصيحة: الكناية أبلغ من الصريح؛ لأنها تجمع بين المعنى الحقيقي واللازم."},{"q":"جعلتُ سماعي للعلمِ أرضًا طيبة. البيان المحوري هنا:","a":["تشبيه السماع بالأرض الطيبة","استعارة مكنية","كناية","مجاز مرسل"],"c":0,"d":"medium","hint":"ربي لمعنى التشبيه كامل","expl":"شبه المتكلم سماعه للعلم بالأرض الطيبة قبولًا للبذور، فوجدنا أداة أو حذفناها ووجه الشبه (القبول)، وهي تشبيه واضح بآلية الذكاء. ولو حذف المشبه به لصار استعارة. نصيحة: عند وجود المشبه والمشبه به معًا فالصورة تشبيه مهما حذفت الأدوات."},{"q":"أيُّ العبارات الآتية تحوي استعارة مكنية؟","a":["العلمُ نورٌ","نشرَ الجهلُ ذراعَهُ في الأمة","هو كالبحر في العطاء","زرعتُ الأرضَ"],"c":1,"d":"hard","hint":"حَدِّد المشبه به المحذوف ولوازمه","expl":"في \"نشر الجهل ذراعه\" شبه الجهل بإنسان يحمل ذراعًا، وحذف المشبه به (الإنسان) وأبقى لازمه (الذراع) فصار مكنية. الأولى تشبيه بليغ، والثالثة تشبيه مؤكد، والرابعة مجاز مرسل بالعلاقة السببية. نصيحة: ابحث عن لازمٍ يُنسب إلى المحذوف من المشبه به لتعرف المكنية."}]},{"title":"علم المعاني وعلم البديع","read":[{"h":"الخبر والإنشاء","t":"الخبر جملة يصحّ أن يوصف قائلها بالصدق أو الكذب لذاتها، مثل \"سافر الوفدُ\". والإنشاء جملة لا تحتمل الصدق والكذب، وينقسم إلى: طلبي (أمر، نهي، استفهام، تمني، نداء) مثل \"احضر، لا تكذب، هل سافرت؟\"، وغير طلبي (مدح، ذم، تعجب، رجاء)."},{"h":"أغراض الخبر البلاغية","t":"الخبر يأتي لأغراض منها: الفائدة، إفادة الحكم، الفخر، التوبيخ، التحسر، التمثيل، والدعاء. فقول الشاعر \"نحن قومٌ لا نقرُّ بذلٍّ\" يفيد الفخر، وقوله تعالى \"وعسى أن تكرهوا شيئًا\" خارج عن معنى الطلب إلى الإرشاد."},{"h":"القصر وطرقه","t":"القصر تخصيص شيء بشيء بطريق مخصوص، بمعنى حصر الحكم في المذكور ونفيه عن غيره. طرقه: بـ(إنما) كقوله تعالى \"إنما أنت مذكِّرٌ\"، بـ(إلا) مع نفي أو نهي أو استفهام: \"ما النجاحُ إلا بالاجتهاد\"، وبالتقديم: \"إياك نعبد\"، و(إنما) و(مِن) مع \"بل\". ويترتب عليه أنواع كالقصر الإضافي."},{"h":"التقديم والتأخير","t":"تقديم المسند إليه أو المسند أو المفعول على الأصل لأغراض بلاغية: (1) الفخر، (2) التهويل، (3) التشويق، (4) التوبيخ، (5) التخصيص. فقوله \"إياك نعبد\" قدم المفعول للقصر والإخلاص. والتأخير يكون للتسهيل أو مراعاة غير ذلك."},{"h":"علم البديع: المحسنات اللفظية والمعنوية","t":"البديع يجمّل الكلام: محسنات لفظية كالجناس (اللفظ المشترك في النطق دون المعنى) والسجع (توافق أواخر الجمل) والازدواج، ومحسنات معنوية كالطباق (جمع الضدين: \"ويحسبون أنهم على شيء\") والمقابلة والتورية. والطباق يفيد إبراز المعنى ووضوحه."}],"qs":[{"q":"إنما العزةُ لمن اتقى. الغرض البلاغي من (إنما):","a":["التوكيد على العموم","القصر والحصر","الانشاء","التقديم"],"c":1,"d":"easy","hint":"إنما تفيد الحصر","expl":"(إنما) من أدوات القصر، تفيد حصر العزة للمتقين ونفيها عن غيرهم، وهو قصر موصوف على صفة. ولو قيل \"العزة لمن اتقى\" لاحتمل المشاركة. نصيحة: أدوات القصر تحفظ بسرعة: إنما، إلا، التقديم."},{"q":"ما يبكيك إلا الفراقُ. هذه الجملة:","a":["خبر صريح","قصر بالاستثناء (مقصور عليه)","انشاء طلبي","توكيد معنوي"],"c":1,"d":"medium","hint":"نكفت بـ\"ما\" ونفي + إلا","expl":"القصر تم بقصر البكاء على الفراق بنفيه عن غيره بطريقة \"ما + إلا\"، فهي قصر الموصوف على الصفة بنفي الحكم وتخصيصه. لو قال \"يبكيني الفراق\" لم يكن قصرًا. نصيحة: صيغة القصر المشهورة: (ما + المفعول + إلا + الفاعل) = قصر موصوف على صفة."},{"q":"إياك نعبدُ وإياك نستعينُ. القصر هنا بطريق:","a":["إنما","تقديم المفعول","أداة الاستثناء","النفي"],"c":1,"d":"hard","hint":"قدم المفعول قبل الفعل","expl":"قدّم المتكلم المفعول \"إياك\" على الفعل، فضمن معنى القصر: العبادة والاستعانة مقصورتان على الله تعالى وحده. ولو قال \"نعبدك\" لم يُفهم الحصر. نصيحة: التقديم = علامة القصر حين يقدم ما حقّه التأخير اتباعًا للبلاغة."},{"q":"أيُّ الجمل الآتية إنشائية غير طلبية؟","a":["سافر الرجلُ","ما أجملَ الوردَ!","احفظ دروسك","هل أنجزتَ واجبك؟"],"c":1,"d":"medium","hint":"التعجب شيء لا يحتمل صدقًا أو كذبًا","expl":"\"ما أجملَ الوردَ\" إنشاء غير طلبي (تعجب) لا يصح فيه الصدق والكذب. \"سافر الرجل\" خبر، و\"احفظ\" أمرٌ طلبي، و\"هل أنجزت\" استفهام طلبي. نصيحة: الإنشاء = ما لا يوصف بصدق ولا كذب؛ والتعجب والمدح والذم غير طلبية."},{"q":"التشويق إحدى وظائف الإضافة كلما أُلقي الخبر. أيُّ العبارة الآتية خُرِج فيها الخبر للفخر؟","a":["نحنُ قومٌ بنى اللهُ مجدَنا","سافر الوفدُ للقمة","نعم الخلقُ","لعلكم ترحمون"],"c":0,"d":"medium","hint":"الفخر إعلان فضل الذات","expl":"\"نحن قوم بنى الله مجدنا\" خرج الخبر لغرض الفخر بعلو المنزلة، فمعناه لفظيًا خبر لكن غايته الفخر. غيره من الخيارات: سفر الوفد خبر عادي، والتعجب إنشاء، والرجاء خرج لغرض الشفقة. نصيحة: عندما يتحدث القائل عن جماعته بمدح فغرض الخبر هو الفخر."},{"q":"أفصح قولك بالبيان تقديرًا، وأفصحْ بمعناه... الصورة البلاغية (أفصح/أفصح):","a":["طباق","جناس تام","سجع","توريه"],"c":1,"d":"easy","hint":"لفظان تام الاتفاق نطقًا","expl":"الجناس التام: كلمتان اتفقنا في الحروف والوزن واتختلفنا في المعنى، وهنا (أفصح) الأولى بمعنى أبين والفعل، (أفصح) الثانية لاختلاف المعنى، وهو من المحسنات اللفظية. ولو اختلفا في التمام صار ناقصًا. نصيحة: الجناس: لفظ موحد المعنى مختلف النطق، والسجع: توافق أواخر الجمل."},{"q":"يُحْيِي ويميتُ، وهو على كل شيء قدير. البلاغة والبلاغة في (يحيي ويميت):","a":["جناس","طباق بين الحياة والموت","سجع","وعي الظل"],"c":1,"d":"easy","hint":"ذكر ضدين متناظرين","expl":"الطباق جمع المتضادين في الكلام، وهنا (الإحياء/الإماتة)، وهو من المحسنات المعنوية ويفيد إبراز المعنى وتقريره. ولو كان الجناس لاتحد اللفظان بلفظ. نصيحة: الطباق = ذكر ضدين، والمقابلة = ذكر شيئين ومقابلهما."}]},{"title":"أدب العصر الحديث (الشعر والنثر)","read":[{"h":"حركة الإحياء والبعث","t":"مدرسة الإحياء دعت إلى إحياء التراث الشعري القديم على نهج البحتري والمتنبي، والاهتمام بالشعر العمودي. من روادها: محمود سامي البارودي (رائد الإحياء)، وأحمد شوقي (أمير الشعراء)، وحافظ إبراهيم (شاعر النيل)، والبلاغة عندهم عالية المضمون."},{"h":"مدرسة الديوان والاتجاه الجديد","t":"مدرسة الديوان أسسها العقاد والمازني وعبد الرحمن شكري، ودعت إلى الوحدة العضوية للقصيدة وتجديد المعاني ونبذ التقليد، والاهتمام بالشعر الوجداني الذاتي بدل المناسبات."},{"h":"مدرسة أبولو والاتجاه الوجداني","t":"مدرسة أبولو أسسها أحمد زكي أبو شادي سنة 1932، ورأت أن الشعر تعبير عن العاطفة الصادقة والذات، وكان من كبارها إبراهيم ناجي وعلي محمود طه. وتأثرت بالرومانسية الغربية."},{"h":"النثر الحديث: القصة والمسرحية","t":"أقبل النثر على فنون جديدة: القصة القصيرة، الرواية، المسرحية، المقال، والسيرة الذاتية. فنجيب محفوظ رائد الرواية الحديثة وحصل على نوبل 1988، ومصطفى لطفي المنفلوطي نثر الشعر بالنثر، وتوفيق الحكيم من رواد المسرح الذهني."},{"h":"خصائص أدب العصر الحديث عامة","t":"تميز أدب العصر الحديث بمعالجة قضايا الوطن والحرية، وتنويع الأوزان والقوافي، والوحدة العضوية، والاهتمام بالمضمون الإنساني، وربط الأدب بقضايا المجتمع، مع ظهور المدارس النقدية الجديدة."}],"qs":[{"q":"أميرُ الشعراء وأحد رواد مدرسة الإحياء في مصر:","a":["أحمد شوقي","إبراهيم ناجي","أحمد زكي أبو شادي","نجيب محفوظ"],"c":0,"d":"easy","hint":"صاحب \"قم للمعلم وفه التبجيلا\"","expl":"أحمد شوقي لقبه أمير الشعراء، وعاصر البارودي في الإحياء، وهي مدرسة تحدّدت في العمودية والتعلق بالتراث. إبراهيم ناجي وأبو شادي من أبولو الرومانسية. نصيحة: الإحياء = شوقي وحافظ، الوجداني = ناجي وأبو شادي."},{"q":"مدرسة الديوان أسسها ثلاثة شعراء هم:","a":["العقاد والمازني وعبد الرحمن شكري","شوقي وحافظ والبارودي","ناجي وأبو شادي وعلي طه","طه حسين والعقاد والرافعي"],"c":0,"d":"medium","hint":"ثلاثي الكتب القونغري الناقد للتقليد","expl":"مدرسة الديوان أسسها العقاد، المازني، وعبد الرحمن شكري سنة 1921، وقدموا الوحدة العضوية والتفكير في القصيدة. شوقي وحافظ من الإحياء، ومدرسة أبولو من الرومانسية. نصيحة: كل اتجاه له رواده، اربط الديوان بالأسماء الثلاثة وحفظها سهل باجتماع \"العقاد المازني شكري\"."},{"q":"هي مدرسة دعت إلى أن الشعر صدقٌ وعاطفةٌ وذاتية، عملت على التحرر من المناسبات:","a":["مدرسة الإحياء","المدرسة الوجدانية (أبولو)","مدرسة الديوان","المدرسة الواقعية"],"c":1,"d":"medium","hint":"أنشأها أبو شادي 1932","expl":"المدرسة الوجدانية (مدرسة أبولو) أنشأها أبو شادي، ورأت الشعر نبعًا من العاطفة والذات والطبيعة، ومشادات منها روافد الرومانسية. مدرسة الإحياء عرفت بالعمودية، والديوان سعت للوحدة العضوية الفكرية. نصيحة: احفظ أبو شادي للمدرسة الوجدانية كما تحفظ العقاد للديوان."},{"q":"أول عربي يفوز بجائزة نوبل في الأدب (1988):","a":["طه حسين","نجيب محفوظ","حافظ إبراهيم","توفيق الحكيم"],"c":0,"d":"easy","hint":"روائي مصري شهير","expl":"نجيب محفوظ أول أديب عربي ينال نوبل في الأدب سنة 1988 عن رواياته الثلاثية و\"أولاد حارتنا\"، وهو رائد الرواية الواقعية الحديثة. طه حسين عميد الأدب العربي مقالات وسيرة. نصيحة: 1988 = نوبل = نجيب محفوظ، ثَبِّتها في ذهنك historians."},{"q":"شاعرُ النيل لقب أُطلق على:","a":["حافظ إبراهيم","أحمد شوقي","محمود سامي البارودي","علي محمود طه"],"c":0,"d":"easy","hint":"من شعراء الإحياء","expl":"حافظ إبراهيم عُرف بشاعر النيل، من أعلام مدرسة الإحياء وشعر المناسبات الوطنية، وصاحبه تعلق له بالتراث. شوقي أمير الشعراء، والبارودي رائد الإحياء. نصيحة: البارودي رائد الإحياء، شوقي أمير الشعراء، حافظ شاعر النيل."},{"q":"من رواد النثر الحديث ومدرسة المسرح الذهني في مصر:","a":["توفيق الحكيم","نجيب محفوظ","المنفلوطي","طه حسين"],"c":0,"d":"medium","hint":"تعمق في أفكار المسرحيات مثل \"أهل الكهف\"","expl":"توفيق الحكيم أبدع المسرح الذهني بأعمال كـ\"أهل الكهف\" و\"مصير صرصار\"، وناقش قضايا الفكر. المنفلوطي خطيب النثر، ونجيب محفوظ الروائي. نصيحة: عند سؤال المدارس الأدبية: الحكيم = مسرح، محفوظ = رواية، العقاد = شعر."},{"q":"قصيدة \"الأطلال\" من أشهر قصائد المدرسة الوجدانية، وقائلها:","a":["إبراهيم ناجي","أحمد شوقي","محمود سامي البارودي","حافظ إبراهيم"],"c":0,"d":"easy","hint":"رقيقٌ ووجداني","expl":"\"الأطلال\" قصيدة لإبراهيم ناجي تمثل المدرسة الوجدانية/الرومانسية بتصوير العاطفة والحنين والذات، وغنتها أم كلثوم. شوقي وحافظ من الإحياء العمودية. نصيحة: ارتبط \"الأطلال\" بناجي، وارتبط \"ويلٌ للمعلم\" بأبو شادي... محفوظ عدو جيد."}]},{"title":"المدرسة الرومانسية والواقعية","read":[{"h":"المدرسة الرومانسية وخصائصها","t":"الرومانسية مذهب أدبي يرفع العاطفة والذات والفردية فوق العقل، ويهرب من الواقع إلى الطبيعة والحلم والشكوى والحنين، فالشعر تعبير عن النفس وأشواقها. ومن روادها في العالم: شاتوبريان ولوركا، وفي مصر: أبولو والشعراء الوجدانيون."},{"h":"المدرسة الواقعية وخصائصها","t":"الواقعية مذهب أولى تصوير الحياة كما هي بعيوبها ومستوياتها، لا كما يجب أن تكون، مع الاهتمام بالتفاصيل الاجتماعية والحلول، فجاءت الرواية الواقعية لتصور المجتمع المصري: الفقر، المأساة، الطبقية، مع النقد الاجتماعي الهادف."},{"h":"الواقعية النقدية","t":"تفرع من الواقعية أسلوب الواقعية النقدية الذي وصف سلبيات المجتمع (الجهل، الفقر، القهر) بهدف الإصلاح، وكان نجيب محفوظ أبرز أسمائها في روايات: \"الثلاثية\"، \"زقاق المدق\"، \"بداية ونهاية\"."},{"h":"الفرق بين الرومانسية والواقعية","t":"الرومانسية تنظر إلى العالم من داخل الذات والعاطفة والرغبة في المثال، والواقعية تنظر إلى العالم من خارجه كما هو قائم. الأول هروب إلى الطبيعة والحلم، والثاني وقوف عند الحقيقة وعلاج المجتمع."},{"h":"الاتجاه الاجتماعي والملتزم","t":"أخذ الشعر والنثر اتجاهًا اجتماعيا ملتزمًا بقضايا الأمة: الحرية، العدل، الاستعمار، فكتب الشعراء والمجتمعات في مواجهة المحتل، واندمجت الأدبية بالمقاومة الوطنية في العصر الحديث."}],"qs":[{"q":"المدرسة الرومانسية تركز على:","a":["العاطفة والذات والطبيعة","تصوير الواقع كما هو بدقة","تقليد النموذج القديم","المعاني الذهنية المجردة"],"c":0,"d":"easy","hint":"اسمها من \"حلم\" و\"وجدان\"","expl":"الرومانسية رفعت العاطفة والذات والطبيعة فوق العقل، وهربت من الواقع إلى الحلم، بينما الواقعية تصور الحياة كما هي، والإحياء يقلد التراث. نصيحة: الرومانسية = قلب/ذات/حلم، الواقعية = مجتمع/مرئي/نقد."},{"q":"من أعلام المدرسة الرومانسية في الشعر العربي الحديث:","a":["إبراهيم ناجي","محمود سامي البارودي","حافظ إبراهيم","أحمد شوقي"],"c":0,"d":"easy","hint":"مدرسة أبولو","expl":"إبراهيم ناجي من رموز الرومانسية الوجدانية (مدرسة أبولو)، بينما البارودي وحافظ وشوقي من مدرسة الإحياء العمودية. نصيحة: قسّم أعلام العصر: إحياء = بارودي/شوقي/حافظ، رومانسية = ناجي/أبو شادي/علي طه."},{"q":"الواقعية النقدية تهدف إلى:","a":["الهروب من المجتمع","كشف عيوب المجتمع والحث على الإصلاح","تمجيد العاطفة فقط","الغموض الفني"],"c":1,"d":"medium","hint":"\"نقدية\" أي تحليل وفضح","expl":"الواقعية النقدية تواصل الأسلوب الواقعي مع إحكام النقد الاجتماعي وتصوير الضعف والجهل بهدف الإصلاح، فهي لا تكتفي بالتصوير بل تحكم نقديًا. وليست هروبًا ولا تعظيمًا للعاطفة. نصيحة: الواقعية النقدية = تصوير + نقد + إصلاح."},{"q":"روائي مصري تميز بالواقعية النقدية وحصل على نوبل:","a":["نجيب محفوظ","توفيق الحكيم","المنفلوطي","يسري السباعي"],"c":0,"d":"easy","hint":"بطل روايات \"الثلاثية\"","expl":"نجيب محفوظ أبرز الواقعيين النقديين في الرواية، بأعمال تصور أحياء القاهرة وطبقات المجتمع، ونال نوبل 1988. الحكيم في المسرح، والمنفلوطي في المقال والخطابة. نصيحة: الثلاثية، زقاق المدق، اللص والكلاب كلها لنحفوظ وتأكد في خصيصة الواقعية."},{"q":"أيّ من الآتي يُعدّ من خصائص الشعر الرومانسي؟","a":["الشكوى والحنين وتصوير الطبيعة","خطاب على المناسبات الرسمية","الوحدة الموضوعية الذهنية الباردة","الاهتمام بالأوزان فقط"],"c":0,"d":"medium","hint":"عاطفة المصريين","expl":"الشعر الرومانسي يمتاز بالشكوى والحنين والصور الطبيعة والحس الوجداني الحر، عكس قصائد المناسبات أو الوصف العمودي الجامد، وقد ازدهر في مدرسة أبولو. نصيحة: ركّز على الألفاظ الدالة على العاطفة (حنين، وجد، طبيعة) لتميز الرومانسية."},{"q":"الفرق الجوهري بين الرومانسية والواقعية:","a":["الرومانسية من الداخل، والواقعية من الخارج","الواقعية تبحث عن المثل والأحلام","الرومانسية تصور الواقع بدقة","لا فرق بينهما"],"c":0,"d":"hard","hint":"نظرة الانطلاق","expl":"الرومانسية تنطلق من الذات والعاطفة وتصور الحياة كما يتمناها الأديب، بينما الواقعية مرآة للحياة كما هي بموضوعية، فالفرق بين رؤيتين: داخلية منطلقة وخارجية ملتزمة. نصيحة: حين تقارن: قل الرومانسية ذاتية، والواقعية موضوعية."},{"q":"قصيدة \"أطلال\" كما تُنسب إلى إبراهيم ناجي تعبّر عن:","a":["الحنين والشكوى الوجدانية","الوصف الخارجي للطبيعة","المدح","الفخر العشائري"],"c":0,"d":"medium","hint":"لحنها يذيب المشاعر","expl":"\"الأطلال\" قصيدة وجدانية تعبر عن الحنين والألم والشكوى، وهي تجسيد كامل للرومانسية في الحس الفني. وليست وصفًا خارجيًا ولا مدحًا. نصيحة: عند سؤال السياق الفني، اربط الأطلال بالمدرسة الوجدانية دائمًا."}]}]}]},{"id":"adabitar","name":"التاريخ الحديث والمعاصر","icon":"🏛️","color":"#8D6E63","books":[{"title":"التاريخ للصف الثالث","icon":"🏛️","chapters":[{"title":"الثورة الفرنسية وأوربا الحديثة","read":[{"h":"الثورة الفرنسية وأسبابها (1789)","t":"اندلعت الثورة الفرنسية سنة 1789 نتيجة تراكم أسباب عدة: استبداد الملك لويس السادس عشر، وتقسيم المجتمع إلى طبقات امتيازات لرجال الدين والنبلاء دون العامة، والأزمة المالية، وانتشار أفكار الأنوار عند روسو وفولتير ومونتسكيو التي دعت للحرية والمساواة وحقوق الإنسان. وجاءت انطلاقة الثورة باقتحام سجن الباستيل في 14 يوليو 1789."},{"h":"نتائج الثورة والدساتير","t":"أعلن المجلس الوطني \"إعلان حقوق الإنسان والمواطن\" في أغسطس 1789، وتحوّلت فرنسا إلى ملكية دستورية ثم جمهورية سنة 1792، وأُعدم الملك لويس السادس عشر سنة 1793. ثم ظهرت مرحلة الاضطراب حتى آل الأمر لنابليون بونابرت."},{"h":"نابليون وحملته على مصر","t":"قاد نابليون حملة على مصر سنة 1798 لقطع الطريق على إنجلترا نحو الهند، واحتل الإسكندرية، وانهزم أسطوله في أبي قير. ثم عاد نابليون إلى فرنسا سنة 1799 وقام بانقلاب أمسك فيه بالسلطة (القنصلية)، ثم أصبح إمبراطورًا سنة 1804، وانهزم نهائيًا في معركة واترلو سنة 1815."},{"h":"مؤتمر فيينا 1815","t":"عُقد مؤتمر فيينا سنة 1815 بعد سقوط نابليون بقيادة النمسا (مترنيخ)، واعتمد مبدأ \"المشروعية\" أي إعادة الحكام الشرعيين، فعادت أسرة بوربون إلى فرنسا، وأعيدت التوازنات الأوروبية التي لم تدم."},{"h":"الحركات القومية في أوربا","t":"شهدت أوربا في القرن 19 حركات توحيد وطنية: توحيد إيطاليا بزعامة كابور وجاريبالدي ومازيني، وتوحيد ألمانيا بزعامة بسمارك \"بالحديد والدم\" الذي توّجها بإمبراطورية سنة 1871، وقيام ثورات 1848 في أوروبا."}],"qs":[{"q":"اندلعت الثورة الفرنسية واستمرت الأحداث في سنة:","a":["1789","1776","1804","1914"],"c":0,"d":"easy","hint":"سنة مشهورة بالباستيل","expl":"اندلعت الثورة الفرنسية سنة 1789 باقتحام الباستيل، وهي الإجابة الصحيحة. سنة 1776 ثورة الولايات المتحدة، و1804 إمبراطورية نابليون، و1914 الحرب العالمية الأولى. نصيحة: احفظ 1789 للباستيل، ويمكنك ربط 1789 مع الدستور الفرنسي الشهير."},{"q":"من أهم نتائج الثورة الفرنسية:","a":["إعلان حقوق الإنسان والمواطن","إرجاع البوربون","خضوع مصر للعثمانيين","قيام جامعة الدول العربية"],"c":0,"d":"easy","hint":"إنجاز يوليو 1789","expl":"أعلن المجلس الوطني بعد الثورة إعلان حقوق الإنسان والمواطن 1789، الذي أرسى مبدأ الحرية والمساواة. عودة البوربون كانت سنة 1815 خلاف ذلك. نصيحة: ربط الثورة بالمبادئ العظمى: الحرية، المساواة، حقوق الإنسان."},{"q":"قاد نابليون الحملة الفرنسية على مصر سنة:","a":["1798","1805","1811","1882"],"c":0,"d":"easy","hint":"قبل إمبراطوريته","expl":"غزا نابليون مصر سنة 1798 واحتل الإسكندرية ثم القاهرة، وأسقط أسطوله في معركة أبي قير. سنة 1805 بداية حكم محمد علي، و1882 الاحتلال الإنجليزي. نصيحة: 1798 = نابليون في مصر، وقبل أن يصبح إمبراطورًا."},{"q":"أُعدم الملك لويس السادس عشر نتيجة الثورة سنة:","a":["1793","1789","1804","1815"],"c":0,"d":"medium","hint":"بعد إعلان الجمهورية","expl":"حوكم لويس السادس عشر وأُعدم بالمقصلة سنة 1793 بعد إعلان الجمهورية 1792، إيذانًا بنهاية الملكية القديمة. فرّق بين 1789 (انطلاقة) و1793 (الإعدام). نصيحة: 92 جمهورية، 93 إعدام الملك، وهي أرقام مرتبطة بزمن واحد."},{"q":"اعتمد مؤتمر فيينا (1815) مبدأ المشروعية الذي يقصد به:","a":["إعادة الحكام الشرعيين إلى عروشهم","تحرير المستعمرات","نشر أفكار الأنوار","إنشاء عصبة الأمم"],"c":1,"d":"medium","hint":"ترميم النظام القديم","expl":"مبدأ المشروعية في مؤتمر فيينا 1815 قوامه إرجاع الأمراء الشرعيين الذين أزالهم نابليون، فعادت البوربون في فرنسا. وبعدها ظهرت ردود الفعل القومية. نصيحة: فيينا 1815 = مشروعية + توازن، وهي أول محاولة لصناعة نظام أوروبي."},{"q":"قامت بتوحيد إيطاليا مع كابور وجاريبالدي خلال القرن 19:","a":["حركة القومية الإيطالية","حركة بسمارك","الثورة الفرنسية","الحركة الصهيونية"],"c":0,"d":"medium","hint":"كابور وغاريبالدي اسمان إيطاليان","expl":"توحيد إيطاليا تم بجهود مازيني وكابور وجاريبالدي حتى اكتمل 1870، بينما بسمارك توحّد ألمانيا. نصيحة: إيطاليا = كابور/غاريبالدي، ألمانيا = بسمارك، اربط الاسم بالدولة."},{"q":"مصطلح السياسة التوسعية عند بسمارك لتوحيد ألمانيا:","a":["الحديد والدم","الثورة السلمية","الانفتاح","المشروعية"],"c":0,"d":"hard","hint":"آلات الحرب والاجتهاد","expl":"شعار بسمارك \"الحديد والدم\" يعني توحيد ألمانيا بالقوة العسكرية لا بالخطابات، فحقق الوحدة سنة 1871. وغيره مفاهيم أوروبية أخرى. نصيحة: \"الحديد والدم\" عبارة حفظها سهلة وتدل على وحدة ألمانيا."}]},{"title":"الدولة العثمانية ومصر (محمد علي وحملاته)","read":[{"h":"العثمانيون ومصر","t":"دخل السلطان سليم الأول مصر سنة 1517 بعد معركة الريدانية (المنصورة) التي قضت على دولة المماليك، فصارت مصر ولاية عثمانية يحكمها والٍ (باشا) ومعه فرقتا الإنكشارية والأجناد."},{"h":"قيام حكم محمد علي (1805)","t":"بعد الحملة الفرنسية، تصارعت الفرق والأطراف في مصر، وبرز محمد علي الجنود ألبانيًا، فاختارته الأمة والياً سنة 1805. ثم قضى على المماليك بمذبحة القلعة سنة 1811، واستقل بحكم مصر عمليًا ونقل عن الدولة العثمانية."},{"h":"إصلاحات محمد علي","t":"نهض بمصر زراعيًا (اهتمام بالقطن وإنشاء القناطر)، وصناعيًا (إنشاء مصانع النسيج والحديد ببولاق)، وتعليميًا (إنشاء المدارس الحديثة والبعثات للغرب والطباعة بمطبعة بولاق)، وبني جيشًا ونظامًا حديثًا قاد ابنه إبراهيم الحملات."},{"h":"حملات محمد علي","t":"وجه حملات للجزيرة العربية للقضاء على الوهابيين في الحجاز 1811، وحملات لحكم السودان 1820، وساهم بأسطوله للباب العالي في حرب اليونان فانكسر في معركة نافارين 1827، ثم هاجم الشام (1831) وهزم العثمانيين، واضطر للقبول بمعاهدة لندن 1840 وفرمان 1841 الذي حصر ولاية مصر في أسرته."},{"h":"أسطول مصر ومعركة نافارين","t":"ارتبط أسطول محمد علي بمصير حملة المورة (اليونان)، فهُزِم في نافارين 1827 بجهود بريطانية وفرنسية وروسية، فتراجع طموحه ورضخ لمطالب الباب العالي مقابل ولاية الشام، ثم تطورت الأحداث إلى حرب الشام 1831."}],"qs":[{"q":"دخل العثمانيون مصر لأول مرة سنة 1517 بعد معركة:","a":["الريدانية","أبي قير","وادي المخازن","التل الكبير"],"c":0,"d":"easy","hint":"معركة قضت على المماليك","expl":"معركة الريدانية سنة 1517 قضى فيها سليم الأول على المماليك وفتح مصر. أبي قير 1798 مع نابليون، والتل الكبير 1882 مع عرابي. نصيحة: 1517 = ريدانية، وتربطها بسليم الأول."},{"q":"تولى محمد علي حكم مصر والأمة تنادي به سنة:","a":["1805","1517","1811","1863"],"c":0,"d":"easy","hint":"بعد الحملة الفرنسية وجدال القيادات","expl":"سنة 1805 انتخبته الأمة والصعاليك واليةً على مصر، بدءًا من حكمه الذي استمر حتى 1848. سنة 1811 مذبحة القلعة، و1863 بداية عصر إسماعيل. نصيحة: 1805 بداية حكم محمد علي، ثم 1811 للقضاء على المماليك."},{"q":"مذبحة القلعة سنة 1811 قضى بها محمد علي على:","a":["المماليك","الوهابيين في الحجاز","ملوك الشام","العثمانيين في الأناضول"],"c":0,"d":"easy","hint":"\"القضاء على الزعامة القديمة\"","expl":"بذبحة القلعة (أو القلعة) 1811 أباد محمد علي رجالات المماليك بدعوة إلى حفل، فتصفى زعامتهم نهائيًا. وحملات الحجاز كانت ضد الوهابيين. نصيحة: مذبحة القلعة 1811 = المماليك، وليست الوحدة الإسلامية قضية."},{"q":"وجه محمد علي حملة السودان بقيادة ابنه في عام:","a":["1820","1798","1805","1811"],"c":0,"d":"medium","hint":"بداية القرن 19 للتمدد جنوبًا","expl":"حملة السودان 1820 قادها إسماعيل كامل باشا ليؤمن الجنوب ويتحكم بالذهب والسودان، وأسسوا الخرطوم. التاريخ الصحيح مطلوب في الاختبارات كثيرًا. نصيحة: اربط توسعات محمد علي: السودان 1820، اليونان 1827 (نافارين)."},{"q":"انكسر أسطول محمد علي في معركة نافارين سنة:","a":["1827","1840","1811","1863"],"c":0,"d":"medium","hint":"بالتآمر الثلاثي لإنقاذ اليونان","expl":"معركة نافارين 1827 حسمت أسطول مصر والعثمانية لصالح الإنجليز والفرنسيين والروس لإنقاذ اليونان، ففقد محمد علي الأسطول وتراجع طموحه. فرّق بينها وبين حرب الشام 1831. نصيحة: نافارين = أسطول، والشام = جيش بري، ربط كل حدث بعنصره."},{"q":"أصدر السلطان العثماني فرمانًا سنة 1841 يقضي بـ:","a":["تأكيد ولاية مصر وراثية في أسرة محمد علي","استقلال مصر الكامل","عودة المماليك للحكم","تمليك قناة السويس"],"c":0,"d":"medium","hint":"تنفيذ معاهدة لندن","expl":"فرمان 1841 قرر: ولاية مصر على مصر والسودان وراثية في أسرة محمد علي مقابل خضوع للسلطان ودفع جزية، وهو ما يُعد بداية لنظام حكم وراثي. استقلال مصر الكامل لم يتحقق. نصيحة: 1841 = مبدأ الوراثة الأسرية؛ معاهدة لندن 1840 = تقليص الأطماع."},{"q":"نهض محمد علي بالتعليم والصناعة في مصر، ومن أبرز الأعمال التعليمية:","a":["إنشاء المدارس الحديثة وإرسال البعثات","إنشاء جامعة الملك فؤاد","تأسيس الأزهر الشريف","افتتاح قناة السويس"],"c":0,"d":"hard","hint":"مطابع بولاق وطلاب لأوربا","expl":"اهتم محمد علي التعليم: إنشاء المدارس الحديثة على النظم الأوروبية وإرسال البعثات العلمية (الأزهر موجود منذ سبقه، والجامعة المصرية تأسست في عهد الأسرة). الصناعة: مصانع بولاق. نصيحة: محمد علي = مدارس + بعثات + مطابع بولاق، وهي أسئلة شائعة."}]},{"title":"مصر والاستعمار والثورة العرابية","read":[{"h":"أزمة ديون إسماعيل والتدخل الأجنبي","t":"في عهد الخديوي إسماعيل تراكمت الديون حتى أُعلن إفلاس الخزينة، فباع حصص مصر في أسهم قناة السويس لبريطانيا سنة 1875، ثم أنشئت اللجنة المالية 1876 والمراقبة الثنائية 1878 (مراقب إنجليزي على الإيراد وفرنسي على المصروفات)."},{"h":"الحركة الوطنية وظهور عرابي","t":"ساءت الأحوال بزيادة الضرائب واكتساب الأجانب الوظائف، فثار الضباط بقيادة أحمد عرابي مطالبين بإلغاء الامتيازات وتكوين مجلس نيابي، فأصدروا بيان 9 سبتمبر 1881 للمطالبة بانتخاب مجلس النواب."},{"h":"مرحلة الثورة والمواجهة","t":"تصاعدت المطالب حتى صار عرابي رئيسًا للحكومة، فردّ البريطانيون بتحريك مصر والأجانب، وأصدرت بريطانيا ومن شاركها مطالب تخلي عرابي عن السلطة، فرفض، ونشبت المعارك حتى سقطت مصر وانقسم الجيش في التل الكبير سنة 1882."},{"h":"الاحتلال الإنجليزي 1882 والنفي","t":"سقطت مصر في يد الإنجليز بعد هزيمة الجيش المصري في معركة التل الكبير 13 سبتمبر 1882، واحتُلت البلاد زهاء 70 عامًا، ونُفي عرابي وزملاؤه إلى سيلان (سريلانكا)."},{"h":"أحكام الاحتلال وإدارة اللوردات","t":"ظل الاستعمار البريطاني يفرض سياسته عبر \"القنصل المتمم\" والقائمين بالإدارة، وكان أعوانهم من الإنجليز في الرقابة، واستمر النظام الريفي في التصفية حتى أفصح عن نفسه بصور أخرى."}],"qs":[{"q":"باع الخديوي إسماعيل أسهم مصر في قناة السويس لبريطانيا عام:","a":["1875","1882","1840","1919"],"c":0,"d":"easy","hint":"أزمة المديونية","expl":"بيعت الأسهم 1875 ماليةً ديسمبر للحصول على دفع ثمن الديون، وهذا بداية التدخل الأجنبي. معاركه مليئة بالدقة الزمنية. نصيحة: 1875 أسهم، 1876 لجنة مالية، 1878 مراقبة ثنائية بترتيب زمني سهل."},{"q":"نظام المراقبة الثنائية (1878) يعني:","a":["إنجليزي على الإيراد وفرنسي على المصروفات","فرنسي على الإيراد وإنجليزي على المصروفات","مراقبة أمريكية عامة","نظام القضاة المختلطين"],"c":0,"d":"medium","hint":"الريع للديون والمدخرون","expl":"المراقبة الثنائية 1878 جعلت للإنجليز مراقبة الإيرادات وللفرنسيين مراقبة المصروفات، سواء كانت الخيارات كذلك بدقة. نصيحة: احفظ \"الإيراد إنجليزية\" و\"المصروفات فرنسية\" لسهولة التذكر."},{"q":"أصدر أحمد عرابي والضباط وطنيو مصر بيانًا مشهورًا في:","a":["9 سبتمبر 1881","13 سبتمبر 1882","26 يوليو 1956","28 فبراير 1922"],"c":0,"d":"medium","hint":"المطالبة بمجلس نيابي","expl":"بيان 9 سبتمبر 1881 طالب فيه عرابي بانتخاب مجلس النواب وإصلاح الجيش، وهو بداية ظهوره قائدًا وطنيًا. ونشأ عنه الأحداث حتى الثورة. نصيحة: واجه الأرقام المساءَلة: 1881 البيان، 1882 التل الكبير."},{"q":"من أهم مطالب الحركة العرابية:","a":["إلغاء الامتيازات الأجنبية وتوظيف المصريين","تغيير اسم الخديوي","تحرير السودان من الاحتلال","تأسيس اتحاد البلاد العربية"],"c":0,"d":"easy","hint":"نصًّا أصيل من بيان 1881","expl":"مطالب عرابي محورية: إلغاء الامتيازات، توظيف المصريين في الوظائف، إنشاء مجلس نيابي، والنهوض بالجيش، أما البدائل فبعيدة عن المطالب المعلنة أو لاحقة. نصيحة: اقرأ مطالب عرابي كُليةً: الجيش والأمة والوطن لا الأفراد."},{"q":"انتهت الثورة العرابية وسيطر البريطانيون بعد معركة:","a":["التل الكبير","أبي قير","حطين","حيوان"],"c":0,"d":"easy","hint":"شرق القناة","expl":"معركة التل الكبير 13 سبتمبر 1882 حسمت مصير الاستعمار: سقط عربي وبُسط البريطانيون سنوات طويلة. والقتال في أبي قير يعني نابليون 1798. نصيحة: التل الكبير 1882 = نهاية عرابي وبداية الاحتلال، مع كونها علامة فاصلة."},{"q":"نُفي أحمد عرابي وزملاؤه بعد هزيمته إلى:","a":["سيلان (سريلانكا)","قبرص","جنوب أفريقيا","سنغافورة"],"c":0,"d":"hard","hint":"جزيرة قصدتهم إنجليزية","expl":"عُوقب عرابي بالنفي إلى سيلان سنة 1882-1901، وعاد إلى مصر عام 1901. والبدائل مستعمرات إنجليزية أخرى سهلة التضليل. نصيحة: جرّب ربط \"عرابي\" و\"سيلان\" في ذهنك لأنهما يتكرران سؤالًا واختبارًا."},{"q":"المقصود بالسياسة التي سارت عليها بريطانيا في مصر بعد 1882:","a":["نظام الاحتلال والإدارة المباشرة بحكم القنصل العام","انتهاء النفوذ","الديمقراطية الكاملة","حكم السودان فقط"],"c":0,"d":"medium","hint":"استعمار تحت قناع الإدارة","expl":"بعد 1882 أدار بريطانيا مصر عبر قنصل عام (كيف الإدامة اللورد كرومر، اللورد اللوردات) ونظام المراقبة الداخلية حتى تناغم الأداء مع مصالحها. لم تكن ديمقراطية ولا انتهاء نفوذ. نصيحة: اقلب الفكرة: الاحتلال 1882-1914 ثم الحماية، وهذا هو الإطار."}]},{"title":"ثورة 1919 وكفاح الأمة","read":[{"h":"مصر والحماية البريطانية","t":"عند اشتعال الحرب العالمية الأولى أعلنت بريطانيا الحماية على مصر سنة 1914، وفصلتها عن الدولة العثمانية، وتولى السلطان حسين كامل ثم فؤاد، وألغيت الرقابة السياسية."},{"h":"الوفد وسعد زغلول","t":"بعد نهاية الحرب هبّ سعد زغلول ورفاقه، فشكلوا وفدًا للمطالبة بالاستقلال الكامل، طلبوا منه التقدم باسم الأمة، وفي 13 نوفمبر 1918 قابل سعد زغلول المندوب للإعلان بطلبات الاستقلال."},{"h":"اندلاع ثورة 1919","t":"رفض البريطانيون مطالب الوفد، فنُفِي سعد زغلول ورفاقه في 8 مارس 1919، فاندلعت الثورة الشعبية من 9 مارس، وانضمت إليها الأزهر والمحامين والطلاب والعمال، وشملت الريف والمدن، وقادت المرأة مظاهراتها."},{"h":"تصريح 28 فبراير 1922 والدستور","t":"ردًا على الثورة أُصدر تصريح 28 فبراير 1922 بإلغاء الحماية وإعلان استقلال مصر \"باستقلال مضيق\"، واعتراف بريطانيا باحتفاظها بمسائل (الجيش، القناة، السودان، الحماية). ثم صدر دستور 1923 القائم على النظام الملكي النيابي."},{"h":"الأحزاب والحياة النيابية","t":"تشكلت بعد ذلك أحزاب: الوفد (زعامة سعد زغلول)، الأحرار الدستوريون (مصطفى باشا) والوطنيون، وترأس سعد زغلول الوزارة أول مرة سنة 1924، وعاشت مصر حياة نيابية متذبذبة بين الملك والحكومة."}],"qs":[{"q":"أعلنت بريطانيا الحماية على مصر في السنة:","a":["1914","1923","1919","1936"],"c":0,"d":"easy","hint":"بداية الحرب العالمية الأولى","expl":"أُعلنت الحماية سنة 1914 مع اندلاع الحرب العظمى، وفُصلت مصر عن الخلافة. واستمرت حتى 1922. ونشأت بيئة الحماية. نصيحة: 1914 = حماية، 1922 = استقلال شكلًاإ، 1923 = دستور."},{"q":"قدم سعد زغلول ورفاقه للمندوب السامي مطالبهم بالاستقلال في:","a":["13 نوفمبر 1918","9 سبتمبر 1881","26 يوليو 1956","28 فبراير 1922"],"c":0,"d":"medium","hint":"بعد الحرب ونهاية هدنة","expl":"في 13 نوفمبر 1918 قابل سعد زغلول المندوب السامي للإعلان بمطالب الأمة بالاستقلال، وظهور الوفد. وُلد في هذا التاريخ تقريبًا. نصيحة: تفرق بين 1918 (الوفد والمطالب) و1919 (الثورة)."},{"q":"الثورة الشعبية العظيمة في مصر اندلعت في يوم:","a":["9 مارس 1919","14 يوليو 1789","13 سبتمبر 1882","30 يونيو 1952"],"c":0,"d":"easy","hint":"بعد نفي سعد بأيام","expl":"بعد نفي سعد 8 مارس 1919، أطلق الشعب ثورته في 9 مارس من كل طبقاته ومحافظاته، فكانت ثورة موحدة. نصيحة: 9 مارس 1919 ثورة في الذاكرة الوطنية، ويُخلّد في يوم 9 مارس."},{"q":"أُصدر التصريح الذي ألغى الحماية وأكد استقلال مصر في:","a":["28 فبراير 1922","6 أكتوبر","23 يوليو 1952","3 أكتوبر 1930"],"c":0,"d":"easy","hint":"نهاية الاحتلال الشكلي","expl":"تصريح 28 فبراير 1922 أعلن إلغاء الحماية وإقامة مصر سلطنةً مستقلة شكلًا مع تحفظات بريطانية. ومن هنا بدأ الاستقلال الناقص. نصيحة: 28 فبراير 1922 = إلغاء الحماية، ويبدو كأنه \"نعمة بشروط\"."},{"q":"صدر دستور 1923 على أساس:","a":["النظام الملكي النيابي","الجمهورية","نظام الشورى","الولايات المتحدة"],"c":0,"d":"medium","hint":"ملك فخري ومجلس نواب","expl":"دستور 1923 أسس نظامًا ملكيًا نيابيًا: ملك له سلطات واسعة (فؤاد الأول) وبرلمان منتخب (مجلس النواب + الشيوخ). فهو توازن بين السلطات. نصيحة: دستور 1923 = عصر الملكية النيابية، ولن يُنصح بالسؤال دراسته."},{"q":"ترأس أول وزارة شعبية في حياتها النيابية سنة:","a":["سعد زغلول 1924","سعد زغلول 1919","نجيب الهلالي","ووزارة 1952"],"c":0,"d":"medium","hint":"زعيم الوفد بعد الثورة","expl":"بعد دستور 1923 قاد سعد زغلول حزب الوفد وترأس أول وزارة شعبية عاتية في يناير 1924. وكان مصطفى كامل سابق في ذلك. نصيحة: اربط الوفد (سعد) بدستور 1923 ودولة 1924."},{"q":"كان شعار الوفد في مرحلته الأولى للاستقلال:","a":["الاستقلال التام غير المشروط","الوحدة العربية","العدوان الثلاثي","الاتحاد الأفريقي"],"c":0,"d":"easy","hint":"صرخة سياسية من سعد","expl":"طالب الوفد وسعد زغلول بالاستقلال الكامل غير المشروط، ورفضوا الحلول الجزئية والتفاوض المعلق، فرُحّلوا كما قادوا الحركة. نصيحة: الاستقلال التام = شعار الوفد في مرحلة أولى ثم بدأ التفاوض فيما بعد."}]},{"title":"الحربان العالميتان وأثرهما على مصر والعالم","read":[{"h":"الحرب العالمية الأولى (1914-1918)","t":"أُشعلت الحرب الأولى باغتيال ولي عهد النمسا في سراييفو 1914، فاصطف العالم ضدًا: الحلفاء (بريطانيا، فرنسا، روسيا... ثم أمريكا 1917) ومعهم قوى المركز (ألمانيا، النمسا، الدولة العثمانية)، وانتهت بهزيمة قوى المركز وإبرام مؤتمر فرساي 1919."},{"h":"أثر الحرب على مصر","t":"قُسّمت مصر تحت الأحكام العرفية وخضعت للإدارة العسكرية البريطانية، وجُندّت الشعوب والفلاحين، وتغيّرت الأوضاع الاقتصادية وتضخم الأسعار، وكانت الحرب سببًا في إعلان الحماية 1914 والثورة 1919."},{"h":"الحرب العالمية الثانية (1939-1945)","t":"اندلعت باجتياح ألمانيا بولندا سنة 1939، فاشترك الحلفاء (بريطانيا، فرنسا، الاتحاد السوفيتي، أمريكا بعد بيرل هاربر 1941) ضد دول المحور (ألمانيا، إيطاليا، اليابان)، وانتهت بسقوط ألمانيا وإلقاء القنبلة الذرية على هيروشيما وناجازاكي 1945."},{"h":"مصر في الحرب الثانية","t":"وقفت مصر إلى جانب الحلفاء ووضعت أراضيها وقواعدها (كما في الأنفاق وعين جالوت في العلمين 1942)، وصارت قناة السويس ممرًا حيويًا، واتخذت إجراءات حربية واقتصادية رغم عدم إعلان الحرب من جانبها."},{"h":"نتائج الحربين على العالم","t":"من نتائج الحرب الأولى: خريطة جديدة للشرق الأوسط (الموصل)، وقيام عصبة الأمم. ومن نتائج الحرب الثانية: قيام الأمم المتحدة 1945، وبروز أمريكا والاتحاد السوفيتي قوتين عظميين، ونهاية الاستعمار القديم."}],"qs":[{"q":"السبب المباشر لاندلاع الحرب العالمية الأولى كان:","a":["اغتيال ولي عهد النمسا في سراييفو","غزو بولندا","أزمة 1929","إلقاء القنبلة الذرية"],"c":0,"d":"easy","hint":"حادثة في البوسنة 1914","expl":"اغتيال فرانز فرديناند ولي عهد النمسا في سراييفو في 28 يونيو 1914 أشعل الحرب بعد شهرين. وغزو بولندا سبب الحرب الثانية. نصيحة: \"سراييفو 1914\" نقطة البداية، و\"بولندا 1939\" بداية الثانية."},{"q":"مدة الحرب العالمية الأولى وطرفاها الخاسر على التوالي:","a":["1914-1918 وهزيمة قوى المركز (ألمانيا)","1939-1945 الحلفاء","1914-1939 لم يخسر أحد","1804-1815 نابليون"],"c":0,"d":"medium","hint":"أربعة أعوام ونهاية في فرساي","expl":"الحرب الأولى 1914-1918 وانتهت بهزيمة قوى المركز وقيام مؤتمر فرساي 1919، أما الثانية بلخص 1939-1945. نصيحة: الأولى = فرساي، الثانية = الأمم المتحدة 1945."},{"q":"أُنشئت عصبة الأمم بعد الحرب الأولى في مؤتمر:","a":["فرساي 1919","فيينا 1815","لندن 1840","كامب ديفيد 1978"],"c":0,"d":"medium","hint":"من نصوص المؤتمر الأكبر","expl":"عصبة الأمم وُلدت من معاهدة فرساي 1919 لتحقيق السلام وتسوية الخلافات، لكنها عجزت... فيينا 1815 مبدأ المشروعية. نصيحة: فرساي = عصبة الأمم، وافصلها عن الأمم المتحدة 1945."},{"q":"بدأت الحرب العالمية الثانية باجتياح ألمانيا لـ:","a":["بولندا","الاتحاد السوفيتي","فرنسا","بريطانيا"],"c":0,"d":"easy","hint":"1 سبتمبر 1939","expl":"غزت ألمانيا بولندا 1 سبتمبر 1939 فدخلت بريطانيا وفرنسا الحرب، لتبدأ العالمية الثانية. احتل السوفيت منها شرقية. نصيحة: \"بولندا\" = بداية الحرب الثانية، وتنفرد بهذا الشرف."},{"q":"من نتائج الحرب العالمية الثانية:","a":["قيام الأمم المتحدة 1945","استمرار عصبة الأمم","نهاية الحركة القومية","سيطرة فرنسا على أوربا"],"c":0,"d":"easy","hint":"بدائلها الفاسدة واضحة","expl":"بعد 1945 أُنشئت الأمم المتحدة مكان عصبة الأمم بهدف حفظ السلم، وظهر القطبان أمريكا والسوفيت. نصيحة: قارن: عصبة 1919 بعد الأولى، أمم متحدة 1945 بعد الثانية."},{"q":"قناة السويس أثناء الحرب العالمية الثانية كانت تستخدم:","a":["ممرًا حيويًا لإمدادات الحلفاء","ساحة معارك بين مصر وألمانيا","محطة بحرية مستقلة","موقعًا للسودان"],"c":0,"d":"medium","hint":"الشحنات الحربية","expl":"استُخدمت قناة السويس وشواطئها ممرًا حيويًا لإمدادات الحلفاء بين البحرين، وهي مضطلع بها في الجبهة العلمين. والبحر الأبيض كان ميدانًا. نصيحة: القناة دائمًا \"ممر حيوي\" في أحداث القرن 20."},{"q":"من أشد آثار الحرب العالمية الثانية على العالم ظهور قوتين عظميين هما:","a":["الولايات المتحدة والاتحاد السوفيتي","بريطانيا وفرنسا","ألمانيا واليابان","الصين والهند"],"c":0,"d":"easy","hint":"بداية الحرب الباردة","expl":"انتهت الحرب الثانية وقد ضعفت أوروبا، وبرزت أمريكا والاتحاد السوفيتي قادتين للعالم في الحرب الباردة، وساد تحالف الشرق والغرب. نصيحة: الحرب الباردة = أمريكا + السوفيت، وهذه نتيجة مباشرة في الباب."}]},{"title":"مصر بعد الاستقلال والتطور السياسي","read":[{"h":"ثورة 23 يوليو 1952","t":"في 23 يوليو 1952 قامت حركة الضباط الأحرار بقيادة جمال عبد الناصر بإسقاط الملكية (العهد الملكي انتهى بفرانك عهده)، ثم أُعلنت الجمهورية سنة 1953، وأجري إصلاح زراعي 1952 يحدد ملكية الأراضي."},{"h":"تأميم قناة السويس 1956","t":"ردًا على المناورات الإمبريالية، أعلن الرئيس جمال عبد الناصر تأميم شركة قناة السويس في 26 يوليو 1956، فاندلع العدوان الثلاثي (بريطانيا، فرنسا، إسرائيل) على مصر، وتم صمود المقاومة، وفشل العدوان."},{"h":"السد العالي والوحدة مع سوريا","t":"بدأ بناء السد العالي في أسوان سنة 1960 بمعونة الاتحاد السوفيتي وانتهى 1971، فيولّد الكهرباء ويحفظ مياه النيل. وفي سنة 1958 قامت الوحدة بين مصر وسوريا (الجمهورية العربية المتحدة) وانتهت 1961."},{"h":"حرب أكتوبر والسلام","t":"في 6 أكتوبر 1973 شنّت مصر العبور والتحرير بقيادة السادات، فاستعادت جزءًا كبيرًا من سيناء، ثم أُعيد فتح القناة 1975، ووقّعت مصر معاهدة السلام (كامب ديفيد/معاهدة السلام المصرية الإسرائيلية) سنة 1979."},{"h":"المراحل اللاحقة","t":"توالى الرؤساء بعد السادات (رحمهم الله) في إدارة الدولة، وتبنت مصر سياسة الانفتاح الاقتصادي والتنموي، وتواجه تحديات اقتصادية وسياسية معاصرة، وتبرز دورها الإقليمي والدولي."}],"qs":[{"q":"حدثت ثورة يوليو 1952 بقيادة:","a":["حركة الضباط الأحرار","حزب الوفد","سعد زغلول","قادة ثورة 1919"],"c":0,"d":"easy","hint":"الحركة العسكرية المالكة لحكم","expl":"الثورة قامت بها حركة الضباط الأحرار بقيادة عبد الناصر وغيرهم من الناصرين عسكريًا، فأعلنت الجمهورية 1953. نصيحة: 1952 = الضباط الأحرار = نهاية الملكية."},{"q":"أُعلنت مصر جمهورية لأول مرة في العام:","a":["1953","1952","1956","1961"],"c":0,"d":"medium","hint":"بعد أقل من عام من الثورة","expl":"في 18 يونيو 1953 أُعلن قيام الجمهورية بإنهاء الملكية (فؤاد الثاني ملكًا صغيرًا) وباتصار جمال عبد الناصر. سنة 1952 فقط للثورة. نصيحة: 52 = ثورة، 53 = جمهورية، 56 = تأميم، ثيّبها بترتيب."},{"q":"أُعلن تأميم شركة قناة السويس في:","a":["26 يوليو 1956","6 أكتوبر 1973","28 فبراير 1922","8 مارس 1919"],"c":0,"d":"easy","hint":"خطاب تاريخي بالإسكندرية","expl":"في 26 يوليو 1956 أعلن جمال عبد الناصر تأميم الشركة في خطاب احتفال الجلاء، وهو سبب العدوان الثلاثي على مصر. نصيحة: 26 يوليو 1956 = تأميم، واربط به \"العدوان الثلاثي\"."},{"q":"قام الاتحاد المصري السوري (الجمهورية العربية المتحدة) سنة:","a":["1958","1952","1945","1981"],"c":0,"d":"medium","hint":"قبل حل 1961","expl":"اتحدت مصر وسوريا سنة 1958 في الجمهورية العربية المتحدة، وانفصلت سوريا عام 1961. وبهذه الوحدة صارَ عهد الناصر. نصيحة: 1958 = وحدة، 1961 = انفصال، وقصة قصيرة في التاريخ."},{"q":"بدأ إنشاء السد العالي في أسوان عام:","a":["1960","1930","1956","1975"],"c":0,"d":"medium","hint":"بمعونة السوفيت","expl":"ابتدأ حفر السد العالي عام 1960 بتمويل وحدات سوفيتية وانتهى 1971، لتوليد الكهرباء وحفظ مياه النيل. ولو أُجيب 1956 لكان بعد تأميم مباشرة لكن المشروع ذاته أُجلّي. نصيحة: ذكر السد العالي: أول إجراءات المشروع 1954/1955، والبناء فعلي 1960."},{"q":"حرب 6 أكتوبر 1973 حققت لمصر:","a":["عبورًا وتحريرًا لسيناء","فوز كامل الموصل","انضمام القواد الإنجليز","إعادة الملكية"],"c":0,"d":"easy","hint":"العبور العظيم للقناة","expl":"في 6 أكتوبر 1973 عبرت القوات المصرية قناة السويس وحطمت خط بارليف واستعادت جزءًا من سيناء، قاهرة إسرائيل مقابل الصمود. وليس جائزة كاملة بدون مفاوضات. نصيحة: \"العبور 73\" نقطة فاصلة في العزة الوطنية."},{"q":"وقعت مصر معاهدة السلام مع إسرائيل (كامب ديفيد) في عهد:","a":["السادات 1979","عبد الناصر 1956","فؤاد الأول 1922","مبارك 2000"],"c":0,"d":"easy","hint":"قاعة كامب ديفيد الأمريكية","expl":"في 1979 وقع الرئيس السادات معاهدة السلام المصرية الإسرائيلية في كامب ديفيد بمشاركة كارتر، مقابل انسحاب إسرائيل من سيناء، فعادت القوة للدبلوماسية. نصيحة: \"السادات = السلام 79\"، وتعويضه نال نوبل."}]}]}]},{"id":"adabigeo","name":"الجغرافيا","icon":"🌍","color":"#26A69A","books":[{"title":"الجغرافيا السياسية والاقتصادية","icon":"🌍","chapters":[{"title":"مقدمة الجغرافيا السياسية ومفاهيمها","read":[{"h":"تعريف الجغرافيا السياسية","t":"الجغرافيا السياسية تدرس العلاقة بين الدولة والعوامل الطبيعية والبشرية التي تحدد قوتها وموقعها، وتبين كيف تؤثر الخصائص المكانية (الموقع، التضاريس، المناخ، السكان، الموارد) على السياسة الخارجية والداخلية. وترتبط بمفهوم الدولة ومكوناتها."},{"h":"الدولة ومقوماتها","t":"تقوم الدولة على ثلاثة مقومات: (1) الإقليم (الأرض ذات الحدود الثابتة)، (2) الشعب (السكان المقيمون الخاضعون للسلطة)، (3) السيادة (السلطة السياسية الكاملة في إدارة شؤونها الداخلية والخارجية). والسلطة السياسية هي السلطة العليا."},{"h":"الحدود السياسية والطبيعية","t":"الحدود الطبيعية تتبع الظاهرات الطبيعية: البحار والأنهار والجبال والصحاري، وتعريفها أسهل وأكثر استقرارًا، بينما الحدود السياسية (الاصطناعية) خطوط وهمية اتفق عليها بالمعاهدات والاتفاقات، وتحل كثير من الخلافات حولها. مثال: الحدود بين مصر وليبيا خطوط وهمية صحراوية."},{"h":"مصادر القوة الوطنية","t":"تتباين قوة الدولة بعناصرها: الموقع الممتاز، المساحة والموارد، وفرة السكان المدربين، التقدم التقني، الوحدة الوطنية، والقيادة الحكيمة. وغياب عنصر قد يُحد من فاعلية الدولة رغم توفر الباقي."}],"qs":[{"q":"تقوم الدولة على ثلاثة مقومات أساسية من أهمها:","a":["الإقليم والشعب والسيادة","الموقع والمناخ والتربة","الصناعة والزراعة والدخل","الموانئ والطرق والسكك"],"c":0,"d":"easy","hint":"ركائز الكيان السياسي","expl":"عناصر الدولة الثلاثة: إقليم وشعب وسيادة، أما الموقع والمناخ والموارد فظروف مساعدة وليست مقومات أساسية. لاحظ أن كل البدائل الأخرى عناصر طبيعية إنتاجية. نصيحة: الدرس الجديد: الإقليم +الشعب+السيادة = الدولة، احفظها كمعادلة."},{"q":"السيادة تعني:","a":["السلطة الكاملة للدولة في شؤونها الداخلية والخارجية","كثرة السكان","قوة الجيش فقط","مجرد رفع العلم"],"c":0,"d":"easy","hint":"أساس الشرعية الدولية","expl":"السيادة تجعل الدولة صاحبة القرار الأعلى على إقليمها وشعبها، داخليًا وخارجيًا، ولا تخضع لإرادة غيرها. الرفع بالعلم أو الجيش أعراض تنفيذية. نصيحة: ميّز بين السيادة (قوة قانونية) والجيش (وسيلة تنفيذ)."},{"q":"الحدود الاصطناعية (السياسية) تختلف عن الطبيعية بأنها:","a":["خطوط وهمية صادرة بالمعاهدات والاتفاقات","تشير إلى الظاهرات الطبيعي فإن البحار والجبال","لا تتغير أبدًا","غير معترف بها"],"c":0,"d":"medium","hint":"وضعتها الدول بيدها","expl":"الحدود السياسية خطوط وهمية اصطناعية تضعها الدول بالاتفاق، بعكس الطبيعية المرتبطة بالمظاهر الجغرافية. وليست ثابتة على الدوام بل قابلة للتعديل. نصيحة: اربط \"اصطناعي\" بالاتفاقات، و\"طبيعي\" بالجغرافيا. هكذا يجيب السؤال عنك."},{"q":"من أمثلة الحدود الطبيعية بين الدول:","a":["الأنهار والبحار والجبال","خط العرض وخط الزوال","الطرق الممهدة","الأسوار العسكرية"],"c":0,"d":"easy","hint":"ظاهرات طبيعية ممتدة","expl":"الحدود الطبيعية تتبع الظواهر الجغرافية من بحار وأنهار وسلاسل جبلية وصحار. وخطوط الطول والعرض تحديدات هندسية في الخرائط فهي اصطناعية. نصيحة: لو راجعت أي حدود نهرية (النيل، الدانوب) فهي طبيعية."},{"q":"من أهم مصادر القوة الوطنية للدولة:","a":["وفرة الموارد والموقع الممتاز والتقنية","عدم وجود شعب","ضعف الموارد","حدود وهمية بدون جيش"],"c":0,"d":"medium","hint":"مركّبات التفوق","expl":"تتحقق القوة بمجموعة عناصر: موقع متميز، موارد وفيرة، سكان متعلمون، تقدم تقني، وحدة وطنية. وأغلب البدائل اشتراطات سلبية تقلل القوة. نصيحة: حلّ سؤال القوة بطرح العوامل الإيجابية المتراكمة لا عامل واحد."},{"q":"مصر تتميز بموقع جغرافي استراتيجي؛ لأنها تطل على قارتين وتسهم بالتحكم بـ:","a":["ممر قناة السويس بين البحرين","سيبيريا","طرق البحار المتجمدة","الصحراء الكبرى وحدها"],"c":0,"d":"easy","hint":"شريان التجارة العالمية","expl":"موقع مصر الاستراتيجي يعود لعبور قناة السويس بين المتوسط والأحمر ورابط آسيا بأفريقيا، فهو ثالث مصادر القوة الوطنية والموقع. نصيحة: كل سؤال \"الموقع الاستراتيجي\" لمصر: القناة وربط القارات."},{"q":"العلاقة بين الجغرافيا السياسية والجغرافيا البشرية أنها:","a":["دراسة التفاعل بين الإنسان والأرض","دراسة المناخ فقط","دراسة الصخور","دراسة الفلك"],"c":0,"d":"medium","hint":"الجولوجيا في صلبها اجتماعية المكانية","expl":"الجغرافيا السياسية تركز على تأثير الإنسان وظروفه الطبيعية في الظواهر السياسية، فهي فرع من الجغرافيا البشرية. وبقية الإجابات فروع طبيعية أخرى منها. نصيحة: حين تتفرع الأسئلة، ركّز على كلمة \"سياسية\" لتختار العلاقة البشرية."}]},{"title":"الجغرافيا الاقتصادية (الزراعة والصناعة والتعدين)","read":[{"h":"الجغرافيا الاقتصادية وفروعها","t":"الجغرافيا الاقتصادية تدرس الظواهر الاقتصادية في توزيعها المكاني: لماذا يقام النشاط في موضع دون آخر، وتشمل الزراعة والصناعة والتعدين والتجارة والنقل. وترتبط بالنشاط البشري والبيئة."},{"h":"الزراعة وأنماطها","t":"الزراعة نمطان: (1) معيشية (اكتفائية) تهدف لسد حاجة الأسرة والمزارع، وتمارس في الأراضي الكثيفة الرطبة، (2) تسويقية (تجارية) تهدف للبيع والتصدير فتنتج المحاصيل النقدية كالقطن وقصب السكر، وتتميز بزراعة واسعة وميكنة."},{"h":"محصول القطن المصري","t":"القطن المصري طويل التيلة عالي الجودة، يزرع في الدلتا ووادي النيل، ويتركز إنتاج المحصول النقدي للتصدير، وله علاقة كبيرة بالري والتربة الطينية وبموسم الأمطار."},{"h":"الصناعة وأنواعها وعواملها","t":"الصناعة نوعان: استخراجية (استخراج المواد الخام من باطن الأرض كالتعدين والنفط) وتحويلية (تحويل المواد الخام إلى منتجات جاهزة). من عوامل قيام الصناعة: المادة الخام، الطاقة، الأيدي العاملة، السوق، النقل، ورأس المال."},{"h":"التعدين والمعادن الرئيسية في مصر","t":"يعد التعدين ركيزة الاقتصاد، من أهم خاماته في مصر: البترول والغاز الطبيعي في الصحراء الغربية (خليج السويس والصحراء الغربية) وسيناء، والحديد في الواحات البحرية وأسوان، والفوسفات في البحر الأحمر، والمنجنيز في سيناء."}],"qs":[{"q":"الزراعة المعيشية في المقام الأول تهدف إلى:","a":["سد حاجة الأسرة من الغذاء","التصدير للخارج","زراعة المحاصيل النقدية فقط","زيادة الدخل القومي"],"c":0,"d":"easy","hint":"من أسمها \"معيشية\"","expl":"الزراعة المعيشية غاية إشباع حاجة المزارع وأسرته دون تجارة، بينما التسويقية تتوجه للبيع والتصدير والربح. نصيحة: \"معيشية = قوت اليوم\"، \"تجارية = بيع وتصدير\"، فرائق المحور."},{"q":"أهم المحاصيل النقدية التصديرية في مصر:","a":["القطن طويل التيلة","الذرة","الأرز","القمح"],"c":0,"d":"medium","hint":"ذو الصيت العالمي","expl":"القطن المصري طويل التيلة من أجود المحاصيل النقدية وقد كان المحصول المحرك للاقتصاد المصري في القرن الماضي. والقمح والأرز والذرة سلع غذائية محلية. نصيحة: المحصول النقدي في مصر = القطن، واحرص على تمييزه عن الغذائي."},{"q":"من عوامل قيام الصناعات التحويلية:","a":["المادة الخام والطاقة والسوق والنقل","نمو الطرق الزراعية","الجفاف","تشتت السكان"],"c":0,"d":"easy","hint":"مركّبات التوطن الصناعي","expl":"التحويلية تحتاج إلى مادة خام وطاقة متاحة وعمالة وسوق ونقل ورأس مال لجذب الاستثمار وإقامة المصانع قرب مصادر الإمداد والاستهلاك. نصيحة: ابدأ أي سؤال عوامل من أولها: المادة الخام أولاً، ثم الطاقة والسوق."},{"q":"الأنشطة الصناعية التي تمارس استخراج المعادن والنفط تسمى:","a":["استخراجية","تحويلية","زراعية","خدمية"],"c":0,"d":"easy","hint":"مباشرة من باطن الأرض","expl":"صناعة استخراجية = الاستخراج والتصدير للمواد الخام (تعدين، نفط)، بينما التحويلية تعالجها إلى سلع جاهزة مثل النسيج. نصيحة: الفرق بين \"تستخرج\" و\"تحوّل\" = المصدر من باطن الأرض مقابل تحويل المنتج."},{"q":"يتركز إنتاج القطن المصري أساسًا في:","a":["الدلتا ووادي النيل","الصحراء الغربية","سيناء","جبال البحر الأحمر"],"c":0,"d":"easy","hint":"أرض الري الخصبة","expl":"القطن يزرع في أراضي الدلتا والوادي حيث التربة الطينية والمياه الوفيرة ومناخ النمو المناسب، وليست الصحاري أرضًا صالحة له. نصيحة: اربط الزراعة المصرية كاملة بالوادي والدلتا لأنهما أنشط مناطق الري."},{"q":"تتمركز حقول البترول الرئيسية في مصر في منطقتين هما:","a":["خليج السويس والصحراء الغربية","شمال سيناء وجنوب أسوان","الفيوم والبحر الأحمر الساحلي","وادي النطرون والمنيا"],"c":0,"d":"medium","hint":"المناطق النفطية المطلة","expl":"البترول المصري يتجمع في خليج السويس والحقول الصحراوية الغربية (أبورديس، خليج السويس، الصحراء الغربية)، مع حقول بسيناء والبحيرة. نصيحة: عند أسئلة التعدين اربط كل معدن بمكانه: بترول = خليج السويس + الصحراء الغربية."},{"q":"من أهم العوامل الطبيعية المؤثرة في النشاط الزراعي:","a":["المناخ والتربة والمياه","السوق المجاورة","الأسعار العالمية","التقنية الحديثة"],"c":0,"d":"medium","hint":"عوامل من الطبيعة","expl":"الزراعة تعتمد أولاً على الظروف الطبيعية: مناخ ملائم، أرض خصبة، ومياه وفيرة، والمتغيرات الاقتصادية (سوق، أسعار) عوامل بشرية ثانوية. نصيحة: نفصل \"طبيعي = مناخ وتربة ومياه\" عن \"بشري = سوق وتقنية\"."}]},{"title":"الموارد المائية والطاقة","read":[{"h":"الموارد المائية في مصر","t":"تعتمد مصر أساسًا على مياه نهر النيل بحصة تقدر بنحو 55.5 مليار متر مكعب سنويًا، وتأتي موارد أخرى من الأمطار في الشمال، والمياه الجوفية في الواحات والصحراء، وتحلية مياه البحر في المناطق الساحلية وفي بناء محطات ببورسعيد."},{"h":"الطاقة ومصادرها","t":"تتنوع مصادر الطاقة: تقليدية كالبترول والغاز والفحم، ومتجددة كالطاقة الشمسية وطاقة الرياح والهيدروكهربائية والحرارة الأرضية والمد والجزر. ومصر غنية بالشمس طوال العام، وبتزامن ذلك مع مساحات للرياح على ساحل البحر الأحمر."},{"h":"طاقة الرياح والشمس في مصر","t":"تستغل الطاقة الشمسية في توليد الكهرباء وتسخين المياه بتكنولوجيات الألواح. ومشروعات طاقة الرياح متمركزة في الزعفرانة على خليج السويس لتوفر سرعة الرياح المناسبة، وتعد منطقة قابلة للتصدير والاستثمار."},{"h":"السد العالي ودوره المائي والطاقي","t":"السد العالي في أسوان يحفظ مياه النيل من التدفق الضائع، ويخزنها لموسم الاحتياج، ويسهم بتوليد الكهرباء من التوربينات الهيدروكهربائية، ويمنع أضرار الفيضانات، وهو أهم المشروعات الإدارية للمياه."},{"h":"ترشيد استخدام المياه","t":"لأزمة المياه الحتمية في مصر، دعت الدولة لرفع كفاءة الري بالتجديد من الري الغمر إلى الري الحديث (الرش والتنقيط)، ومعالجة مياه الصرف وإعادة استخدامها، وترشيد الاستهلاك المنزلي والزراعي."}],"qs":[{"q":"الحصة السنوية لمصر من مياه نهر النيل تقدر بنحو:","a":["55.5 مليار متر مكعب","100 مليون فقط","ملياري متر مكعب","لا توجد حصة"],"c":0,"d":"easy","hint":"رقم شهير في ملف المياه","expl":"اتفاقية 1959 حددت حصة مصر 55.5 مليار متر مكعب من مياه النيل سنويًا هي أساس الزراعات والشرب. نصيحة: احفظ 55.5 (مليار م3) في ملف مياه النيل، فهي معلومة إحصائية ثابتة."},{"q":"الطاقة المتجددة في مصر تعتمد في المقام الأول على:","a":["الشمس لأن مصر غنية بها طول العام","الفحم","النفط","المعادن"],"c":0,"d":"medium","hint":"مناخ مشمس","expl":"مصر ذات إشعاع شمسي عالٍ صحراء واسعة فترتكز مشاريع الطاقة المتجددة على الشمس والرياح. والفحم والنفط مصادر تقليدية ناضبة. نصيحة: المشاريع الحديثة: شمس (بنبان أسوان) + رياح (الزعفرانة)."},{"q":"تتمركز مشروعات طاقة الرياح في مصر عند منطقة:","a":["الزعفرانة على خليج السويس","شمال الصعيد","جنوب الدلتا","وادي النطرون"],"c":0,"d":"medium","hint":"نجحت سرعة الرياح بها","expl":"منطقة الزعفرانة على خليج السويس جاذبة لمزارع الرياح بسبب تدفق الرياح المستمر، وهو مركز مشهور لمحطات الرياح المولدة. نصيحة: الزعفرانة = رياح وقصة في الخريطة، ومحطاتها على البحر الأحمر."},{"q":"يختزن ويتحكم في مياه الفيضان ويولّد الكهرباء في مصر:","a":["السد العالي","قناطر إسنا","سور الحاج","نفق الواحات"],"c":0,"d":"easy","hint":"الأخطر في بنيانه","expl":"السد العالي في أسوان خزان عملاق خزّن مياه النيل (بحيرة ناصر) ويولّد تيارات التوربينات الهيدروكهربائية ويمنع أضرار الفيضان. نصيحة: ربط \"الفيضان + الكهرباء + حفظ المياه\" بالسد العالي مباشرة، فهذا وظيفته."},{"q":"الري الحديث الذي يرشّد المياه ويستخدم في الأراضي الصحراوية:","a":["الري بالتنقيط والرش","الري بالغمر","الري بالغاطس","الري بالأعواد"],"c":0,"d":"easy","hint":"يقتصد في كل قطرة","expl":"الري الجسم من التنقيط والرش يوجه الماء لجذور النبات دون رشح في الأراضي الرملية والصحراوية، ويوفر الماء والوقت. الري بالغمر عكس ذلك. نصيحة: كلمة \"ترشيد\" في سؤال = الري الحديث (تنقيط + رش)."},{"q":"وضع شركة الطاقة بمصر من أهم مصادرها الجديدة:","a":["الغاز الطبيعي المكتشف حديثًا في البحر المتوسط","الفحم المستورد","وقود المخلفات الزراعية فقط","الاستيراد من أوربا"],"c":0,"d":"medium","hint":"حقول بحرية","expl":"اكتشافات الغاز في البحر المتوسط (منطقة ظهر وغيره) جعلت الغاز الطبيعي مصدرًا محوريًا يوفر حاجة الكهرباء وقت الذروة ويدعم التصدير، فتحقق الاستقلال الطاقي. نصيحة: \"غاز\" = البحر المتوسط، وخنجر مصر يتجه إلى الحي الواعد."},{"q":"تقوم إدارة المياه في مصر على مبدأ:","a":["الترشيد ورفع كفاءة الاستخدام وإعادة التدوير","التوسع في زراعة الأسطح والتبذير","تلويث الأنهار","استيراد الأغذية فقط"],"c":0,"d":"medium","hint":"استدامة الموارد","expl":"بسبب ندرة الماء تتبنى مصر مبادئ الترشيد ورفع كفاءة الري وإعادة استخدام المياه والمتجددة، مع تحلية مياه البحر، لمواجهة الفجوة المائية. نصيحة: تعدد الإجابات الإيجابية: رشيد = كفاءة = ممارسة دائمة."}]},{"title":"التكتلات الاقتصادية والعولمة","read":[{"h":"التكامل الاقتصادي والعولمة","t":"التكامل الاقتصادي تعاون بين مجموعة دول لإزالة العوائق التجارية وتوظيف الإمكانات المشتركة، مثل الاتحاد الأوروبي والنافتا. أما العولمة فهي تكامل الأسواق والأنشطة الاقتصادية عالميًا بفضل تكنولوجيا الاتصالات والتحرير التجاري."},{"h":"المؤسسات المالية الدولية","t":"أُنشئت مؤسسات للنظام الاقتصادي العالمي: صندوق النقد الدولي (قروض وترتيبات مالية وإعادة هيكلة)، والبنك الدولي (تمويل مشروعات تنموية)، ومنظمة التجارة العالمية (تنظيم التجارة الدولية وفصل المنازعات). ومقرها في بعضها واشنطن أو جنيف."},{"h":"أبرز التكتلات الاقتصادية","t":"الاتحاد الأوروبي أحد أضخم التكتلات بقيادة اقتصادية موحدة (اليورو) ومقر رئيسي في بروكسل، والنافتا/USMCA تكتل أمريكا الشمالية، والآسيان في جنوب شرق آسيا، والسوق المشتركة لميركوسور، والتعاون الخليجي والعربي (جامعة الدول العربية 1945)."},{"h":"إيجابيات التكتلات والعولمة","t":"التكتلات توسع الأسواق وتخفض تكاليف الإنتاج وتنقل التقنية وتوفر فرص العمل وتبادل الخبرات، والعولمة تسهل انتقال رأس المال والمعرفة والسياحة وعمليات البحث والتطوير."},{"h":"سلبياتها وتحدياتها","t":"عن سلبياتها: تعميق الفجوة بين الغني والفقير، وتهديد الصناعات المحلية، وهروب رأس المال عند الأزمات، وانتشار الأزمات المالية بين الدول المترابطة، لذا تلجأ الدول للحمائية والسياسات الوقائية."}],"qs":[{"q":"منظمة التجارة العالمية تختص بـ:","a":["تنظيم التجارة الدولية وفصل المنازعات","تمويل السدود","حفظ السلام","تسليح الدول"],"c":0,"d":"easy","hint":"دوائر \"WTO\"","expl":"منظمة التجارة العالمية (WTO، الجنيف) تضبط قواعد التجارة الدولية، وتفصل في نزاعات الحمائية والعوائق الجمركية. ونلاحظ ليست تمويلًا ولا حفظ سلام. نصيحة: تكون الأممية: WTO = تجارة، IMF = مال، World Bank = تمويل مشاريع."},{"q":"الاتحاد الأوروبي أقرب إلى تكتل:","a":["اقتصادي بدمج السوق والعملة (اليورو)","عسكري بحت","سياحي","ديني"],"c":0,"d":"medium","hint":"عملة مشتركة","expl":"الاتحاد الأوروبي دمج اقتصادات الدول الأعضاء في سوق موحدة وعملة موحدة (اليورو) وسياسات خارجية مشتركة، وإن توسع إلى تنسيق سياسي. فهو نموذج التكامل الإقليمي الأعمق. نصيحة: تذكر \"اليورو\" كدلالة تكامل أوروبا الاقتصادي."},{"q":"أُنشئت جامعة الدول العربية عام:","a":["1945","1919","1956","1973"],"c":0,"d":"easy","hint":"التاسع من مارس ذلك العام","expl":"تأسست جامعة الدول العربية عام 1945 في القاهرة (ميثاق بموقعه) لتنظيم التعاون بين الدول العربية سياسيًا واقتصاديًا، وتٌعد أعرق التنظيمات الإقليمية العربية. نصيحة: 1945 جامعة عربية، وهي سنة التأسيس الشهيرة في أبحاث المنطقة."},{"q":"من الإيجابيات التي تعود على الدول من التكتلات الاقتصادية:","a":["توسيع الأسواق ونقل التقنية","خروج رؤوس الأموال","إغراق الصناعات المحلية","عزل الدولة"],"c":0,"d":"easy","hint":"تكامل إنتاجي","expl":"تكامل اقتصادي يوسع السوق المشتركة ويخفض التكاليف ويمكن من نقل التقنية وتدريب الخبرات، أما هروب رأس المال وإغراق الصناعات فأضرار العولمة. نصيحة: التفرقة: إيجابيات التكتل = فرص، وسلبيات العولمة = مخاطر."},{"q":"العولمة الاقتصادية تعني:","a":["تكامل الأسواق وانتقال رأس المال عبر الحدود","انغلاق الدولة","الاكتفاء الذاتي الكامل","إلغاء التجارة"],"c":0,"d":"easy","hint":"حرية الحركة العالمية","expl":"العولمة = تكامل الأسواق وحرية تدفق رأس المال والسلع والمعرفة عبر الحدود بفضل النقل والاتصالات ومؤسسات مالية عالمية. نصيحة: ضد العولمة \"الانغلاق\"، لذلك اقترن في التعريف بفكرة الحرية والتدفق."},{"q":"من أبرز سلبيات العولمة على الدول النامية:","a":["اتساع الفجوة بين الغني والفقير","زيادة فرص العمل","نقل التكنولوجيا","تحسين البنية التحتية"],"c":0,"d":"medium","hint":"الاندماج غير المتوازن","expl":"تزيد العولمة الفجوة التنموية بين الدول المتقدمة والنامية لتغلب المنافسة غير المتكافئة، بينما زيادة فرص العمل ونقل التكنولوجيا من إيجابياتها. نصيحة: عندما يذكر \"سلبيات\"، ابحث عن الخيار الظالم اجتماعيًا (الفجوة)."},{"q":"تكتل النافتا يضم دول أمريكا الشمالية (وتحول إلى USMCA)، ومن الدول الأعضاء:","a":["مصر والسودان","الولايات المتحدة وكندا والمكسيك","ألمانيا وفرنسا","اليابان وكوريا"],"c":0,"d":"easy","hint":"أمريكا الشمالية","expl":"نافتا (الآن USMCA) تجمع الولايات المتحدة وكندا والمكسيك في سوق أمريكية شمالية، بينما أوروبا/قارة آسيا خارجها. نصيحة: حرف \"أمريكا الشمالية\" في اسم التكتل يكفي للإجابة: أمريكا وكندا والمكسيك."}]},{"title":"دراسة تطبيقية: مصر ودول العالم","read":[{"h":"الموقع الجغرافي لمصر","t":"تقع مصر في الشمال الشرقي لقارة أفريقيا وتلتحم بآسيا عبر سيناء، وتشرف على البحرين المتوسط والأحمر، وتتصل القارات عبر قناة السويس، وهذا الموقع جعلها معبرًا عالميًا للحضارات والتجارة."},{"h":"السكان وتوزيعهم في مصر","t":"يكتظ نحو 95% من سكان مصر في وادي النيل والدلتا (5% من المساحة)، بينما تعاني الصحاري من الندرة السكانية، وتنمو الأقاليم الحضرية الجديدة (المناطق الصحراوية والمدن الجديدة) لتحقيق توزيع أكثر توازنًا."},{"h":"مقومات الاقتصاد المصري","t":"يقوم الاقتصاد على موارد متنوعة: الزراعة (القطن والمحاصيل)، الصناعة (الغزل والنسيج والبتروكيماويات)، التعدين والنفط، السياحة (الآثار والشواطئ والبيئة)، والنقل والتجارة بمروره الحر على القناة والموانئ."},{"h":"مشروعات التنمية","t":"من أهم مشروعات التنمية: مشروع توشكى (استصلاح زراعي جنوبي)، مشروعات استصلاح مليون فدان، خطة مدن الصحراء الغربية الجديدة، محور تنمية قناة السويس، ومحطات الطاقة الشمسية ببنبان. وتسعى التنمية المستدامة لتلبية حاجات الحاضر دون الإضرار بالأجيال."},{"h":"السياحة في مصر","t":"أنشطة السياحة في مصر متنوعة: ثقافية أثرية (الأهرامات والمعابد)، ترفيهية شاطئية (البحر الأحمر وسيناء)، علاجية (عين سخنة وسيوة)، وبيئية. والسياحة مصدر قومي مهم للدخل وحافز للاستثمار."}],"qs":[{"q":"موقع مصر الجغرافي يميزها أنها تقع في:","a":["ملتقى قارتي أفريقيا وآسيا","وسط أوروبا","شبه الجزيرة العربية","أوقيانوسيا"],"c":0,"d":"easy","hint":"قارتان متجاورتان","expl":"مصر جسر بين أفريقيا وآسيا عبر سيناء، ومشرفة على المتوسط والأحمر، فهي عند مفترق قارات ثلاث تجارياً. نصيحة: أذكر دائمًا \"ملتقى القارات\" في أي سؤال عن موقع مصر."},{"q":"يتركز سكان مصر في مساحة تقدر بنحو:","a":["95% في وادي النيل والدلتا","10% في الصحراء","50% في مدن القناة","النصف في جنوب الصعيد"],"c":0,"d":"medium","hint":"الحياة قرب النهر","expl":"كمية 95% من السعودين يقطنون الوادي والدلتا (نحو 5% فقط من مساحة البلد)، أما الصحاري فسكانها قليلون متفرقون، وهو خلل التوزيع السكاني. نصيحة: الإحصاء 95% في 5% من المساحة، حقيقة محورية في الجغرافيا السكانية."},{"q":"أشهر الصناعات المصرية ذات التاريخ العريق فيها:","a":["صناعة الغزل والنسيج","صناعة السفن الفضائية","صناعة الثلج الصناعي","الطباعة الحجرية"],"c":0,"d":"easy","hint":"قماش القطن","expl":"صناعة الغزل والنسيج من أبرز الصناعات التحويلية على القطن المصري، وواحدة من أكبر دولارات الصادرات سابقًا، وتتوزع في مدن الدلتا والقاهرة. نصيحة: \"قماش\" و\"قطن\" رابطان بالغزل والنسيج، وهي الأعرق في مصر."},{"q":"قناة السويس تربط بين:","a":["البحر المتوسط والبحر الأحمر","المتوسط والبحر الأسود","الأحمر وبحر العرب","الأحمر والبحر الميت"],"c":0,"d":"easy","hint":"بين بحرين بالموقع المصري","expl":"تعبر القناة من بورسعيد على المتوسط حتى السويس على الأحمر، فتختصر الطريق التجارية بين أوروبا وآسيا. نصيحة: المهم حفظ طرفيها: بورسعيد (شمال) والسويس (جنوب)."},{"q":"مشروع توشكى الهادف إلى التنمية والاستصلاح يقع في:","a":["جنوب مصر (جنوب الوادي)","شبه جزيرة سيناء","الدلتا","واحة سيوة الشمالية"],"c":0,"d":"medium","hint":"مياه الخزان النوبي","expl":"مشروع توشكى (بناء الرفع من بحيرة ناصر) لتوفير أراضٍ زراعية من بحيرة السد جنوبًا، وتحويل الصحراء لأرض منتجة. واضح من الشمال. نصيحة: توشكى = بحيرة ناصر = جنوب، واصطحبها نحوك عند حدائق التنمية."},{"q":"توجد محطة بنبان للطاقة الشمسية في محافظة:","a":["أسوان","الإسكندرية","بورسعيد","الجيزة"],"c":0,"d":"medium","hint":"المشمسة على خط الجنوب","expl":"بنبان في أسوان أكبر مزارع شمسية في مصر، لتوفر الإشعاع الشمسي، وتجلت في رؤية 2030 للطاقة المتجددة. نصيحة: \"بنبان\" و\"أسوان\" = شمس، و\"الزعفرانة\" و\"خليج السويس\" = رياح، علاقات ثنائية سهلة."},{"q":"التنمية المستدامة تعني:","a":["تلبية حاجات الحاضر دون الإضرار بحقوق الأجيال القادمة","استنزاف الموارد سريعًا","التنمية الصناعية وحدها","التوسع السكاني غير المنظم"],"c":0,"d":"easy","hint":"توازن الحاضر والمستقبل","expl":"التنمية المستدامة تعني إشباع احتياجات اليوم مع الحفاظ على الموارد الطبيعية والبيئة للأجيال المقبلة، فهي رؤية متوازنة طويلة الأجل. نصيحة: كل تعريف مستدام = \"حاضر دون تفريط في المستقبل\"، وبه تُكمل الجملة."}]}]}]},{"id":"adabifal","name":"الفلسفة والمنطق","icon":"🧠","color":"#7E57C2","books":[{"title":"الفلسفة والمنطق","icon":"🧠","chapters":[{"title":"ماهية الفلسفة ومدارسها","read":[{"h":"معنى الفلسفة","t":"الفلسفة لغةً مركبة من كلمتين يونانيتين: فيليا (حب) وسوفيا (حكمة)، أي حب الحكمة. وهي تفكير حر منظم في أعمق المشكلات الإنسانية: الوجود، المعرفة، القيم، والتفكير في الحياة تأملًا وتعليلًا، وتتفرع إلى الميتافيزيقا (ما وراء الطبيعة) والمنطق والأخلاق والقيم."},{"h":"المدرسة المادية","t":"المادية ترى أن المادة هي أصل الوجود والحقيقة، وأن كل الظواهر (الفيزيائية والعقلية) تفسر بالمادة وحركتها، ومن روادها ديمقريطس في الفلسفة القديمة، وكارل ماركس الذي صاغ فلسفة الجدل المادي (المادية الجدلية والتاريخية)."},{"h":"المدرسة المثالية","t":"نقيض المادية: المثالية ترى أن الفكرة أو الروح هي الحقيقة الفعلية، وأن المادة مجرد مظهر أو ظل، وتتجسد عند أفلاطون (عالم المثل الحقيقي والعالم المحسوس ظل له)، وعند هيجل في المثالية الألمانية."},{"h":"البراجماتية والوجودية والوضعية","t":"البراجماتية (الذرائعية) لجيمس وديوي ترى أن المعيار العملي للنظرية هو نجاحها في تحقيق النفع. والوجودية لسارتر وكيركجارد تجعل الوجود الإنساني والحرية والمسؤولية محور التأمل. والوضعية لأوجست كونت تقصر المعرفة على الظواهر التي تدرك بالملاحظة والتجربة."},{"h":"أهمية الفلسفة وقيمتها","t":"تكمن قيمة الفلسفة في تنمية التفكير الناقد، وضبط المفاهيم، وتكوين رؤية كلية للكون والحياة، والتفكير في القيم والأخلاق والسياسة، والاستفادة منها في حل المشكلات المعاصرة وبحث معنى الحياة."}],"qs":[{"q":"معنى الفلسفة لغةً (كما تدل الكلمة اليونانية):","a":["حب الحكمة","علم النفس","علم الاجتماع","دراسة التاريخ"],"c":0,"d":"easy","hint":"فحسابها في الأصل اليوناني","expl":"الفلسفة من \"فيلو\" (حب) و\"سوفيا\" (حكمة) أي حب الحكمة، أما غيرها فتعريفات لفروع معرفة أخرى. نصيحة: لتحفظ أصل الكلمة، فرّق \"فيلوسوفيا = حب الحكمة\"."},{"q":"مدرسة فلسفية ترى أن المادة هي أصل الوجود والحقيقة:","a":["المادية","المثالية","الوجودية","الوضعية"],"c":0,"d":"easy","hint":"اسمها يدل على عقيدتها","expl":"المادية من المادة: تفسر الوجود كله بالمادة وحركتها، وعكسها المثالية. وسؤال \"المدرسة المادية\" في الاختبار راجع دائمًا للجذر اللغوي. نصيحة: هكذا تنميز بين المادية (مادة) والمثالية (فكرة)."},{"q":"يرى أفلاطون أن الحقيقة الفعلية هي:","a":["عالم المثل","عالم المحسوسات","الواقع المادي","الظواهر الحسية"],"c":1,"d":"medium","hint":"المحسوس عند الفيلسوف ظل للمثل","expl":"أفلاطون مثالي: المثل هي الحقيقة الكاملة، والعالم المحسوس المتغير مجرد صورة وظل لها، ولذات الأصل المثالي ننشد. نصيحة: ارتبط أفلاطون بعالم المثل، فسؤال \"المثل\" يصب في الاتجاه المثالي."},{"q":"من رواد فلسفة الوجودية:","a":["سارتر وكيركجارد","ديمقريطس","ماركس","أوجست كونت"],"c":0,"d":"easy","hint":"أسماء معاصرة existentialistes","expl":"الوجودية ارتبطت بفلسفة الذات والحرية: كيركجارد (مؤسس) وسارتر وهيدجر في أوربا الحديثة، في حين أن البقية رواد مدارس أخرى. نصيحة: كلما ورد \"الوجودية\" اربطه بـ(سارتر + كيركجارد)."},{"q":"المدرسة الوضعية عند أوجست كونت تقصر المعرفة على:","a":["الظواهر التي تُدرك بالملاحظة والتجربة","الحدس النقلي","عالم المثل","الإلهام الديني"],"c":1,"d":"medium","hint":"مبدأ العلم التجريبي","expl":"الوضعية تعتمد على المعرفة العلمية الوضعية المبينة على الملاحظة والتجربة القابلة للتحقق، وتنفي ما لا يخضع للملاحظة. نصيحة: \"الوضعية = علمية تجريبية\"، هكذا تفصلها عن غيرها من الطرق في المعرفة."},{"q":"البراجماتية (الذرائعية) تقول بأن الحقيقة المعيارية للنظرية هو:","a":["نجاحها في تحقيق نتائج عملية نافعة","موافقتها للمثل","مصدرها التاريخي","قبول السلطة لها"],"c":0,"d":"medium","hint":"ما ينفع فهو صحيح","expl":"البراجماتية (جيمس، ديوي) تعتبر النفع وقابلية التطبيق محك الصدق: صحة الفكرة بفائدتها العملية في الحياة. نصيحة: \"البراغما = العمل\"، وكل سؤال يلمح للنفع يجيب البراجماتية."},{"q":"أهمية دراسة الفلسفة في حياتنا تتجلى في:","a":["تنمية التفكير الناقد وربط أفكار الكون","حفظ النصوص التاريخية","حماية الذات دون بحث","مجرد الاستئناس"],"c":0,"d":"easy","hint":"وظيفة عقلية عليا","expl":"الفلسفة تكسب مهارات التفكير الناقد والتحليل المنطقي وبناء رؤية كلية للوجود والقيم، فهي تعلم كيف نفكر لا ماذا نفكر. نصيحة: كل سؤال عن \"فائدة الفلسفة\" اختر ما يخص التفكير والتحليل لا الحفظ."}]},{"title":"المنطق الصوري والقياس","read":[{"h":"المنطق الصوري وتعريفه","t":"المنطق علم يعصم الفكر من الخطأ، وهو أداة استدلال صحيحة لتنظيم أفكارنا في مقدمات ونتائج، ويسمى \"صوريًا\" لأنه لا يهتم بمضمون القضايا بل بصورها وأشكالها الصحيحة، وأسسه أرسطو في مؤلفات \"الأورجانون\"."},{"h":"الحدود وأقسامها","t":"الحد (المصطلح) لفظ دال على معنى. أقسامه: (1) اللفظ المفرد والمركب، (2) الكلية (تطبق على جملة الأفراد: \"إنسان\") والجزئية (\"خالد\")، (3) الكلية الذاتية والكلية العرضية، (4) النوع والجنس والفصل والخاصة والعرض العام. والألفاظ: الكلي والكلي الدال على صفات."},{"h":"القضايا وأنواعها","t":"القضية (الحكم) جملة خبرية يحتمل الصدق أو الكذب، مثل \"النيل أطول الأنهار\". وتنقسم إلى: حملية (موجبة: \"س ص\"، سالبة: \"س ليس ص\")، وشرطية (متصل: \"إن كان أ ب فج د\"، منفصل: \"إما أ وإما ب\"). وبالنظر للكم: كلية وجزئية."},{"h":"العلاقات بين القضايا","t":"بين القضايا علاقات: (1) التناقض بين قضيتين لا تصحان معًا ولا تكذبان معًا (كل س ص/ بعض س ليس ص)، (2) التضاد بين كلية موجبة وكلية سالبة، (3) التداخل بين الجزئية الموجبة والجزئية السالبة، (4) والتقابل في مربع القضايا المعروف."},{"h":"القياس وأشكاله","t":"القياس استدلال غير مباشر يتكون من مقدمتين ونتاج، والمقدمتان تحويان الحد الأوسط (المركزي) الذي يحذف من النتيجة، ومثال: كل إنسان فانٍ (کبری) وسقراط إنسان (صغرى) فسقراط فانٍ. له أربعة أشكال بحسب موقع الحد الأوسط، وله قواعد وشروط للنتيجة."}],"qs":[{"q":"المنطق الصوري يعنى بـ:","a":["صورة العقلية وشكلها لا مضمونها","محتوى الأفكار","علوم الدين","النحو"],"c":0,"d":"easy","hint":"\"صوري\" من الصورة","expl":"المنطق \"صوري\" يهتم بالشكل الصحيح للاستدلال (ترتيب الحدود والقضايا) دون النظر لمحتواها، ومن هنا اسمه. نصيحة: كلمة \"شكل/صورة\" في السؤال تدلك على المنطق الصوري نفسه."},{"q":"القضية جملة خبرية:","a":["يصح فيها الصدق والكذب","تدل على أمر دائم فقط","طلب ناهي","لا تحتمل الحكم"],"c":0,"d":"easy","hint":"أمثلة القضايا صدقًا وكذبًا","expl":"القضية حكم عقلي قابل للتصديق أو التكذيب، كقولنا \"الماء يغلي عند 100°\"، بخلاف الطلب/النداء الذي لا قوة له. نصيحة: قارن: الخبر قابل للتصديق، فالإنشاء لا يقبل ذلك."},{"q":"\"كل الناس فانون\" قضية من حيث الكم والكيف هي:","a":["كلية موجبة","جزئية موجبة","كلية سالبة","جزئية سالبة"],"c":0,"d":"medium","hint":"تطبق على كل الأفراد+ لا نفي","expl":"\"كل\" تجعلها كلية، ولخلوها من النفي تكون موجبة (سواء كان الحكم ثبوتيًا)، أي كلية موجبة، وهي كل س ص. نصيحة: حوّل إلى رمز: \"كل س ص\" = كلية موجبة، ثم أجب بأمان."},{"q":"\"بعض الطلاب مجتهدون\" قضية من حيث الكم والكيف:","a":["جزئية موجبة","كلية موجبة","جزئية سالبة","كلية سالبة"],"c":0,"d":"medium","hint":"يبدأ بـ\"بعض\"","expl":"تبدأ بـ\"بعض\" فتُعدّ جزئية، وهي ثبوتية من غير نفي فتصبح جزئية موجبة (بعض س ص). نصيحة: احفظ \"بعض\" علامة الجزئية، و\"لا/ليس\" علامة السلب."},{"q":"القياس الاستدلال بصحة تكون الصورة هي:","a":["مقدمتان ونتاج","نتاج مستقيم","حد واحد","فروع الرياضيات"],"c":0,"d":"easy","hint":"أشكال ثلاثية","expl":"القياس ثلاثي الأجزاء: مقدمتان + نتيجة، تتبادلان بالحد الأوسط، مثال سقراط الفاني نموذج. ومن ثم فإن الخيارات التي تقتصر على جزء واحد باطلة. نصيحة: صورة القياس = مقدمة + مقدمة = نتيجة، راجعها كمعادلة."},{"q":"من قواعد النتيجة في القياس المنطقي:","a":["ألا تكون أوسع من مقدمتيها","أن تكون أوفق ومعارضة","أن تسبق المقدمات","أن تحذف الحد الأكبر"],"c":0,"d":"hard","hint":"لا يشمل ما لا تغطيه المقدمات","expl":"قاعدة: النتيجة لا تزيد عن المقدمات مدى إخبارها؛ فلا تضم جزأً غير مغطى بالمقدمات، وكلما خالفنا ذلك وقع الخطأ. نصيحة: \"لا نتج أعم مما استدل به\"، ذكّر نفسك بالقاعدة في سؤال النتيجة."},{"q":"الحد الكلي من حيث استيعابه للأفراد يكون:","a":["ينطبق على جميع أفراد جنسه","مختصًا بفرد واحد","لا ينطبق لفظيًا","جزئيًا دائمًا"],"c":0,"d":"medium","hint":"\"إنسان\" ينطبق على كل البشر","expl":"الحد الكلي كلفظ يؤخذ على كل أفراد ما دل عليه، مثل: \"إنسان\" يسري على كل إنسان، أما \"خالد\" فيحدد فردًا واحدًا. نصيحة: السؤال عن الكلي: اسأل نفسك هل ينطبق على كثيرين؟ نعم = كلي."}]},{"title":"المنطق الرمزي الحديث","read":[{"h":"نشأة المنطق الرمزي","t":"المنطق الرمزي يجري أسلوب الرياضيات على الاستدلال: يتفاهم الباحثون بأحرف ورموز (ف، ق، س، ص) تعبر عن القضايا والروابط، وتطور على يد بول (جبر القضايا) وفريجه ورسل، وهو أساس المنطق الجديد والحاسوب وأنظمة الذكاء."},{"h":"جبر القضايا","t":"يرمز في جبر القضايا للقضية البسيطة بحرف لاتيني (ف)، وأدوات الربط: النفي (¬) والجمع \"و\" (∧) والفصل \"أو\" (∨) والاقتضاء الشرطي \"إذا...فإن\" (→) والتكافؤ (↔). والجمل المركبة تُبنى بهذه الروابط."},{"h":"جداول الصدق","t":"يوضح جدول الصدق القيمة المنطقية لقضية مركبة في كل الحالات. قواعد أساسية: (ف∧ق) صادقة إذا صدق الطرفان فقط، (ف∨ق) صادقة إذا صدق أحدهما، والنفي يعكس القيمة، والتضمن (ف→ق) كاذب في حالة واحدة: صدق المقدم وكذب التالي."},{"h":"أنواع الفصل","t":"الفصل نوعان: (1) الفصل الشامخ \"أو\" بمعنى أحدهما أو كلاهما، فيكون صادقًا إذا صدقت إحداهما أو كلتاهما، (2) الفصل الحصري (الصرف) بمعنى \"إما...أو\" إذ لا يجتمع الطرفان: صادق إذا صدق أحدهما فقط."},{"h":"قواعد الاستدلال الرمزي","t":"أهم قواعد الاستدلال: قاعدة نفي النفي، القياس الافتراضي (implication)، وقاعدة الفصل/الجمع، وقاعدة شرطية العكس والنقيض: كل قضية تكافئ عكس نقيضها (من ف→ق نستنتج ¬ق→¬ف). وهذه القواعد أساس البرمجة."}],"qs":[{"q":"يرمز المنطق الرمزي للقضايا البسيطة بحروف، وأداة النفي (¬) تعني:","a":["نفي القضية وعكس صدقها","تأكيد القضية","الربط بين قضيتين","الاستفهام عنها"],"c":0,"d":"easy","hint":"علامة التصحيح","expl":"النفي (¬) يحول صدق القضية إلى كذبها والعكس، فيرمز للقضية السالبة. أما البقية فتوابع ربط أو تأكيد. نصيحة: احفظ الرموز: ¬ نفي، ∧ جمع، ∨ فصل، → توسط."},{"q":"قضية \"ف ∧ ق\" (ف و ق) تكون صادقة فقط عندما:","a":["ف وق صادقتان معًا","إحداهما صادقة","كلاهما كاذبة","نصف قيمة"],"c":0,"d":"easy","hint":"الوصل يشترط الاثنين","expl":"الجمع \"و\" (∧) يتطلب صدق الطرفين معًا؛ فإذا خالف أحدهما كانت الجملة المركبة كاذبة. نصيحة: ربط الوصل = اشتراط الكل، واحفظه في جدول صدق تلقائيًا."},{"q":"قضية \"ف ∨ ق\" (ف أو ق) يكون صدقها عندما:","a":["صدق أحدهما على الأقل","صدقها يتطلب كذبهما معًا","لا علاقة بالأطراف","صدق ق فقط"],"c":0,"d":"easy","hint":"الفصل مرن","expl":"الفصل \"أو\" الشامل يصدق إذا صدق أحدهما أو كلاهما معًا، ولا يكذب إلا إذا كذبا كلاهما، وهذا مبدأ جدول الصدق. نصيحة: \"أو\" = خيارات متاحة، إن فشل الجميع فقط تكذب."},{"q":"العبارة الشرطية \"إذا ف فإن ق\" (ف→ق) تكون كاذبة في الحالة الواحدة التي فيها:","a":["المقدم ف صادق والتالي ق كاذب","المقدم كاذب","التالي صادق","الاثنان صادقان"],"c":0,"d":"medium","hint":"حالة الانتهاك الوحيدة","expl":"الشرطية (ف→ق) تكذب إذا صدق الشرط (ف) وخالف المطلوب (ق)، فما عدا ذلك صادقة مهما كانت القيم. نصيحة: تذكر \"انتهاك الوعد\": الوعد ينكسر إذا تحقق الشرط ولم يتحقق الوعيد."},{"q":"الفصل الحصري \"إما ف أو ق\" يُعد أيضًا صحيحًا إذا:","a":["صدق أحدهما فقط لا كلاهما","صدق كلاهما معًا","كذب كلاهما","كانا متطابقين"],"c":0,"d":"medium","hint":"\"إما أو\" لا تجمع","expl":"في الفصل الحصري ينبغي أن يصدق أحد الطرفين حصرًا ولا يصدقان معًا، بخلاف الفصل الشامل الذي يجمع. نصيحة: انتبه سؤال \"إما أو\" الحصري مقابل \"أو\" الشامل."},{"q":"قاعدة \"عكس النقيض\" في المنطق الرمزي تعني:","a":["من ف→ق نستنتج ¬ق→¬ف","من ف نستنتج ق","من ¬ق نستنتج ف","ق ابقائها كما هي"],"c":0,"d":"hard","hint":"نقلب الأطراف مع النفي","expl":"قاعدة عكس النقيض: الشرطية (ف→ق) تكافئ (¬ق→¬ف)، فإذا صدق العكس تساوي، مثل: إن رسبت لم أذاكر = إن ذاكرت ما رسبت. نصيحة: عند السؤال الرمزي: اقلب وأضف لنفي الطرفين جملة، والنتيجة تعادل."},{"q":"يختلف المنطق الرمزي الحديث عن المنطق الصوري بأنه:","a":["يستعمل الرياضية والرموز في الاستدلال","يعمل باللغة العادية فقط","يهمل العلاقات","يبحث في المعنى وحده"],"c":0,"d":"easy","hint":"أسلوب الجبر","expl":"الرمزي استخدم الرموز الرياضية (جبر القضايا) لتشكيل قواعد دقيقة، بينما الصوري يقرأ بالقضايا اللغوية الاعتيادية. نصيحة: كلمة \"رمزي\" = أحرف ورموز رياضية، وهي ما يميزه عن الصوري."}]},{"title":"النظريات الفلسفية (الوجودية والمادية والمثالية)","read":[{"h":"الوجودية ومبادئها","t":"الوجودية تجعل الوجود الإنساني محور الفلسفة: الإنسان يولد ثم يبني ذاته بأفعاله واختياراته الحرة، وبذلك يسبق الوجودُ الماهية عند سارتر، والإنسان مسؤول عما يفعله ونموذج للأجيال. روادها: كيركجارد (ديني)، هيدجر، سارتر (ملحد)."},{"h":"المادية ومبادئها","t":"المادية ترى المادة أساس كل شيء: الطبيعة مادية متحركة، والفكر مادة متطورة. والمادية الجدلية عند ماركس ترى أن التغيرات الاجتماعية تنبع من الصراع الطبقي وتطور وسائل الإنتاج، والمادية التاريخية تفسر التاريخ بالعلاقات الاقتصادية."},{"h":"المثالية ومبادئها","t":"المثالية تقول إن الحقيقة عقلية أو روحية: عند أفلاطون المثل الكمالية هي الأصل، وعند هيجل الفكرة (الروح المطلقة) هي جوهر الوجود وتتطور جدليًا، والمادة ظل مؤقت للفكرة. القيم والمثل العليا غاية الوجود."},{"h":"النقاش بينها وحدود كل نظرية","t":"المادية تفوت الجوانب الروحية والقيم، والمثالية تفصل الإنسان عن الواقع الملموس، والوجودية قد تغالي في الفردية الحرية. والتقاء النظريات يفيد: كما خرجت الفلسفة على تفاعل فكري نقدي. والدراسة تطلب ربط النظرة بالموقف."},{"h":"وجهات النظر في حرية الإنسان","t":"تتباين النظريات في الإنسان: الوجودية تؤكد الحتمية الأخلاقية للحرية والاختيار، والمادية تحدد الإنسان بالظروف الاقتصادية، والمثالية تجعله مريدًا نحو المثل، فاختلف التقييم ويتستر كل تفسير على أسس مختلفة."}],"qs":[{"q":"مبدأ \"الوجود يسبق الماهية\" من أصول الفلسفة:","a":["الوجودية","المادية","المثالية","الوضعية"],"c":0,"d":"easy","hint":"سارتر رائده","expl":"الوجودية عند سارتر تقول: الإنسان لا يولد بكائن محدد، بل يوجد أولًا ثم يبني ماهيته باختياراته، فهذا الشعار هو بديهية وجودية. نصيحة: كل عبارة \"الوجود يسبق الماهية\" في الاختبار إشارة مباشرة إلى الوجودية."},{"q":"المادية الجدلية ارتبطت بفيلسوف هو:","a":["كارل ماركس","أفلاطون","هيجل","أرسطو"],"c":0,"d":"medium","hint":"فيلسوف الاقتصاد والصراع","expl":"كي ماركس قاد المادية الجدلية والتاريخية التي تفسر التاريخ بالصراع بين الطبقات ووسائل الإنتاج، وهي أساس نظريته الاشتراكية. نصيحة: \"الجَدَل\" + \"ماركس\" ثنائي الالتصاق لا انفكاك لهما."},{"q":"عند أفلاطون العالم الحقيقي الكامل هو:","a":["عالم المثل","عالم الحس المتغير","النفس الأخلاقية","الظواهر العلمية"],"c":0,"d":"easy","hint":"له عالم مجرد","expl":"بالنسبة للمثالية الأفلاطونية المثل هي الحقيقة التي لا تتغير، والعالم المحسوس الذي ندركه هو ظل لها، فسؤال \"أفلاطون\" يقود إلى عالم المثل. نصيحة: أفلاطون = مثل/روح، وهو المفتاح بين المثالية."},{"q":"تتبنى فلسفة الوجودية موقفًا من الإنسان مفاده:","a":["حرية الاختيار والمسؤولية الكاملة","حتمية محضة","الأنانية","العبودية للمصير"],"c":0,"d":"easy","hint":"مؤلفات سارتر الإنسان حر","expl":"الوجودية تؤكد حرية الإنسان في خلق ذاته ومسؤوليته الكاملة عن أفعاله، لأن الإنسان محكوم بأن يكون حرًا، وكل خيار يترتب عليه. نصيحة: الوجودية = حرية + مسؤولية، مهما بدت الصياغة متشابكة."},{"q":"يرى هيجل في فلسفته المثالية أن جوهر الوجود هو:","a":["الفكرة (الروح) التي تتطور جدليًا","المادة","الشعور الحسي","الطبيعة الصماء"],"c":0,"d":"hard","hint":"فيلسوف المثالية الألمانية","expl":"هيجل: الحقيقة كلّها هي الفكرة/الروح، ومسارها الفكري الجدلي (أطروحة-نقيض-تركيب) هو ما يسير به العالم، فالمادة محض مظهر. نصيحة: \"هيجل = مثالية = جدل\"، ثلاثة أبعاد في سطر واحد للحفظ."},{"q":"من نقد الفلسفة المادية أنها:","a":["تقلل من قيمة الجوانب الروحية والقيم","تعظم الأمور الروحية فقط","تنكر الوجود المادي","لا تهتم بالعلم"],"c":0,"d":"medium","hint":"نزعة الإبصار الحسي","expl":"يُنتقد في المادية إهمالها النفس والروح والقيم وردها كلها إلى حركة المادة، بينما تقر بوجود المادة وتصحي العلم. نصيحة: عند سؤال \"نقد\" فكّر بالمقابل المحذوف: مادية=مادة، فتفقد الروح والقيم."},{"q":"أنجع منهاج في تقويم النظريات الفلسفية هو:","a":["النقد المتوازن القائم على أدلة ومناقشة عقلية","قبول إحداهن دون سؤال","التمسك بالهوى","رفض الجميع جميعًا"],"c":0,"d":"easy","hint":"أسلوب منهجي فلسفي","expl":"تقويم النظريات يتجلى بالنقد العقلاني المستند إلى الحجة والبرهان وفحص المقدمات ثم المفاضلة، ماجدًا أفكار النظريات في سياقها. نصيحة: \"النقد الفلسفي\" عند الأسئلة يعني الحجة والمناقشة، لا الرفض القطعي."}]},{"title":"النقد والتقويم المنطقي","read":[{"h":"مفهوم النقد في المنطق","t":"النقد إخضاع الفكرة أو القضية للاختبار العقلي: فحص دلالة الألفاظ، ثم صدق القضايا، ثم صحة الاستدلال، وتمييز الحجة السليمة من الحجة المغالطة، وهو جوهر التفكير الناقد والمهارة الأساسية في تقويم الحجج."},{"h":"مغالطات منطقية شائعة","t":"من المغالطات المشهورة: (1) التعميم المتسرع من أمثلة قليلة، (2) ربط السبب بالنتيجة لدى غير مرجح، (3) مهاجمة الشخص بدل حجته، (4) الاستدلال بالسلطة غير المؤهلة، (5) مغالطة اللا أدري، و(6) الاستدلال الدائري. ودراستها تحصننا من الخطأ."},{"h":"الاستقراء والاستنباط","t":"الاستقراء انتقال من الجزئيات إلى الكلي: نلاحظ حالات كثيرة فنستنتج قانونًا (يصيب الاحتمال). والاستنباط (القياس) انتقال من الكلي إلى الجزئي: من قانون عام إلى حالة خاصة، والنتاج فيه يقيني إذا صدقت المقدمات. والبين في المنهج العلمي: تجمع بينهما."},{"h":"معايير تقويم القضايا","t":"عند تقويم القضية نراعي: (1) وضوح الألفاظ والدلالة، (2) اتساق القضية مع غيرها، (3) المعايير التجريبية أو المنطقية للتحقق، (4) سلامة مصادر المعلومة، (5) الالتزام بالقواعد المنطقية والكمية والكيفية."},{"h":"أنا أنقد بإنصاف","t":"النقد البناء يجمع بين قواعد المنطق والنظر؛ فهو يصحح الاعتلال ويصلح القضايا، بعكس النقد الهدام الذي لا يبحث إلا عن الإسقاط. فالناقد يسأل: ما الدليل؟ وهل السند صحيح؟ فتنصب الفائدة على الحقيقة."}],"qs":[{"q":"النقد في منطق التفكير هو:","a":["فحص القضايا والأدلة بالاختبار العقلي","مجرد الاعتراض","الذم","تغريب الأفكار"],"c":0,"d":"easy","hint":"منهج تحليل الأدلة","expl":"\"النقد\" في المنطق هو الفحص والتقويم: ننظر في صدق المقدمات وسلامة الاستدلال، وليس اعتراضًا سلبيًا ولا ذمًا، فالنقد العلمي إيجابي. نصيحة: في أسئلة النقد، اختر ما يدل على \"فحص + تقويم عقلاني\"."},{"q":"من أشهر المغالطات المنطقية التي تحدث عند التعميم من أمثلة قليلة:","a":["التعميم المتسرع","قياس الأشكال","قاعدة عكس النقيض","جدول الصدق"],"c":0,"d":"medium","hint":"الاستدلال من العينة الضيقة","expl":"التعميم المتسرع مغالطة الاستدلال من عدد صغير من الحالات إلى حكم كلي، مثل: صادفت فقيرًا مخادعًا فقلت كل الفقراء كاذبون. نصيحة: إذا رأيت \"أمثلة قليلة ← حكم عام\" فهل ما المقابل؟ \"تعميم متسرع\"."},{"q":"الاستقراء انتقال الفكر من:","a":["الجزئيات إلى الكليات","الكلي إلى الجزئي","الخاص إلى الخاص","العام إلى الأعم"],"c":0,"d":"easy","hint":"من الأمثلة للقانون","expl":"الاستقراء يبدأ من ملاحظة جزئيات متعددة ليشتق قانونًا كليًا، بعكس الاستنباط الذي يبدأ من الكلي إلى الجزئي. نصيحة: \"ترديد الجزئيات تلد القانون\" = استقراء، وهكذا تقف على الفرق."},{"q":"الاستنباط تعني عملية انتقال من:","a":["الكلي إلى الجزئي","الجزئي إلى الكلي","الأمثلة لقوانين","البيانات للتجارب"],"c":0,"d":"easy","hint":"من القاعدة للحالة","expl":"الاستنباط/القياس ينطلق من قاعدة عامة صادقة ثم يطبقها على حالة خاصة، فهو يقيني بشرط صحة الحدس. نصيحة: كرر \"الاستدلال من القاعدة\" وتذكر النموذج: كل إنسان فانٍ، سقراط إنسان، فسقراط فانٍ."},{"q":"العلاقة بين \"كل س ص\" و\"لا شيء من س ص\" (العام wave by العكس) تسمى:","a":["التضاد"," التناقض","التداخل","الاتصالات"],"c":0,"d":"medium","hint":"لا يصحان معًا وقد يكذبان معًا","expl":"بين كلية موجبة (كل س ص) وكلية سالبة (لا شيء من س ص) علاقة التضاد: يستحيل صدقهما معًا لكن قد يكذبان معًا، بينما التناقض بين كلية موجبة وجزئية سالبة. نصيحة: \"تضاد = إقصاء الكل + احتمال الكذب جميعهم\"، عن بدائل تربك كثيرين."},{"q":"القضيتان \"كل أ ب\" و\"بعض أ ليس ب\" بينهما علاقة:","a":["تناقض","تضاد","تداخل","تكافؤ"],"c":0,"d":"hard","hint":"إحداهما نفي لعموم الأخرى","expl":"(كل أ ب) و(بعض أ ليس ب) لا تجتمعان ولا تكذبان معًا، وهذه هي علاقة التناقض التامة بين القضية الكلية والجزئية النقيضة. أي علاقة فريدة شاملة. نصيحة: لا تخلط: تناقض = نقيض تام للعموم، تضاد = تصادم الكليتين."},{"q":"النقد البناء الهادف يرمي إلى:","a":["تصحيح الاعتلال وتجويد الأفكار","إسقاط الخصم فقط","التشكيك الدائم","تجاهل الأدلة"],"c":0,"d":"easy","hint":"ليس هدامًا","expl":"النقد البناء يسعى لإصلاح المقدمات وتقويم الاستدلال ورفع جودة الفكرة مع الكشف عن الخلل، بخلاف الهدام الذي يقتصر على الاعتراض بلا بديل. نصيحة: \"بناء = إصلاح مع الاقتراح\"، وتتميز عن \"سلبية الاعتراض\"."}]}]}]},{"id":"adabinfs","name":"علم النفس والاجتماع","icon":"👥","color":"#42A5F5","books":[{"title":"علم النفس والاجتماع","icon":"👥","chapters":[{"title":"النمو الإنساني والمراحل","read":[{"h":"النمو ومظاهره","t":"النمو تغير تدريجي مستمر في تركيب الكائن ووظائفه منذ الإخصاب حتى الموت، ويشمل النمو الجسمي والعقلي والانفعالي والاجتماعي واللغوي، ويتأثر بعاملين متداخلين: الوراثة (الاستعدادات التي أُعدت وراثيًا) والبيئة (المؤثرات المحيطة والخبرة)."},{"h":"دوافع النمو وأسسه","t":"النمو تسلسلي ثابت ترتيبًا وسرعة نسبية، ويخضع لظاهرة الفروق الفردية. تظهر الحساسية لنواحي معينة في فترات النمو \"العمر الحرجة\"، وقد يُسرع أو يُبطأ لظروف صحية وتغذية وغيره ووجبات اكتساب المهارات."},{"h":"مراحل النمو","t":"تسلسل مراحل النمو: (1) ما قبل الميلاد، (2) الطفولة المبكرة الممتدة (الرضاعة المبتدئة، ومرحلة المشي والحضانة)، (3) الطفولة المتأخرة (6-12)، (4) المراهقة (12 - حوالي 21)، (5) الرشد والرجولة والكهولة، و(6) الشيخوخة بعد الكبر."},{"h":"خصائص كل مرحلة","t":"الرضاعة: النمو الجسمي الأسرع. الطفولة المبكرة: النمو اللغوي والتقلبات. الطفولة المتأخرة: التكيف والانتماء لمجموعة الرفاق والتطور المنطقي. المراهقة: البحث عن الهوية، التغيرات الهرمونية والنفسية، والتمرد الهادئ أحيانًا. الرشد: الثبات العاطفي والمسؤولية. الشيخوخة: انحدار تدريجي في البعض."},{"h":"الوراثة والبيئة والتفاعل","t":"تؤكد الأبحاث أن النمو نتيجة تفاعل الوراثة (القدرات والإمكانات الجينية) مع البيئة (التربية والمؤثرات)، فلا ينبغي الجزم بأن إحداهما كافية، ومهم القياس أمام: السؤال يقوي كلاهما في صفاتهما وتأثير الاحتياجات."}],"qs":[{"q":"النمو الإنساني يعني:","a":["تغيرًا تدريجيًا مستمرًا في تركيب الكائن ووظائفه","توقف التطور","ثبات الجسم","نمو العضلات فقط"],"c":0,"d":"easy","hint":"التطور الشامل","expl":"النمو تعريفه كلية: تغير تدريجي مستمر في الهيكل والوظائف العقلية والجسمية والنفسية والاجتماعية، ولا يتوقف عند عضو واحد. نصيحة: تعريف النمو في الاختبار يجب أن يجمع \"التدرج والاستمرار والشمول\"."},{"q":"يمر النمو الإنساني بمرحلة تتسم بسرعة النمو الجسمي والفترة الحرجة المعروفة في:","a":["الرضاعة وما قبل الميلاد","الرشد","المراهقة","الشيخوخة"],"c":0,"d":"medium","hint":"أسرع مرحلة جسميًا","expl":"في الرضاعة وما قبل الميلاد يكون النمو الجسمي أسرع معدلاته، فلا تشملها مرحلة الحركية البطيئة، بينما تبدو المراهقة أبرز للنمو النفسي. نصيحة: أسرعة نمو = الرضاعة، وأبرز أزمة نفسية = المراهقة، ثنائي محفوظ."},{"q":"من العوامل التي يخضع لها النمو في توجيه تكوين الفرد:","a":["الوراثة والبيئة معًا في تفاعل","الوراثة وحدها","البيئة وحدها","الصدفة دون غيرها"],"c":0,"d":"easy","hint":"معادلة التنمية","expl":"النمو حصيلة تفاعل الوراثة (الاستعداد) والبيئة (المحيط والخبرة)، لا أحدهما منفردًا بالحسم، وهو مبدأ راسخ في علم النفس. نصيحة: عند سؤال عن عوامل النمو عبر خيارين، اختر \"التفاعل بين الوراثة والبيئة\"."},{"q":"المراهقة (من 12-21 تقريبًا) تتسم عند الذكر بالبحث عن:","a":["الهوية الذاتية والثقة بالنفس","الثبات التام","التوقف الدراسي","انعدام التغيرات"],"c":0,"d":"easy","hint":"محاكمة الأسئلة الوجودية","expl":"مرحلة المراهقة تبرز فيها الحاجة لتكوين الهوية، ورغبة في الاستقلال وتأكيد الذات والتفرد، وهي أبرز خصالها النفسية. نصيحة: كل ما يتصل بـ\"الهوية والاستقلال\" في المراهقة إجابة مقبولة بثقة."},{"q":"أهم ما يميز الطفولة المبكرة (سنة - 6 سنوات تقريبًا):","a":["النمو اللغوي والتطور الحركي السريع","الاستقرار الكامل","النسيان التام","توقف التفاعل الاجتماعي"],"c":0,"d":"medium","hint":"عصر التكلم والمشي","expl":"يتميز المبكر بالتقدم السريع في اللغة والحركة واستكشاف البيئة، وهي أساس تكوين الذكاء اللفظي والاجتماعي. نصيحة: \"مبكر = لغة وحركة واستكشاف\"، ضعها في خانات المراحل كلها."},{"q":"الرشد واستكمال النضج النفسي يتميز بـ:","a":["الثبات الانفعالي وتحمل المسؤولية","الاعتماد التام على الآخرين","الإحباط الدائم","العزل الاجتماعي"],"c":0,"d":"easy","hint":"سمة الخبرة الناضجة","expl":"الرشد يمتاز بالتوازن الانفعالي والاستقلال الاقتصادي والاجتماعي وتحمل المسؤولية الزوجية والمهنية، وهي قمة النضج النفسي. نصيحة: تكون معادلة النضج: رشح = مسؤولية + ثبات عاطفي."},{"q":"إبراز الفروق الفردية في النمو يؤكد أن:","a":["كل إنسان يسير في نموه حسب معدله الخاص","الكل يتساوى تمامًا","الفروق لا توجد","النمو متوقف"],"c":0,"d":"easy","hint":"البصمات الفردية","expl":"الفروق الفردية حقيقة في النمو: يتباين الأفراد سرعةً وترتيبًا وبنيةً نتيجة الوراثة والبيئة، فالنمو لا يوحد الجميع. نصيحة: عند ذكر \"فروق فردية\" اختر دائمًا ما يمنح الفرد إيقاعه الخاص."}]},{"title":"الميول والاتجاهات والدافعية","read":[{"h":"الميول وتعريفها وأنواعها","t":"الميل استعداد مكتسب يتجه صاحبه نحو نشاط معين ويستمتع به ويرغب فيه. أنواع الميول: مهنية (لعمل معين)، رياضية، أدبية/علمية، فنية، اجتماعية، ترفيهية. ويتسع الميل بالتجربة والخبرة والحاجة."},{"h":"الاتجاهات ومكوناتها","t":"الاتجاه استعداد نفسي مكتسب نسبيًا ثابت تجاه موضوع ما، تقويمه إيجابيًا أو سلبيًا. مكوناته ثلاثة: (1) معرفي (معلومات ومعتقدات)، (2) وجداني (مشاعر الحب أو الكره)، (3) سلوكي (نزعة التصرف نحو الموضوع). الاتجاهات تتعلم وتتبدل."},{"h":"الدافعية ومعنى الدافع","t":"الدافعية الحالة الداخلية التي تحرك السلوك نحو هدف، وتُفسر لماذا يبدأ الشخص نشاطًا ويستمر فيه. والدافع حاجة أو شعور يلهب السلوك حتى الإشباع، وأنواع الدوافع: فسيولوجية (جوع، عطش، نوم)، وعقلية/اجتماعية (معرفة، انجاز، انتماء)."},{"h":"دورة السلوك الدافعي","t":"سلسلة السلوك: (1) دافع داخلي، (2) سلوك موجه نحو هدف، (3) تحقيق الهدف وإشباع الحاجة، (4) عودة التوازن. والمقصود بالدافع الخارجي (مكافأة) والداخلي (متعة الفعل نفسه). والتعزيز يزيد سلوك الاحتباس."},{"h":"الميول والاتجاهات والدافعية متكاملة","t":"ترتبط المفاهيم: ميل للأنشطة يقود لاتجاه نحوها، ودافعية تحرك الفعل، وتتفاعل مع الشخصية والبيئة والخبرات. ولكل مؤشر تطبيقات في التوجيه التعليمي والمهني والإرشاد النفسي."}],"qs":[{"q":"الميل في علم النفس هو:","a":["استعداد يجعل الفرد ينشط ويزداد شغفًا نحو عمل معين","سلوك قهري كامل","مرض نفسي","ارتباط ثابت بالخوف"],"c":0,"d":"easy","hint":"شعور التوجه نحو النشاط المحبوب","expl":"الميل استعداد مكتسب يميل فيه الشخص للنشاط ويستمتع ويظهر له تفضيلًا، وينمو بالتجربة. وليست تكرارًا مرضيًا ولا خوفًا. نصيحة: كلمة \"استعداد + تفضيل النشاط\" لكلمة ميل، وتحفظ أصل المعنى."},{"q":"الاتجاه يتكون من ثلاثة مكونات أساسية هي:","a":["معرفي ووجداني وسلوكي","جسمي وعضلي","مادي ومكاني","مشروط وحر"],"c":1,"d":"easy","hint":"مثلث الاتجاه","expl":"مكونات الاتجاه: المعرفة والاعتقاد (معرفي)، الشعور (وجداني)، ونية التصرف (سلوكي)، فالثلاثية هي البنية. نصيحة: اختبار سريع: (ما أعرفه + ما أشعر به + ما أفعله) = الاتجاه."},{"q":"الدافع في علم النفس يُقصد به:","a":["حالة داخلية تحرك السلوك وتوجهه نحو هدف","سلوك عشوائي","رغبة خامدة","فكرة هامة فقط"],"c":0,"d":"easy","hint":"محرك الفعل","expl":"الدافع تنبيه داخلي (حاجة) يولّد حركة تجاه هدف يحقق الإشباع؛ فالدافع محرك السلوك لا السلوك نفسه. نصيحة: \"دافع = محرك داخلي\" و\"سلوك = فعل ظاهر\"، لتنفصل الآمر عن المفعول."},{"q":"من الدوافع الفسيولوجية الأساسية عند الإنسان:","a":["الجوع والعطش والنوم","الرغبة في الفن","غياب الأهداف","التسكع"],"c":0,"d":"easy","hint":"مطالب جسمية","expl":"الدوافع الفسيولوجية طبيعية بيولوجية: جوع وعطش ونوم ورغبة جنسية وحماية، بينما الاهتمام الفني معرفي واجتماعي مكتسب. نصيحة: اقسم: فسيولوجي = أصل الجسم، ومعرفي/اجتماعي = مكتسب نفسي."},{"q":"عند إشباع الحاجة يعود الكائن إلى حالة الزيادة التوازن النفسي؛ هذه الظاهرة تسمى:","a":["الاتزان الدافعي (الإشباع)","الاحباط والاضطراب","الانسحاب","اللاحمول"],"c":0,"d":"medium","hint":"نهاية دورة الدافع","expl":"بعد إشباع الحاجة يكتمل السلوك بالاستتباب (الاتزان الداخلي)، فيهدأ النشاط حتى تجدد الحاجة، وهذا هو منطق دورة الدافع. نصيحة: \"إشباع = اتزان\" و\"حرمان = توتر\"، فاصلهما مثل مضادين."},{"q":"النظام التعليمي ينمي الميول والداخليات للطلاب؛ فالدافعية الخارجية مثل:","a":["المكافأة والدرجات والتهاني","السرور بالفعل نفسه","الابتكار","غور الاهتمام"],"c":0,"d":"medium","hint":"عوامل من الخارج","expl":"الدافعية الخارجية تأتي من مؤثرات البيئة: جوائز ودرجات وتقدير، بينما الداخلية من متعة الإنجاز ذاتها، وكلامنا هنا عن الخارجية. نصيحة: قسم أسئلة \"خارجي/داخلي\": الخارج جوائز، والداخل متعة ذاتية."},{"q":"من أسس قياس الاتجاهات في الدراسات النفسية:","a":["استبيانات وتدرجات ليكرت واختبارات تقييم","قياس الطول فقط","المقابلة غير موثقة","الغش في الاختبار"],"c":0,"d":"medium","hint":"أدوات بحث كمية","expl":"الاتجاهات تقاس بوسائل: الاستبيان بمقياس ليكرت (موافق/محايد/معارض)، البطاقات الإسقاطية، والمواقف التجريبية، وهي أدوات تقويم قابلة للتفعيل العملي. نصيحة: عند سؤال \"أدوات قياس\" اختر الاستبيان/مقياس التقدير لا المقاييس البدنية."}]},{"title":"التعلم ونظرياته","read":[{"h":"مفهوم التعلم","t":"التعلم تغير شبه دائم في السلوك نتيجة الخبرة والتمرين، ولا يشمل التغيرات الفطرية بالنضج أو المؤقتة بالتعب والدواء. وهو عملية بناء مع يشمل المهارات والمعرفة والاتجاهات والقيم."},{"h":"النظريات السلوكية (الكلاسيكية والاجرائية)","t":"الإشراط الكلاسيكي لبافلوف: مثير شرطي يقترن بمثير غير شرطي ليخرج استجابة مكتسبة (سعال الكلب عند الجرس). الإشراط الإجرائي لثورندايك وسكينر: التعلم من نتائج السلوك، وقانون الأثر (النتيجة المبهجة تقوي الارتباط)، والتسليح يزيد السلوك."},{"h":"نظرية المحاولة والخطأ وقانون الأثر","t":"لاحظ ثورندايك في قفصه: يتعلم الحيوان بالتجربة والخطأ ويحتفظ بالاستجابات الناجحة، وقانون الأثر يقضي بأن السلوك الذي يتبعه جزاء إيجابي يقوى تكراره، والذي يتبعه ألم يضعُف. وهذه نظرية تعتمد على التسليح والتقوية."},{"h":"التعلم المعرفي لدى كوهلر","t":"كوهلر في أبحاثه على الشمبانزي أثبت التعلم بالاستبصار (البصيرة): حل المشكلة يستند لفهم العلاقات بين أجزاء الموقف دفعة واحدة دون محاولات خاطئة كثيرة، وهذا تعلم معرفي بعيد عن مجرد التعزيز الميكانيكي."},{"h":"التطبيقات التربوية","t":"تستفيد التربية من النظريات: تنظيم التقوية والمكافآت، مراعاة الفروق، عرض المشكلات للتفكير، والتقييم المستمر، وتدريب المهارات بالتكرار والتدرج مع التغذية الراجعة."}],"qs":[{"q":"يعرف التعلم بأنه:","a":["تغير شبه دائم في السلوك نتيجة الخبرة","تغير فطري بالنضج","استجابة تلقائية","تغير مؤقت بالتعب"],"c":0,"d":"easy","hint":"مكتسب ومستمر","expl":"التعلم تغيير شبه دائم سلوكي ناشئ عن خبرة وتدريب؛ فلا التعال النضج الفطري ولا الإرهاق الزائل يدخلان فيه. نصيحة: التفريق الثلاثي: تعلم (خبرة) × نضج (تكوين) × تعب (مؤقت)."},{"q":"تجربة بافلوف الشهيرة على الكلب أسفرت عن مبدأ:","a":["الإشراط الكلاسيكي","الاستبصار","المحاولة والخطأ","الحتمية"],"c":0,"d":"easy","hint":"جرس = سعال","expl":"بافلوف: اقترن الجرس بالمؤكل فأصدر الكلب استجابة (سعال) للمثير الشرطي، وهو الإشراط الكلاسيكي، أساس النظريات السلوكية. نصيحة: \"جرس + كلب\" = كلاسيكي لبافلوف، أول ما يتبادر في الاختبار."},{"q":"صندوق كوهلر وغير ذلك من تجارب التعلم الإجرائي ارتبطت بـ:","a":["سكينر","بافلوف","فرويد","ماسلو"],"c":0,"d":"medium","hint":"والتسليح الاختياري","expl":"سكينر في صندوقه الإجرائي: التعلم بالتسليح الموقوت (استجابات تزيد بالمكافأة)، برزت نظرية الإشراط الإجرائي وفروقها عن كلاسيكي بافلوف. نصيحة: لخص سؤال \"صندوق سكينر = إجرائي وتسليح\"، منفصل عن \"جرس بافلوف\"."},{"q":"قانون التأثير في التعلم ينص على أن:","a":["السلوك الذي يتبعه جزاء مرضي يقوى","التكرار وحده يكفي","العقاب وحده يعلّم","الغفران يثبت السلوك"],"c":0,"d":"medium","hint":"ربط النتيجة بالسلوك","expl":"لثورندايك: النتائج الممتعة بعد سلوك تقوي رابطه؛ والمزعجة تضعفه، فالتسليح والتقوية هما قوام \"قانون الأثر\". نصيحة: عند سؤال \"قانون الأثر\" اذكر ما يُقوّي الارتباط = المكافأة الإيجابية، والعكس جزاء سلبي."},{"q":"أسهم كوهلر في تفسير التعلم بنظرية:","a":["البصيرة والفهم الكلي للموقف","الإشراط الكلاسيكي","المحاولة والخطأ","الغريزة"],"c":0,"d":"easy","hint":"الشمبانزي والفِهم","expl":"كوهلر (الجشطالت) رأى التعلم فهمًا كاملًا للموقف دفعة واحدة (بصيرة)، وليس تراكم محاولات، وقدّم ذلك على السلوكية الميكانيكية. نصيحة: \"بصيرة/فهم = كوهلر\" و\"أثر/محاولة = ثورندايك\"، فهما قرينان متقابلان."},{"q":"التعزيز السالب في الإشراط الإجرائي يعني:","a":["حذف مثير مزعج لزيادة السلوك","تقديم مثير سار مجاني","فرض عقاب جسدي","وقف التعلم كليًا"],"c":0,"d":"hard","hint":"إزالة للعقوبة لا تقديم","expl":"تعزيز سالب = إزالة المثير المزعج بعد السلوك المرغوب ليزداد تكراره، كإيقاف الضجيج بعد الاجتهاد، لا يختلط مع العقاب. نصيحة: تعزيز سالب = إزالة مؤلم يزيد السلوك؛ وعقاب = تقديم مؤلم يقلّله."},{"q":"من تطبيقات النظريات السلوكية في الفصل:","a":["استخدام المكافآت والتغذية الراجعة المنظمة","حفظ القواعد دون تدريب","تصريف المخاوف","الغش الممنهج"],"c":0,"d":"easy","hint":"مخرجات ملموسة","expl":"التطبيق التربوي للسلوكية: تنظيم التعزيز والمكافآت، تقديم تغذية راجعة فورية، تقسيم المهمة لمهارات، ومراقبة التقدم، تلك أفضل من الحفظ الخام. نصيحة: كل سؤال تطبيقي سلوكي إجابته \"مكافآت وتغذية راجعة وتدريج\"."}]},{"title":"التفاعل الاجتماعي والنظم الاجتماعية","read":[{"h":"التفاعل الاجتماعي","t":"التفاعل الاجتماعي تبادل مؤثرات واتصالات بين فردين أو أكثر ومنها تتشكل العلاقات الاجتماعية، صوره: التعاون، التبادل، التنافس، الصراع، والتكيف، وتفسره الأدوار المتبادلة والاتصال والتوقعات."},{"h":"النظام الاجتماعي","t":"النظام الاجتماعي شبكة منسجمة من الأدوار والقواعد والمعايير التي تنظم سلوك الأفراد في مجال معين، مثل: نظام الأسرة، التعليم، الدين، السياسة، والاقتصاد، وكل نظام يحقق وظيفة أساسية للمجتمع."},{"h":"المراكز والأدوار","t":"المركز الاجتماعي: موقع الفرد في البنية الاجتماعية (طالب، أب، مدير)، والدور الاجتماعي: السلوك المتوقع من شاغل المركز. ومراكز الشخص متعددة ويرافقها أدوار متعددة، وتلك التعددية مصدر غنى وصراعات دورية."},{"h":"الجماعات الاجتماعية","t":"الجماعة مجموعة متحدة يتبادل أعضاؤها التفاعل والانتماء. أنواعها: أولية (علاقات مباشرة ووثيقة كالأسر والأصدقاء)، وثانوية (أهداف رسمية كالعمل والمدرسة)، ورسمية/غير رسمية، ومرجعية يطمح الفرد إلى الانضمام لها."},{"h":"التنشئة الاجتماعية","t":"التنشئة عملية انتقال الثقافة والقيم والمعايير من جيل لآخر عبر مؤسسات: الأسرة (الأولى)، المدرسة، الإعلام، الرفاق، فتشكّل شخصية الفرد وتعدّه لدور اجتماعي ناضج."}],"qs":[{"q":"التفاعل الاجتماعي يعني:","a":["تبادل التأثير والاتصال بين أفراد المجتمع","التوحد العصبي","انفصال التام","الجمود"],"c":0,"d":"easy","hint":"حوار متبادل","expl":"التفاعل الاجتماعي تبادل التأثير والاتصال المتبادل (استجابة وإعادة استجابة)، ومنه تتكون العلاقات وأنماط السلوك. البدائل صفات انعزال وجمود. نصيحة: \"تفاعل = تبادل واتصال\"، وهذه أول سمة تسأل عنها."},{"q":"نظام الأسرة في علم الاجتماع يقوم بوظيفة:","a":["التنشئة الاجتماعية واستمرار النسل","صناعة السلاح","إدارة البنوك","المعارك"],"c":0,"d":"easy","hint":"المؤسسة التربوية الأولى","expl":"الأسرة نظام اجتماعي يضمن التكاثر والتنشئة الأولى ونقل القيم والرعاية الانفعالية، فهو أقدم وأهم النظم. نصيحة: كل سؤال \"وظيفة الأسرة\" إجابته التنشئة والاستمرار الثقافي، فاجعلها قاعدة."},{"q":"المركز الاجتماعي يمثل:","a":["موقع الفرد في البنية الاجتماعية","قدرته العضلية","لون ملابسه","رأيه السياسي فقط"],"c":0,"d":"easy","hint":"تصنيف البنية","expl":"المركز الاجتماعي هو الموقع الذي يشغله الفرد في البناء الاجتماعي (مهنة، دور عائلي...)، والدور هو ما يُتوقع منه. نصيحة: ميّز: المكان = مركز، والتوقعات = دور، وصِغ منهما \"موضع/مسمى\"."},{"q":"الدور الاجتماعي للفرد يعني:","a":["السلوك المتوقع من شاغل مركزه","انتقاله من مكان","شكله الخارجي","رغباته الخفية"],"c":0,"d":"medium","hint":"في مقابل المركز","expl":"الدور يقابل المركز: مركز (اب، مدير) له دور (رعاية، تنظيم)، والسلوك المتوقع وفق المعايير الاجتماعية هو محتوى الدور. نصيحة: ضع في الحسبان: \"مركز = منصب، دور = أداء\"، أي أنهما وجهان لعملة."},{"q":"من أمثلة الجماعات الأولية التي تتميز بعلاقات مباشرة ووثيقة:","a":["الأسرة والأصدقاء","الاتحاد الدولي","وزارة المالية","شركة عالمية"],"c":0,"d":"easy","hint":"روابط عاطفية","expl":"الجماعة الأولية علاقات مباشرة وجها لوجه ووشائج عاطفية، مثل الأسرة ورفاق اللعب، بخلاف الجماعة الثانوية الرسمية الملاحقة. نصيحة: \"أولية = صغيرة + علاقات حميمة\"، و\"ثانوية = مؤسسات رسمية\"."},{"q":"تتم التنشئة الاجتماعية أولًا وبشكل أساس في:","a":["الأسرة","المطاعم","الشارع المجرد","الانترنت وحده"],"c":0,"d":"easy","hint":"الخلية الأولى","expl":"الأسرة المؤسسة الأولى للتنشئة، يليها المدرسة والإعلام والرفاق؛ فالطفل يتعلم منها اللغة والقيم والاتجاهات. نصيحة: ترتيب وسائل التنشئة: أسرة ← مدرسة ← إعلام ← رفاق، وعليك الالتزام بالترتيب."},{"q":"من أنماط التفاعل الاجتماعي الإيجابي بين أفراد المجتمع:","a":["التعاون والتبادل والتكيف","الانعزال والكسل","التدمير","تحطيم العلاقات"],"c":0,"d":"easy","hint":"مقومات الالتحام","expl":"أنماط التفاعل الإيجابية: تعاون، تبادل، تنافس شريف، تكيف، وهي تبني التماسك الاجتماعي بعكس الصراع الهدام. نصيحة: عند السؤال \"أنماط التفاعل\" ابدأ بالأنماط البناءة حتى لو جاء خيارات خبيثة."}]},{"title":"المشكلات الاجتماعية وكيفية مواجهتها","read":[{"h":"المشكلة الاجتماعية","t":"المشكلة الاجتماعية موقف أو نمط حياة يشكل خللًا في التوازن الاجتماعي ويؤثر سلبيًا على فئات كبيرة من المجتمع، ويختلف حددها باختلاف القيم والعصر، وأمثلتها: الفقر، البطالة، الإدمان، البكالوريا والهجرة غير النظامية، العنف والعشوائيات."},{"h":"أسباب المشكلات","t":"أسباب متعددة تتداخل: اقتصادية (فقر وبطالة)، اجتماعية (تفكك أسري، هجرة)، سكانية (ضغط سكاني)، تعليمية (تسرب)، وثقافية (دعايات هدامة)، وإنهاء دوري للدولة والأسرة والمجتمع المدني."},{"h":"الوقاية والعلاج","t":"مواجهة المشكلات خطين: وقاية (تعليم وتوعية وبرامج تنموية وبناء قيم) ومعالجة (تدخل حكومي ومبادرات مجتمعية ودعم للفئات الأكثر تأثرًا)، والاهتمام بالشراكات بين مؤسسات الدولة والمنظمات الأهلية أوضح سبل الفعالية."},{"h":"دور المؤسسات","t":"المؤسسات التعليمية: تنشئة وبناء المهارات. الدينية: غرس الضمير والقيم. الإعلامية: توعية وتوجيه. والدولة: سياسات اقتصادية اجتماعية، بشبكة أمان اجتماعي، وقوانين، وبرامج توظيف وتدريب."},{"h":"الفقر والبطالة نموذجًا","t":"الفقر نتيجة لعدم كفاية الدخل لسد الحاجات الأساسية، والبطالة فجوة بين العمل المتاح وطلب السوق، وكلاهما مغذيان للمشكلات الأخرى، لذا يتطلب حلهما تنمية متوازنة، ومشروعات صغيرة، وتدريب مهني، وتحفيز للاستثمار."}],"qs":[{"q":"المشكلة الاجتماعية تعرف بأنها:","a":["خلل يؤثر سلبًا على فئات كبيرة من المجتمع","ظاهرة فردية عابرة","رأي غير متفق","مسار طبيعي"],"c":0,"d":"easy","hint":"تجاوز شائع مؤثر","expl":"المشكلة الاجتماعية خلل عام يمس شرائح مجتمعية واسعة ويتطلب حلها جهودًا جماعية، وليست قضية فردية خاصة، ولا أمر عابر. نصيحة: كلمة \"واسعة\" و\"مجتمعية\" في تعريف المشكلة، ركّز على الاتساع والعموم."},{"q":"من أهم أسباب المشكلة السكانية التي تواجه المجتمع:","a":["الزيادة السكانية الكبيرة مقارنة بالموارد","كثرة الموجات السياحية","انخفاض معدل المواليد","الطاقة النووية"],"c":0,"d":"easy","hint":"الضغط على الخدمات","expl":"المشكلة السكانية تنبثق من النمو السكاني السريع مقابل الموارد المحدودة، فيضغط على التعليم والصحة والسكن. نصيحة: عندها قل: \"نمو سكاني × موارد = ضغط\". وسؤال السبب يلزم ذكره."},{"q":"البطالة في مصر تمثل مشكلة اقتصادية واجتماعية لأنها:","a":["تفقد الفرد دخله وتضعف مهاراته وفعاليته","تزيد الثقافة","تنعش الاقتصاد","تحد من السكان"],"c":0,"d":"medium","hint":"الأثر المزدوج","expl":"البطالة تحرم الفرد من الدخل وتؤثر على الطاقات والثقة والاندماج الاجتماعي، فترتبط بأضرار نفسية وعائلية واقتصادية، فلا يصلح من كتب عنها ضررًا. نصيحة: \"بطالة = فقر دخل + إحباط\"، وهكذا تُكمل منطق المشكلة."},{"q":"من السياسات الفعالة لمواجهة الفقر والبطالة:","a":["إنشاء مشروعات صغيرة وتدريب مهني وتنمية الموارد","زيادة الرسوم","تجميد المهارات","توقف الدعم الإنتاجي"],"c":0,"d":"easy","hint":"توليد الفرص","expl":"الخط الرشيد: مشروعات صغيرة، تدريب مهني يتوافق مع السوق، قروض ميسرة، وتشجيع الاستثمار؛ فهي تولد فرصًا وتعالج الجذر لا العرض. نصيحة: أي بديل يرفع الإنتاجية والمهارات هو الأقوى في سؤال المواجهة."},{"q":"دور المؤسسات التعليمية في مواجهة المشكلات الاجتماعية يتجلى في:","a":["بناء الوعي والمهارات وتكوين الشخصية السوية","عزل الفرد","نشر النــمطية","حظر الحريات"],"c":0,"d":"easy","hint":"البذرة التكوينية","expl":"التعليم يبني الوعي والتفكير الناقد والاتجاهات الإيجابية والمهارات الإنتاجية، فيؤهل للعمل الصالح ويعالج جذور المشكلات، ولا يصلح أي أدوار قمعية. نصيحة: كل سؤال \"دور المدرسة\" = توعية وبناء قدرات؛ هذه خلاصة التربية."},{"q":"تلعب منظمات المجتمع المدني دورًا في العلاج عندما تقوم بـ:","a":["مبادرات تطوعية ودعم الفئات الأكثر تأثرًا","تحمل الدولة كل الحل","بناء الجدران","استبعاد المتطوعين"],"c":0,"d":"medium","hint":"الشراكة الأهلية","expl":"المجتمع المدني شريك: جمعيات أهلية، متطوعون، مبادرات تنموية، ودعم للأسر الأولى بالرعاية، فتخفف العبء عن الدولة وتوصل الخدمات. نصيحة: \"مجتمع مدني = تطوع وشراكة\"، في أي حل يُسند إليها."},{"q":"استراتيجية الوقاية من المشكلات الاجتماعية تعتمد أولًا على:","a":["التوعية والتنمية وتكوين القيم","الانتظار حتى تتفاقم","الرد بالعنف","تجاهل الأسباب"],"c":0,"d":"easy","hint":"المنع قبل العلاج","expl":"الوقاية تسبق العلاج: توعية، تعليم، تنمية موارد، ترسيخ قيم مجتمعية، وبنيان مؤسسات قوية، فتقل احتمالات نشوء المشكلات أصلًا. نصيحة: فرّق: \"وقاية = منع مبكر\" و\"علاج = تدخل لاحق\". وفي السؤال اختر ما يبدو مبكرًا واستباقيًا."}]}]}]},{"id":"adabien","name":"اللغة الإنجليزية","icon":"🇬🇧","color":"#3949AB","books":[{"title":"English 3rd","icon":"🇬🇧","chapters":[{"title":"Grammar Unit: Relative & Reported Speech","read":[{"h":"Relative Pronouns","t":"Relative pronouns join a clause to a noun: (who) for people as subject, (whom) for people as object, (which) for things and animals, (whose) for possession, and (that) for people or things in defining clauses. Example: \"The man who lives next door is a doctor.\""},{"h":"Defining vs Non-defining Clauses","t":"A defining relative clause gives essential information without commas: \"The book that I bought is interesting\". A non-defining clause adds extra information, is between commas, and cannot use \"that\": \"My brother, who lives in Cairo, is an engineer.\""},{"h":"Reported Speech: Statements","t":"When reporting statements we move the tense back: \"I am tired\" → He said (that) he was tired; \"I will come\" → She said she would come. We also change pronouns and time words: now→then, today→that day, yesterday→the day before, tomorrow→the next day, this→that."},{"h":"Reported Questions and Commands","t":"To report yes/no questions we use if/whether: \"Are you busy?\" → She asked me if I was busy. Wh-questions keep the question word: \"Where do you live?\" → She asked me where I lived. Commands: \"Clean the room!\" → He told me to clean the room (asked, told + to + base)."},{"h":"Reporting Verbs and Order","t":"Common reporting verbs: said (that), told (someone), asked, warned, advised, promised, offered. Notice: \"He said me\" is wrong; we say \"He told me\" or \"He said to me\". The tense of the reporting verb usually stays in the past."}],"qs":[{"q":"The man ___ car was stolen called the police.","a":["whose","which","who","whom"],"c":0,"d":"easy","hint":"علاقة ملكية بين الرجل والسيارة","expl":"We need a possessive relative pronoun, and \"whose\" shows possession: \"the man whose car\". \"which\" is for things, \"who\" is for people as subject, and \"whom\" is for people as object. Exam tip: choose \"whose\" whenever a noun follows the gap."},{"q":"My brother, ___ lives in Cairo, is a famous doctor.","a":["who","which","whose","that"],"c":2,"d":"medium","hint":"جملة غير محددة بين فاصلتين","expl":"The clause is non-defining (extra information between commas), so we use \"who\" for people, not \"that\". \"which\" is for things, and \"whose\" shows possession. Exam tip: commas = non-defining; and never use \"that\" after commas."},{"q":"She said, \"I am tired.\" → She said that she ___.","a":["was tired","is tired","am tired","has tired"],"c":0,"d":"easy","hint":"الإزاحة الزمنية للخلف","expl":"In reported speech we move the tense back: present \"am\" becomes past \"was\", and pronouns change (\"I\" to \"she\"). Present simple would keep direct speech, so it is wrong here. Exam tip: backshift = present → past in reported statements."},{"q":"\"Where do you live?\" → She asked me where I ___.","a":["lived","live","living","to live"],"c":0,"d":"medium","hint":"سؤال غير مباشر يزحزح الماضي","expl":"In an indirect wh-question we keep the question word, change word order to subject+verb, and backshift the tense: \"do you live\" → \"I lived\". Exam tip: reported questions are not questions in form, so no \"do/does\" and no question mark sense."},{"q":"\"I saw him yesterday,\" she said. → She said she saw him ___.","a":["the day before","yesterday","tomorrow","next day"],"c":0,"d":"medium","hint":"تغيير ظروف الزمن","expl":"In reported speech \"yesterday\" changes to \"the day before\" (or \"the previous day\") because the time reference moves back. Exam tip: memorise the time changes: now→then, today→that day, tomorrow→the next day."},{"q":"He told me ___ my homework carefully.","a":["to do","do","doing","did"],"c":0,"d":"easy","hint":"الأمر غير المباشر = to + فعل","expl":"Commands are reported with \"told/asked + object + to + base verb\": \"Do your homework\" → \"He told me to do my homework.\" Exam tip: after told/asked/advised/warned + object, always use the infinitive with \"to\"."}]},{"title":"Grammar Unit: Conditionals & Passive","read":[{"h":"Zero and First Conditionals","t":"Zero conditional (general truths): If + present, present → \"If you heat water to 100°C, it boils.\" First conditional (real future): If + present, will + base → \"If it rains, we will cancel the match.\""},{"h":"Second Conditional","t":"Second conditional (unreal present/future): If + past simple, would + base → \"If I had a million dollars, I would travel around the world.\" We use \"were\" for all subjects in formal English: \"If I were you...\""},{"h":"Third Conditional","t":"Third conditional (unreal past): If + past perfect, would have + past participle → \"If I had studied, I would have passed the exam.\" It expresses regret or a different outcome in the past."},{"h":"Passive Voice: Forms","t":"Passive = be + past participle. The tense of \"be\" changes: present (is/are) → \"English is spoken in Egypt\"; past (was/were) → \"The novel was written in 1957\"; present perfect (has/have been) → \"The bridge has been built.\" We mention the agent with \"by\"."},{"h":"Active and Passive Patterns","t":"Active: Subject + verb + object → \"Shakespeare wrote Hamlet.\" Passive: Object + verb (be + pp) + by + subject → \"Hamlet was written by Shakespeare.\" The object of the active becomes the subject of the passive."}],"qs":[{"q":"If it ___, we will cancel the match.","a":["rains","rained","will rain","would rain"],"c":0,"d":"easy","hint":"الشرطي الأول","expl":"First conditional: If + present simple → will + base verb, so \"rains\" is correct. \"will rain\" never appears in the if-clause. Exam tip: \"if + present → will\" = real future, keep the pattern fixed."},{"q":"If I ___ a million dollars, I would travel the world.","a":["had","have","will have","would have"],"c":0,"d":"medium","hint":"الشرطي الثاني غير الواقعي","expl":"Second conditional uses past simple in the if-clause with would + base: \"If I had...\". Exam tip: for unreal present, always choose the past simple after \"if\" with \"would\"."},{"q":"If I had studied harder, I ___ the exam.","a":["would have passed","would pass","pass","will pass"],"c":0,"d":"easy","hint":"الشرطي الثالث عن الماضي","expl":"Third conditional: If + had + pp → would have + pp, so \"would have passed\" is correct. Exam tip: \"had studied\" signals the past unreal, so the main clause must use \"would have + pp\"."},{"q":"\"The novel ___ by Naguib Mahfouz in 1957.\"","a":["was written","wrote","writes","is writing"],"c":0,"d":"medium","hint":"مبني للمجهول في الماضي","expl":"The sentence is passive (the book did not write itself), past tense: was + written. \"wrote\" would need a subject like \"he\", and present forms clash with \"1957\". Exam tip: find the agent and the past time, then choose \"was/were + pp\"."},{"q":"English ___ in Egypt as a first foreign language.","a":["is spoken","speaks","spoken","speaking"],"c":0,"d":"easy","hint":"حقيقة عامة مبنية للمجهول","expl":"A general present fact expressed in the passive needs \"is + past participle\": is spoken. Exam tip: a passive present sentence with a thing/idea as subject always takes \"am/is/are + pp\"."},{"q":"If you heat water to 100°C, it ___.","a":["boils","will boil","would boil","boiled"],"c":0,"d":"medium","hint":"صفر شرطي = حقيقة علمية","expl":"Zero conditional for scientific truths: If + present → present, so \"boils\". Present simple expresses an always-true fact. Exam tip: general scientific facts = zero conditional, both halves present."}]},{"title":"Vocabulary Sets","read":[{"h":"Words About People and Society","t":"Key words: citizen (a person who belongs to a country), society, community, education, employment, poverty, crime. Example: \"The government provides free education for all citizens.\""},{"h":"Words About Energy and Environment","t":"Key words: renewable (can be replaced), sustainable, pollution, recycle, solar energy, wind power, resources. Example: \"Renewable energy sources like the sun do not run out.\""},{"h":"Learning and Technology","t":"Key words: e-learning (learning by technology), skills, knowledge, modern, improve, achieve. Example: \"E-learning lets students study anywhere with an internet connection.\""},{"h":"Travel and Phrasal Verbs","t":"Useful phrasal verbs: show up (arrive), give up (stop), look after (take care), turn off/on, and travel words: tourist, journey, destination, ticket. Example: \"He showed up late for the meeting.\""},{"h":"Money and Work","t":"Key words: income (money you earn), salary, salary vs wage, job, applicant, career, earn, achieve. Example: \"Her monthly income is enough to cover all family needs.\""}],"qs":[{"q":"\"... The government provides free education for all ___.\"","a":["citizens","tours","customers","tourists"],"c":0,"d":"easy","hint":"سكان الدولة","expl":"\"Citizens\" are the people who legally belong to a country, and they are the ones a government serves with free education. Customers buy things, and tourists visit for leisure. Exam tip: government + people of the state = citizens."},{"q":"Renewable ___ like solar energy never run out.","a":["sources","products","exports","packages"],"c":0,"d":"medium","hint":"مصادر الطاقة المتجددة","expl":"\"Sources\" collocates with energy: renewable energy sources. Products/exports/packages do not fit the scientific meaning here. Exam tip: remember the collocation \"energy source(s)\"."},{"q":"He ___ up late for the meeting yesterday.","a":["showed","made","gave","took"],"c":0,"d":"medium","hint":"ظهور فجائي","expl":"The phrasal verb \"show up\" means to arrive or appear, and it takes \"showed\" as its past form. The other verbs form different phrasal verbs with different meanings. Exam tip: memorise common phrasal verbs: show up, give up, look after, turn down."},{"q":"Learning through modern technology is called ___.","a":["e-learning","booking","traffic","mining"],"c":0,"d":"easy","hint":"تعلم إلكتروني","expl":"\"E-learning\" means learning using electronic devices and the internet. The other options are unrelated fields like booking (حجز) or traffic (مرور). Exam tip: the prefix \"e-\" = electronic, as in e-mail and e-learning."},{"q":"A person who travels for pleasure is called a ___.","a":["tourist","tenant","nurse","lawyer"],"c":0,"d":"easy","hint":"زائر للاستجمام","expl":"A \"tourist\" travels for pleasure and sightseeing. A tenant rents a place, a nurse cares for patients, and a lawyer works in law. Exam tip: connect tourist with tourism and travel."},{"q":"The amount of money you earn from your work is your ___.","a":["income","achievement","danger","knowledge"],"c":0,"d":"hard","hint":"الدخل الشهري","expl":"\"Income\" is the money received for work or investments. Achievement, danger, and knowledge are not amounts of money. Exam tip: income = money you earn; salary = fixed monthly pay."}]}]}]},{"id":"adabifr","name":"اللغة الفرنسية (الأجنبية الثانية)","icon":"🇫🇷","color":"#5C6BC0","books":[{"title":"Français 3e (Synthèse)","icon":"🇫🇷","chapters":[{"title":"Grammaire: Articles et Temps","read":[{"h":"Les articles définis et indéfinis","t":"Articles définis: le (masculin), la (féminin), les (pluriel), l (devant voyelle). Indéfinis: un (masc.), une (fém.), des (pluriel). Exemples: le soleil, la table, les livres, un café, une école, des amis."},{"h":"Les articles partitifs","t":"Pour les quantités non comptées (du, de la, de l, des): \"Je bois du lait\", \"Elle mange de la soupe\", \"On prend de l eau\". Après un négatif, on utilise \"de/d ...\" : \"Je ne bois pas de café.\""},{"h":"Le présent de vouloir\\u2019s verbes en -er","t":"Le présent: parler → je parle, tu parles, il/elle parle, nous parlons, vous parlez, ils/elles parlent. Avec être et avoir: je suis, tu es, il est, nous sommes ; j ai, tu as, il a, nous avons."},{"h":"Le passe composé","t":"Passé composé = auxiliaire (être/avoir) + participe passé. Avec la plupart des verbes on utilise avoir: \"J ai mangé une pomme.\" Avec les verbes de mouvement (aller, venir, arriver, partir) on utilise être: \"Il est arrivé hier.\""},{"h":"Le futur proche","t":"Futur proche = aller (présent) + infinitif: \"Je vais étudier demain\", \"Nous allons voyager en été.\" Il exprime une action très proche dans le futur."}],"qs":[{"q":"Complète: \"___ soleil est très chaud aujourd'hui.\"","a":["Le","La","Un","Des"],"c":0,"d":"easy","hint":"أداة تعريف للمفرد المذكر \"ال\"","expl":"\"Soleil\" is a singular masculine noun, so the definite article is \"le\". \"La\" is feminine, \"un\" is indefinite, and \"des\" is plural. Exam tip: remember sun in French is masculine: le soleil."},{"q":"Complète: \"Elle ___ une pomme.\" (manger, présent)","a":["mange","manges","mangeons","mangent"],"c":0,"d":"medium","hint":"ضمير الغائب مع الفعل في -er","expl":"With the subject \"elle\" (third person singular), the -er verb takes the ending \"-e\": elle mange. \"-es\" is for tu, \"-ons\" for nous, \"-ent\" for ils/elles. Exam tip: for il/elle, drop the -er and add -e."},{"q":"Au passé composé: \"Il ___ arrivé à huit heures.\"","a":["est","a","sont","ai"],"c":0,"d":"medium","hint":"فعل حركة نستخدم être","expl":"\"Arriver\" is a movement verb and takes \"être\" as its auxiliary: \"il est arrivé.\" \"A\" would be used with avoir verbs like manger. Exam tip: movement verbs (venir, aller, arriver, partir, rester) take être."},{"q":"Futur proche: \"Je ___ étudier demain.\"","a":["vais","suis","ai","va"],"c":0,"d":"medium","hint":"aller مضارع + مصدر","expl":"Futur proche = aller in the present + infinitive: je vais étudier. \"suis\" would be for être, and \"ai\" is avoir. Exam tip: to express a near future, always use \"aller au présent + infinitif\"."},{"q":"Complète: \"Je bois ___ lait chaque matin.\"","a":["du","de la","des","les"],"c":0,"d":"hard","hint":"كمية غير معدودة من \"lait\"","expl":"With uncountable masculine nouns we use the partitive \"du\": du lait. \"de la\" is for feminine, \"des\" for plural, \"les\" definite plural. Exam tip: partitive du/de la/de l/des = some for uncountable items."},{"q":"L'article indéfini correct pour \"école\" est:","a":["une","un","le","du"],"c":0,"d":"medium","hint":"\"école\" اسم مؤنث يبدأ بحرف علة","expl":"\"École\" is feminine, so the indefinite article is \"une\". Even though it starts with a vowel and takes l with the definite article, \"une école\" is correct. Exam tip: check gender first: école is feminine."}]},{"title":"Vocabulaire et Communication","read":[{"h":"Les salutations et les formules","t":"Pour saluer: Bonjour, Bonsoir, Salut. Pour demander des nouvelles: Comment ça va? Comment allez-vous? Pour remercier: Merci, Merci beaucoup. Réponse: De rien. Pour dire au revoir: Au revoir, À bientôt, À demain."},{"h":"Les nombres et l'heure","t":"Les nombres: un, deux, trois... (vingt, trente, quarante, cinquante, soixante, cent, mille). Pour demander l'heure: \"Quelle heure est-il?\" Réponse: \"Il est deux heures.\""},{"h":"Le vocabulaire de la maison et de la classe","t":"La maison: la chambre, la cuisine, le salon, la salle de bains, la fenêtre, la porte. En classe: un livre, un stylo, un cahier, un tableau, un professeur, un élève. Exemple: \"Le livre est sur la table.\""},{"h":"Les mots interrogatifs","t":"Les adverbes interrogatifs: où (أين), quand (متى), comment (كيف), pourquoi (لماذا), combien (كم). Exemples: \"Où habites-tu? Quand partez-vous? Comment vas-tu?\""},{"h":"La communication au quotidien","t":"Pour acheter: \"Combien ça coûte?\" Pour commander: \"Je voudrais... s'il vous plaît.\" Pour s'excuser: \"Excusez-moi, Pardon.\" Pour exprimer l'accord: \"D'accord, Bien sûr.\" Ces phrases vous aident à communiquer au quotidien."}],"qs":[{"q":"Pour saluer le matin en français, on dit:","a":["Bonjour","Merci","Au revoir","Pardon"],"c":0,"d":"easy","hint":"تحية الصباح","expl":"\"Bonjour\" is the morning/hello greeting. \"Merci\" means thanks, \"Au revoir\" goodbye, and \"Pardon\" excuse me. Exam tip: greetings first phrases: Bonjour (صباحاً), Bonsoir (مساءً)."},{"q":"\"Merci\" en arabe signifie:","a":["شكرًا","عفوًا","من فضلك","مرحبًا"],"c":0,"d":"easy","hint":"كلمة الشكر","expl":"\"Merci\" means \"thank you\" (شكراً). \"De rien\" means you are welcome, \"s'il vous plaît\" means please, and \"Bonjour\" means hello. Exam tip: when translating daily words, remember the polite trio: Merci, De rien, S'il vous plaît."},{"q":"\"Comment ça va?\" signifie:","a":["كيف حالك؟","ما اسمك؟","كم الساعة؟","أين تعيش؟"],"c":0,"d":"easy","hint":"سؤال عن الحال","expl":"\"Comment ça va?\" literally means \"how is it going?\" = how are you. Asking the name is \"Comment tu t'appelles?\", the time is \"Quelle heure est-il?\". Exam tip: \"Comment\" = كيف; always link the question word to its meaning."},{"q":"Le mot \"une maison\" signifie:","a":["منزل","كتاب","طعام","طريق"],"c":0,"d":"easy","hint":"مكان السكن","expl":"\"Une maison\" = a house (منزل). \"Un livre\" is a book, \"une route\" is a road, and food is \"la nourriture\". Exam tip: when learning nouns, memorise the gender with the word (une maison, un livre)."},{"q":"Le mot \"un livre\" signifie en arabe:","a":["كتاب","قلم","باب","إنترنت"],"c":0,"d":"easy","hint":"مادة القراءة","expl":"\"Un livre\" = a book (كتاب). A pen is \"un stylo\", a door is \"une porte\", and the internet is \"l'internet\". Exam tip: classroom objects are favourite exam items: livre, stylo, cahier, tableau."},{"q":"Pour demander le temps (متى), on utilise:","a":["Quand","Où","Combien","Pourquoi"],"c":0,"d":"medium","hint":"أداة استفهام للزمان","expl":"\"Quand\" means when (متى), used for time questions. \"Où\" = where (أين), \"Combien\" = how much/quantities (كم), \"Pourquoi\" = why (لماذا). Exam tip: make a small grid of question words and match the meanings."}]},{"title":"Civilisation et Culture","read":[{"h":"La France et ses symboles","t":"La France est un pays d'Europe de l'Ouest, sa capitale est Paris. Ses symboles: le drapeau bleu-blanc-rouge, la devise \"Liberté, Égalité, Fraternité\", et la Marseillaise (l'hymne national)."},{"h":"Les monuments célèbres de Paris","t":"Les monuments de Paris: la Tour Eiffel, le musée du Louvre (المتحف الأشهر), l'Arc de Triomphe, Notre-Dame, et Montmartre avec la basilique du Sacré-Cœur. Le Louvre abrite la Joconde."},{"h":"Les pays francophones","t":"Le français est parlé dans de nombreux pays: la France, le Canada (Québec), la Suisse, la Belgique, et plusieurs pays africains comme la Tunisie, le Maroc, l'Algérie, le Sénégal, et aussi la Côte d'Ivoire."},{"h":"L'Égypte et la France","t":"L'Égypte et la France entretiennent des relations historiques et culturelles fortes: le français est enseigné en Égypte, l'Institut français du Caire organise des activités culturelles, et les deux pays collaborent dans les domaines de l'archéologie et la culture."},{"h":"La monnaie et la langue","t":"La monnaie de la France est l'euro (€). Plus de 300 millions de personnes parlent le français dans le monde, et c'est une langue officielle dans des organisations internationales comme l'ONU et l'UNESCO."}],"qs":[{"q":"La capitale de la France est:","a":["Paris","Londres","Madrid","Berlin"],"c":0,"d":"easy","hint":"مدينة النور","expl":"La capitale de la France est Paris (مدينة النور), ville des monuments célèbres. Londres est la capitale du Royaume-Uni, Madrid celle de l'Espagne, Berlin celle de l'Allemagne. Exam tip: cities and countries must be matched exactly."},{"q":"La Tour Eiffel se trouve dans la ville de:","a":["Paris","Nice","Lyon","Marseille"],"c":0,"d":"easy","hint":"ملكة المعالم","expl":"La Tour Eiffel est le symbole de Paris, construite sur le Champ-de-Mars. Les autres villes françaises n'ont pas cette tour comme symbole. Exam tip: Eiffel = Paris, the classic cultural question."},{"q":"Le musée célèbre de Paris qui abrite la Joconde est:","a":["le Louvre","le stade de France","Orly","le Père-Lachaise"],"c":0,"d":"medium","hint":"متحف الموناليزا","expl":"Le musée du Louvre est le musée le plus célèbre de Paris et abrite des chefs-d'œuvre comme la Joconde (الموناليزا). De Père-Lachaise est un cimetière célèbre. Exam tip: \"la Joconde\" + \"musée\" = le Louvre."},{"q":"Quelle est la monnaie utilisée en France?","a":["l'euro","le dollar","la livre","le dinar"],"c":0,"d":"easy","hint":"عملة الاتحاد الأوروبي","expl":"La France utilise l'euro (€) comme monnaie. Le dollar est américain, la livre anglaise, et le dinar utilisé dans plusieurs pays arabes. Exam tip: euro = currency of France and most of the European Union."},{"q":"Quel pays africain est francophone?","a":["la Tunisie","l'Indonésie","le Brésil","la Chine"],"c":0,"d":"medium","hint":"دولة شمال إفريقيا تنطق الفرنسية","expl":"La Tunisie (avec le Maroc et l'Algérie) est un pays francophone d'Afrique du Nord, où le français est très utilisé. L'Indonésie, le Brésil et la Chine ne sont pas francophones. Exam tip: francophone countries: Maghreb countries, Sénégal, Canada (Québec), Suisse, Belgique."},{"q":"\"Merci beaucoup\" signifie:","a":["شكرًا جزيلًا","مع السلامة","صباح الخير","من فضلك"],"c":0,"d":"easy","hint":"شكر مؤكد","expl":"\"Merci beaucoup\" = thank you very much (شكرًا جزيلاً). \"Au revoir\" means goodbye, \"Bonjour\" good morning, \"s'il vous plaît\" please. Exam tip: \"beaucoup\" means a lot/much, so it strengthens many expressions."}]}]}]}]},{"id":"ilmu","name":"الشعبة العلمية — عام","icon":"🔬","color":"#3949AB","grad":"linear-gradient(135deg,#3949AB,#26C6DA)","desc":"الأحياء، الفيزياء، الكيمياء، الرياضيات — درب عقلك بالمادة العلمية للثانوية العامة","subjects":[{"id":"biology","name":"الأحياء","icon":"🧬","color":"#4CAF50","books":[{"title":"الوراثة والتطور","icon":"🧬","chapters":[{"title":"الأوسمة والصفات","read":[{"h":"مندل وأساسيات الوراثة","t":"استطاع الراهب النمساوي جريجور مندل بين عامي 1856 و1863 صياغة القوانين الأساسية للوراثة من خلال تجاربه الدقيقة على نبات البازلاء. اختار البازلاء لأنها سريعة التكاثر، ذات صفات متقابلة واضحة مثل الطول والقصر، ويمكن التحكم في تلقيحها بدقة. جاءت أهم نتائج تجاربه فيما يعرف بقانونا الوراثة: قانون انعزال الصفات وقانون التوزيع الحر للعوامل الوراثية."},{"h":"الصفة السائدة والصفة المتنحية","t":"الصفة السائدة Dominant هي التي تظهر على الفرد مهما كان نوع الجين الآخر المرافق لها، ويرمز لها بحرف كبير مثل (T). أما الصفة المتنحية Recessive فلا تظهر إلا إذا اجتمع جيناها معاً مثل (tt)، فإذا وجد معها جين سائد خُبئت وراثياً وإن لم تختبئ مظهرياً. مثال: نبات طويس القامة (T) سائد على القصير (t)، فالنبات Tt يظهر طويلاً مع أنه لا يزال يحمل جين القصر."},{"h":"النمط الجيني والنمط الظاهري","t":"النمط الجيني Genotype هو التركيب الكامل للعوامل الوراثية للفرد مثل TT أو Tt أو tt. أما النمط الظاهري Phenotype فهو ما يظهر على الفرد من صفات مثل الطول أو القصر أو لون الأزهار. الفرد الذي يحمل عاملين متشابهين كـ TT أو tt يسمى نقي التكوين (متماثل الجينات Homozygous)، والذي يحمل عاملين مختلفين كـ Tt يسمى هجيناً (متغاير الجينات Heterozygous)."},{"h":"مربع بانيت","t":"مربع بانيت أداة رائعة للتنبؤ باحتمالات وراثة الصفات. تكتب الجاميتات الخاصة بأحد الأبوين على المحور الأفقي، وجاميتات الأب الآخر على المحور الرأسي، ثم نملأ المربعات بدمج الجاميتات. مثال: تزاوج Tt × Tt يعطي احتمال الفتح: TT، Tt، Tt، tt أي بنسبة مظهرية 3 طول : 1 قصر، ونسبة جينية 1:2:1. هذا هو جوهر قانون انعزال الصفات، إذ تنفصل العوامل في الجاميتات ثم تتباعد في الأبناء وفق الاحتمالات."},{"h":"قانون التوزيع الحر (الاستقلال)","t":"ينص على أن جينات الصفات المختلفة (مثل شكل البذور ولونها) تتوزع مستقلة في الجاميتات، لأنها تقع على كروموسومات مختلفة أو بعيدة بعضها عن بعض. لذلك عند دراسة صفتين معاً تتنبأ النتائج كأن كل صفة تتصرف مستقلة، وتجمع النسب الناتجة بضرب الاحتمالات."},{"h":"خلاصة الدرس","t":"الوراثة المندلية تقوم على: صفة سائدة وأخرى متنحية، نمط جيني (تركيبة الجينات) ونمط ظاهري (الظهور)، فحص (متحين) أو هجين (متغاير)، وقانوني انعزال الصفات والتوزيع الحر. مربع بانيت يجعل التنبؤ سهلاً: وزع الجاميتات ثم اجمع الاحتمالات."}],"qs":[{"q":"من هو العالم الذي وضع القوانين الأساسية للوراثة من تجاربه على نبات البازلاء؟","a":["جريجور مندل","تشارلز داروين","جيمس واطسون","لويس باستور"],"c":0,"d":"easy","hint":"راهب نمساوي وتجاربه على البازلاء","expl":"الإجابة الصحيحة: مندل، فهو واضع قوانين الوراثة الأولى من تجارب البازلاء في أواخر القرن التاسع عشر. داروين مشهور بنظرية التطور وليس الوراثة، وواطسون اشترك في اكتشاف شكل الحمض النووي، وباستور رائد علم الأحياء الدقيقة. نصيحة: تذكّر أن مندل = البازلاء، مثل (عيد ميلاد المناهج الوراثية)."},{"q":"في تزاوج نبات بازلاء طويل القامة نقي (TT) مع نبات قصير القامة (tt)، تكون جميع نباتات الجيل الأول:…","a":["طويلة القامة","قصيرة القامة","متوسطة القامة","نصفها طويل ونصفها قصير"],"c":0,"d":"easy","hint":"الجاميتات T و t فقط، والجين السائد يغطي المتنحي","expl":"الصواب: طويلة القامة، لأن كل فرد من الجيل الأول يحمل التركيب Tt والجين السائد (T) يغطي أثر الجين المتنحي فيظهر الطول دائماً. لن يظهر القصر إلا في الجيل الثاني عند اجتماع t مع t. نصيحة: عندما يكون أحد الأبوين نقي الثاث فهما لا يعطيان إلا جاميتاً واحداً (T أو t)، أي أن كل الأبناء من نوع واحد."},{"q":"النمط الجيني لفرد يحمل جينين متشابهين تماماً مثل (TT) أو (tt) يسمى:…","a":["نقي التكوين (متماثل الجينات)","متغاير الجينات (هجين)","ناتجاً من التهجين","مورثاً منقوصاً"],"c":0,"d":"medium","hint":"متماثل = Homozygous، متغاير = Heterozygous","expl":"الصواب: نقي التكوين أو متماثل الجينات، وهو يعني تشابه العاملين المحملين للصفة. أما متغاير الجينات فهو اتحاد جينين مختلفين كـ Tt. الخيارات الأخرى تخالف المصطلحات المعتمدة في علم الوراثة. نصيحة: كلمة \"نقيّاً\" في السؤال تعني متماثلاً دائماً، و\"هجيناً\" تعني متغايراً."},{"q":"باستخدام مربع بانيت في تزاوج فردين هجينين (Tt × Tt) تظهر النسبة المظهرية في الجيل الثاني:…","a":["3 طول : 1 قصر","1 طول : 3 قصر","1:2:1","كلها طويلة"],"c":0,"d":"medium","hint":"احتمل الجينات: TT, Tt, Tt, tt","expl":"الصواب: 3 طول : 1 قصر. تنتج الجاميتات T وt من كل أب، وعند دمجها نحصل على TT وTt وTt وtt، فالتركيبات الثلاث الأولى تحمل الجين السائد فتظهر طويلة، وأخيراً tt يظهر قصيراً. نسبة 1:2:1 هي النسبة الجينية لا المظهرية. نصيحة: المظهرية = عدّ المظاهر، الجينية = عدّ التراكيب."},{"q":"الصفة المتنحية هي الصفة التي:…","a":["لا تظهر إلا عندما يجتمع جيناها معاً","تظهر دائماً حتى مع غيره من الجينات","تنتقل من الأم فقط","لا يمكن دراستها وراثياً"],"c":0,"d":"easy","hint":"تختبئ مظهرياً بوجود الجين السائد","expl":"الصواب: لا تظهر إلا عند اجتماع جينيها معا كـ (tt)، لأن وجود جين سائد واحد (Tt) يخفيها. المتنحية لا تنتقل من جنس دون آخر، وحالات ظهورها في الأبناء القصيرة دليل على أنها كانت كامنة عند الآباء. نصيحة: تذكّر أن الصفة المتنحية \"خجولة\" لا تظهر إلا إذا التقى شقيقها."},{"q":"عدد الجاميتات المختلفة التي يمكن أن يكوّنها فرد تركيبه الوراثي (AaBb) هو:…","a":["4 جاميتات","2 جاميتين","8 جاميتات","16 جاميتاً"],"c":0,"d":"hard","hint":"العدد = 2 مرفوعة لعدد أزواج الصفات غير المتماثلة","expl":"الصواب: 4 جاميتات (AB وAb وaB وab). كل صفة غير متماثلة تعطي عاملين، فتتضاعف الاحتمالات: 2×2=4. هذا يوضح قانون التوزيع الحر للعوامل الوراثية. نصيحة: احسب عدد الجاميتات بالصورة 2 أس عدد الصفات غير المتماثلة، فـ AaBb = 2² = 4."},{"q":"يعبّر مربع بانيت عن:…","a":["كل الاحتمالات الممكنة لوراثة الصفات في الأبناء","عدد كروموسومات الجيل الثاني","تركيب الحمض النووي للفرد","ترتيب الجينات على الكروموسوم"],"c":0,"d":"easy","hint":"أداة تنبؤ بأزواج الجاميتات","expl":"الصواب: كل الاحتمالات الممكنة لوراثة الصفات، فهو جدول يوضح نتائج دمج الجاميتات الأبوية ونسبها. لا يتصل بعدد الكروموسومات ولا بتركيب الحمض النووي ولا بترتيب الجينات فوق الكروموسوم. نصيحة: اعتبر مربع بانيت \"لعبة تقدير احتمالات\" تضع فيها الجاميتات ثم تقرأ النتيجة."},{"q":"ينص قانون انعزال الصفات على أن:…","a":["الجاميتات تستقبل عاملاً واحداً من كل زوج من عوامل الصفة","العوامل تتوزع بحرية غير مستقلة","كل الجاميتات تحمل كل العوامل","الجاميتات لا تحمل أي عوامل"],"c":0,"d":"medium","hint":"كيف ينتقل زوج الصفات إلى الجاميتات؟","expl":"الصواب: عند تكوين الجاميتات ينعزل زوج العوامل ويدخل عامل واحد فقط لكل جاميتا، وهذا ما يحافظ على ثبات عدد الكروموسومات جيلاً بعد جيل. لا تتوزع العوامل مجتمعة، وحمل الجاميتات كل العوامل أو لا شيء يخالف الملاحظة العملية. نصيحة: قصّر القاعدة: جاميتا = نصف العوامل (عامل واحد من كل زوج)."}]},{"title":"التوائم والاستنساخ","read":[{"h":"أنواع التوائم","t":"يتكون التوأم الطفيلي (أحادي الزيجوت Identical) من تلقيح بويضة واحدة بحيوان منوي واحد ثم انقسام اللاقحة لاحقاً إلى جنينين أو أكثر، لذا يشتركان في نفس المادة الوراثية ويكونا من الجنس نفسه ويشبهان بعضهما شبهة تامة. أما التوأم غير المتماثل (ثنائي الزيجوت Fraternal) فينتج عن تلقيح بويضتين مختلفتين بحيوانين منويين مختلفين في نفس الوقت، وقد يكونان من جنسين مختلفين ولا يتشابهان أكثر من أي أخوين."},{"h":"الاستنساخ: تعريفه وأنواعه","t":"الاستنساخ Cloning هو إنتاج نسخ متطابقة وراثياً من خلية أو كائن حي دون تلقيح جنسي. أنواعه: 1) استنساخ الجينات: إدخال جين بشري في بكتيريا لإنتاج مادة مفيدة كالإنسولين، 2) الاستنساخ الإنجابي: إنتاج حيوان كامل مطابق وراثياً لحيوان آخر مثل النعجة دوللي عام 1997، 3) الاستنساخ العلاجي: إنتاج خلايا جذعية للأغراض الطبية تجريبية."},{"h":"استنساخ النعجة دوللي","t":"أنجح الاستنساخ الإنجابي لثديي، إذ أخذت نواة خلية جسدية من ضرع نعجة بيضاء، وزرعت في بويضة مجردة من نواتها من نعجة أخرى، ثم وضعت في رحم نعجة بديلة. ولدت دوللي نسخة مطابقة للنعجة المتبرعة بالنواة وليس للأمهات الأخريات، وهذا أُثبت أن نواة الخلية الجسدية تحمل كل الخارطة الوراثية المطلوبة للكائن كاملاً."},{"h":"تطبيقات الاستنساخ","t":"يستخدم الاستنساخ الوراثي في: إنتاج الأدوية والهرمونات كالإنسولين وهرمون النمو الحيواني (الأنسولين أول ما أنتج بالبكتيريا)، والحفاظ على السلالات الحيوانية المهددة بالانقراض، وتحسين الثروة الحيوانية، واستنساخ الأعضاء والأنسجة للأبحاث الطبية."},{"h":"الأخلاقيات الحيوية Bioethics","t":"مقابل غموض المستقبل يتحفظ العلماء على: استنساخ البشر كوسيلة للتكاثر بسبب ارتفاع نسبة التشوهات والوفاة المبكرة، وقلة التجارب الآمنة، ومخاوف من خلق حياة بلا أب أو أم حقيقي. أما الاستنساخ العلاجي فأقل تحفظاً لأنه يخدم إنقاذ المرضى، لكنه يلزم بضوابط صارمة وموافقة أخلاقية. أجمعت اللجان الأخلاقية على إدانة الاستنساخ الإنجابي البشري."},{"h":"خلاصة الدرس","t":"التوائم أحادية الزيجوت من بويضة واحدة وحدة مادة وراثية وجنس، وثنائية الزيجوت من بويضتين كأي أشقاء. الاستنساخ ثلاثة أنواع: جينات، إنجابي (دوللي)، وعلاجي. تطبيقاته طبية وزراعية واعدة، لكن الاستنساخ الإنجابي البشري مرفوض علمياً وأخلاقياً لأن مآلاته خطرة."}],"qs":[{"q":"التوائم المتطابقة (أحادية الزيجوت) تنشأ عن:…","a":["تلقيح بويضة واحدة ثم انقسام اللاقحة إلى جنينين","بويضتين مختلفتين بحيوانين منويين","بويضة واحدة بحيوانين منويين","انقسام البويضة قبل التلقيح"],"c":0,"d":"medium","hint":"التطابق الجيني يبدأ من بويضة واحدة","expl":"الصواب: تلقيح بويضة واحدة ثم انقسام اللاقحة إلى جنينين، فتحصلان على نفس المادة الوراثية ويكونان من الجنس نفسه. أما خيار بويضتين بحيوانين منويين فهو صفة التوأم غير المتطابق. الخيارات الباقية غير واقعية في السيرورة الطبيعية. نصيحة: الكلمة المفتاح \"متطابقة\" = مصدر واحد (بويضة واحدة)."},{"q":"أي الخيارات التالية ينطبق على التوأم ثنائي الزيجوت؟","a":["قد يكونان من جنسين مختلفين","دائماً من الجنس نفسه","تتشابه مادتهما الوراثية تماماً","يتطابقان في الملامح دائماً"],"c":0,"d":"easy","hint":"بويضتان مختلفتان → جينات مختلفة","expl":"الصواب: قد يكونان من جنسين مختلفين لأنهما من تلقيحين مستقلين، وتشابههما كتشابه أي أخوين وليس كتوأم متطابق. الخيارات الباقية تخص التوأم أحادي الزيجوت. نصيحة: \"ثنائي\" = بويضتان = احتمال اختلاف الجنس."},{"q":"النعجة دوللي أول حيوان ثديي أُنتج بطريقة:…","a":["الاستنساخ الإنجابي من نواة خلية جسدية","التلقيح الصناعي الطبيعي","التكاثر اللاجنسي بالتبرعم","الهندسة الوراثية للبيض الملقح"],"c":0,"d":"medium","hint":"نواة من خلية ضرع نعجة","expl":"الصواب: الاستنساخ الإنجابي من نواة خلية جسدية، حيث نقلت نواة خلية ضرع النعجة البيضاء إلى بويضة مجردة من نواتها. التلقيح الاصطناعي يبقى تكاثراً جنسياً، وليس تبرعماً، والهندسة الوراثية تغيّر جينات وليست استنساخاً لكائن كامل. نصيحة: دوللي = المثال الكلاسيكي للنقل النووي."},{"q":"يُعتبر إدخال الجين البشري للإنسولين في البكتيريا لتصنيعه مثالاً على:…","a":["الاستنساخ العلاجي","الاستنساخ الجيني","الاستنساخ الإنجابي","التكاثر الجنسي"],"c":0,"d":"medium","hint":"بإعادة الجين لا بإعادة الكائن كله","expl":"الصواب: الاستنساخ الجيني، لأنه نسخ جين البشري للأنسولين داخل بكتيريا تعمل كمصنع. الاستنساخ العلاجي يخص إنتاج خلايا وأعضاء للعلاج، والإنجابي لإنتاج كائن كامل مطابق، والجنسي لا علاقة له هنا. نصيحة: لاحظ الفرق: نسخ الجين = جيني، نسخ الخلية الجذعية = علاجي، نسخ الكائن = إنجابي."},{"q":"أجمعت اللجان الأخلاقية الحيوية على:…","a":["إدانة الاستنساخ الإنجابي البشري","اتحاد الاستنساخ الإنجابي","تشجيع الاستنساخ لجميع الفصائل","منع كل أنواع الاستنساخ"],"c":0,"d":"easy","hint":"الخطر الأكبر على كرامة الإنسان","expl":"الصواب: زادت اللجان الأخلاقية على إدانة الاستنساخ الإنجابي البشري بسبب التشوهات والمخاطر الأخلاقية الكبيرة. الاستنساخ العلاجي مقبول بضوابط لأنه يصب في إنقاذ المرضى، وليس مرفوضاً كله كما قد يظن الطالب. نصيحة: الأخلاقيات تفرق بين \"علاجي مقبول\" و\"إنجابي بشري مرفوض\"."},{"q":"الاستنساخ العلاجي يهدف إلى:…","a":["الحصول على خلايا جذعية لغرض علاج الأمراض","إنتاج نسخ كاملة من البشر","تحسين إنتاج الألبان فقط","تكاثر الحيوانات المهددة بالفناء فقط"],"c":0,"d":"easy","hint":"الغاية منه طبية","expl":"الصواب: الحصول على خلايا جذعية تستخدم لعلاج أمراض مثل بعض الأنيميا والسكري، وهي نسخ مخبرية وليست أجنة كاملة. الخيارات الأخرى تخص الاستنساخ الإنجابي أو تطبيقات زراعية ثانوية. نصيحة: العلاجي = الأنسجة والعلاج، الإنجابي = كائن كامل."},{"q":"لماذا تظهر التوائم أحادية البويضة ملامح متقاربة جداً؟","a":["لأنها انبثقت من نفس اللاقحة فتشابك المادة الوراثية","لأنها نشأت في فترة حمل واحدة","لأنها عاشت في نفس البيئة فقط","لأن أوزانها متطابقة عند الميلاد"],"c":0,"d":"medium","hint":"مصدر الجينات واحد","expl":"الصواب: لأنها انبثقت من نفس اللاقحة، فينطبق عندها الجينات، وهذه هي نقطة التشابه الكبير. تشابه الحمل والبيئة أمر ثانوي حتى في التوائم المختلفة، والبيئة وحدها لا تفسر التشابه الجيني التام. نصيحة: التشابه = نفس البويضة، والاختلافات الطفيفة = البيئة."},{"q":"يعترض العلماء على الاستنساخ الإنجابي البشري لأن:…","a":["معدلات الفشل والتشوهات مرتفعة جداً","يمنع إنتاج اللقاحات","يرفع إنتاج المحاصيل الزراعية","يغني عن الدراسات الجينية"],"c":0,"d":"medium","hint":"نتائج التجارب على الحيوان موحية","expl":"الصواب: غب معدلات الفشل والتشوهات والوفيات مرتفعة جداً في تجارب الثدييات مثل دوللي فماتت مبكراً، ولذلك يعد استنساخ البشر خطراً أخلاقياً وعلمياً. الخيارات الأخرى لا تعكس الإشكال الحقيقي. نصيحة: اعرف سببين للرفض: ارتفاع الأخطاء، والأثر على كرامة الإنسان."}]}]},{"title":"كيمياء الحيوية والتمثيل الغذائي","icon":"⚗️","chapters":[{"title":"التمثيل الغذائي","read":[{"h":"البناء الضوئي","t":"عملية يقوم بها النبات لتحويل الطاقة الضوئية إلى طاقة كيميائية مختزنة في الجلوكوز، تحدث في البلاستيدات الخضراء وتحتاج إلى ثاني أكسيد الكربون والماء وضوء الشمس وأصباغ الكلوروفيل، ومعادلها العام: 6CO₂ + 6H₂O + طاقة ء → C₆H₁₂O₆ + 6O₂. من على البلاستيد الخضراء نقرأ أن الوصول للغلوكوز ممره من غريمات ثابتة: الضوء والماء والكربون."},{"h":"مراحل البناء الضوئي","t":"تمر العملية بمرحلتين: الأولى التفاعلات الضوئية وفيها يتم امتصاص الضوء وتحليل الماء وتوليد طاقة (ATP) ونواتج مختزلة (NADPH) وينطلق الأكسجين، وتحدث في الأغشية الثايلاكويدية. الثانية التفاعلات اللاضوئية (غياب الضوء / دورة كالفن) وفيها يثبت ثاني أكسيد الكربون ويتحول إلى سكر جلوكوز، وتحدث في أرضية البلاستيد (الاستروما)."},{"h":"التنفس الخلوي والهوائيات","t":"التنفس الخلوي هو عملية تحرير الطاقة المختزنة في الجلوكوز داخل الخلايا لإنتاج مركبات الطاقة (ATP). النوع الهوائي يحتاج أكسجيناً ويعطي طاقة عالية: قصيّة عامة C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + طاقة، ويتم بمراحل متتابعة: تحلل السكر (بالسيتوبلازم) ثم دورة كربس (بالميتوكندريا) ثم سلسلة نقل الإلكترون (بالأغشية الداخلية للميتوكندريا) وينتج منها أكبر كمية ATP."},{"h":"التنفس اللاهوائي والتخمّر","t":"عند غياب الأكسجين تلجأ الخلية إلى التنفس اللاهوائي. في الخميرة يتحول الجلوكوز إلى كحول إيثيلي وثاني أكسيد الكربون وطاقة قليلة (التخمر الكحولي)، وفي العضلات إلى حمض اللاكتيك (التخمر اللبني) الذي يُسبب إحساس الإجهاد والتعب. التخمّر يعطي طاقة أقل بكثير من التنفس الهوائي لأنه لا يتم فيه تفكك الجلوكوز ليستخفي كاملاً."},{"h":"أهمية التمثيل الغذائي في الحياة","t":"البناء الضوئي هو المصدر الأساسي للأكسجين في الجو وتغذية جميع الشبكات الغذائية، والتنفس الخلوي يحوّل غذاء جميع الكائنات إلى طاقة تعمل بها خلاياها. علاقتهما عكسية مكملة: نواتج أحدهما مدخلات الآخر (CO₂ وO₂ تتبادلان)، وهذا توازن طبيعي رائع يدعم استمرار الحياة على كوكب الأرض."},{"h":"خلاصة الدرس","t":"البناء الضوئي: ضوء + ماء + CO₂ → جلوكوز + O₂ في البلاستيدات بمرحلتين (ضوئية ولاضوئية). التنفس الهوائي: جلوكوز + O₂ → CO₂ + H₂O + ATP بكثافة عالية في الميتوكندريا. اللاهوائي: تخمر كحولي بالخميرة أو لاكتيكي بالعضلات بكمية طاقة أقل. معادلة كل منهما معكوسة للأخرى لضمان دورة الحياة."}],"qs":[{"q":"المعادلة العامة للبناء الضوئي هي:…","a":["6CO₂ + 6H₂O + طاقة ضوئية → C₆H₁₂O₆ + 6O₂","6O₂ + 6H₂O ← 6CO₂ + C₆H₁₂O₆","CO₂ + H₂O → C₆H₁₂O₆ + O₂","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O"],"c":0,"d":"easy","hint":"مدخلات: ماء وثاني أكسيد كربون وضوء","expl":"الصواب: ثاني أكسيد الكربون + الماء + الضوء يُنتجان الجلوكوز والأكسجين، هذا اتجاه العملية طاقة تخزين. الخيار الأخير معادلة التنفس الهوائي المعكوسة، والخيار الثالث غير موزونة. نصيحة: البناء الضوئي \"يخزن\" بوصفه طاقة، والتنفس \"يحرر\"."},{"q":"تحدث التفاعلات الضوئية في البناء الضوئي داخل:…","a":["أغشية الثايلاكويدات بالبلاستيد","الاستروما (أرضية البلاستيد)","الريبوسومات","النواة الخلوية"],"c":0,"d":"medium","hint":"مكان الامتصاص الضوئي وتفكيك الماء","expl":"الصواب: داخل أغشية الثايلاكويدات حيث توجد أصباغ الكلوروفيل ومراكز التفاعل. أما دورة كالفن (اللاضوئية) فتحدث في الاستروما. الريبوسومات والنواة غير مربوطين بالبناء الضوئي. نصيحة: وزّع المهام: \"الأغشية ضوئية، والاستروما لاضوئية\"."},{"q":"ناتج التفاعلات الضوئية الذي يُطلق في الهواء هو:…","a":["الأكسجين","ثاني أكسيد الكربون","الجلوكوز","النيتروجين"],"c":0,"d":"easy","hint":"ينطلق من تحليل الماء (التحلل الضوئي)","expl":"الصواب: الأكسجين، وينطلق من تحليل الماء في التفاعلات الضوئية. لا يحدث ثاني أكسيد الكربون، والجلوكوز ناتج دورة كالفن اللاضوئية. نصيحة: ولو سُئلت \"ما مصدر الأكسجين؟\" قُل: تحليل الماء، هذا نقطة شائعة في الامتحانات."},{"q":"أين تنتج أكبر كمية من ATP في التنفس الهوائي؟","a":["في سلسلة نقل الإلكترون بالميتوكندريا","في تحلل السكر بالسيتوبلازم","في دورة كربس","في الهواء الخارجي"],"c":0,"d":"medium","hint":"آخر مراحل التنفس وأغزرها طاقة","expl":"الصواب: سلسلة نقل الإلكترون، فهي المرحلة الأخيرة وتنتج النسبة الأكبر من الطاقة (حوالي 34 جزيء ATP من أصل 38 تقريباً). تحلل السكر يعطي جزيئين فقط، ودورة كربس تعطي عدداً محدوداً. نصيحة: كلما تقدمنا في المراحل: 2 (تحلل) ← 2 (كربس) ← 34 (سلسلة نقل)."},{"q":"عند غياب الأكسجين في عضلات الإنسان ينتج عن تحلل الجلوكوز:…","a":["حمض اللاكتيك","الكحول الإيثيلي","ثاني أكسيد الكربون فقط","الجلوكوز نفسه"],"c":0,"d":"easy","hint":"التخمر اللبني في العضلات","expl":"الصواب: حمض اللاكتيك، الذي يتراكم في العضلات مسبباً الشعور بالتعب بعد الجهد الشاق. الكحول الإيثيلي نتاج التخمر في الخميرة. ثاني أكسيد الكربون ناتج جزئي هنا وليس الرابط الأساس. نصيحة: رجوع لمسألة: اللاكتيك = العضلات، الكحولي = الخميرة."},{"q":"جزء الخلية الذي يعمل فيه تحلل السكر (المرحلة الأولى للتنفس) هو:…","a":["السيتوبلازم","الميتوكندريا","النواة","غشاء الخلية"],"c":0,"d":"medium","hint":"تحدث دون الحاجة للأكسجين وبسرعة","expl":"الصواب: السيتوبلازم، حيث يتحلل الجلوكوز إلى مركبات أبسط بكمية طاقة قليلة ولا يشترط وجود الأكسجين فيها. أما الميتوكندريا فهي مسرح المراحل التالية. النواة والغشاء ليستا ذات صلة. نصيحة: رتّب العناصر: \"تحلل (سيتوبلازم) ثم كربس وسلسلة النقل (ميتوكندريا)\"."},{"q":"الفرق الجوهري بين التنفس الهوائي واللاهوائي هو:…","a":["كمية الطاقة المتحررة أكبر في الهوائي","اللاهوائي يعطي طاقة أكبر","الهوائي لا يحتاج إلى سوائل","اللاهوائي يحدث في النهار فقط"],"c":0,"d":"easy","hint":"الأكسجين هو الفرق الشائع","expl":"الصواب: الهوائي يحرر طاقة أكبر بكثير لأنه يفكك الجلوكوز تفككاً كاملاً، بينما اللاهوائي يترك طاقاً جزئية مخزنة في النواتج. كلام باقي الخيارات غير دقيق علمياً. نصيحة: زبدة القاعدة: أكسجين = تفكك كامل = طاقة كبيرة."},{"q":"العلاقة بين البناء الضوئي والتنفس الخلوي في النظام البيئي:…","a":["علاقة تكميلية تتبادل فيها النواتج (O₂ وCO₂)","متضادة تماماً بلا تبادل","كلاهما يستهلك الأكسجين","كلاهما ينتج الجلوكوز فقط"],"c":0,"d":"medium","hint":"نواتج أحدهما مدخلات الآخر","expl":"الصواب: علاقة تكميلية؛ فالأكسجين الناتج من البناء الضوئي يستخدمه التنفس، وثاني أكسيد الكربون الناتج من التنفس يعود للبناء الضوئي. الخيارات الأخرى لا تتطابق مع دورة المواد تلك. نصيحة: دائماً في أسئلة المقارنة: البناء يتغذى ب CO₂ والمتنفس يطرده، وبالعكس."}]},{"title":"الهرمونات","read":[{"h":"نظام الغدد الصماء","t":"الغدد الصماء غدد لاتوجد لها قنوات، تفرز هرموناتها مباشرة إلى الدم الذي ينقلها إلى خلايا الأهداف التنظيمية. الهرمون مادة كيميائية ينظم عمليات النمو والتمثيل الغذائي والتوازن الداخلي. منها البنكرياس، الغدة الدرقية، الغدة النخامية، الغدة الكظرية، الغدد الجنسية وغيرها."},{"h":"البنكرياس وتنظيم السكر","t":"البنكرياس غدة تعمل بنظامين: خارجي الإفراز (أنزيمات هضمية) وصماء (إفراز هرمونات). خلايا بيتا تفرز الإنسولين الذي يخفض سكر الدم بزيادة دخول الجلوكوز للخلايا وتخزينه كليكوجين، وخلايا ألفا تفرز الجلوكاجون الذي يرفع سكر الدم بتحويل الجليكوجين إلى جلوكوز. توازن الهرمونين يحفظ السكر في مداه الطبيعي، وخلل الإنسولين يسبب مرض السكري."},{"h":"الغدة الدرقية","t":"تقع في مقدمة الرقبة وتفرز هرمون الثيروكسين الذي يحتوي اليود وينظم معدل التمثيل الغذائي واستهلاك الطاقة. نقص اليود يسبب تضخم الغدة (الدرقة أو الغُدة المتضخمة). نقص الثيروكسين عند الأطفال يسبب تأخر النمو العقلي والجسمي، وزيادته ترفع معدل الأيض فيزيد التوتر وفقدان الوزن وسرعة ضربات القلب."},{"h":"الغدة الكظرية","t":"غدتان فوق الكليتين، تتكون كل منهما من قشرة ولب. لب الغدة الكظرية تفرز هرمون الأدرينالين والنورأدرينالين استجابة لحالات الطوارئ والخطر (القتال أو الهروب) فيرفع ضربات القلب وضغط الدم ويجهز العضلات للعمل. قشرة الغدة تفرز هرمونات مثل الكورتيزول المنظم لسكر الدم والاستجابة للالتهابات، والألدوستيرون المنظم للماء والأملاح."},{"h":"الغدة النخامية سيدة الغدد","t":"تقع في قاعدة المخ وتسمى \"المايسترو/سيدة الغدد\" لأنها تفرز هرمونات تنظم عمل غدد أخرى، مثل: هرمون النمو GH، الهرمون المنشط للدرقية TSH، والمنشط للكظرية ACTH، والهرمونات المنشطة للغدد الجنسية FSH وLH. في قصور النخامية لا تعمل الغدد التابعة لها بالصورة الصحيحة."},{"h":"خلاصة الدرس","t":"الهرمونات رسائل كيميائية من غدد بلا قنوات إلى دم. البنكرياس: إنسولين يخفض السكر وجلوكاجون يرفعه. الدرقية: ثيروكسين ينظم الأيض ويحتاج اليود. الكظرية: أدرينالين للطوارئ وكورتيزول للمقاومة. النخامية: سيدة الغدد تتحكم في كثير منها. التوازن الهرموني سر صحة الجسم الدائمة."}],"qs":[{"q":"الهرمون المسؤول عن خفض تركيز السكر في الدم هو:…","a":["الإنسولين","الجلوكاجون","ثيروكسين","الأدرينالين"],"c":0,"d":"easy","hint":"تفرزه خلايا بيتا في البنكرياس","expl":"الصواب: الإنسولين، يخفض سكر الدم بزيادة إدخال الجلوكوز إلى الخلايا. الجلوكاجون يعمل عكسياً فيرفع السكر، والثيروكسين ينظم الأيض العام، والأدرينالين للطوارئ. نصيحة: إنسولين = \"أبو الحلواني\" خفض السكر، وكلمة الجلوكاجون تحوي \"جلوكو\" أي سكراً يرفعه."},{"q":"الخلايا ألفا في البنكرياس تفرز هرمون:…","a":["الجلوكاجون","الإنسولين","الثيروكسين","الكورتيزول"],"c":0,"d":"medium","hint":"هرمون رافع للسكر","expl":"الصواب: الجلوكاجون، الذي يرفع السكر عند انخفاضه بتحويل الجليكوجين المخزن إلى جلوكوز. الإنسولين تفرزه خلايا بيتا، والثيروكسين تفرزه الدرقية، والكورتيزول تفرزه القشرة الكظرية. نصيحة: ثبّت العلاقة: بيتا = إنسولين، ألفا = جلوكاجون."},{"q":"تضخم الغدة الدرقية يرتبط عادة بنقص عنصر:…","a":["اليود","الحديد","الكالسيوم","الفلور"],"c":0,"d":"easy","hint":"عنصر يدخل في تركيب الثيروكسين","expl":"الصواب: اليود، لأن الثيروكسين يتركب في وجوده وعند نقصه تفرط الغدة في العمل كتعويض فتتضخم. الحديد للهيموغلوبين، والكالسيوم للعظام، والفلور للأسنان. نصيحة: حلّ عبارة \"درقية = يود\" كأنها زوج واحد في الذاكرة."},{"q":"يفرز هرمون الأدرينالين من:…","a":["لب الغدة الكظرية","البنكرياس","الغدة النخامية","المبايض"],"c":0,"d":"easy","hint":"هرمون الطوارئ السريع","expl":"الصواب: لب الغدة الكظرية، يستجيب لحالات الخطر بتسريع ضربات القلب ورفع الضغط. البنكرياس يفرز إنسولين وجلوكاجون، والنخامية سيدة الغدد، والمبايض هرمونات جنسية أنثوية. نصيحة: عدّ أول حرف: كظرية فوق الكلية فيها \"لب للطوارئ وقشرة للاستجابة\"."},{"q":"الغدة التي تسمى \"سيدة الغدد الصماء\" هي:…","a":["النخامية","الدرقية","الكظرية","البنكرياس"],"c":0,"d":"easy","hint":"تفرز هرمونات تحكم غداً أخرى","expl":"الصواب: النخامية، لأنها تفرز هرمونات منشطة توجه الغدد الأخرى (الدرقية، الكظرية، الجنسية) وتدير منظومة الصماء. بقية الغدد منفذة وليست القائدة. نصيحة: النخامية \"الرئيس التنفيذي\" والغدد الأخرى \"الموظفون\"."},{"q":"قصور إفراز الإنسولين يؤدي إلى الإصابة بـ:…","a":["مرض السكري","ارتفاع ضغط الدم","تضخم الغدة الدرقية","هشاشة العظام"],"c":0,"d":"easy","hint":"مرض يرفع سكر الدم","expl":"الصواب: السكري، إذ يتراكم الجلوكوز في الدم لأن الخلايا لا تدخله. لا يسبب ضغط الدم مباشرة، ولا تضخم الدرقية (نقص يود)، ولا هشاشة العظام. نصيحة: السكري = مشكلة الإنسولين. إذا ذُكر \"جلوكوز عال\" ففكر فوراً في الإنسولين."},{"q":"هرمون الثيروكسين وظيفته الأساسية:…","a":["تنظيم معدل التمثيل الغذائي للطاقة","خفض سكر الدم","تنظيم الكالسيوم في العظام","إنتاج خلايا الدم الحمراء"],"c":0,"d":"medium","hint":"يتحكم في قوة الأيض العامة بالجسم","expl":"الصواب: تنظيم معدل التمثيل الغذائي واستهلاك الطاقة، فزيادته تسرع الأيض ونقصه يبطئه. خفض السكر للإنسولين، والكالسيوم لهرمونات الغدة جارة الدرقية، وكرات الدم للكلى ونخاع العظم. نصيحة: دائم تذكّر: الثيروكسين = منظم \"وقود\" الجسم والإيقاع الحراري."},{"q":"هرمون الكورتيزول تفرزه:…","a":["قشرة الغدة الكظرية","لب الغدة الكظرية","الغدة النخامية","جدار البنكرياس"],"c":0,"d":"hard","hint":"قشر الغدة مقابل لبها","expl":"الصواب: قشرة الغدة الكظرية، وينظم السكر والالتهابات والمناعة. الأدرينالين من اللب، والنخامية سيدة الغدد، والبنكرياس لتنظيم السكر. نصيحة: وضّح الفرق: \"القشرة = كورتيزول وألدوستيرون، اللب = أدرينالين\"."}]}]},{"title":"التصنيف الحديث وشجرة الحياة","icon":"🌿","chapters":[{"title":"الممالك والتصنيف الحديث","read":[{"h":"أهمية التصنيف","t":"التصنيف علم ترتيب المخلوقات الحية في مجموعات متدرجة متشابهة، ليسهل دراستها ومعرفة علاقاتها. بدأ بظهور التصنيف بنظامين تقليديين، ثم تطور مع تقدم المعلومات الوراثية والجزيئية إلى نظام حديث يرتكز على تحليل الحمض النووي لتحديد القرابة التطورية الحقيقية."},{"h":"التصنيف الهرمي","t":"مراتب التصنيف من الأوسع إلى الأضيق: المملكة → الشعبة → الطائفة → الرتبة → الفصيلة → الجنس → النوع. النوع Type هو أصغر وأهم وحدة، ويشمل كل الأفراد القادرين على التزاوج وإنتاج نسل خصب، ويُكتب علمياً بكلمتين: الجنس ثم النوع، مثال: Homo sapiens (الإنسان العاقل)."},{"h":"الممالك الخمس التقليدية","t":"التقسيم الكلاسيكي يقسم الكائنات إلى خمس ممالك: 1) البدائية (الطلائعيات Protoctista) وهي حقيقية النواة معظمها أحادية الخلية مثل الأميبا، 2) الوبكتيريا/البكتيريا الحقيقية Monera (مثل بكتيريا القولون)، 3) الفطريات Fungi مثل الخميرة والعفن، 4) النباتات Plantae ذاتية التغذية بالبناء الضوئي، 5) الحيوانات Animalia غير ذاتية التغذية متحركة عادة."},{"h":"نظام المجالات الثلاثة","t":"تطوّر حديث مبني على تحليل الرنا الريبوسومي يقسم الحياة إلى ثلاثة مجالات Domain: 1) البكتيريا الحقيقية Bacteria، 2) البكتيريا القديمة/البكتيريا العتيقة Archaea (تعيش في بيئات قاسية كالينابيع الحارة والماء المالح)، و3) حقيقيات النوى Eukarya التي تشمل الطلائعيات والفطريات والنباتات والحيوانات. الفرق الجوهري بين البكتيريا للقديمة والحقيقية في تركيب الأغشية والرنا وليس في الشكل."},{"h":"أساسيات التسمية الثنائية","t":"وضعها العالم لينيوس، وتعتمد على اسمين: الجنس (بالحرف الكبير) والنوع (بالحرف الصغير) وتكتب إما بخط مائل أو تحته خط، وتستخدم الثنائية اللاتينية لضمان توحيد الاسم العلمي بين علماء العالم كله مهما اختلفت لغاتهم."},{"h":"خلاصة الدرس","t":"التصنيف الحديث يبدأ من ثلاثة مجالات: بكتيريا حقيقية، بكتيريا قديمة، حقيقيات نواة. الممالك خمس: بدائية، بكتيريا، فطريات، نباتات، حيوانات. الترتيب الهرمي: مملكة←شعبة←طائفة←رتبة←فصيلة←جنس←نوع. والتسمية الثنائية للينيوس توحّد الاسم العلمي."}],"qs":[{"q":"أصغر مرتبة تصنيفية من بين الخيارات التالية هي:…","a":["النوع","الجنس","الفصيلة","الرتبة"],"c":0,"d":"easy","hint":"الوحدة التي يتزاوج أعضاؤها وتخصيب نسلها","expl":"الصواب: النوع، وهو أصغر وحدة تصنيفية وأكثرها تحديداً، لأن الجنس شيوخ الفصيلة فصاعد كلها مراتب أوسع. تذكّر الدرج التصاعدي: نوع ← جنس ← فصيلة ← رتبة. نصيحة: استخدم جملة تساعدك مثل: \"نوعنا جملَ فصيلةً من رتبة الشعبة في المملكة\"."},{"q":"نظام التسمية الثنائية وضعه العالم:…","a":["كارولس لينيوس","داروين","جريجور مندل","واطسون"],"c":0,"d":"easy","hint":"عالم سويدي أب التصنيف الحديث","expl":"الصواب: لينيوس، مبتكر التسمية الثنائية للكائنات. داروين صاحب نظرية التطور، ومندل أبو الوراثة، وواطسون اكتشف شكلي DNA مع كريك. نصيحة: ربط: لينيوس = تصنيف وتسمية، مندل = وراثة، داروين = تطور."},{"q":"الاسم العلمي للإنسان العاقل Homo sapiens يشير إلى:…","a":["الجنس ثم النوع","النوع ثم الجنس","الفصيلة ثم الرتبة","الطائفة فقط"],"c":0,"d":"medium","hint":"أكبر الوحدتين يسبق أصغرها دائماً","expl":"الصواب: الجنس Homo ثم النوع sapiens، فالنظام الثنائي يبدأ بالجنس مرفوع الرأس. العكس غير صحيح كما تذكر الخيارات الأخرى. نصيحة: ثبّت: \"جنس، ثم نوع، كما هو الحال في Homo sapiens\"."},{"q":"أي الخيارات التالية يعد أمثلة على أفراد تنتمي غالباً للمملكة الحيوانية؟","a":["الأسد والزرافة","الخميرة والعفن","الأميبا والطحالب","البكتيريا الحلقية"],"c":0,"d":"easy","hint":"مخلوقات متحركة غير ذاتية التغذية عادة","expl":"الصواب: الأسد والزرافة من الحيوانات. الخميرة والعفن فطريات، والأميبا طلائعيات، والبكتيريا بدائيات نواة لا تنتمي للملكة الحيوانية. نصيحة: الحيوانات = تتحرك وتستهلك غيرها غذاء. لفطريات = تمتص غذاءها من البيئة."},{"q":"أي الخيارات التالية يمثل الكائنات الحية التي تعيش غالباً في البيئات القاسية كالينابيع الحارة؟","a":["البكتيريا القديمة (العتيقة)","البكتيريا الحقيقية","الفطريات","الطلائعيات"],"c":0,"d":"medium","hint":"مجال مستقل يجيد الظروف القصوى","expl":"الصواب: البكتيريا القديمة Archaea، المشهورة بالقدرة على الحياة في ينابيع الحرارة والملح وشديد الحموضة. البكتيريا الحقيقية أوسع بيئياً لكن ليس بالضرورة الظروف القاسية، والفطريات والطلائعيات أوسع تنوعي. نصيحة: الاسم ذاته \"العتيقة\" يحفّك على أنها نجت من أقدم الظروف القاسية."},{"q":"أي خصائص من الآتية مميز للطلائعيات (البدائيات حقيقية النواة أحادية الخلية)؟","a":["وجود نواة حقيقية في الخلية","خلوها من أي نواة","أنها جميعاً تقتل من النبات","عدم امتلاكها أي وسيلة حركة"],"c":0,"d":"medium","hint":"حقيقية النواة وتنتمي عادة لمجموعة واحدة","expl":"الصواب: امتلاك نواة حقيقية، إذ الطلائعيات حقيقية النواة (خلاف البكتيريا البدائية النواة). العبارات الباقية غير صحيحة عامة. نصيحة: راجع: \"بدائية النواة = بكتيريا، حقيقية النواة = طلائعيات فطريات نبات حيوان\"."},{"q":"الأفراد القادرون على التزاوج وإنتاج نسل خصب ينتمون في الأصل إلى:…","a":["النوع الواحد","المملكة الواحدة","الشعبة الواحدة","الجنس الواحد"],"c":0,"d":"medium","hint":"تعريف أساسي لوحدة النوع","expl":"الصواب: النوع الواحد، فالقدرة على التزاوج وإنتاج نسل خصب هي التعريف البيولوجي للنوع. لا يكفي تشابه المملكة أو الشعبة أو الجنس وحده لهذه المعايير. نصيحة: \"النسل الخصب\" علامة النوع، واحذر من أن حصان وحمار مثلاً لا ينتجان نسل الخصيب (بغل عاقر)."},{"q":"فائدة قسمة حقيقيات النوى إلى ممالك مختلفة كما في:…","a":["الفطريات والنباتات والحيوانات","الأنواع في الشعب والجامعات","أي جزء من البكتيريا إلى قسمين","كل ما سبق خاطئ"],"c":0,"d":"hard","hint":"فرز الكائنات الحقيقية النوى في مجموعات متمايزة التغذية والبنية","expl":"الصواب: فرز الفطريات والنباتات والحيوانات في ممالك مختلفة: للفطريات طريق امتصاصي، والنباتات ذاتية التغذية، والحيوانات مستهلكة. العبارات الأخرى لا تصف هذا التقسيم. نصيحة: الفرق الغذائي أساسي: نبات يصنع غذاءه، حيوان يلتهمه، فطر يمتصه."}]}]},{"title":"أساسيات الحياة","icon":"🌱","chapters":[{"title":"الخلية: وحدة الحياة","read":[{"h":"نظرية الخلية","t":"كل كائن حي يتكون من خلية أو أكثر؛ الخلية هي أصغر وحدة بنائية ووظيفية؛ الخلايا تنشأ من خلايا سابقة بالانقسام."},{"h":"البدائية النووية والخلية النواة","t":"البدائية (بكتيريا) بلا نواة حقيقية وDNA حر في السيتوبلازم؛ والحقيقية النواة فيها نواة محاطة بغشاء وعضيات."},{"h":"العضيات الرئيسية","t":"النواة (المادة الوراثية)، الميتوكوندريا (توليد الطاقة ATP)، الريبوسومات (صنع البروتين)، الشبكة الإندوبلازمية، جهاز جولجي (التعبئة)، البلاستيدات (في النبات) للبناء الضوئي."},{"h":"فرق نبات وحيوان","t":"الخلايا النباتية لها جدار خلوي وبلاستيدات خضراء وفجوة عصارية كبيرة، بينما الحيوانية لا جدار فيها وإنما غشاء خلوي فقط."},{"h":"التركيز","t":"الغشاء البلازمي: حاجز اختياري النفاذية؛ النقل عبر: الانتشار، النقل النشط، الخاصية الأسموزية."},{"h":"الخلاصة","t":"الخلية لبنة الحياة: نواة تدير، وعضيات تؤدي وظائف (ميتوكوندريا للطاقة، ريبوسوم للبروتين)، وجدار وبلاستيدات تفرق النبات عن الحيوان."}],"qs":[{"q":"عضية توليد الطاقة (ATP):…","a":["الميتوكوندريا","النواة","الريبوسوم","جولجي"],"c":0,"d":"easy","hint":"محطة الطاقة"},{"q":"صناعة البروتين تتم في:…","a":["الريبوسومات","النواة","الجدار","الفجوة"],"c":0,"d":"easy","hint":"مصنع البروتين"},{"q":"من الفروق النباتية هي جدار خلوي:…","a":["صح","لا","بدل السيتوبلازم","فقدانه"],"c":0,"d":"easy","hint":"نبات سلولوزي"},{"q":"الخلايا دون نواة حقيقية تسمى:…","a":["بدائية النواة","حقيقية النواة","نوية فقط","كريمة"],"c":0,"d":"easy","hint":"بكتيريا"},{"q":"تركيب المادة الوراثية:…","a":["نواة","ميتوكوندريا","بلاستيد","فجوة"],"c":0,"d":"easy","hint":"الوسط الوراثي"},{"q":"البلاستيدات الخضراء تؤدي:…","a":["البناء الضوئي","التنفس","التخليق البروتيني","الإخراج"],"c":0,"d":"easy","hint":"صبغة الكلوروفيل"}]},{"title":"الوراثة وقوانين مندل","read":[{"h":"مذنبات الوراثة","t":"المورثات (الجينات) وحدات الوراثة موجودة على الكروموسومات داخل النواة؛ كل صفة تحددها زوجية جينات (أليلان)."},{"h":"مفردات أساسية","t":"سائد/متنحٍّ: الجين السائد يظهر في الطراز الشكلي حتى لو كان مزدوجاً أو مع متنحي؛ والمتنحي لا يظهر إلا عند اجتماع أليلين متنحيين."},{"h":"قانون مندل الأول (انعزال الأزواج)","t":"عند تكوين الأعراس ينفصل أليلا كل زوج ولا ينتقلان معاً؛ فتوزع التهجين بنسبة 3:1 في الطرز الشكلية للجيل الثاني."},{"h":"قانون مندل الثاني (التوزيع الحر)","t":"انفصال أليز كل صفة وراثية مستقل عن الآخر؛ في الأزواج المستقلة تأتي النسبة 9:3:3:1 (الصفات المزدوجة)."},{"h":"الطرز الشكلية والأبوية","t":"الطراز الجيني: تركيب الأليلات (AA, Aa, aa)؛ الطراز الشكلي: الصفة الظاهرة (بذر أصفر/أخضر)."},{"h":"الخلاصة","t":"الجينات السائدة والمتنحية، قوانين مندل الثلاثة: الانعزال، التوزيع الحر، وكروموسومات الجنس — أساس علم الوراثة الحديث."}],"qs":[{"q":"الجينات توجد على:…","a":["الكروموسومات","البروتينات","الدهون","الماء"],"c":0,"d":"easy","hint":"حامل الوراثة"},{"q":"الأليل السائد يظهر:…","a":["عند اجتماعه مع متنحي أو سائد نسخة","شرط تنحي فقط","لا يظهر","ينحجب دائماً"],"c":0,"d":"medium","hint":"describe"},{"q":"في تهجين أحادي الصفة 3:1 يعبر عن:…","a":["نسبة الطرز الشكلية","نسبة الجينات","عدد الكروموسومات","نسبة الأعراس"],"c":0,"d":"easy","hint":"مظهر"},{"q":"قانون مندل الثاني:…","a":["التوزيع الحر للصفات","القاهر الانعزالي","التنافر","التراكم"],"c":0,"d":"medium","hint":"استقلال"},{"q":"النمط الجيني AA يسمى:…","a":["متماثل الألائل سائد","متخالف","متنحٍّ متماثل","هجين"],"c":0,"d":"easy","hint":"homozygous"},{"q":"تنتمي نسبة 9:3:3:1 إلى تهجين:…","a":["ثنائي الصفة مستقل","أحادي الصفة","مرتب جر دنده","سائد فقط"],"c":0,"d":"hard","hint":"ثنائي وراثيه"}]}]},{"title":"جسم الإنسان","icon":"🫀","chapters":[{"title":"الجهاز الهضمي والتنفسي","read":[{"h":"الهضم","t":"تحويل الغذاء إلى مواد بسيطة تمر عبر غشاء الأمعاء. الجهاز: فم → مريء → معدة → أمعاء دقيقة → أمعاء غليظة. الإنزيمات (أميلاز النشا، ببسين البروتين، ليباز الدهن)."},{"h":"الامتصاص","t":"في الأمعاء الدقيقة (الزغابات) يمتص الكلوكوز والأحماض الأمينية والفيتامينات في الدم؛ والأملاح الصفراء تستحلب الدهن."},{"h":"التنفس","t":"أخذ الأكسجين وطرح ثاني أكسيد الكربون. الأعضاء: أنف → حنجرة → قصبة (trachea) → شعبتان → رسغان فعليان في الرئة."},{"h":"التبادل الغازي","t":"يحدث في الحويصلات الهوائية بين الهواء والدم عبر الغشاء الرقيق؛ تسهل مساحة سطح كبيرة ونفاذية عالية."},{"h":"التنفس الخلوي","t":"في الميتوكوندريا: جلوكوز + أوكسجين → طاقة + CO2 + ماء. التنفس الهوائي يفوق اللاهوائي طاقة."},{"h":"الخلاصة","t":"الهضم يحلل الغذاء بالإنزيمات، والامتصاص بالزغابات؛ والتنفس يحصل الأكسجين للحويصلات والتنفس الخلوي ينتج الطاقة."}],"qs":[{"q":"امتصاص معظم المواد الغذائية:…","a":["الأمعاء الدقيقة","المعدة","الأمعاء الغليظة","الفم"],"c":0,"d":"easy","hint":"زغابات"},{"q":"الإنزيم الذي يفكك النشا:…","a":["الأميلاز","الببسين","الليباز","الأنسولين"],"c":0,"d":"easy","hint":"يقسم النشويات"},{"q":"تبادل الغازات يحدث:…","a":["الحويصلات الهوائية","القصبة","المريء","البلعوم"],"c":0,"d":"easy","hint":"acini"},{"q":"هضم الدهون يساعد فيه:…","a":["الصفراء","العصارة المعدية","اللعاب","المخاط"],"c":0,"d":"medium","hint":"تستحلب الدهون"},{"q":"التنفس الخلوي يحدث في:…","a":["الميتوكوندريا","النواة","الجدار","الشعيرات"],"c":0,"d":"easy","hint":"محطة الطاقة"},{"q":"الشدب (vocal) موجود في:…","a":["الحنجرة","المريء","القصبة الهوائية","الشعب"],"c":0,"d":"medium","hint":"صوتي"}]},{"title":"القلب والدورة الدموية والكلى","read":[{"h":"القلب","t":"مضخة رباعية الحجرات (أذينان وبطينان)؛ يدخل الدم الأذينين ويدفع من البطينين عبر الشرايين، والحواجز تمنع اختلاط الدم المؤكسد بالغير مؤكسد."},{"h":"الدورة الدموية","t":"دورة رئوية (للتزود بالأكسجين) ودورة جسمية (توصل الأكسجين للأنسجة)؛ الشرايين، أوردة، شعيرات تصل النقل عبر الغشاء."},{"h":"الدم","t":"بلازما (90% ماء)، دماء حمراء (نقل O2 بالهيموغلوبين)، دماء بيضاء (مناعة)، صفائح (تجلط)."},{"h":"الكلى والجهاز البولي","t":"الكليتان تنتجان البول وتنظمان الماء والملح والتوازن: لا تستطيع الاستغناء عن نيفرون (وحدة وظيفية) عددها مليون للكلى."},{"h":"الترشيح","t":"الدم → الكليون ← بول أولي في الكبسولة ← إعادة امتصاص مفيدة (جلوكوز، ماء) ← بول نهائي."},{"h":"الخلاصة","t":"القلب يدور الدم في دورتين؛ والدم ينقل O2 والغذاء؛ والكلى تنقي وضبط التوازن عبر النيفرونات."}],"qs":[{"q":"عدد حجرات قلب الإنسان:…","a":["4","2","3","5"],"c":0,"d":"easy","hint":"أذينان وبطينان"},{"q":"ناقل الأكسجين في الدم:…","a":["الهيموغلوبين","الصفائح","البلازما","الهرمون"],"c":0,"d":"easy","hint":"صبغة"},{"q":"الوحدة الوظيفية للكلى:…","a":["النيفرون","القشرة","الحوض","الأنبوب الكلوي فقط"],"c":0,"d":"easy","hint":"nephron"},{"q":"الصفائح الدموية مسؤولة عن:…","a":["تجلط الدم","نقل الأكسجين","المناعة","الهرمونات"],"c":0,"d":"easy","hint":"تخثر"},{"q":"الدورة الرئوية تنقل الدم إلى:…","a":["الرئتين","القلب","المخ","العضلات"],"c":0,"d":"easy","hint":"أكسجين"},{"q":"ظهور الجلوكوز في البول يدل غالباً على مرض:…","a":["السكري","فشل الكبد","الأنيميا","الزهايمر"],"c":0,"d":"medium","hint":"خلل في هرمون الأنسولين"}]}]}]},{"id":"physics","name":"الفيزياء","icon":"⚡","color":"#2196F3","books":[{"title":"الكهرباء والمجالات","icon":"⚡","chapters":[{"title":"التيار المستمر","read":[{"h":"التيار الكهربائي وقانون أوم","t":"التيار الكهربائي هو مرور شحنات كهربائية في موصل، ووحدته الأمبير A. وينص قانون أوم على أن الجهد المطبق على موصل يتناسب طردياً مع التيار المار فيه بثبات المقاومة: V = I × R، حيث V الجهد بالفولت، I التيار بالأمبير، R المقاومة بالأوم Ω. المقاومة مواد تقاوم مرور التيار وتحول جزءاً من الطاقة إلى حرارة. أمبير واحد = الشحنة التي تمر في ثانية واحدة (العلاقة I = Q/t)."},{"h":"المقاومة والمقاومية","t":"مقاومة الموصل تتوقف على: نوع المادة (سمة تسمى المقاومية ρ)، طوله L وزادت الثقة لمساحة مقطعه A وحرارته. الصيغة: R = ρ·L/A. أي أن المقاومة تزيد بزيادة الطول وتقل بزيادة مساحة المقطع، وهذا يفسر لماذا السمك يجعل الأسلاك أوفر مقاومة. زيادة درجة الحرارة عادة تزيد مقاومة الفلزات وتقلل مقاومة أشباه الموصلات."},{"h":"دائرة التوالي والتوازي","t":"التوصيل على التوالي: تسلسل عناصر واحدة بعد الأخرى؛ فتظل شدة التيار واحدة في كل الأجزاء، وتُجمع المقاومات جمعاً مباشراً (R الكلية = R₁+R₂+...)، وتُوزع الجهود على المقاومات. التوصيل على التوازي: تفريع من نفس النقطتين؛ فيتساوى الجهد على كل الفرع، ويقل التيار الفرعي بوجود مقاومة، والمقاومة الكلية تحسب من: 1/R الكلية = 1/R₁ + 1/R₂ + ... أي أن المقاومة الكلية أصغر من أصغر مقاومة."},{"h":"القدرة والطاقة الكهربائية","t":"القدرة الكهربائية P هي معدل تحويل الطاقة، وتحسب من العلاقة P = V·I، وباستخدام قانون أوم تأخذ صوراً مثل P = I²·R أو P = V²/R، ووحدتها الواط W. الطاقة الممتصة E = P × t وبوحدتها الواط/ساعة أو الجول. لكل جهاز كهربائي قدرة مسجلة (مثل مصباح 100 واط)، وزيادة استهلاك الطاقة بزيادة القدرة وزمن التشغيل."},{"h":"تطبيقات الدوائر العملية","t":"في البيوت توصّل الأجهزة على التوازي، حتى يعمل كل جهاز مستقل بجهد المنزل الكامل، وإذا تعطل واحد استمرت الباقية. ومفتاح الأمان (المنصهر) سلك رفيع يمر به التيار فينصهر عند ارتفاعه دخلاً يحمي الدائرة. أسلاك الفصل المنخفض تقاوم التيار، فتصبح المنشآت أسخن."},{"h":"خلاصة الدرس","t":"قانون أوم: V=IR. المقاومة تخضع لطبيعة المادة والطول والمقطع والحرارة. التوالي يجمع المقاومات ويثبت التيار، والتوازي يثبت الجهد ويقلل المقاومة الكلية. القدرة P=VI، والطاقة E=Pt. المنصهر أمان الدائرة، والأجهزة المنزلية على التوازي."}],"qs":[{"q":"بنص قانون أوم، إذا تضاعف الجهد المطبق على مقاومة ثابتة فإن شدة التيار:…","a":["تتضاعف هي أيضاً","تنقص للنصف","تبقى دون تغيير","تنعدم تماماً"],"c":0,"d":"easy","hint":"العلاقة الطردية V = I × R","expl":"الصواب: يتضاعف التيار، لأن V تتناسب طردياً مع I عند ثبات R. فإذا صار الجهد ضعفاً، مر التيار ضعفاً. لا تنقص ولا تبقى ثابتة ولا تنعدم. نصيحة: O عند ثبات المقاومة الجهد والتيار توأمان طرديان."},{"q":"وحدة قياس شدة التيار الكهربائي هي:…","a":["الأمبير","الفولت","الأوم","الواط"],"c":0,"d":"easy","hint":"شحنة في الثانية","expl":"الصواب: الأمبير وحدة التيار، فالتفرق بين الوحدات: الفولت للجهد، والأوم للمقاومة، والواط للقدرة. نصيحة: ثبت المثلث: V جهد (فولت) × I تيار (أمبير) = P قدرة (واط)."},{"q":"مقاومتان (6 Ω) و(3 Ω) متصلتان على التوالي. المقاومة الكلية للدائرة…:…","a":["9 أوم","2 أوم","18 أوم","3 أوم"],"c":0,"d":"medium","hint":"في التوالي تُجمع المقاومات جمعاً مباشراً","expl":"الصواب: 9 أوم، لأن التوالي يجمع: 6+3=9. القيمة 2 أوم ناتجة من قانون التوازي (6×3÷9)، و18 من الضرب الخاطئ. نصيحة: \"توالي يجمع، توازي يقلل\". إذا أعطيتها توالي اجمع فوراً."},{"q":"نفس المقاومات (6Ω) و(3Ω) بتوصيل على التوازي: المقاومة الكلية تكون:…","a":["2 أوم","9 أوم","18 أوم","6 أوم"],"c":0,"d":"medium","hint":"المقاومة الكلية في التوازي أصغر من أصغر مقاومة","expl":"الصواب: 2 أوم؛ 1/R = 1/6 + 1/3 = 3/6، فيكون R = 2. ولاحظ أنه أصغر من 3 أصغر مقاومة، بينما التوالي كان 9. نصيحة: في التوازي توقع دائماً نتيجة أقل من أصغر قيمة، واحتفظ بالقاعدة العكسية في الذاكرة."},{"q":"القدرة المستهلكة في مصباح يعمل بجهد 220 فولت ويمر به تيار 0.5 أمبير تساوي:…","a":["110 واط","440 واط","220 واط","55 واط"],"c":0,"d":"easy","hint":"P = V × I","expl":"الصواب: 110 واط، لأن P = 220 × 0.5 = 110. الخيارات الأخرى نتائج حسابات مغايرة. نصيحة: احفظ بالوحدات: واط = فولت × أمبير، فهي حماية ذهبية لك في هذا الباب."},{"q":"تزداد مقاومة موصل معدني عندما:…","a":["يزيد طوله","يقل طوله","تزداد مساحة مقطعه","تنخفض حرارته للصفر"],"c":0,"d":"medium","hint":"R = ρ × L / A","expl":"الصواب: عند ازدياد الطول لأن المقاومة تتناسب طردياً معه. مساحة المقطع أكبر تخفف مقاومة، والحرارة الأقل عموماً تخفف مقاومة الفلز. نصيحة: قياس بسيط: سلك طويل = طريق طويل للشحنة = مقاومة أكثر."},{"q":"التوصيل الكهربائي للأجهزة المنزلية يكون في الغالب على الشكل:…","a":["التوازي","التوالي","عشوائياً","بلا حماية"],"c":0,"d":"easy","hint":"لكي يعمل كل جهاز بجهد كامل ويستقل}","expl":"الصواب: التوازي، حتى يحصل كل جهاز على جهد المنزل الكامل ويعمل مستقلاً، وتتضمن الأمان فإذا تعطل جهاز بقيت الباقية تعمل. لو كان التوالي لأوقف جهاز كنورج أحمر جميع الأبيات. نصيحة: \"منزلي = متوازي\" قاعدة عملية لحياتك اليومية وللاختبار."},{"q":"يمر بالمنصهر (المصهرة) تيار أعلى من المسموح فينصهر السلك لأن مقصوده:…","a":["قطع الدائرة حماية للأجهزة","زيادة الجهد الكهربائي","رفع مقاومة السلك الرئيسي","تحويل التيار لخارج المنزل"],"c":0,"d":"medium","hint":"عنصر أمان ذو سلك رفيع","expl":"الصواب: قطع الدائرة لحماية الأجهزة من التلف نتيجة زيادة التيار، فيتحول التيار دون جهازين للاسلاك إلى تيار يحترق سبيكة الانصهار فينقطع. ليس لزيادة الجهد ولا لرفع المقاومة إذ الغاية حمايتنا. نصيحة: المنصهر \"صمام أمان\": سلك رفيع يضحي بنفسه قبل الأجهزة."}]},{"title":"المجال الكهربائي والجاذبية","read":[{"h":"الشحنة الكهربائية وقانون كولوم","t":"الشحنات نوعان: موجبة وسالبة، وتتجاذب المختلفة وتتنافر المتماثلة. قانون كولوم يحدد قوة الجاذبية أو التنافر بين شحنتين: F = k × q₁×q₂ / r²، حيث k ثابت كولوم، وq شحنة، وr البعد بينهما. القوة تتناسب طردياً مع حاصل ضرب الشحنتين وعكسياً مع مربع البعد: أي أن زيادة البعد مرتين تقسم القوة على 4."},{"h":"المجال الكهربائي","t":"المجال الكهربائي مقدار ما يحيط بشحنة من قدرة على التأثير في الشحنات الأخرى، ويعرف عند نقطة بأنه القوة اللاحقة بشحنة اختيارية موجبة صغيرة مقسومة عليها: E = F / q، ووحدته نيوتن/كولوم أو فولت/متر. شد المجال تزداد بالقرب من الشحنة وتنحدر ببعده. قوتها عبر الشحنة الاختبارية الموجبة."},{"h":"خطوط المجال الكهربائي","t":"خطوط وهمية مرسومة بحيث: تخرج من الشحنة الموجبة وتدخل إلى الشحنة السالبة، ولا تتقاطع، وتتناسب كثافتها مع شدة المجال، وكلما اقتربت من الشحنة تقاربت الخطوط. رسمها يساعد على توقع اتجاه القوة التي تشعر بها شحنة موجبة إذا وُضعت في المجال، إذ تتحرك في اتجاه الخطوط."},{"h":"الجاذبية وقانون نيوتن","t":"الجاذبية قوة التجاذب بين الكتل، ويعرف بمقدارها: F = G × m₁×m₂ / r². وشد المجال الجاذبي على سطح الأرض يساوي تسارع الجاذبية g = G×M/r² قريب من 9.8 م/ث². الجاذبية دائماً قوة جذب فقط بينما الكهربائية قد تكون جذباً أو دفعاً، والجاذبية أضعف بكثير من القوى الكهربائية بالعالمين المتناهي الصغر والكبير."},{"h":"المقارنة الكهربائية والجاذبية","t":"نقاط التشابه: كلتاهما تتناقصان مع مربع المسافة، وكلتاهما قوتان حقلان ناتجة عن خاصية (شحنة أو كتلة). نقاط الاختلاف: كولوم يسمح بالجاذبية والتنافر، والنيو يتجاذب فقط؛ كولوم مربوط بالشحنة، والنيو بالكتلة؛ القوة الكهربائية أكبر شأناً من الجاذبية بدرجات هائلة. في الذرة تكون قوى إلكترون والنواة الكهربائية ساحقة مقارنة بالجاذبية الكتلية."},{"h":"خلاصة الدرس","t":"قانون كولوم: F = k·q₁q₂/r² (طردي مع الشحنتين، عكسي مع مربع البعد). المجال E = F/q وخطوطه من موجب إلى السالب. الجاذبية: F = G·m₁m₂/r² وتجاذب دوماً. أوجه الشبه: قانونان بعكس مربع المسافة. أوجه الاختلاف: جذب فقط للجاذبية ووحدة النوع للشحنة، وقوتها الكهربائية أعتى."}],"qs":[{"q":"عند مضاعفة المسافة بين شحنتين، القوة الكهربائية بينهما:…","a":["تصبح ربع القيمة الأصلية","تصبح ضعفها","تصبح نصفها","تبقى ثابتة"],"c":0,"d":"easy","hint":"القوة تتناسب عكسياً مع مربع البعد","expl":"الصواب: ربع القيمة الأصلية؛ لأن القوة تتناسب عكسياً مع مربع المسافة (1/r²)، فجعل البعد ضعفاً يقسم القوة على 4. لا تتضاعف ولا تتنصف ولا تثبت. نصيحة: القاعدة الذهبية: \"مربع المسافة\" فانتبه للكلمة \"مربع\"."},{"q":"وحدة قياس المجال الكهربائي هي:…","a":["نيوتن/كولوم","جول","واط","أوم"],"c":0,"d":"easy","hint":"قوة ÷ شحنة","expl":"الصواب: نيوتن/كولوم (أو فولت/متر) من E=F/q. الجول للطاقة، والواط للقدرة، والأوم للمقاومة. نصيحة: ابني وحدة من معرّفها: مجال = قوة/شحنة، فيصبح نيوتن/كولوم."},{"q":"خطوط المجال الكهربائي:…","a":["تخرج من الشحنة الموجبة وتدخل إلى السالبة","تدخل الموجب وتخرج من السالب","لا تتأثر بالشحنات","تتقاطع دائماً"],"c":0,"d":"medium","hint":"اتجاه القوة على شحنة موجبة","expl":"الصواب: تخرج من الموجبة وتدخل للسالبة، فالشحنة الموجبة تنفصل عن النقط المعاكسة. لا تقبل الشحنات عكس ذلك، ولا تتقاطع الخطوط أبداً في نقطة واحدة، وهي تأتي بسبب الشحنات أصلاً. نصيحة: \"من + إلى −\" كأنه اتجاه أطراف البطارية بالخارج."},{"q":"في قانون الجاذبية العام، تعتمد قوة التجاذب بين جسمين طردياً على:…","a":["حاصل ضرب الكتلتين","حاصل قسمة الكتلتين","مربع المسافة","ثابت كولوم"],"c":0,"d":"easy","hint":"F = G·m₁·m₂/r²","expl":"الصواب: حاصل ضرب الكتلتين، بمقدار الازدياد طردياً، بينما المسافة مربعة تنقص القوة، وثابت كولوم خاص بالكهرباء وليس الجاذبية. نصيحة: قارن دائماً بين القانونين: كولوم في بسطه شحنة×شحنة، وقانون الجاذبية في بسطه كتلة×كتلة."},{"q":"أوجه الشبه بين قوة كولوم وقوة الجاذبية أن كلتيهما:…","a":["تتناقص مع مربع المسافة","تتنافر بالشحنات المختلفة","دائماً تجاذب فقط","تعتمد على درجة الحرارة"],"c":0,"d":"medium","hint":"قانونان متطابقان في شكل الاعتماد على البعد","expl":"الصواب: تتناقصان مع مربع المسافة، فكلتاهما من نوع قوى \"معكوسة مربع المسافة\". التنافر بالشحنات المختلفة خاطئ (المختلفة تتجاذب)، والجاذبية الدائمة صفة الجاذبية وحدها لا كولوم، والحرارة ليست في القانونين. نصيحة: إذا سُئل عن تشابه فقل: \"الاثنتان عكس مربع المسافة\"."},{"q":"قوة الجاذبية بين إلكترون ونواة الذرة مقارنة بقوة كولوم بينهما:…","a":["أصغر بكثير جداً","أكبر بكثير","متساوية تماماً","لا تُحسب"],"c":0,"d":"hard","hint":"القوى الكهربائية أقوى بمقياس هائل","expl":"الصواب: أصغر بكثير جداً، إذ القوتان الكتلتان للنوى والالكترون صغيرة، بينما القوة الكهربائية الهائلة بين شحنتيهما هي التي تحكم بيئة الذرة. لذا لا تساوي ولا تتفوق ولا يوجد ما يمنع حسابها. نصيحة: الجاذبية تهم في الأجسام الضخمة، والكهرباء تهم في الجسيمات الذرية."},{"q":"للحصول على مجال كهربائي نشده 2 نيوتن/كولوم على شحنة تجريبية قيمتها 1 كولوم يجب أن تكون القوة اللاحقة بها:…","a":["2 نيوتن","1 نيوتن","4 نيوتن","2/1 نيوتن"],"c":0,"d":"medium","hint":"E = F/q ⇒ F = E × q","expl":"الصواب: 2 نيوتن، لأن F = E × q = 2 × 1 = 2. الخيارات الأخرى من عمليات مغايرة. نصيحة: أعد ترتيب القانون حالما تشاء: F = E×q أو E = F/q."},{"q":"شحنتان موجبتان متساويتان في المقدار تفصل بينهما مسافة صغيرة، فأي العبارات صحيح:…","a":["تتنافران بقوة كولوم","تتجاذبان بقوة كولوم","لا تؤثر إحداهما في الأخرى","تتحولان إلى شحنتين سالبتين"],"c":0,"d":"easy","hint":"التماثل يتنافر","expl":"الصواب: تتنافران، فالشحنات المتماثلة (موجب مع موجب) تتنافر، والمختلفة تنجذب. لا تجاذب بينهما ولا تأثير معدوم. نصيحة: القاعدة: \"المتماثل يتدافع، والمختلف يتجاذب\" تنطبق على الشحنات والمغناطيسات أيضاً."}]},{"title":"الحث الكهرومغناطيسي","read":[{"h":"قانون فاراداي للحث","t":"لاحظ فاراداي أن مرور التيار في ملف يقلب المجاورة يمكن أن يولّد تياراً في ملف آخر أزمنة انتقال، فالعلاقة بين التغير في المجال المغناطيسي وتوليد القوة الدافعة الكهربائية تسمى الحث الكهرومغناطيسي. ينص قانون فاراداي: ق.د.ك = −N × (ΔΦ/Δt)، أي أن القوة الدافعة المستحثة تتناسب طردياً مع معدل تغير التدفق المغناطيسي Φ عبر الملف ومع عدد لفاته N. لا يُحث تيار في دائرة إلا إذا تغير التدفق المغناطيسي عبرها."},{"h":"قانون لينز واتجاه الحث","t":"ينص قانون لينز على أن التيار المستحث يتخذ الاتجاه الذي يعاكس سبب توليده، أي يعاكس التغيير في التدفق المغناطيسي الذي أتاه. هذا مبدأ حفظ الطاقة: إذا ساعد التيار المستحث سببه لازداد التدفق بلا حد وتولّدت طاقة من لا شيء، وهو مستحيل، لذلك تعكس دائماً. علامة الطرح في قانون فاراداي هي تعبير رياضي عن قانون لينز."},{"h":"طرق تقوية التيار المستحث","t":"يمكن زيادة القوة الدافعة المستحثة عبر: 1) زيادة عدد لفات الملف (N)، 2) زيادة سرعة تغير التدفق (تحريك المغناطيس أسرع)، 3) زيادة شدة المجال المغناطيسي (مغناطيس أقوى)، 4) زيادة مساحة الحلقة الخاضعة للتغير. كل هذه ترفع القيمة ΔΦ/Δt وبالتالي القوة الدافعة."},{"h":"المحولات الكهربائية","t":"المحول جهاز يستخدم لتغيير قيم الجهد والتيار في دوائر التيار المتردد اعتماداً على الحث المتبادل، ويتكون من قلب حديدي وملفين: الملف الابتدائي والثانوي. إذا زاد عدد لفات الملف الثانوي عن الابتدائي رفع الجهد (محول رافع) والعكس محول خافض. العلاقة: Vs/Vp = Ns/Np. وجهد المتردد يتغير تلقائياً يحدث الحث، ولذلك المحول لا يعمل مع التيار المستمر الثابت."},{"h":"التيارات الدوامية (Eddy Currents)","t":"عند تحريك موصل في مجال مغناطيسي، تتولد بهذا الموصل تيارات مغلقة تتجه نحو المركز، تسمى التيارات الدوامية، تسبب توليد حرارة وقد تؤدي فقد طاقة. تُستغل في: التسخين بالحث (أفران الحث)، والكبح الكهرومغناطيسي للموازين العالية، وفي الطرف الآخر تقلل خسائرها بتصنيع القلب الحديدي شرائح معزولة عن بعضها لقطع مسارات التيارات الكبيرة."},{"h":"خلاصة الدرس","t":"الحث: توليد تيار بتغير التدفق المغناطيسي، ويعبر عنه فاراداي: ق.د.ك = −N(ΔΦ/Δt)، ولينز: التيار المستحث يعاكس سببه. تقوى القوة الدافعة باللفات الأكثر والحركة الأسرع والمغناطيس الأقوى. المحول يعمل بالمتردد ويغير الجهد بنسبة اللفات Vs/Vp = Ns/Np. التيارات الدوامية حرارة وضربة إضافية تُدار كماً أو تُستغل للتسخين والكبح."}],"qs":[{"q":"توريد شريط مغناطيسي داخل ملف ثابت يولد تياراً في الملف، وهذا ناتج عن:…","a":["الحث الكهرومغناطيسي","التوصيل الحراري","التوصيل الكهروستاتيكي","الجاذبية الذرية"],"c":0,"d":"easy","hint":"التغيير في التدفق المغناطيسي يولدا قوة دافعة","expl":"الصواب: الحث الكهرومغناطيسي، حين يتغير التدفق المغناطيسي عبر الملف فيتولد تيار مستحث. لا علاقة لها بالحرارة أو الكهروستاتيكية أو الجاذبية. نصيحة: لاحظ: تحريك المغناطيس (تغير التدفق) = عمود الحث الكهرومغناطيسي الأساس."},{"q":"ينص قانون فاراداي على أن القوة الدافعة الكهربائية المستحثة في ملف:…","a":["بالتناسب الطردي مع معدل تغير التدفق المغناطيسي","عكسية مع عدد اللفات","ثابتة مهما تغير التدفق","دائماً صفراً"],"c":0,"d":"medium","hint":"ق.د.ك = −N × (ΔΦ/Δt)","expl":"الصواب: تتناسب طردياً مع معدل تغير التدفق المغناطيسي (وعدد اللفات أيضاً). لا تنقص بزيادة اللفات، ولا بثبات التدفق، إذ إن تغير التدفق شرط أصلي للتحرض. نصيحة: الثابت المتغير: كلما \"تغيّر\" التدفق أسرع، ارتفعت القوة الدافعة."},{"q":"وفق قانون لينز، التيار المستحث يتخذ دائماً اتجاهاً:…","a":["يعاكس السبب المولد له","يوافق السبب ويقويه","عمودياً على السبب","مستقلاً تماماً"],"c":0,"d":"medium","hint":"المبدأ صيانة الطاقة","expl":"الصواب: يعاكس السبب المولد له، فيعارض التغير في التدفق الذي أتاه. لو وافقه لتضخم التدفق بلا حدود وتولدت طاقة مجاناً مخالفة مبدأ حفظ الطاقة، لذلك الخيارات الأخرى خاطئة. نصيحة: الجملة المفتاح: \"يعاكس سببه\" = قانون لينز، وعلامة الطرح في فاراداي هي ترجمتها."},{"q":"المحول الكهربائي يعمل فقط مع التيار:…","a":["المتردد","المستمر الثابت","المستمر النبضي البطيء","جميع الأنواع"],"c":0,"d":"easy","hint":"يحتاج تغيراً في التدفق باستمرار","expl":"الصواب: المتردد، لأن تغير جهده المستمر يتغير التدفق فيتولد الحث. التيار المستمر الثابت لا يسبب تغيراً فلا حث ولا فائدة منه في المحول. لا يعمل مع المستمر ولا النبضي البطيء بفعالية. نصيحة: \"محول = مبدل تردد\": مخصص لتيار المتردد المتغير."},{"q":"لتضخيم الجهد في محول، يجب أن يكون عدد لفات الملف الثانوي:…","a":["أكبر من لفات الابتدائي","أصغر من لفات الابتدائي","مساوياً للفات الابتدائي","منعدماً"],"c":0,"d":"easy","hint":"نسبة الجهد = نسبة عدد اللفات","expl":"الصواب: أكبر من عدد لفات الملف الابتدائي، فكلما زادت اللفات في الثانوي ارتفع الجهد فيه (محول رافع). الأصغر ينتج خافضاً والمساوي يثبت الجهد تقريباً. نصيحة: \"كثرت اللفات، ارتفع الجهد\" ملاحظة سريعة للمحولات."},{"q":"العلاقة بين عدد لفات الملفين والجهود في المحول المثالي هي:…","a":["Vs/Vp = Ns/Np","Vs×Vp = Ns/Np","Ns/Vs = Vp/Np","Vp/Vs = Ns/Np"],"c":0,"d":"medium","hint":"نسبة الجهد تطابق نسبة اللفات","expl":"الصواب: Vs/Vp = Ns/Np، فتتغير الجهود تبعاً للعدد. الخيارات الأخرى من قلب النسب بشكل خاطئ. نصيحة: ضع فوق المجهول، وعبور بين الجهد واللفات بنفس النسبة، وتحقق من منطقية النتيجة."},{"q":"التيارات الدوامية في قلب محول تقلل كفاءته لأنه يرافقها:…","a":["توليد حرارة ومفاقيد طاقة","زيادة التدفق المضاعف","زيادة عدد اللفات","انعدام الحث"],"c":0,"d":"medium","hint":"المرور في القلب المعدني الكبير يعمل كملف مغلق","expl":"الصواب: توليد حرارة وفقد طاقة داخل القلب، لذلك تُصنع قلوب المحولات من شرائح معزولة لتقطيع مسارات هذه التيارات وفقد أقل. لا تزيد التدفق ولا اللفات ولا تلغي الحث. نصيحة: \"دوامية = دفّاية\": ارتجف الحرارة عند وجودها، وإذا أردت خفض فقدها فاعزل القلب شرائح."},{"q":"لتقليل خسائر التيارات الدوامية في المحولات يُصنع القلب الحديدي:…","a":["من شرائح معزولة متلاصقة","كتلة واحدة مصمتة","من الخشب","من الزجاج"],"c":0,"d":"easy","hint":"تقليل مسارات التيارات الغليظة","expl":"الصواب: من شرائح معزولة عن بعضها، فتكسر الدائرة الواسعة للتـ‌Eddy وتقللها. الكتلة المصمتة تزيدها، والخشب والزجاج لا يعملان قلوباً مغناطيسية. نصيحة: \"شرائح معزولة = عدّادات دوامية خاسرة\" قاعدة تحفظها عن ظهر قلب."}]}]},{"title":"الذرة والنشاط الإشعاعي","icon":"☢️","chapters":[{"title":"التركيب الذري","read":[{"h":"نموذج بور للذرة","t":"قدّم نيلز بور عام 1913 نموذجاً يكون فيه الإلكترون يدور حول النواة في مدارات (أغلفة) محددة ذات طاقة ثابتة، لا يصدر الإلكترون طاقة أثناء بقائه في مدار ثابت. الإشعاع يظهر فقط عندما ينتقل الإلكترون بين المدارات: يقفز إلى مدار أعلى بامتصاص طاقة (فوتون)، ويهبط إلى مدار أدنى بإطلاق طاقة (فوتون). نواتج المدارات: كلما زاد رقم المدار زاد نصف قطره وزادت طاقته وبعده عن النواة."},{"h":"مستويات الطاقة (Quantization)","t":"طاقة الإلكترون في الذرة \"كم\" أي تتغير في مضاعفات منفصلة، لا بأي قيمة. أهم الأغلفة: الرئيسي الأول K يستوعب 2 إلكتروناً، والثاني L يستوعب 8، والثالث M يستوعب 18 بمقاعد الأطفال، والقاعدة 2n². انتقال الإلكترون المثار من غلاف بعيد إلى أقرب النواة يطلق طاقة تساوي فرق المستويين، وفي شعاع خطي مهولة كأطياف الغازات."},{"h":"التأثير الكهروضوئي","t":"التأثير الكهروضوئي: انبعاث الإلكترونات من سطح معدن عند تسليط إشعاع ساقط بتردد مناسب (أعمال صورف هذه كما عمل أينشتاين الذي شرحها). كل فوتون يصطدم بإلكترون ويمنحه طاقته كاملة. لو كان تردد الضوء الساقط دون حد العتبة للمعادن، لا تنبعث إلكترونات مهما زادت شدة الضوء، وهذه النتيجة كانت عصية على النظرية الموجية وحدها، وأيدت الطبيعة الجسيمية للضوء."},{"h":"طاقة الفوتون والمعادلات","t":"الفوتون كمّ من طاقة الضوء لا كتلة له. طاقته E = h × f حيث h ثابت بلانك (6.63×10⁻³⁴ جول·ثانية) وf التردد. وبما أن التردد = سرعة الضوء ÷ الطول الموجي (f = c/λ)، يمكن كتابة E = h×c/λ، أي أن الطول الموجي الأقصر (تردد أعلى) يعني فوتون أحلى طاقة؛ لذا أشعة جاما أقوى من أشعة الراديو."},{"h":"الأطياف الذرية وثبات الذرة","t":"خطوط الطيف الذري الناتجة عن انتقال الإلكترونات بين المستويات هي \"بصمة\" العنصر الكيميائي، فلكل عنصر طيف مميز يحدد بواسطته في الأجرام البعيدة. نماذج الذرة تطورت من رذرفورد (نواة وإلكترونات تدور) إلى بور (مدارات كمية) ثم النموذج الكمومي الحديث المبني على الاحتمالات والدوال الموجية."},{"h":"خلاصة الدرس","t":"بور: إلكترون بمدارات طاقة محددة ويتقلب بينها بإصدار أو امتصاص فوتون. مستويات الطاقة منفصلة كمياً بقانون 2n². التأثير الكهروضوئي: خروج الإلكترونات من المعدن عند تردد كافٍ، وطاقة الفوتون E=hf وتشير لطبيعة الضوء المزدوجة (موجة وجسيم)."}],"qs":[{"q":"في نموذج بور، يبعث الإلكترون طاقة فقط عندما:…","a":["ينتقل بين مستويات الطاقة","يبقى في مداره الثابت","يصطدم بالنواة","يغطي نصف مدار"],"c":0,"d":"medium","hint":"الإشعاع مقابل فرق المستويين","expl":"الصواب: عند الانتقال بين مستويات الطاقة، فيطلق ويبعث فوتوناً أثناء هبوطه ويمتصه عند صعوده. وأثناء ثباته في مداره لا يصدر طاقة. اذهلني ولا يصطدم بالنواة في النموذج البوري. نصيحة: ركّز: \"مستقر لا يصدر، متحول يصدر أو يستهلك\"."},{"q":"أقصى عدد إلكترونات يستوعبها الغلاف الثاني (L) حول النواة هو:…","a":["8 إلكترونات","2 إلكترون","18 إلكترون","32 إلكترون"],"c":0,"d":"easy","hint":"القاعدة العامة 2n²","expl":"الصواب: 8 إلكترونات، لأن 2×2²=8. الأول K: 2 والثالث M: 18، والتوزيع الصحيح يبدأ بالأقرب للنواة. نصيحة: احفظ السلالم: 2، 8، 18، 32 وتستخرجها من 2n²."},{"q":"التأثير الكهروضوئي هو ظاهرة:…","a":["انبعاث إلكترونات من سطح المعدن عند سقوط ضوء بتردد مناسب","تحول المعدن إلى سائل بالتسخين","انكسار الضوء في الماء","تصادم النوى الثقيلة"],"c":0,"d":"easy","hint":"إفتكاك إلكترونات بفوتونات الضوء","expl":"الصواب: انبعاث الإلكترونات من سطح معدن بفعل فوتونات الضوء عند تردد عشرة. لا يخص التحول للسائل ولا انكسار الضوء ولا التصادم النووي. نصيحة: اربط الأسماء: \"كروي الكتروني فوتوني\" = ضوء يكسّر إلكترون المعدن."},{"q":"شرح أينشتاين للتأثير الكهروضوئي عامل أساسي في إثبات أن للضوء:…","a":["طبيعة جسيمية (فوتونات)","طبيعة موجية فقط","سرعة متغيرة","كتلة ضخمة"],"c":0,"d":"medium","hint":"فوتون واحد يضع طاقته في إلكترون واحد","expl":"الصواب: طبيعة جسيمية، لأن تفسير نزوع الإلكترونات بتردد معين لا يستقيم مع الموجة المستمرة فقط، وأثبت أن الضوء كموجة وكجسيم. لا يثبت سرعة متغيرة، والضوء ينحني ويسير بسرعة ثابتة في الخلاء. نصيحة: \"فوتون\" كلمة تعني جسيم ضوئي، والظاهرة الكهروضوئية دليله الأشهر."},{"q":"طاقة الفوتون تُعطى بالعلاقة:…","a":["E = h × f","E = m × c","E = f / h","E = h × λ"],"c":0,"d":"easy","hint":"ثابت بلانك مضروباً في التردد","expl":"الصواب: E = h×f؛ طاقة الفوتون تساوي ثابت بلانك في التردد. الصيغ الباقية تخص معادلات أخرى غير صحيحة هنا. نصيحة: الارتباط المقدس: h مع f دائماً، ونستدل على الطاقة بترددها: كلما زاد التردد زادت الطاقة."},{"q":"أي الأشعة الآتية يملك فوتوناتها أعلى تردد (أقصر طول موجي)؟","a":["أشعة جاما","موجات الراديو","الضوء الأحمر","الأشعة تحت الحمراء"],"c":0,"d":"medium","hint":"تردد أعلى = طاقة أعلى = طول موجي أقصر","expl":"الصواب: أشعة جاما ذات تردد الأعلى وطاقة الفوتونات الأعظم، بينما موجات الراديو هي الأدنى تردداً، والضوء الأحمر أعلى من تحت الحمراء لكنه أدنى من جاما. نصيحة: رتب من الأدنى للأعلى: راديو ← تحت حمراء ← أحمر ← جاما."},{"q":"الإلكترون عند انتقاله من مستوى طاقة أعلى إلى مستوى أدنى:…","a":["يبعث فوتوناً بطاقة تساوي فرق المستويين","يمتص فوتوناً","يتحول إلى نيوترون","يختفي تماماً"],"c":0,"d":"easy","hint":"فرق الطاقتين يخرج كشعاع","expl":"الصواب: يبعث فوتوناً طاقته فرق المستويين (E2−E1)، وهذا أساس أطياف الخطوط. لا يمتص الطاقة المتناقصة إطلاقاً بل يتحرر منها. الخيارات الأخرى لا تتفق مع معلومات نموذج بور. نصيحة: \"نزول = إرسال/إصدار، صعود = امتصاص\" ولتكن قاعدة سريعة."},{"q":"يوصف نموذج بور الذري بأنه أعرض لتنقيح من عمل النماذج السابقة للذرة لأنه:…","a":["اقترح مستويات طاقة محددة يتحرك فيها الإلكترون","ألغى فكرة النواة تماماً","قال إن كل الإلكترونات في موضع واحد","أنكر ظهور الأطياف"],"c":0,"d":"hard","hint":"فكرة \"الكم\" من إسهامه الأساسي","expl":"الصواب: اقترح مستويات طاقة كمية محددة أثمرت تفسير الأطياف والاستقرار. لم يلغ النواة بل أبقاها مركزاً، ولا صحة لوضع الإلكترونات كلها في مكان واحد ولا في خلو الأطياف. نصيحة: بور = بورصة الأغلفة الكمية، فهو من \"كمّم\" ذرة رذرفورد."}]},{"title":"النشاط الإشعاعي","read":[{"h":"أنواع الإشعاع","t":"النواة غير المستقرة تصدر إشعاعات لتصبح أكثر استقراراً: إشعاع ألفا (α): نواتان هيليتان ذرتان موجبتان، شحنته +2، تقاومه ورقة رقيقة، أضعف نفاذاً وأشد تأيناً. إشعاع بيتا (β): إلكترونات سريعة شحنتها −1، نفاذها أعلى (حتى صفيحة ألمنيوم)، من إشعاع ألفا. إشعاع جاما (γ): إشعاع كهرومغناطيسي دون كتلة وشحنة، أعظم نفاذاً، ولا يوقفه إلا طبقة رصاص سميكة أو خرسانة، وتأينه ضعيف."},{"h":"عمر النصف (Half-life)","t":"عمر النصف هو الزمن اللازم لتحلل نصف عدد ذرات العنصر المشع. يحدد النشاط وسرعة التحلل. مثال: عنصر عمر نصفه 5 سنين، فبعد 5 سنوات يتحلل نصف معتاه، وبعد 10 سنوات يتحلل ثلاثة أرباع (بقي الربع). بعد n دورات تبقى الكمية = (1/2)^n × الكمية الأصلية. عمر النصف ثابت لكل نظير مشع مهما تغيرت الظروف."},{"h":"استخدامات النشاط الإشعاعي","t":"للأشعة النووية استخدامات: تشخيص وعلاج الأورام (علاج السرطان بأشعة جاما)، تعقيم الأدوات الطبية والعبوات، تتبع عمليات التمثيل الغذائي بالكواشف المشعة، تحديد أعمار الآثار بأسلوب الكربون المشعـ C-14، وتوليد الطاقة في المحطات النووية. تساعد الكواشف (المقتفيات) العلماء في متابعة تفاعلات داخل جسم دون تدخل جراحي."},{"h":"الوقاية والحماية من الإشعاع","t":"احتياطات السلامة: البعد عن المصدر كلما أمكن (قاسافة تضعف الإشعاع)، التخفيف بالوقت (تقلل زمن التعرض)، الحجب بالحواجز المناسبة (ورق لألفا، ألمنيوم لبيتا، رصاص وخرسانة لجاما)، واستخدام ملاقط تراقب الجرعات. فهم خصائص الإشعاع تحديد نوع الحاجز الأنسب لكل إشعاع."},{"h":"الطاقة النووية والانشطار","t":"الانشطار النووي تفكك نواة ثقيلة كيورانيوم-235 عند امتصاص نيوترون، وينبعث مخزون طاقة هائل + نيوترونات تسرّع التفاعل المتسلسل. المحطات النووية تحول تلك الحرارة لتدوير توربينات تولد الكهرباء، مع مخاطر إدارة النفايات المشعة والحوادث، لذا يشترط حفظها في حاويات محكمة عميقة."},{"h":"خلاصة الدرس","t":"الإشعاعات: ألفا (جسيم +2 نفاذ ضعيف)، بيتا (إلكترون −1 نفاذ متوسط)، جاما (موجة نفاذ عالية). عمر النصف: زمن تحلل نصف الذرات ثابت لكل نظير. استخدامات: علاج، تشخيص، تعقيم، تتبع CO₂، تأريخ آثار، طاقة. الوقاية: مسافة، وقت، حواجز حسب النوع. الطاقة النووية من الانشطار مع اهتمام أمني ونفايات."}],"qs":[{"q":"ترتيب الإشعاعات النووية الثلاثة من الأقل نفاذاً إلى الأعلى نفاذاً هو:…","a":["ألفا ثم بيتا ثم جاما","جاما ثم بيتا ثم ألفا","بيتا ثم ألفا ثم جاما","ألفا ثم جاما ثم بيتا"],"c":0,"d":"easy","hint":"الشحنة والكتلة يتحددان النفاذية","expl":"الصواب: ألفا أضعف نفاذاً (ورقة توقفها)، ثم بيتا (ألمنيوم)، ثم جاما (رصاص/خرسانة). العكس صحيح إذا كان السؤال عن التأين: ألفا أقواها تأيناً. نصيحة: مقياس النفاذ: من الثقيل المشحون الثقيل لأخفّه وأسرعه محفوظ: ألفا < بيتا < جاما."},{"q":"إشعاع ألفا هو في الحقيقة:…","a":["نواة ذرة هيليوم موجبة الشحنة","إلكترون سالب سريع","موجة كهرومغناطيسية ضعيفة","نيوترون حر"],"c":0,"d":"easy","hint":"شحنة +2 كتلته 4","expl":"الصواب: نواة ذرة هيليوم (بروتونان + نيوترونان) بشحنة +2. بيتا إلكترون، جاما موجات، والنيوترون ليس من أنواع الإشعاع الأساسية. نصيحة: ألفا = شحنة 2+ ووزن 4، تماماً كذرة هيليوم.\" "},{"q":"الزمن اللازم لتحلل نصف كمية العنصر المشع في العينة يسمى:…","a":["عمر النصف","الزمن الإشعاعي","الحياة المتوسطة للنيوترون","زمن التفاعل الذري"],"c":0,"d":"easy","hint":"ثابت لكل نظير مشع","expl":"الصواب: عمر النصف Half-life، ألمفهوم الحاسم في حساب نشاط التحلل. لا تسمى بالتسميات الباقية، فالزمن الإشعاعي والحياة المتوسطة مفاهيم مختلفة وتحلل بطرق أخرى. نصيحة: أي سؤال عن \"نصف العينة\" فقارنه بعمر النصف مباشرة."},{"q":"إذا كان عمر النصف لنظير مشع 10 أيام وبقى منه في العينة 12.5% من الكمية الأصلية، فكم مرت من الأيام؟","a":["30 يوماً","20 يوماً","40 يوماً","10 أيام"],"c":0,"d":"hard","hint":"نصف + نصف + نصف = 12.5%","expl":"الصواب: 30 يوماً، لأن 100% ← 50% (بعد 10 أيام) ← 25% (بعد 20) ← 12.5% (بعد 30)، أي ثلاثة أطوار عمر النصف. الخيارات الأخرى لا توافق ثلاث دورات. نصيحة: عدّ الأنصاف: نصف النصف النصف = (1/2)³ = 1/8 = 12.5%."},{"q":"يُستخدم اليود المشع والكواشف النووية في الطب من أجل:…","a":["تشخيص أمراض الغدة الدرقية وتتبع وظائف الجسم","رصد أحوال الطقس فقط","زيادة المحاصيل فقط","تحلية المياه فقط"],"c":0,"d":"medium","hint":"كاشف مشع يدخل الجسم ويتبع مساراً","expl":"الصواب: تشخيص أمراض الغدة الدرقية وتتبع وظائف الجسم عبر المقتفيات المشعة التي تفتش طريقها. الخيارات الأخرى التطبيقات الزراعية والصناعية جزئية ولا تشمل الاستعمال المطلوب. نصيحة: الكاشف المشع = \"جاسوس مشع\" يخبر الأطباء بمسار العمليات الجسمية."},{"q":"أفضل حواجز للوقاية من إشعاع جاما هو:…","a":["طبقة سميكة من الرصاص أو الخرسانة","ورقة رقيقة ورق","لوح خشب رقيق","ملابس قطن عادية"],"c":0,"d":"easy","hint":"نفاذ كبير يحتاج جداراً صلباً كثيفاً","expl":"الصواب: طبقة سميكة من الرصاص أو الخرسانة، فالجزء الأكثر نفاذاً يتطلب كثافة عالية. الورق يوقف ألفا فقط، والخشب والأقمشة لا تقي جاما. نصيحة: جاما = \"جدار حاد القسمة\": رصاص أو خرسانة، وألفا = ورقة، وبيتا = ألمنيوم."},{"q":"الانشطار النووي هو:…","a":["تفكك نواة ثقيلة كاليورانيوم إلى نواتين والتشغيل مع إطلاق طاقة","اندماج نواتين خفيفتين","تحول النواة إلى غاز","انبعاث إلكترون من الذرة"],"c":0,"d":"medium","hint":"قصف النواة الثقيلة بالنيوترونات","expl":"الصواب: تفكك نواة ثقيلة مثل يورانيوم-235 بعد امتصاص نيوترون إلى نواتين متوسطتين مع إطلاق طاقة ونيوترونات تحافظ على التفاعل المتسلسل. اندماج النواتين هو اندماج نووي مختلف، والانبعاث الإلكتروني ليس انشطاراً. نصيحة: \"الانشطار = تقسيم كبير\" و\"الاندماج = دمج كبير\"، ففرق بينهما سريعاً."},{"q":"الطاقة الكهربائية المحطات النووية تستمد حرارتها من:…","a":["تفاعل الانشطار النووي المتحكم فيه","احتراق الفحم","الرياح فقط","طاقة الشمس فقط"],"c":0,"d":"easy","hint":"عملية التحكم المتسلسل داخل المفاعل","expl":"الصواب: من الانشطار النووي المتحكم فيه الذي يسخن الغاية لتدوير التوربين المولد للكهرباء. الفحم متاح في محطات حرارية تقليدية، والريح والشمس متجددان وليسا نوويين. نصيحة: المحطة النووية = مفاعل انشطاري + مولد بخاري + توربين + مولد كهرباء."}]}]},{"title":"الميكانيكا","icon":"⚙️","chapters":[{"title":"القياس والحركة","read":[{"h":"القياس والوحدات","t":"النظام الدولي: الطول (متر m)، الكتلة (كيلوجرام kg)، الزمن (ثانية s)، درجة الحرارة (كلفن K). دقة القياس: الحكم بين قراءات صادقة دقيقة."},{"h":"المسافة والإزاحة والسرعة","t":"الإزاحة مقدار متجه من نقطة البداية للنهاية؛ السرعة = مسافة/زمن (m/s)؛ والعجلة = تغير السرعة/زمن (m/s²)."},{"h":"موذج Graham القوى","t":"القوة أول قانون نيوتن: الجسم يبقى في حالته إلا بقوة خارجية (القصور الذاتي). الثاني: F = ma. الثالث: لكل فعل رد فعل مساوٍ ومعاكس."},{"h":"قوانين الحركة الدقيقة","t":"الثابت: تسارع متساوٍ v = v0 + at؛ x = v0 t + ½ at²؛ v² = v0² + 2ax."},{"h":"الشغل والطاقة","t":"الشغل = القوة × الإزاحة في اتجاهها (واط جول). الطاقة: حركية (KE=½mv²)، وضغطية (PE=mgh). الطاقة محفوظة: لا تفنى ولا تستحدث إلا بتحول."},{"h":"الخلاصة","t":"وحدات القياس الموفقة، والحركة تحت العجلة لتساوية، والقوى (نيوتن) وقوانين الحركة والطاقة المحفوظة — هي أساس الفيزياء الميكانيكية."}],"qs":[{"q":"وحدة قياس القوة في النظام الدولي:…","a":["نيوتن","جول","واط","باسكال"],"c":0,"d":"easy","hint":"الاسم يحمله"},{"q":"قانون نيوتن الثاني معادلته:…","a":["F=ma","F=mv","E=mc²","V=IR"],"c":0,"d":"easy","hint":"تسارع"},{"q":"السرعة = :…","a":["مسافة/زمن","زمن/مسافة","قوة/كتلة","كتلة×عجلة"],"c":0,"d":"easy","hint":"قسمة"},{"q":"طاقة الحركة تعبر بـ:…","a":["½mv²","mgh","½mv","Fd"],"c":0,"d":"medium","hint":"كتلة×سرعة مربع"},{"q":"القصور الذاتي يشرحه:…","a":["قانون نيوتن الأول","الثاني","الثالث","الثقل"],"c":0,"d":"easy","hint":"حالة بدون قوة"},{"q":"وحدة الشغل والطاقة:…","a":["جول","نيوتن","كلفن","أمبير"],"c":0,"d":"easy","hint":"W=Fd"}]},{"title":"الكهرباء والمغناطيسية","read":[{"h":"الكهرباء الساكنة","t":"الشحنات تتجمع بالاحتكاك؛ قاعدة: (متعاكسات تجاذب) والأسماء المتشابهة تتجاوب. قانون كولوم: القوة تتناسب عكسياً مع مربع المسافة."},{"h":"التيار الكهربائي","t":"حركة الإلكترونات في موصل؛ قانون أوم: V = IR؛ ربط الأجهزة بالتوالي او التوازي بأثر على الجهد والتيار."},{"h":"قانون أوم تطبيقياً","t":"مصدر جهد (بطارية) يحرض التيار عبر مقاومة؛ ذروة: الفولط = أمبير × أوم. الطاقة: P = VI (واط)."},{"h":"الدوائر","t":"توالي: التيار ثابت والمقاومة تجمع؛ تواز: الفولط ثابت وكل فرع مستقل."},{"h":"المغناطيسية","t":"المواد المغناطيسية (حديد، نيكل، كوبالت)؛ القطب الشمالي والجنوبي للمغناطيس؛ متعاكسان يتجاذبان. قلب حديد يرفع شدة المجال (المغناطيس الكهربائي)."},{"h":"الخلاصة","t":"شحنات وكولوم، تيار بشكلٍ V=IR، دوائر توالي/تواز، مغناطيس وهندسة الحقن؛ ومجالات دينامو فيولت المولدات."}],"qs":[{"q":"قانون أوم:…","a":["V=IR","F=ma","E=mc²","P=mgh"],"c":0,"d":"easy","hint":"فولط"},{"q":"وحدة التيار:…","a":["أمبير","فولط","أوم","واط"],"c":0,"d":"easy","hint":"شدة"},{"q":"في التوصيل توالي:…","a":["التيار ثابت والمقاومات تجمع","الفولط ثابت","القدرة معدومة","لا يمر تيار"],"c":0,"d":"easy","hint":"سلسلة"},{"q":"الشحنات المتشابهة:…","a":["تتنافر","تتجاذب","تتعادل","تتبادل"],"c":0,"d":"easy","hint":"متعاكسة"},{"q":"القدرة الكهربائية = :…","a":["P=VI","P=IR","P=V/R","P=I/R"],"c":0,"d":"medium","hint":"فولط×تيار"},{"q":"قطب المغناطيس المتشابهة:…","a":["يتنافران","يتجاذبان","يحجبان","يذوبان"],"c":0,"d":"easy","hint":"أقطاب"}]}]},{"title":"الضوء والصوت","icon":"💡","chapters":[{"title":"الضوء والانعكاس والانكسار","read":[{"h":"طبيعة الضوء","t":"الضوء موجات كهرومغناطيسية ينتقل في الفراغ بسرعة 3×10⁸ م/ث؛ أشكاله: مرآة، انعكاس، انكسار، حيود، تشتت (قوس قزح)."},{"h":"الانعكاس","t":"سقوط الضوء على سطح: قواعد الانعكاس - زاوية السقوط = زاوية الانعكاس. المرايا: مستوية (صورة معتدلة خيالية مقلوبة)، محدبة (مصغرة)، مقعرة (مكبرة في حالات)."},{"h":"الانكسار","t":"انحراف الضوء عند انتقاله بين وسطين (هواء→زجاج/ماء). مؤشر الانكسار n = سرعة الفراغ / سرعة الوسط."},{"h":"العدسات","t":"محدبة (مجمع) تولد صورة حقيقية مقلوبة على بؤرة، محدبة توصل البنية الكبرى؛ مقعرة (ناشر الفكر) صورة خيالية مصغرة."},{"h":"أجزاء العين","t":"القرنية، الحدقة، العدسة، الشبكية؛ تحدب العدسة نجيد تركيز الصورة (انقباض/ارتخاء). التصحيح: لقصر النظر عدسة مقعرة، ولبعد النظر محدبة."},{"h":"الخلاصة","t":"الضوء موجات سريعة: انعكاس بقاعدة الزوايا، انكسار بتغير الوسط، عدسات محدبة/مقعرة، وعلوم العين بالإبصار."}],"qs":[{"q":"سرعة الضوء في الفراغ:…","a":["3×10⁸ م/ث","340 م/ث","3000 م/ث","10⁶ م/ث"],"c":0,"d":"easy","hint":"سرعة هائلة"},{"q":"زاوية السقوط = زاوية:…","a":["الانعكاس","الانكسار","الانحراف","الحيود"],"c":0,"d":"easy","hint":"مرآة"},{"q":"العدسة المحدبة تعمل:…","a":["مجمع الضوء","ناشرة","ممتصة","مشتتة"],"c":0,"d":"easy","hint":"مجمع"},{"q":"صورة المرآة المستوية:…","a":["معتدلة خيالية","حقيقية مقلوبة","مكبرة","مصغرة"],"c":0,"d":"easy","hint":"خيالية"},{"q":"قصر النظر يصحح بعدسة:…","a":["مقعرة","محدبة","سطوح","أسطوانية"],"c":0,"d":"medium","hint":"تشظي"},{"q":"العدسة المجمعة صورة جسم بعيد:…","a":["حقيقية مقلوبة","خيالية معتدلة","معكوسة مصغرة","لا صورة"],"c":0,"d":"medium","hint":"أقرب من البؤرة"}]}]}]},{"id":"chemistry","name":"الكيمياء","icon":"🧪","color":"#9C27B0","books":[{"title":"كيمياء غير العضوية","icon":"⚗️","chapters":[{"title":"الفلزات الانتقالية ومركباتها","read":[{"h":"الفلزات الانتقالية","t":"الفلزات الانتقالية عناصر تقع في وسط الجدول الدوري (المجموعات 3 إلى 12)، من أشهرها: الحديد، النحاس، الزنك، الكروم، المنغنيز، التيتانيوم. تتميز بأن إلكتروناتها تكتمل تدريجياً في الأغلفة الداخلية، وتتعدد حالات تأكسدها، وتكوّن مركبات ملونة، وتستخدم كمحفزات كثيراً. عنصرها الاستثنائي هو أنها تظهر خواص فلزية عالية كاللمعان والموصلية والصلابة."},{"h":"أكاسيد الفلزات الانتقالية","t":"تتفاعل الفلزات الانتقالية مع الأكسجين مشكلة أكاسيد، وتختلف خواص تلك الأكاسيد: بعضها قاعدي كأكسيد الحديد الثنائي FeO، وبعضها حمضي كأكسيد الكروم السداسي CrO₃، وبعضها متعدد الحالات مثل أكاسيد المنجنيز. تستخدم أكاسيد الفلزات كأصباغ (الحديد يلون البناء بالبني الأحمر)، وفي صناعة الزجاج والخزف والوسطية المغناطيسية."},{"h":"الأكسدة الأنودية (الأكسدة الكهربائية)","t":"عملية تكوين طبقة أكسيد واقية على سطح الفلز (خاصة الألومنيوم) بجعله الأنود (القطب الموجب) في خلية التحليل الكهربائي. الطبقة المتكونة تحمي المعدن من التآكل، وتزيد مقاومة الخدش، ويمكن صبغها مباشرة بألوان جميلة فالمنتجات في الألمنيوم المؤكسد (أواني، أبواب، هياكل دراجات هوائية) مألوفة في الحياة."},{"h":"الفلزات الانتقالية كمحفزات","t":"تُعتبر الفلزات الانتقالية ومركباتها من أهم المحفزات في الصناعة: الحديد يحفز تصنيع الأمونيا بطريقة هابر، النيكل يحفز هدرجة الزيوت في صناعة المارجرين، النحاس يستخدم في كثير من التفاعلات، ومحولات عوادم السيارات تستخدم البلاتين والبلاديوم لتحويل الغازات السامة إلى أقل ضررًا. المحفز يسرّع التفاعل دون أن يستهلك نفسه."},{"h":"الاستخدامات الحياتية","t":"الفلزات الانتقالية أساس الصناعة والعمارة: الحديد فولاذ البناء، النحاس الأسلاك الكهربائية والمواسير، الكروم طلاء مضاد للصدأ وفولاذ لا يصدأ، المنجنيز يقوي السبائك، التيتانيوم في الطائرات والزراعات الطبية لمع التوازن والخفوة. اللون في جواهر مثل \"الزمرد\" يرتبط بوجود أيونات الكروم الممتدة."},{"h":"خلاصة الدرس","t":"الفلزات الانتقالية: وسط الجدول، حالات تأكسد متعددة، مركبات ملونة، محفزات فعالة. أكاسيدها إما قاعدية أو حمضية أو متعددة. الأكسدة الأنودية تحمي الألومنيوم بطبقة أكسيد قابلة للصبغ. محفزاتها: حديد للأمونيا، نيكل لزيوت، وبلاكين للعوادم. وهي عماد البنية والصناعة."}],"qs":[{"q":"من أمثلة الفلزات الانتقالية الواردة بالمنهج:…","a":["الحديد والنحاس والكروم","الصوديوم والبوتاسيوم","المغنيسيوم والكالسيوم","الألومنيوم فقط"],"c":0,"d":"easy","hint":"عناصر وسط الجدول الدوري","expl":"الصواب: الحديد والنحاس والكروم، من عناصر المجموعات الانتقالية. الصوديوم والبوتاسيوم فلزات قلوية، والمغنيسيوم والكالسيوم قلوية ترابية، والألومنيوم فلز عادي ويأتي لاحقاً. نصيحة: فلزات انتقالية \"وسط الدوري\" وفلزات أخرى \"أطرافه\" على اليسار."},{"q":"أكسدة الألومنيوم الكهربائية (الأنودية) تهدف إلى:…","a":["تكوين طبقة أكسيد واقية وجميلة على سطحه","إذابة الألومنيوم كلياً في الماء","تحويله إلى بخار","جعل الألومنيوم موصلاً للكهرباء أكثر"],"c":0,"d":"medium","hint":"الأنود هو القطب الذي يحدث عليه التأكسد","expl":"الصواب: تكوين طبقة أكسيد واقية تحمي من التآكل وتمنع مزيداً من الأكسدة وتقبل الأصباغ، فيكون الألومنيوم أكثر صلاباً وأجمل. لا يُذاب ولا يصبح بخاراً، وهو أصلاً موصل جيد للكهرباء. نصيحة: الأنودية = \"درع أكسيدي\"؛ حرف \"أ\" في الأنود يعني الأكسدة."},{"q":"لتحفيز تصنيع غاز الأمونيا (طريقة هابر) يُستخدم فلز:…","a":["الحديد","النيكل","النحاس","الفضة"],"c":0,"d":"medium","hint":"محفز صناعة NH₃","expl":"الصواب: الحديد، وهو المحفز الكلاسيكي لتفاعل النيتروجين والهيدروجين في عملية هابر. النيكل يستخدم في هدرجة الزيوت، والنحاس في تفاعلات كثيرة، والفضة في عمليات أكسدة مختارة. نصيحة: \"هابر حديد، وزيوت نيكل\": جملة تربط المحفز بموقعه."},{"q":"الخواص المميزة للفلزات الانتقالية أنها:…","a":["تتعدد حالات تأكسدها وتكوّن مركبات ملونة","عديمة الحالات التأكسدية","لا تكوّن مركبات","لون أبيض فضي فقط دائماً"],"c":0,"d":"easy","hint":"فراغ الإلكترونات في الأغلفة الداخلية","expl":"الصواب: تعدد حالات التأكسد وتكوين مركبات ملونة من أهم خصائصها، لأن إلكترونات d تشارك في التفاعلات بدرجات مختلفة. تنفرد بتلك المرونة عن فلزات أطرف الجدول. نصيحة: تذكّر \"متعدد الألوان والحالات\" علامة مميزة سريعة لفلز انتقالي."},{"q":"أيون النحاس الثنائي Cu²⁺ محلوله المائي يكون لونه:…","a":["أزرق","أحمر قرمزي","عديم اللون","أخضر داكن"],"c":0,"d":"easy","hint":"من أشهر الألوان المرتبطة بمركبات النحاس","expl":"الصواب: أزرق، وهو لون محلول كبريتات النحاس المشهور في المختبرات والتجارب. الألوان الأخرى لا تخص الأيون هذا مباشرة، فهي مرتبطة بعناصر أخرى. نصيحة: ربط رقمي: \"Cu ثنائي = أزرق\"، فإذا شاهدت محلولاً أزرقاً فكر في النحاس."},{"q":"يعمل النيكل كمحفز في عملية:…","a":["هدرجة الزيوت لصناعة المارجرين","تحميص الخبز","تقطير البترول","صناعة الصابون بالتبريد"],"c":0,"d":"hard","hint":"إضافة الهيدروجين للروابط المزدوجة","expl":"الصواب: هدرجة الزيوت النباتية لتحويل الروابط المزدوجة إلى مفردة فتصبح الزيوت صلبة أو سائلة واكتساب قوام المارجرين. لا يشارك في تحميص الخبز ولا تقطير البترول ولا صناعة الصابون بهذا التشكيل. نصيحة: \"نيكل = هدرجة الزيوت\"، و\"الحديد = الأمونيا\"، احفظ الزوجين معاً."},{"q":"الكروم يستخدم بصورة واسعة في صناعة:…","a":["الفولاذ المقاوم للصدأ وطلاء الحماية","الوقود الأحفوري","الأسمدة النيتروجينية","الطلاء الزيتي فقط"],"c":0,"d":"medium","hint":"يضيف صلابة ومنع صدأ","expl":"الصواب: الفولاذ المقاوم للصدأ وطلاء حماية المعادن (كروم طلاء لمي) لأنه لا يتأكسد. لا يستخرج وقوداً ولا نيتروجيناً كأسمدة بهذا المعنى المباشر. نصيحة: \"الكروم كرومية = لمعان لا يصدأ\"، وهو سر الصلب اللامع في الأدوات."},{"q":"طبقة الأكسيد التي تتكون على الألمنيوم المؤكسد أنودياً تتميز بأنها:…","a":["صبغوها الجمال والحماية من التآكل","تجعله هشاً فوراً","تذوب في الماء","تخفض صلابته"],"c":0,"d":"medium","hint":"طبقة رقيقة متينة فوق المعدن","expl":"الصواب: تمثل درعاً واقية قابلة للصبغ، فتزيد مقاومة التآكل والخدش وتفتح مجال الطلاء الألواني. لا تسبب الهشاشة ولا تذوب بالماء ولا تخفض الصلابة. نصيحة: صورة ذهنية: \"بدلة حماية ملونة للألمنيوم كلوحة الجدران\"."}]},{"title":"الأحماض والقواعد","read":[{"h":"الأحماض والقواعد وخصائصها","t":"الحمض مادة تمنح أيون الهيدروجين H⁺ عند ذوبانها في الماء، والقلوية (القاعدة) مادة تقبل H⁺ أو تمنح OH⁻. طعام الأحماض: طعم حامض (الليمون، الخل)، تحويل ورقة عباد الشمس الزرقاء للأحمر، تتفاعل مع الفلزات مطلقة هيدروجيناً. القواعد: طعم مر، ممصّة قابضة، تحوّل عباد الشمس الأحمر للأزرق، ويصبح عند ذوبانها في الماء رحيقاً مكة. أحماض مشهورة: HCl حمض الهيدروكلوريك، H₂SO₄ الكبريتيك، CH₃COOH الخليك."},{"h":"مقياس pH","t":"مقياس أس الهيدروجين يحدد درجة حموضة المحلول من 0 (أقصى حمضية) حتى 14 (أقصى قلوية)، والقيمة 7 تعني تعادلاً (ماء نقي). المحلول الأقل من 7 حمضي، والأعلى من 7 قاعدي. الفرق في درجة واحدة يمثل فرقاً بمقدار 10 أضعاف في التركيز، وجودة الماء في ارتفع من 3 إلى 5 يعني حموضة أقل بمئة مرة."},{"h":"التعادل والمعايرة","t":"التعادل تفاعل الحمض مع القاعدة لإنتاج ملح وماء: H⁺ + OH⁻ → H₂O، وينتج عند اختيار كميتين متعادلتين بالتوازن. المعايرة طريقة تجريبية لتحديد تركيز مجهول: يُسقط محول قاعدي معلوم التركيز تدريجياً على حمض مجهول في دورق مع كاشف كيميائي (مثل الفينول فثالين) يتغير لونه عند نقطة التعادل، ثم نحسب التركيز من القانون C₁V₁ = C₂V₂."},{"h":"المحاليل المنظمة (المخازن التصريفية)","t":"محاليل تتغير قيمة pH فيها بصورة شبه ثابتة عند إضافة حمض أو قاعدة بكميات قليلة أو التخفيف، وتتكون عادة من حمض ضعيف مع ملحه من قاعدة قوية (مثل حمض الخليك + خلات الصوديوم) أو قاعدة ضعيفة مع ملحها. تنظم هذه المحاليل pH في السوائل البيولوجية (دم الإنسان يعمل كمنظم)، وفي صناعات الأدوية والتحاليل الدقيقة."},{"h":"تطبيقات حيوية وصناعية","t":"للأحماض والقواعد تطبيقات: حمض الهيدروكلوريك في المعدة لعامل الهضم، حمض الكربونيك في المشروبات الغازية، الأمونيا والقواعد في منظفات، هيدروكسيد الصوديوم لصناعة الصابون، ولعلاج حموضة المعدة نستخدم مضادات حموضة قاعدية تتفاعل لتعديل التوازن. الحموضة في التربة تشجع تكليف الفلاحين لضبطها بالجير."},{"h":"خلاصة الدرس","t":"الحمض يمنح H⁺ ويحمر أزرق الشمس، والقاعدة تقبل H⁺ وتزرق أحمرها. pH من 0 إلى 14 والتوازن 7. التعادل H⁺+OH⁻→H₂O والمعايرة C₁V₁=C₂V₂ مع كاشف لوني. المحاليل المنظمة تحفظ pH شبه ثابت وهي سر استقرار الدم وصناعة المواد الحيوية."}],"qs":[{"q":"عند إضافة ورقة عباد الشمس الزرقاء إلى محاليل حمضية تتحول إلى اللون:…","a":["الأحمر","الأزرق","الأخضر","عديم اللون"],"c":0,"d":"easy","hint":"خاصية حضائرة الأصول","expl":"الصواب: الأحمر، فهي المؤشر الكلاسيكي للحموضة وأما القاعدة فتحول الحمراء للأزرق. لا تبقى زرقاء ولا خضراء ولا عديمة اللون. نصيحة: الجملة السحرية: \"الحمض أحمر، والقلوي أزرق\" واستخدمها كأنها إشارة لون الطريق."},{"q":"ماء مقطر نقي عند درجة الحرارة العادية يكون رقم pH نحو:…","a":["7","0","14","3"],"c":0,"d":"easy","hint":"التعادل التام","expl":"الصواب: 7 قيمة التعادل للماء النقي. الصفر أعلى الحموضة، و14 أعلى القلوية، و3 حمضي واضح. نصيحة: حفظ سريع: ماء نقي = 7، أقل من 7 حمضي، وأكثر من 7 قاعدي."},{"q":"عندما ترتفع درجة حموضة محلول من 4 إلى 6، فإن هذا يعني أن قوة الحموضة:…","a":["تناقصت إلى المئة","تناقصت إلى العشرة","ازدادت إلى العشرة","لا تغير"],"c":0,"d":"hard","hint":"كل وحدة pH فرق 10 أضعاف","expl":"الصواب: تناقصت إلى المئة، لأن ارتفاع رقم pH نقطتين يعني كل وحدة أنقاص حموضة 10 أضعاف، فأصبحت حموضة أقل بمقدار 10×10=100. إذا انتقل من 4 إلى 2 فالحموضة تتضاعف مئة مرة بالعكس. نصيحة: حقق من هذا المكان: \"كل تقدم وحدة = ÷10 حموضة\"، في رقمين = ÷100."},{"q":"معادلة تفاعل التعادل الحمضي والقاعدي تنتج:…","a":["ملحاً وماء","حمضاً وماء","قاعدة وملح فقط","غاز النيتروجين"],"c":0,"d":"easy","hint":"H⁺ + OH⁻ → H₂O","expl":"الصواب: ملحاً وماء، وهذا التعريف القياسي للتفاعل. لا ينتج حمضاً ولا قاعدة، وانبعاث النيتروجين غير الأساسي هنا. نصيحة: تذكّر: \"حمض + قاعدة = ملح + ماء\" كأنها صفقة تبادل مكونة."},{"q":"الغرض من المعايرة (التاِترج) في الكيمياء هو:…","a":["تحديد تركيز محلول مجهول بواسطة محلول معروف","غليان المحاليل","تغيير لون الورق","تجفيف الأملاح"],"c":0,"d":"medium","hint":"عملية قياس الكمية المتعادلة","expl":"الصواب: تحديد تركيز محلول مجهول عبر إضافة معلوم التركيز تدريجياً حتى نقطة التعادل ثم الحساب بالعلاقة C₁V₁=C₂V₂. لا تهتم بغليان أو تجفيف أو تغيير لون الورق بذاته. نصيحة: المعايرة = \"ميزان التركيز المخبري\"، وتسجل نقطة النهاية بلون الكاشف."},{"q":"مثال على حمض ضعيف يوجد بصورة طبيعية في الطعام هو:…","a":["حمض الخليك (الخل)","حمض الهيدروكلوريك","حمض الكبريتيك","حمض النيتريك"],"c":0,"d":"easy","hint":"حمض التجارب والمطبخ الآمن","expl":"الصواب: حمض الخليك الموجود في الخل، فهو حمض عضوي ضعيف. الهيدروكلوريك والكبريتيك والنيتريك أحماض معدنية قوية تؤدي للتآكل ولا توضع في الطعام. نصيحة: \"الأطعمة = أحماض عضوية ضعيفة؛ الأحماض المعدنية = قوية وخطرة\"."},{"q":"المحلول المنظم (المنظم الحيوي) يتميز بأن:…","a":["يحافظ على شبه ثبات pH عند إضافة حمض أو قاعدة بكميات قليلة","يتغير لونه كل ثانية","يمنح حرارة كبيرة جداً","يوصل الكهرباء فقط دون معنى"],"c":0,"d":"medium","hint":"مقاومة تغير الحموضة","expl":"الصواب: يحافظ على ثبات pH شبه التام، بتعويض أي اضافية حمض أو قاعدة قليلة. هذه هي خاصية نظام الدم والأدوية والمحاليل الحيوية. الخيارات الأخرى لا تصف وظيفته. نصيحة: المنظم = \"حارس التوازن\" يحافظ على الرقم رغم ضغوط الإضافة."},{"q":"لقياس حموضة أو قلوية محلول يعتمد مؤشر عباد الشمس على:…","a":["تغير اللون بتغير طبيعة الحل","الذوبان في الحرارة","التطاير في الهواء","الترسيب في القاع"],"c":0,"d":"easy","hint":"وسيلة ملاحظة سريعة","expl":"الصواب: تغير اللون بتغير طبيعة المحلول: أحمر في حمض وأزرق في قاعدة (وفي النقطة المتعادلة أخضر أحياناً). لا يعتمد مؤشر العباد على الذوبان الحراري ولا التطاير ولا الترسب. نصيحة: مؤشر = \"مرآة للألوان\": كلما تغير الوسط تغيّر لونه."}]}]},{"title":"كيمياء عضوية","icon":"🧪","chapters":[{"title":"الهيدروكربونات","read":[{"h":"الهيدروكربونات وأنواعها","t":"الهيدروكربونات مركبات تتكون من الكربون والهيدروجين فقط، وهي أساس النفط والغاز الطبيعي. تنقسم إلى: الألكانات (مشبعة روابط مفردة)، الألكينات (روابط مزدوجة)، والألكاينات (روابط ثلاثية). الصيغة العامة: الألكان CnH(2n+2)، والألكين CnH(2n)، والألكاين CnH(2n−2) مع الصيغة المناسبة لكل منها."},{"h":"التسمية (IUPAC)","t":"نسمي السلسلة الطويلة من الكربونات أساس الاسم، ورقم الذرات يبدأ من الطرف الأقرب للتفرع أو الرابطة المتعددة، ثم نذكر مواضع وأسماء الاستخلاصات (ميثيل، إيثيل). بادئة، عدد وحجم الذرات وفق السلسلة (ميث، إيث، بروب، بيوت، بنت...) ولاحقة تدل على النوع: −ان (ألكان)، −إين (ألكين)، −اين (ألكاين). مثال: بروبـ2ـين مطلقة تعبر عن رابطة مزدوجة بين الكربون الثاني والثالث."},{"h":"الخواص الفيزيائية الأساسية","t":"الألكانات الأربعة الأولى غازات، والخامس حتى السابع عشر سوائل يزداد لزوجتها، والأعلى منها مواد شمعية صلبة. الروابط المفردة المشبعة تجعل الألكانات أقل تفاعلاً من الألكينات والألكاينات غير المشبعة، وتساعد الروابط المتعددة على تفاعلات الإضافة: إضافة الهيدروجين (هدرجة) أو هالوجين (وهالوجين). الألكانات ذات الروابط المشبعة يشاركون أساساً في تفاعلات الإحلال لا الإضافة."},{"h":"التفاعلات المهمة","t":"الاحتراق: تتحد الهيدروكربونات مع الأكسجين وتنتج CO₂ وماء وطاقة (الوقود). الهدرجة: إضافة الهيدروجين لروابط مزدوجة بوجود نيكل محلول (تحويل الزيوت). الهلجنة بالإحلال للألكانات: ذرة هيدروجين تستبدل بهالوجين كالكلور بوجود ضوء. الإضافة للألكينات والألكاينات: كسر رابطة π وإضافة ذرات جديدة عبر الرابطة المزدوجة."},{"h":"التكسير (Cracking)","t":"التكسير كسر في الروابط الكيميائية لجزيئات الهيدروكربونات الكبيرة (مثل تلك الموجودة في النفط الخام) إلى جزيئات أصغر مفيدة كالبنزين، بإحدى طريقتين: التكسير الحراري بالحرارة الشديدة، والتكسير الحفزي بوجود محفز وضغط، والأخير أدق وأكثر إنتاجية للبنزين المرغوب. واستخدامه لزيادة انتاج المشتقات القيمة من النفط الخام هدف التكرير."},{"h":"خلاصة الدرس","t":"الألكان مشبع CnH(2n+2)، الألكين رابطة مزدوجة CnH(2n)، الألكاين ثلاثية CnH(2n−2). التسمية: أطول سلسلة + الأقرب للرابطة + اللواحق. التفاعلات: احتراق، هدرجة، إضافة (لغير المشبع)، إحلال (للمشبع). التكسير يحول الكبير لصغير (بنزين). النفط مشروع كيمياء يومية."}],"qs":[{"q":"الصيغة الجامعية للألكانات (مشبعة) هي:…","a":["CnH(2n+2)","CnH(2n)","CnH(2n−2)","CnH(n)"],"c":0,"d":"easy","hint":"لا روابط مزدوجة وكتلة هيدروجين أقصى","expl":"الصواب: CnH(2n+2) آخر ما يصل إليه الهيدروجين في وصلات مفردة (الميثان CH₄). CnH(2n) للألكينات وCnH(2n−2) للألكاينات. نصيحة: احفظ العائلة: \"+2 مشبع، 0 مزدوج، −2 ثلاثي\"."},{"q":"رابطة كيميائية موجودة في جميع الألكينات هي:…","a":["رابطة مزدوجة واحدة على الأقل","رابطة ثلاثية دائماً","رابطة أيونية","رابطة تناسقية"],"c":0,"d":"easy","hint":"لاحقة −ين في أسمائها للدلالة","expl":"الصواب: رابطة مزدوجة واحدة على الأقل بين ذرتين، فهم غير المشبع. الألكاين هو الثلاثي، والألكانات لا تحتوي ولا أيونية في الهيدروكربونات (روابط تساهمية). نصيحة: \"2ن\" وكأن اللاحقة \"إين\" تذكرك بـ\"رابطة 2 (مزدوجة)\"."},{"q":"عند إضافة الهيدروجين إلى الإثيلين (C₂H₄) بوجود النيكل ينتج:…","a":["الإيثان","الأسيتيلين","الإيثانول","الكلوروإيثان"],"c":0,"d":"hard","hint":"إشباع الرابطة المزدوجة بالهيدروجين","expl":"الصواب: الإيثان C₂H₆، لأن الهدرجة تشبع الرابطة المزدوجة C₂H₄+H₂→C₂H₆. لا ينتج أسيتيلين (ثلاثي) ولا إيثانول (هيدروكسيل) ولا كلورومشتق. نصيحة: الهدرجة = \"مصفوفة هيدروجين\" تحول المزدوج إلى مفرد: إيثيل→إيثان."},{"q":"التفاعل الرئيسي الذي تشترك فيه الألكانات المشبعة هو:…","a":["الإحلال (الاستبدال)","الإضافة","التركيب الجمعي","البلمرة"],"c":0,"d":"medium","hint":"لا روابط مزدوجة للانفتاح","expl":"الصواب: الإحلال، إذ تستبدل ذرة هيدروجين بهالوجين مثل الكلور بوجود الضوء. الألكانات لا تقبل إضافة بمعنى فتح رابطة لأنها لا تملك روابط π، أما الإضافة والبلمرة فتخص غير المشبع. نصيحة: \"مشبع = إحلال فقط، وغير مشبع = إضافة وبلمرة\"."},{"q":"استخدام الهيدروكربونات كوقود يعتمد على تفاعل:…","a":["الاحتراق مع الأكسجين","التبخر البسيط","التعادل","الأكسدة القليلة"],"c":0,"d":"easy","hint":"طاقة حرارية من الاتحاد مع O₂","expl":"الصواب: الاحتراق، وهو اتحاد الهيدروكربون بالأكسجين منتجاً CO₂ وH₂O وطاقة حرارية. التبخر لا يولد الطاقة ولا التعادل ولا أكسدة جزئية بهذا المعنى. نصيحة: الاحتراق = \"وقود + أكسجين = طاقة\"، سبب المواد المشتعلة في بيوتنا وسياراتنا."},{"q":"التكسير الحفزي للهيدروكربونات الكبيرة يركز على:…","a":["تحويلها إلى جزيئات أصغر مثل البنزين","زيادة حجم الجزيئات","تكوين أملاح","إنتاج الأمونيا"],"c":0,"d":"medium","hint":"قيمة على النفط الخام الجميل","expl":"الصواب: تحويل الجزيئات الكبيرة إلى أصغر وأنفع مثل البنزين المشتق المرتفع الاستهلاك. لا يزيد الألياف ولا يكوّن أملاحاً ولا ينتج أمونيا. نصيحة: \"التكسير = تكسير كبير لصغير\"؛ ربط النفط بالبنزين بوابة الربح."},{"q":"المركب CH₄ هو:…","a":["الميثان","الإيثان","البروبان","البوتان"],"c":0,"d":"easy","hint":"أصغر ألكان","expl":"الصواب: الميثان، وهو غاز طبيعي أساسياً بأربعة هيدروجينات وذرة كربون واحدة. الإيثان C₂H₆ والبروبان C₃H₈ والبوتان C₄H₁₀ المترتبون بعده. نصيحة: سلم الكربونات: ميث=1، إيث=2، بروب=3، بيوت=4، وبنت=5."},{"q":"المجموعة (السلسلة المتجانسة) التي تحتوي على رابطة ثلاثية هي:…","a":["الألكاينات","الألكانات","الألكينات فقط صيغة C₂H₄","الأرومايات"],"c":0,"d":"easy","hint":"الأسيتيلين مثالها الأشهر","expl":"الصواب: الألكاينات ذات الرابطة الثلاثية مثل الأسيتيلين C₂H₂. الألكانات مفردة والألكينات مزدوجة، والأرومايات حلقات عطرية. نصيحة: \"اين/اين\": فخرى واضحة، ١ مفرد، ٢ مزدوج، ٣ ثلاثي."}]},{"title":"المؤثرات الحيوية (الكيمياء الحيوية العضوية)","read":[{"h":"الكحولات والأحماض الكربوكسيلية","t":"الكحولات مركبات عضوية تحتوي مجموعة الهيدروكسيل OH⁻ مرتبطة بسلسلة كربونية؛ مثال: إيثانول (مشروب روحي وتكفير، وقود حيوي)، وله خواص قلة نسبية السمية في الأعشاب. الأحماض الكربوكسيلية تحتوي مجموعة الكوكسيل COOH، مثل حمض الأسيتيك (خل) وحمض الستريك (ليمون)، وتتفاعل مع الكحولات في تفاعل الأسترة منتجة إسترات عطرية وماء."},{"h":"البروتينات الأحماض الأمينية","t":"البروتينات بوليمرات طبيعية من وحدات صغيرة تسمى الأحماض الأمينية ترتبط ببعض بروابط ببتيدية. وهي وحدات بناء الجسم (العضلات، الأنزيمات، الأجسام المضادة). عند هضم البروتين في الجسم يُفكك إلى أحماض أمينية ثم يعاد ترتيبها بحسب الكود الوراثي إلى بروتينات أخرى. كل حمض أميني له مجموعة أمين NH₂ ومجموعة كربوكسيل COOH."},{"h":"الكربوهيدرات والدهون","t":"الكربوهيدرات مركبات تحتوي الكربون والهيدروجين والأكسجين (سكريات ونشويات)، وتعمل مصدراً سريعاً للطاقة: الجلوكوز والألياف. السكريات الأحادية كالجلوكوز والفركتوز، والثنائية كالسكروز (سكر المائدة) ولاكتوز (لبن)، والمتعددة كالنشا والسليولوز والجليكوجين. الدهون (الشحوم) استرات للأحماض الدهنية والجلسرول: تخزن طاقة أعلى وإحاطة الأعضاء وبناء الأغشية، وفائضها يتراكم مسبباً سمنة."},{"h":"البوليمرات","t":"البوليمر جزيء ضخم من وحدات مكررة تسمى المونومرات. بوليمرات طبيعية: نشا، سليولوز، بروتين، ومعظمها عضوي. بوليمرات اصطناعية: بولي إيثيلين (أكياس)، بولي فينيل كلورايد PVC (مواسير)، وبوليمرات تكثيف مثل النايلون والبوليستر. تختلف خواص البوليمر حسب نوع المونومر وطريقة الترابط (تضاعف الإضافة مقابل التكثيف)."},{"h":"الصابون","t":"الصابون ملح صوديوم أو بوتاسيوم لأحماض دهنية. يتكون من رأس محب للماء (مقبول H₂O) وذيل كاره للماء (يجذب الزيوت)، فيعمل كأنه \"جسر\" يجمع الزيت مع الماء فيستحلب الدهن ويُغسل. يصنع بالتسخين الساخن للزيوت أو الدهون مع هيدروكسيد الصوديوم (التصبن)، وسبب كفاءته أنه يكوّن مذيلاً يحمل الاتربة وقطرات الزيت بعيداً عن القماش."},{"h":"خلاصة الدرس","t":"كحولات (OH) وأحماض كربوكسيلية (COOH) تنتج الإسترات عطرة. بروتينات من أحماض أمينية بروابط ببتيدية = وحدات بناء الجسم. كربوهيدرات طاقة سريعة (جلوكوز ونشا)، ودهون طاقة مركزة. بوليمرات: طبيعية (نشا، بروتين) واصطناعية (بولي إيثيلن، PVC). صابون \"ذيل كاره للماء ورقبة محبة للماء\" يطرد الدهون عن الملابس."}],"qs":[{"q":"المجموعة الوظيفية التي تميز الكحولات هي:…","a":["الهيدروكسيل OH","الكربوكسيل COOH","الأمين NH₂","الألدهيد CHO"],"c":0,"d":"easy","hint":"الصيغة الإيثانول CH₃CH₂OH","expl":"الصواب: الهيدروكسيل OH المرتبط بالسلسلة الكربونية. COOH تميز الأحماض الكربوكسيلية، وNH₂ تميز الأمينات، وCHO الألدهيدات. نصيحة: \"OH = كحول، COOH = حمض، NH₂ = أمين\" الثلاثي الأول في تصنيف المؤثرات."},{"q":"الوحدة الأساسية لبناء البروتينات هي:…","a":["الأحماض الأمينية","الجلوكوز","الأحماض الدهنية","النوكليوتيدات"],"c":0,"d":"easy","hint":"الببتيدات منها تتكون","expl":"الصواب: الأحماض الأمينية المترابطة بروابط ببتيدية، فكل بروتين سلسلة منها. الجلوكوز وحدة الكربوهيدرات، والأحماض الدهنية للدهون، والنوكليوتيدات للأحماض النووية. نصيحة: \"بروتين = ببتيد = أحماض أمينية\" جلسة حفظ تتمنى أن تتكرر."},{"q":"أي الخيارات التالية يعد من الكربوهيدرات:…","a":["النشا","كينون","الأنزيم","الشحم"],"c":0,"d":"easy","hint":"سكريات ونشويات","expl":"الصواب: النشا، وهو عديد السكريات من الجلوكوز. الأنزيم بروتين، والشحم دهن، وكلمة \"كينون\" لا تعد كربوهيدرات معتمدة. نصيحة: فتّش عن كلمات: \"سكر، نشا، جليكوجين، سليولوز\" = كربوهيدرات."},{"q":"في تفاعل الأسترة تتفاعل الكحول مع حمض كربوكسيلي وينتج عن ذلك:…","a":["إستر وماء","ملح فقط","أمين وماء","ألكان"],"c":0,"d":"medium","hint":"إيناستر عطري الشبه","expl":"الصواب: إستر وماء، إذ يتحد OH الكحول مع H الخاص بالحمض في تكسير رابطة وتكوين إستر برائحة عطرية. الخيارات الأخرى لا مطابقة لنتاج هذا التفاعل. نصيحة: \"أسترة = إستر + ماء\"؛ إذ يكون الإستر مصدر عطور الفاكهة في مختبر الذوق."},{"q":"وظيفة الصابون عند الغسيل تعتمد على تركيب جزيئه من:…","a":["رأس محب للماء وذيل كاره للماء","جزئين محبين للماء","ذيلين كارهين للماء","قطبين موجبين"],"c":0,"d":"medium","hint":"طبيعة مزدوجة تجمع زيتاً وماء","expl":"الصواب: وجود رأس محب للماء وذيل كاره للماء يجمع الزيت مع الماء فتستحلب الدهون وتُرفع. لو كان الجزيء محباً للماء بالكامل لما التصقت به زيوت، وأما الأقطاب الموجبة فتفصيل أخرى غير متفق. نصيحة: الصابون = \"شخصيتان: رأس يتعامل مع الماء وذيل يمسك الدهن\"."},{"q":"البوليمرات البلاستيكية مثل البولي إيثيلين تتكون من:…","a":["تكرر وحدات الإيثيلين المونوميرية","وحدات من الجلوكوز فقط","أحماض أمينية فقط","ذرات معادن"],"c":0,"d":"medium","hint":"مونومر (إيثيلين) يتكرر آلاف المرات","expl":"الصواب: تكرر وحدات الإيثيلين المونومرية (CH₂=CH₂) كما في أكياس البولي إيثيلين. الجلوكوز يبني النشا والسليولوز، والأحماض الأمينية تبني البروتين، والمعادن ليست عضوية. نصيحة: البلمرة = \"صورة مكررة من اللبنة الواحدة (المونومر)\"؛ بولي إيثيلين = إطارات إيثيلين متكررة."},{"q":"الجليكوجين يعتبر:…","a":["شكل تخزين السكر في أجسام الحيوان","دهوناً غير مشبعة","بروتيناً بنيوياً","فيتامين يذوب في الماء"],"c":0,"d":"hard","hint":"نظير النشا في الكبد والعضلات","expl":"الصواب: شكل تخزين الجلوكوز في كبد وعضلات الإنسان والحيوان، ذو فروع كثيرة يطلق سكراً سريعاً. ليس دهن ولا بروتين ولا فيتامين. نصيحة: \"النشا مخزن النبات والجليكوجين مخزن الحيوان\" وثّقها زوجاً حفظ."},{"q":"الدهون وظيفة إضافية عن تخزين الطاقة فهي:…","a":["عنصر بناء للأغشية الخلوية وعزل وحماية الأعضاء","مصدر تعليمي للحمض النووي","مقتصر على الطعم فقط","وسيلة نقل الأكسجين في الدم"],"c":0,"d":"medium","hint":"دورها في الغشاء البلازمي والتصنيع القشري","expl":"الصواب: بناء الأغشية (الفوسفوليبيدات) وعزل الأعضاء وحمايتها وتخزين الفيتامينات الذائبة. الحمض النووي ليس دهنياً، والأكسجين ينقله الهيموغلوبين بروتين. نصيحة: الدهون \"لبنة الغشاء، وعازل حراري\" ومخزن الطاقة الأول. الزيوت كغذاء كثيفة الطاقة."}]}]},{"title":"الذرة والجدول الدوري","icon":"⚛️","chapters":[{"title":"الذرة ومكوناتها","read":[{"h":"نموذج الذرة","t":"الذرة أصغر وحدة لعنصر تحتفظ بخصائصه؛ تتكون من نواة (بروتونات + نيترونات) وإلكترونات تدور في مستويات طاقة."},{"h":"البروتون والنيترون والإلكترون","t":"البروتون موجب، النيترون متعادل، الإلكترون سالب خفيف. العدد الذري = عدد البروتونات، العدد الكتلي = بروتونات + نيترونات."},{"h":"النظائر","t":"ذرات العنصر نفسه بعدد نيترونات مختلف (مثل الكربون 12، 13، 14) — نفس العدد الذري واختلاف العدد الكتلي."},{"h":"التوزيع الإلكتروني","t":"الإلكترونات ترتب في مستويات: K(2) L(8) M(8+) — 2، 8، 8... وتنمو حسب غلاف المدار الكبير."},{"h":"الأيونات","t":"الذرة التي تفقد أو تكسب إلكترونات: تتحول كاتيون (+) أو أنيون (-)؛ الأيونات في الروابط الأيونية أساس البايونج."},{"h":"الخلاصة","t":"الذرة: نواة (بروتونات+نيترونات) وإلكترونات؛ العدد الذري للبروتونات، الكتلي للجسيمين؛ النظائر بنيترونات متغيرة."}],"qs":[{"q":"العدد الذري = عدد:…","a":["البروتونات","النيترونات","الإلكترونات فقط","النيوترونات"],"c":0,"d":"easy","hint":"البروتون"},{"q":"الجسيم المشحون سالباً:…","a":["الإلكترون","البروتون","النيترون","دهرويتشو"],"c":0,"d":"easy","hint":"شحنة سالبة"},{"q":"العدد الكتلي = :…","a":["بروتونات + نيترونات","بروتونات فقط","إلكترونات","بروتونات – نيترونات"],"c":0,"d":"medium","hint":"مجموع نويات"},{"q":"النظائر تختلف في:…","a":["عدد النيترونات","عدد البروتونات","شحنة","النوع"],"c":0,"d":"medium","hint":"نفس العدد الذري"},{"q":"أول مستوى طاقة يتسع لـ:…","a":["2","8","18","32"],"c":0,"d":"medium","hint":"إلكترونان"},{"q":"ذرة تفقد إلكترونين تصبح:…","a":["كاتيون شحنة +2","أنيون -2","متعادلة","أيون -1"],"c":0,"d":"hard","hint":"موجبة"}]},{"title":"الجدول الدوري والروابط","read":[{"h":"الجدول الدوري","t":"رتّبه مندليف، ثم تحسن بمنديليف الجديد. عناصره مرتبة بزيادة العدد الذري؛ الدورة (أفقي) والمجموعة (رأسي) — элементы نفس المجموعة مماثلة الخواص."},{"h":"المجموعات","t":"مجموعة الفلزات القلوية (1)، القلوية الترابية (2)، الهالوجينات (17)، الغازات الخاملة (18)."},{"h":"الرابطة الأيونية","t":"انتقال إلكترونات من فلز إلى لا فلز؛ مثال NaCl (صوديوم كلور). الروابط قوية وتنشأ بلورية."},{"h":"الرابطة التساهمية","t":"من مشاركة أزواج إلكترونات بين لا فلزات؛ مثال الماء H2O والميثان CH4. أو تساهمية قطبية (لو زميل) أو منسية."},{"h":"المعادلات والوزن","t":"كتابة المعادلة بتوازن الذرات: 2H2 + O2 → 2H2O. الحفظ العلمي: كتلة المتفاعلات = كتلة النواتج."},{"h":"الخلاصة","t":"الجدول دوري (مجموعات/دوائر) تنظم العناصر؛ والروابط: أيونية بنقل إلكترونات، تساهمية بمشاركة؛ والمعادلات توازن علمياً."}],"qs":[{"q":"رتّب مندليف العناصر حسب:…","a":["العدد الذري","الكتلة","اللون","الصلابة"],"c":0,"d":"easy","hint":"أساس الترتيب"},{"q":"الهالوجينات تقع في المجموعة:…","a":["17","1","18","2"],"c":0,"d":"medium","hint":"غاضب fluorine"},{"q":"الرابطة في NaCl:…","a":["أيونية","تساهمية","فلزية","هيدروجينية"],"c":0,"d":"easy","hint":"نقل إلكترون"},{"q":"الرابطة في الماء H2O:…","a":["تساهمية","أيونية","استقطاب","تنسيقية"],"c":0,"d":"easy","hint":"مشاركة"},{"q":"أصل المعادلة المتوازنة العلمي:…","a":["حفظ الكتلة","التفاعل","الطاقة","الحرارة"],"c":0,"d":"easy","hint":"لافوزييه"},{"q":"غازات خاملة مجموعة:…","a":["18","1","11","6"],"c":0,"d":"medium","hint":"نيون ارجون"}]}]},{"title":"التفاعلات والأحماض","icon":"🧪","chapters":[{"title":"التفاعلات الكيميائية والأحماض والقواعد","read":[{"h":"أنواع التفاعلات","t":"اتحاد، تفكك، إزاحة، تبادل. مثال الاتحاد: 2Fe + O2 → 2FeO. التفاعل بمعدل أسرع بالحرارة أو العامل المساعد."},{"h":"الأحماض","t":"مذاق حامض، تحول ورق عباد الشمس ((يه) إلى أحمر، التفاعل مع الفلز النشط ينتج هيدروجين. أمثلة: HCl، H2SO4 (نافذ كبريتيك)."},{"h":"القواعد والأس","t":"ملمس صابوني، تحول ورق الأزرار إلى أزرق، التفاعل مع الأحماض لتكوين ملح + ماء (تفاعل التعادل). أمثلة: NaOH، NH3."},{"h":"التعادل","t":"حمض + قاعدة ← ملح + ماء. مثال: HCl + NaOH → NaCl + H2O. مؤشر التوتر مثل الفينولفثالين يتغير اللون على التعادل."},{"h":"أهمية","t":"الأحماض القوية: ببطاريات، صناعية؛ القواعد: تنظيف، طبية؛ التوازن الحمضي القلوي ضروري في الجسم (نسبة مائية ثابتة)."},{"h":"الخلاصة","t":"تفاعلات (اتحاد/تفكك/إزاحة/تبادل)، الأحماض (حامضة، ورق أحمر، تتفاعل بفلز)، القواعد (صابونية، زرقاء)، والتعادل إلى ملح وماء."}],"qs":[{"q":"ورق عباد الشمس يتغير للون الأحمر مع:…","a":["الأحماض","القواعد","الأملاح","الماء فقط"],"c":0,"d":"easy","hint":"حامض"},{"q":"حمض + قاعدة ← :…","a":["ملح + ماء","هيدروجين + ملح","معدن","محلول"],"c":0,"d":"easy","hint":"تعادل"},{"q":"مثال حمض:…","a":["HCl","NaOH","NaCl","NH3"],"c":0,"d":"easy","hint":"حامض كلوريد"},{"q":"تفاعل الحمض مع فلز يطلق:…","a":["هيدروجين","أكسجين","نيتروجين","ثاني أكسيد الكربون"],"c":0,"d":"medium","hint":"فقاعات"},{"q":"مثال قاعدة (هيدروكسيد):…","a":["NaOH","HCl","HNO3","CO2"],"c":0,"d":"medium","hint":"صوديوم هيدروكسيد"},{"q":"التفاعل: 2Fe + O2 → 2FeO من نوع:…","a":["اتحاد","تفكك","إزاحة","تبادل"],"c":0,"d":"hard","hint":"عنصاران فنتاج واحد"}]}]}]},{"id":"math","name":"الرياضيات","icon":"📐","color":"#009688","books":[{"title":"التفاضل والتكامل","icon":"∫","chapters":[{"title":"نسبة التغير والمعدل اللحظي","read":[{"h":"الاشتقاق كمية التغير","t":"المشتقة هي قياس المعدل الذي تتغير به الدالة عندما يتغير متغيرها، وهو أيضاً ميل المماس للمنحنى عند نقطة. رمز المشتقة: f′(x) أو dy/dx. نسبياً: إذا كانت الدالة تزيد بنسبة، فمشتقتها تتناسب مع معامل التغير. أساس الحساب: مشتقة الدالة عند نقطة = حد ميل القاطع عندما تقترب النقطتان من بعضهما (lim Δy/Δx)."},{"h":"قاعدة القوة والمشتقات الأساسية","t":"القواعد الأساسية: مشتقة xⁿ هي nxⁿ⁻¹ (مثال: مشتقة x³ = 3x²)، مشتقة الثابت = صفر، مشتقة (c×f) = c×f′، ومشتقة الجمع = جمع المشتقات. أمثلة شائعة: مشتقة x = 1، مشتقة x² = 2x، مشتقة 1/x = −1/x²، ومشتقة sin x = cos x ومشتقة cos x = −sin x."},{"h":"قاعدة الضرب والقسمة (الخارج)","t":"قاعدة الضرب: (fg)′ = f′·g + f·g′، أي نشتق الأول في الثاني + الأول في مشتقة الثاني بالتناوب. قاعدة القسمة: (f/g)′ = (f′g − fg′)/g²، البسط نهابة \"الأول مشتقاً×الثاني + الأول×الثاني مشتقاً\" تنسيقياً، مع ضرورة تسوية المقام مربعاً، والترتيب مهم: الأول في مشتقة الثاني مطروحاً."},{"h":"قاعدة السلسلة (الدالة المركبة)","t":"عند تركيب دالتين (مثل d dx لـ (x²+1)⁵) نستخدم قاعدة السلسلة: نشتق الدالة الخارجية ونبقي الداخلية كما هي ثم نضرب في مشتقة الداخلية. اختصر: df(g(x))/dx = f′(g(x)) × g′(x). مثال: مشتقة (3x+1)⁴ = 4(3x+1)³ × 3. بدون هذه الخطوة تضيع المشتقة كلها."},{"h":"أمثلة شاملة","t":"احسب مشتقة y = 4x³: 12x². مشتقة y = (x²+1)²: نبدأ بالخارجية فتصبح 2(x²+1) × 2x = 4x(x²+1). مشتقة حاصل ضرب y = x·sin x: = 1×sin x + x·cos x. مشتقة y = (x)/(x+1): = ((1)(x+1) − x(1))/(x+1)² = 1/(x+1)². الرسم التوضيحي: المشتقة تميل المنحنى والزمن معاً."},{"h":"خلاصة الدرس","t":"المشتقة = ميل المماس والمعدل اللحظي. القواعد: القوة (nxⁿ⁻¹)، الثابت (0)، الجمع، الضرب f′g+fg′، القسمة (f′g−fg′)/g²، والسلسلة f′(g(x))·g′(x). كل التفاضل يعتمد على هذه القواعد الخمس بجدول جاهز للاشتقاق."}],"qs":[{"q":"مشتقة الدالة f(x) = x⁵ تساوي:…","a":["5x⁴","4x⁵","x⁴/5","5x⁶"],"c":0,"d":"easy","hint":"نزّل الأس ضرباً ثم نقصه واحداً","expl":"الصواب: 5x⁴ بينموه، نزّل الأس 5 إلى الأمام ثم نقصه: x⁵⁺⁻¹ = x⁴. باقي الخيارات تظهر خطأ في النزول أو النقصان. نصيحة: القاعدة الذهبية: \"الأس للأمام ضارباً، ثم نقص واحداً فوق\"."},{"q":"مشتقة الدالة الثابتة f(x) = 7 تساوي:…","a":["0","7","1","7x"],"c":0,"d":"easy","hint":"الثابت لا يتغير، وميله أفقي","expl":"الصواب: صفر، لأن الثابت لا تتغير قيمته مهما تغير x، بيانه خط أفقي ميله صفر. بقية الخيارات تخلط مع مفاهيم أخرى. نصيحة: الثابت \"جامد\" فمشتقته \"لا شيء\" (صفر)."},{"q":"مشتقة الدالة f(x) = x²·sin x باستخدام قاعدة الضرب تساوي:…","a":["2x·sin x + x²·cos x","x²·cos x","2x·sin x − x²·cos x","2x·cos x"],"c":0,"d":"medium","hint":"f′g + fg′","expl":"الصواب: 2x·sin x + x²·cos x، إذ نشتق الأول (x²→2x) في الثاني، زائداً الأول في مشتقة الثاني (sin→cos). العبارات الباقية تهمل أحد الحدين أو تغير الإشارة خطأ. نصيحة: قاعدة الضرب = \"كل واحد يأخذ دوره\": الأول مشتقاً والثاني كما هو، ثم العكس."},{"q":"باستخدام قاعدة السلسلة، مشتقة (2x+3)⁶ تساوي:…","a":["12(2x+3)⁵","6(2x+3)⁵","6(2x+3)⁵ × 2 × 2","2(2x+6)⁵ ×6"],"c":0,"d":"medium","hint":"الخارجية 6u⁵ × مشتقة الداخلية (2)","expl":"الصواب: 12(2x+3)⁵، لأن مشتقة الخارجية 6(2x+3)⁵ مضروبة في مشتقة الداخلية (2x+3)′ = 2، فيكون 12(2x+3)⁵. الخيار الذي نسي الضرب بـ2 ناقص، والآخر ضرب خارج السياق. نصيحة: \"سلسلة = حلقة خارجية ثم داخلية\": لا تنس أن تضرب مشتقة القدح الداخلي."},{"q":"قاعدة مشتقة ناتج قسمة دالتين (f/g) هي:…","a":["(f′g − fg′)/g²","(f′g + fg′)/g²","(f′g)/g′","g′(f′)/g"],"c":0,"d":"easy","hint":"شكل الصورة المتشابهة للبسط بمطروحات","expl":"الصواب: (f′g − fg′)/g²، البسط فيه المشتق الأول في الثاني مطروحاً منه الأول في مشتق الثاني، كله على مربع المقام. اتجاه الطرح مهم، فلو عكسته لاختلت الإشارة. نصيحة: قم بأستاذية \"مطروح أعلى\": مشتقة البسط × المقام — البسط × مشتقة المقام، ثم تقسيم على مربع المقام."},{"q":"مشتقة الدالة f(x) = 3x² + 2x + 5 تساوي:…","a":["6x + 2","6x + 2 + 5","3x + 2","6x² + 2"],"c":0,"d":"easy","hint":"كل حد على انفراد، والثابت يصبح صفراً","expl":"الصواب: 6x+2، لأن مشتقة 3x² هي 6x، ومشتقة 2x هي 2، ومشتقة الثابت 5 صفر. من ادخل \"5\" في الناتج أخطأ، ومن خفض الأس خطأ. نصيحة: عولج تفاضل الحدود حداً بعد حد ثم اجمع: أقوى تعامل مع كثيرات الحدود."},{"q":"القيمة الهندسية للمشتقة الأولى عند نقطة على منحنى هي:…","a":["ميل المماس للمنحنى عند تلك النقطة","مساحة المنطقة تحت المنحنى","طول المنحنى","إحداثي x للنقطة"],"c":0,"d":"easy","hint":"المشتقة = نسبة التغير اللحظي","expl":"الصواب: ميل المماس عند النقطة، وهذا المعنى الهندسي الأساسي للاشتقاق. المساحة تحت المنحنى تخص التكامل، والطول قضية أخرى. نصيحة: تفاضل = \"ميل\"، تكامل = \"مساحة\". هذا الفصل بينهما سر الفهم."},{"q":"أوجد مشتقة الدالة y = (x+1)/(x−1) باستخدام قاعدة القسمة:…","a":["−2/(x−1)²","2/(x−1)²","(x−1)/x","−1/(x−1)"],"c":0,"d":"hard","hint":"البسط: (1)(x−1) − (x+1)(1)","expl":"الصواب: −2/(x−1)²، لأن البسط = (x−1)−(x+1) = −2، والمقام = (x−1)². من نسي المطروح عكس الإشارة أو حصل على بسط خاطئ أخطأ. نصيحة: في البسط المطروح جعل: الأول مشتقاً×الثاني − الأول×الثاني مشتقاً، واضبط النصوص قبل القسمة."}]},{"title":"التطبيقات على الدوال (الاشتقاق)","read":[{"h":"النقاط الحرجة","t":"النقاط الحرجة نقاط المنحنى التي تكون فيها المشتقة الأولى صفراً أو غير معرّفة، وعندها يكون التماس أفقياً. لحسابه: نحوّل من f′(x)=0 ونوجد قيم x، ثم إحداثياتها (0 تقابل f(x)). وتعني فترات صعود المنحنى إلى قمة أو هبوط؛ وهي المرشحات لنقاط العظمى والصغرى المحلية."},{"h":"التزايد والتناقص بإشارة المشتقة","t":"إشارة المشتقة تحدد سلوك الدالة: إذا كانت f′(x) > 0 في فترة فإن الدالة متزايدة، وإذا كانت f′(x) < 0 فهي متناقصة، وعند صفر المشتقة قد تكون لحظة تحول من تزايد إلى تناقص (عظمى محلية) أو العكس (صغرى). تحديد المجالات يتطلب تعيين جذور المشتقة ثم فحص إشارتها في كل فترة تقسمها تلك الجذور."},{"h":"القيم العظمى والصغرى (التحسين)","t":"النقطة العظمى المحلية: تتغير إشارة المشتقة من + إلى − (تزايد قبلها وتناقص بعدها). الصغرى المحلية: تتغير من − إلى +. لحظات التحسين نقوم ببناء دالة المطلوب (كالمساحة أو الربح) من بيانات المسألة، نشتقها، نساوي المشتقة صفراً لإيجاد النقطة الحرجة، ثم نتأكد بطريقة الإشارة أنها عظمى حقيقية، ونحسب القيمة القصوى."},{"h":"خطوات البرنامج التحسيني","t":"1) عرف المتغيرات وأكتب دالة المطلوب، 2) اشتقها، 3) اجعل المشتقة صفراً وأوجد القيم الحرجة، 4) افحص إشارة المشتقة حول كل قيمة حرجة، 5) احسب القيمة المطلوبة عند النقطة المناسبة، 6) تحقق بالتعويض. مثال: إذا كان الربح R(x) مشتقه R′(x)=0 عند x=4 وكانت الإشارة + قبلها و − بعدها فهي عظمى."},{"h":"أمثلة تطبيقية","t":"مثال: أوجد القيم العظمى والصغرى لـ f(x)=x²−4x+3. المشتقة 2x−4=0 ⇒ x=2، والإشارة سالبة قبله وموجبة بعده فهي صغرى، والقيمة f(2)=−1. ومثال التحسين: إذا كانت مساحة المستطيل الثابتة المحيط، فالعظمى عند مربع، وهو ما تثبته المشتقة بربط الأبعاد في دالة واحدة."},{"h":"خلاصة الدرس","t":"النقاط الحرجة من f′(x)=0. تزايد بإشارة + وتناقص بإشارة −. العظمى: إشارة تتحول من + إلى −، والصغرى من − إلى +. في مسائل التحسين: اكتب دالة المطلوب، اشتق، ثم مالت صفراً، وافحص الإشارة، واحسب القيمة. هذه سلسلة واضحة خطوة بخطوة."}],"qs":[{"q":"النقاط الحرجة للدالة f(x) = x² − 4x توجد عندما:…","a":["المشتقة تساوي صفراً (2x−4=0 ⇒ x=2)","المشتقة أكبر من صفر","الدالة = صفر","الطول أكبر من الصفر"],"c":0,"d":"medium","hint":"f′(x)=0 شرط النقاط الحرجة","expl":"الصواب: عند 2x−4=0 ⇒ x=2، فقد تكون القيمة الحرجة. بقية الخيارات لا تعطي شرطاً لنقاط حرجة. نصيحة: أسهل طريق: اشتق ثم اسأل \"متى يصير الناتج صفراً؟\" فهذه هي النقطة الحرجة."},{"q":"الدالة تكون متزايدة في فترة ما إذا كان:…","a":["مشتقتها موجبة في تلك الفترة","مشتقتها سالبة","مشتقتها صفراً دائماً","غير معرفة"],"c":0,"d":"easy","hint":"إشارة التفاضل تحدد السلوك","expl":"الصواب: الموجب، فعند f′>0 يزداد الاقتران كلما كبر x. السالب يصف تناقصاً، والصفر ثباتاً. نصيحة: اختصار: \"زائد = صعود (متزايد)، ناقص = نزول (متناقص)\"."},{"q":"عند نقطة تحول الدالة من التزايد إلى التناقص، نقطة المنحنى تسمى:…","a":["عظمى محلية","صغرى محلية","نقطة انقلاب","أصل الإحداثيات"],"c":0,"d":"medium","hint":"قمم التل تتحول بالاتجاه","expl":"الصواب: عظمى محلية؛ لأنها أعلى ما حولها: صعود قبلها ونزول بعدها. الصغرى تحول من تناقص إلى تزايد، ونقطة الانقلاب تغيّر تقعر المنحنى، والأصل نقطة على المحاور. نصيحة: تصور تلاً: القمة = عظمى، والوادي = صغرى، وترسخه في ذهنك بلغة الجبل."},{"q":"لإيجاد أبعاد مستطيل أعظم مساحة بثبات محيطه، فإن الخطوة الأولى:…","a":["اكتابة دالة المساحة بدلالة متغير واحد فقط","مضاعفة المحيط","رسم مربع مباشرة","حذف جميع المتغيرات"],"c":0,"d":"easy","hint":"ربط العرض والطول بالمحيط الثابت","expl":"الصواب: اكتب المساحة بدلالة متغير واحد (باستخدام معادلة المحيط في العلاقة بين البعدين)، ثم اشتق. الباقي ليس خطوة في مسائل التحسين. نصيحة: مسائل التحسين = \"متغير واحد في دالة واحدة\": إذا بقي متغيران، استخدم القيد للتخلص من أحدهما."},{"q":"إذا تغيّرت إشارة المشتقة من سالب إلى موجب عند نقطة حرجة، فهذه النقطة:…","a":["صغرى محلية","عظمى محلية","نقطة تقاطع","دالة ثابتة"],"c":0,"d":"medium","hint":"من النزول إلى الارتفاع يعني قاعاً","expl":"الصواب: صغرى محلية، لأن النزول قبلها والصعود بعدها يجعلانها أدنى محيطها. العظمى تتميز بالإشارة المعاكسة (+ ثم −). نصيحة: \"− ثم + = قاع/صغرى، + ثم − = قمة/عظمى\"، وهذا اختبار الإشارة الشهير."},{"q":"القيمة العظمى المحلية للدالة f(x) = −x² + 4x عند النقطة الحرجة x=2 هي:…","a":["4","2","0","8"],"c":0,"d":"hard","hint":"عوّض x=2 في f وليس في مشتقتها","expl":"الصواب: 4، لأن f(2) = −4+8 = 4. لا تضع قيمة x=2 نفسها ولا الناتج 0 ولا القيمة المزدوجة. القيمة العظمى تخرج من تعويض النقطة في الدالة الأصلية. نصيحة: بعد النقطة الحرجة \"اركب الدالة الأصلية\" لتحسب القيمة، ولا تكسرها في المشتقة."},{"q":"الدالة f(x) = x³ تكون:…","a":["متزايدة دائماً على R","متناقصة دائماً","عظمى عند صفر","صغرى عند صفر"],"c":0,"d":"hard","hint":"اشتقها: 3x² ≥ 0 دائماً","expl":"الصواب: متزايدة دائماً؛ فمشتقتها 3x² موجبة أو صفراً على كل الأعداد، فهي لا تنزل ولا تتوقف بقيمتها. كما أنها لا تحقق عظمى أو صغرى عند صفر رغم أن مشتقتها هناك صفر، لأن الإشارة لا تتغير. نصيحة: تذكّر: شرط النقاط الحرجة كافٍ أن الإشارة تتغير فعلاً، وليس أن المشتقة صفر فقط."},{"q":"في اختبار علامة المشتقة الأولى لتأكيد عظمى محلية، نتحقق أن:…","a":["موجبة قبل النقطة وسالبة بعدها","سالبة قبل وسالبة بعد","موجبة قبل وموجبة بعد","تساوي صفراً دائماً"],"c":0,"d":"medium","hint":"صعود ثم هبوط","expl":"الصواب: موجبة قبل النقطة وسالبة بعدها، أي انتقال من التزايد إلى التناقص. لو بقي المعاملات سالبة أو موجبة لاختفت العظمة المحلية، والصفر الدائم دلالة ثبات. نصيحة: \"قبلها تعلو وبعدها تهبط\" = عظمى؛ و\"قبلها تهبط بعدها تعلو\" = صغرى."}]},{"title":"التكامل","read":[{"h":"التكامل غير المحدد (المعكوس)","t":"التكامل هو عكس الاشتقاق: إيجاد الدالة الأصلية التي مشتقتها هي الدالة المعطاة. قاعدة القوة المعكوسة: ∫ xⁿ dx = xⁿ⁺¹/(n+1) + C، بشرط n≠−1. الثابت C ثابت تكامل يُضاف لأنه يختفي أثناء الاشتقاق. أمثلة: ∫ x dx = x²/2 + C، ∫ 3dx = 3x + C، ∫ cos x dx = sin x + C."},{"h":"قواعد التكامل الأساسية","t":"تكامل المجموع = مجموع التكاملات، والتكامل الثابت المضروب يخرج خارج علامة التكامل: ∫c·f(x)dx = c∫f(x)dx. تكامل 1/x هو ln|x|+C (لأن مشتقته هي 1/x). قائمتك الجاهزة: ∫xⁿ، ∫cos، ∫sin، ∫eˣ، ∫1/x بحيث تحفظ قراءة عكس المعيار."},{"h":"التكامل المحدد","t":"التكامل المحدد له حدود علوية وسفلية (مثل ∫ₐᵇ) ويُحسب بتعويض القيمة العليا في الدالة الأصلية ناقص تعويض السفلية. النتيجة رقم حقيقي وليست دالة، لذلك لا يُضاف ثابت C. الرمز يعبر عن جمع لا متناهٍ من التغيرات الصغيرة بين النقطتين."},{"h":"المساحة تحت المنحنى","t":"التكامل المحدد ∫ₐᵇ f(x)dx يحسب المساحة المحصورة بين منحنى الدالة ومحور x من a إلى b، بشرط عدم تعذر إشارة الدالة في الفترة. إذا كانت الدالة تحت المحور (سالبة) جاءت المساحة بالاتجاه المعاكس، فقد يطلب أخذ القيمة المطلقة أو تقسيم الفترة عند تغير الإشارة. هذه العلاقة - التكامل=مساحة - أهم تطبيق حسابي في التفاضل والتكامل للفروع الحياتية كالفيزياء والاقتصاد."},{"h":"التكامل في التطبيقات","t":"من بين التطبيقات: حساب المسافات من السرعات (تكامل السرعة يعطي الإزاحة)، مساحة مناطق تحت منحنيات العرض والطلب في الاقتصاد، حساب أحجام الأجسام الدورانية، وتطبيقات الترددات والإحصاء، وفي الطبيعيات على التجميع الزمني للطاقة. السبب واحد: كل معدل لحظي (مشتقة) يعود للتكامل للمقدار الأصلي المتراكم."},{"h":"خلاصة الدرس","t":"التكامل معكوس التفاضل: ∫xⁿ = xⁿ⁺¹/(n+1)+C، وتكامل الجمع جمع التكاملات، وثابت يخرج. المحدّد: تعويض العليا ناقص السفلى بلا C. المساحة تحت المنحنى = قيمة المحدد بين الحدين المناسبين مع مراعاة الإشارة. التكامل \"جامع الأشتات\" بعد أن فرّقها الاشتقاق."}],"qs":[{"q":"التكامل غير المحدد ∫ x³ dx يساوي:…","a":["x⁴/4 + C","x²/3 + C","4x³ + C","x⁴ + C"],"c":0,"d":"easy","hint":"زِد الأس واحداً ثم اقسم","expl":"الصواب: x⁴/4 + C، وفق قاعدة ∫xⁿ = xⁿ⁺¹/(n+1). الخيار x⁴ بلا قسمة يفوّت التقسيم، والباقي من قواعد أخرى. نصيحة: \"تكامل = أضفن 1 ثم قسّم\"، على عكس الاشتقاق تماماً."},{"q":"لماذا نضيف الثابت C في التكامل غير المحدد؟","a":["لأن أي دالة تختلف بثابت لها نفس المشتقة","لأن التكامل دائماً قيمته صفر","للتقريب العشري","لموازنة الوحدات"],"c":0,"d":"medium","hint":"مشتقة الثابت تساوي صفراً","expl":"الصواب: لأن مشتقة أي ثابت صفر، فيفقد الثابت أثناء الاشتقاق، فلضمان شمول كل الدوال الأصلية نختم بـ C (ثابت اختياري). لا صفر للتكامل ولا تقريب. نصيحة: \"C = عائلة الدوال\": التكامل يرجع لك عائلة مشتقات متشابهة تفرق بينها قيمة الثابت."},{"q":"قيمة التكامل المحدد ∫₀¹ 2x dx تساوي:…","a":["1","0","2","4"],"c":0,"d":"easy","hint":"∫2x = x² ثم عوّض من 1 إلى 0","expl":"الصواب: 1، لأن ∫2x dx = x² + C، والتعويض المحدد: (1)²−(0)² = 1−0 = 1. الباقي نتائج حسابات خاطئة. نصيحة: في المحدد: عوّض الحد الأعلى أولاً ثم انقص تعويض الحد الأدنى، ولا تسهل في الآلة الحساب."},{"q":"التكامل المحدد ∫ₐᵇ f(x)dx يعبر عن:…","a":["المساحة بين المنحنى ومحور x من a إلى b","ميل المماس","طول القوس دائماً","نهاية المتتابعة"],"c":0,"d":"medium","hint":"عدد يجرى تجميع التغيرات بين حدين","expl":"الصواب: المساحة المحصورة بين المنحنى ومحور x بين الحدين، فهو التجسيد الهندسي الأبرز للتكامل المحدد. الميل يخص المشتقة، وطول القوس بطريقة مختلفة، ونهاية المتتابعة حساب. نصيحة: تفاضل=ميل وتكامل محدد=مساحة؛ فبعد أن تعلّمت \"مساحة\" تكمل جملة السياق النظرية."},{"q":"التكامل المحدد الناتج يأتي كقيمة:…","a":["رقمية ثابتة (بلا ثابت C)","دالة x بثابت تكامل","متجهة","دائمًا صفر"],"c":0,"d":"easy","hint":"تعويض حدود يجعل النواتج أرقاماً","expl":"الصواب: القيمة المحددة تكون رقماً (بلا C)، لأن التعويض بالحدود يلغي أي ثابت. الناتج الدالة يخص غير المحدد، وليست متجهة ولا صفراً بالضرورة. نصيحة: القاعدة: \"محدد = رقم، غير محدد = دالة + C\"."},{"q":"لحساب المساحة الكلية تحت منحنى يعبر محور x في منتصف الفترة، يجب:…","a":["تقسيم الفترة عند مواضع تغير الإشارة وأخذ القيم المطلقة","التكامل مباشرة دون انتباه","حذف الجزء السالب","إضافة ثابت كبير"],"c":0,"d":"hard","hint":"المساحة الحقيقية لا تكون سالبة","expl":"الصواب: تقسيم الفترة عند نقاط تغير الإشارة (حيث f=0) وأخذ القيم المطلقة لكل مقطع، فالتكامل الواحد قد يطرد الأجزاء السالبة. الاجتياح المباشر يخطئ والإشارة السالبة \"تُسقط\" المساحة. نصيحة: مساحة = إيجابية دائماً؛ إذا مرّ المنحنى تحت المحور، قسم وجب جمع المقادير المطلقة."},{"q":"قيمة التكامل المحدد ∫₁² 3 dx تساوي:…","a":["3","6","1","9"],"c":0,"d":"easy","hint":"∫3dx = 3x ثم عوّض 2 ثم 1","expl":"الصواب: 3، لأن 3x عند 2 = 6 وعند 1 = 3، والفرق = 3 (وهي مساحة مستطيل عرضه 1 وارتفاعه 3). الخيارات الباقية حسابات خاطئة. نصيحة: تكامل الثابت = \"الثابت × الفرق بين الحدين\"، وهذه مباشرة أي علاقة منطقية."},{"q":"أي من الآتي يعد تطبيقاً على التكامل المحدد في الفيزياء؟","a":["حساب الإزاحة من دالة السرعة الزمنية","حساب الميل اللحظي","حساب معدل التغير","حساب العظمى بواسطة الإشارة"],"c":0,"d":"medium","hint":"التجمع الزمني للمعدلات","expl":"الصواب: حساب الإزاحة بتكامل السرعة الزمنية، فالتكامل \"يجمع\" السرعة المتغيرة عبر الزمن. الميل والتفاضل يخصان الفيزياء الأخرى، وتحسين العظمى باب اشتقاقي. نصيحة: \"التكامل يبني الكل من المعدلات\": من السرعة نبني المسافة، ومن القدرة نبني الطاقة."}]}]},{"title":"الهندسة التحليلية والمتجهات","icon":"📊","chapters":[{"title":"المتجهات","read":[{"h":"المتجه وتمثيله","t":"المتجه كمّ له مقدار واتجاه معاً، مثل القوة والسرعة والإزاحة (بعكس الكميات القياسية كالكتلة والحرارة). يكتب رياضيًا بالصورة v = ai + bj أو (a, b)، حيث a المركبة الأفقية وb الرأسية. طول المتجه (المناس) = √(a²+b²)، واتجاهه يتحدد بالزاوية التي يصنعها مع المحور الأفقي (tan θ = b/a). يساوي المتجهان عندما يتساوى مقدارهما واتجاههما معاً."},{"h":"الضرب القياسي (Dot Product)","t":"الضرب القياسي v·u = |v||u|cos θ، ناتجه عدد (قياسي) وليس متجهًا. صيغة المركبات: v·u = v₁u₁ + v₂u₂. إذا كان حاصل الضرب صفرًا كانت المتجهات متعامدة (θ=90°)، وإذا تزامن المتجهان نال أقصى قيمة موجبة. يستخدم في: حساب الزاوية بين مستقيمين، وإيجاد إسقاط متجه على آخر، وفي أعمال الشغل (الشغل = قوة·إزاحة)."},{"h":"الضرب الاتجاهي (Cross Product)","t":"الضرب الاتجاهي v×u = |v||u|sin θ n̂، ناتجه متجه عمودي على مستوى المتجهين، ومقداره يساوي مساحة متوازي الأضلاع الذي يشكلهان. سمته الأساسية أنه نتاج اتجاه (متجهة) وليس عددا؛ فترتيب الطرفين يغير إشارة الناتج: v×u = −(u×v). يستخدم لتحديد العمودي على مستويات وفي قوانين الدوران والمغناطيسية."},{"h":"معادلة المستقيم في الفضاء","t":"المستقيم في الفضاء يوصف بالاتجاه والممرّ: معادلاته الوسيطية من نقطة P₀ واتجاه d: x = x₀+at، y = y₀+bt، z = z₀+ct. والتخطيط المباشر للمستقيم من نقطتين يعطيك اتجاهه d = P₂−P₁. مستقيمان متوازيان إذا كان اتجاهاهما متوازيين (واحد مضاعف للآخر)، ومتعامدان إذا كان ضربهما القياسي صفرًا."},{"h":"معادلة المستوى","t":"المستوى في الفضاء يُحدد بنقطة عليه ومتجه عمودي عليه n (العمودية normal). معادلته القياسية: n₁(x−x₀)+n₂(y−y₀)+n₃(z−z₀)=0، أو المختصرة ax+by+cz+d=0، حيث (a,b,c) مركبات العمودي. إيجاد مستوٍ من ثلاثة نقاط: نحسب متجهين بينهما ثم ضربهما الاتجاهي يعطي العمودي. زاويتان نحو نقطة بين مستوى: من ضرب المراد القياسي لعموديهما."},{"h":"خلاصة الدرس","t":"المتجه: مقدار واتجاه، طوله √(a²+b²). الضرب القياسي عدد = |v||u|cosθ وصفر يعني تعامد. الضرب الاتجاهي متجه عمودي ومقداره مساحة متوازي الأضلاع. المستقيم: نقطة واتجاه (بارامتري). المستوى: نقطة ومتجه عمودي. كلها أدوات لقراءة الفضاء ثلاثي الأبعاد."}],"qs":[{"q":"كميات مثل القوة والسرعة تمثل بأشعة لأن لها:…","a":["مقداراً واتجاهاً","مقداراً فقط","اتجاهاً فقط","شحنة دائماً"],"c":0,"d":"easy","hint":"ماذا يحتاج وصفها الكامل؟","expl":"الصواب: مقداراً واتجاهاً معاً، وهذا تعريف المتجه. الكمية التي لها مقدار فقط (كالحرارة والكتلة) قياسية، و\"أن يكون بشحنة دائماً\" لا علاقة له بالموضوع. نصيحة: المتجه = \"علامة على الطريق + قياسه\"، أي جملة كاملة من مقدار واتجاه."},{"q":"طول المتجه v = (3, 4) يساوي:…","a":["5","7","12","1"],"c":0,"d":"easy","hint":"الجذر التربيعي لمجموع مربعي المركبتين","expl":"الصواب: 5، لأن √(3²+4²) = √25 = 5، وهذا مثلث فيثاغورسي مشهور 3-4-5. بقية الخيارات من تجميع أو ضرب مكونات لا يمثل الطول. نصيحة: احفظ الثلاثي السحري (3,4,5) وأي توأم (6,8,10) لسرعة حساب الأطوال."},{"q":"الضرب القياسي للمتجهين u وv يساوي صفراً. يستنتج أن:…","a":["المتجهان متعامدان","المتجهان متوازيان","المتجهان متساويان في الطول","أحدهما مجهول"],"c":0,"d":"medium","hint":"cos90° = 0","expl":"الصواب: متعامدان، لأن |u||v|cosθ=0 مع غير صفرية المقادير يعني cosθ=0 أي θ=90°. التوازي يعني θ=0° أو 180° فيكون الناتج أقصى أو أدنى قيمته، لا صفراً. نصيحة: قاعدة ذهبية بإشارة: إذا كان الضرب القياسي صفراً فقل فوراً \"تعامد\"."},{"q":"ناتج الضرب المتجهي (الاتجاهي) لشعاعين هو:…","a":["متجه عمودي على مستوى المتجهين","عدد قياسي حقيقي","مركبة أفقية فقط","منحنى"],"c":0,"d":"medium","hint":"الضرب الذي نتيجته شعاعية","expl":"الصواب: متجه عمودي على مستوى المتجهين، ومقداره مساحة متوازي الأضلاع. الضرب القياسي هو عدد، والأفقية وحدها لا تكفي لحصيلة ناقل كامل. نصيحة: \"اتجاهي = متجه عمودي\" وسيلة ذاكرة: حرف \"اتجاهي\" يشير لدخول متجه النتائج بقيادة العموديّ."},{"q":"معادلة المستوى في الصورة ax + by + cz = d تشير إلى أن المتجه العمودي على المستوى هو:…","a":["(a, b, c)","(d, 0, 0)","(-a, -b, d)","(x, y, z)"],"c":0,"d":"medium","hint":"الإحداثيات الثلاثة المرافقة للمتغيرات","expl":"الصواب: (a, b, c)، إذ المعاملات في الصورة العامة للمستوى هي مركبات العمودي (normal). المتغيرات x وy وz نقطة على السطح وليست عمودياً. نصيحة: \"معاملات البسط = العمودي\": في ax+by+cz=d اقرأ العمودي مباشرة من (a,b,c)."},{"q":"الزاوية بين متجهين تحسب من علاقة:…","a":["cosθ = (u·v)/(|u||v|)","sinθ = (u·v)/(|u||v|)","tanθ = u·v","θ دائماً 90°"],"c":0,"d":"easy","hint":"أعد ترتيب صيغة الضرب القياسي","expl":"الصواب: cosθ = (u·v)/(|u||v|)، لأن u·v = |u||v|cosθ، فنعزل cosθ بضرب المقادير قسمت. الجيب يخص الضرب الاتجاهي، والباقي شروح مستقلة. نصيحة: \"قياسي = جيب التمام، اتجاهي = جيب\". خبر تجعل به الخيارات مقفلة."},{"q":"الشغل المبذول بحسب الفيزياء يساوي الضرب القياسي للقوة في الإزاحة، لذا فهو:…","a":["كمية قياسية","كمية متجهة","متجه عمودي","صفر دائماً"],"c":0,"d":"hard","hint":"نتيجة ضرب بُنط قياسية دائماً عدد","expl":"الصواب: كمية قياسية، لأن ضرب DOT yield عدد لا متجه، وهذا يشير لأهم تمديد للضرب القياسي في الفيزياء. لو كان متجهًا لتغيّر معنى الشغل. نصيحة: كل نتيجة dot product = عدد. ذكّرك: \"الشغل عدد، والقوة متجه\"."},{"q":"مستقيمان في الفضاء اتجاهاهما d₁ وd₂ متوازيان إذا كان:…","a":["d₁ يساوي مضاعفاً عددياً لـ d₂","الضرب القياسي بينهما صفر","طولهما متساوٍ","أحدهما يمر بنقطتين"],"c":0,"d":"easy","hint":"متجهان متوازيان للتوازي مستقيمين","expl":"الصواب: أَحَدّهما مضاعف (ثابت) للآخر، أي يشتركان في نفس الاتجاه كالخطوط المتوازية. الضرب الصفري يدل تعامداً، وتساوي الأطوال لا يضمن التوازي. نصيحة: إذا كانت مركبات الاتجاه متناسبة (مثل (1,2,3) و(2,4,6)) فاعلم أنها متوازية خطوطاً."}]},{"title":"المخروطيات (الأخماس المستوية)","read":[{"h":"المخروطيات تعريفها","t":"المخروطيات (القطوع المخروطية) منحنيات تنتج من تقاطع مستوى مع مخروط دائري قائم، وتشمل: الدائرة، القطع الناقص (الإهليلج)، القطع المكافئ، والقطع الزائد. يأثر اهتمام المنهج بالدائرة والناقص والمكافئ. تمثل هذه المنحنيات مسارات الكواكب والتطبيقات الهندسية والفيزيائية. كل قطع عرف بمجموعة نقاط تحقق شرطاً هندسياً بين نقاط ثابتة (البؤر) وخط."},{"h":"الدائرة","t":"محل النقط التي تبعد بمسافة ثابتة (نصف القطر r) عن نقطة ثابتة (المركز). معادلتها القياسية (x−h)² + (y−k)² = r² حيث المركز (h,k)، والصورة الموسعة x²+y²+Dx+Ey+F=0. المعادلة العامة تمثل دائرة شرط أن لا يكون معامل x² وy² مختلفين صفراً، وأربعة حدود مربعة تكتمل على مركز ونصف قطر بالتدريج."},{"h":"القطع الناقص (الإهليلج)","t":"محل النقط التي مجموع بعديها عن بؤرتين ثابتتين مقدار ثابت (أكبر من بعد البؤرتين). معادلته القياسية: x²/a² + y²/b² = 1، والأكبر في المقام (a) يحدد المحور الأكبر. الخاصية: مجموع المسافات إلى البؤرتين ثابت، والبؤرتان على المحور الأكبر، والاختلاف المركزي (eccentricity) أقل من 1، ومسار الكواكب حول الشمس إهليلجي بقانون كبلر."},{"h":"القطع المكافئ","t":"محل النقط المتساوية البعد عن بؤرة ثابتة وخط دليل ثابت. معادلته القياسية المفتوحة لأعلى: y = a(x−h)² + k، والمفتوحة لليمين x = a(y−k)² + h. العام(ة) y = ax²+bx+c يحوي دائماً قمة (رأس) عند x=−b/2a ومحور تناظر، وقيمة a تتحكم في الفتح وضيق المنحنى. تستخدم القطوع المكافئة في الهوائيات اللاقطة والعاكسات لأنها تعكس الإشارات نحو البؤرة."},{"h":"تمييز أنواع القطوع","t":"بفحص المعادلة بعد إكمال المربعات نتعرف النوع: إذا كان أعلاه مربعان للـ x وy (معاملات متساوية إذا اختلطت) فهي دائرة، وإذا كان مجموع مربعين قسم على ثابتين مختلفين (x²/a²+y²/b²=1) فهي قطع ناقص، وإذا ظهر مربع واحد فقط للـ x أو y فهي قطع مكافئ (بلا ظهور مربعين معاً). القطع الزائد يبين علامة − بين المربعين."},{"h":"خلاصة الدرس","t":"الدائرة: مسافة ثابتة عن مركز، ميلها (x−h)²+(y−k)²=r². الناقص: مجموع بعدي النقطة عن بؤرتين ثابت وميله x²/a²+y²/b²=1، ومسار الكواكب. المكافئ: نقاط متساوية البعد عن بؤرة ودليل، معادلة برأس ومحور تناظر. بفحص المعادلة بعد إكمال المربع نعرف النوع فوراً."}],"qs":[{"q":"معادلة الدائرة التي مركزها نقطة الأصل ونصف قطرها 5 هي:…","a":["x² + y² = 25","x² + y² = 5","x + y = 25","x² − y² = 25"],"c":0,"d":"easy","hint":"بالصيغة القياسية للدائرة والصورة (x²+y²=r²)","expl":"الصواب: x²+y²=25، لأن r²=5²=25 للمركز (0,0). الخيارات بتساوي 5 وطرح مربعين لا تشكل دائرة مركزها الأصل ونصف قطرها 5. نصيحة: الدائرة = \"مربعات مجموع = مربع نصف القطر\"؛ إذا قيل مركز الأصل يصبح التمثيل أبسط كثيراً."},{"q":"القطع الناقص يمثل مسار الكواكب حول الشمس حسب قانون:…","a":["كبلر","نيوتن","أينشتاين","بور"],"c":0,"d":"medium","hint":"قوانين حركة الكواكب","expl":"الصواب: قانون كبلر الذي لاحظ أن الكواكب تتحرك في مسارات إهليلجية الشمس في بؤرة منها. نيوتن أعطى الجاذبية العامة، وأينشتاين النسبية، وبور نموذج الذرة. نصيحة: \"كواكب إهليلجية = كبلر\"، مثل ما \"الذرة بوردية\" ذاكرتك البصرية تذّكر أسماء العلماء."},{"q":"في معادلة القطع الناقص x²/25 + y²/9 = 1 يقع المحور الأكبر على محور:…","a":["x لأن 25 أكبر من 9","y لأن 9 أقل","z لأن...","الأقطار"],"c":0,"d":"medium","hint":"المقام الأكبر يحدد محور البؤر","expl":"الصواب: x، فالمقام الأكبر 25 تحت x² يعني أن البعد الأكبر على محور x، ومحور أكبر طوله 2a=10. لو كان الأكبر تحت y لصار المحور الرأسي. نصيحة: \"أكبر مقام = اتجاه المحور الأكبر\": حالة مباشرة عند تمييز القطع الناقص."},{"q":"شرط أن تمثل معادلة من الدرجة الثانية في x وy دائرة هو:…","a":["تساوي معاملي x² وy² وعدم وجود حد xy","اختلاف المعاملين","غياب x² تماماً","وجود xy فقط"],"c":0,"d":"hard","hint":"تماثل الأشكال الهندسية","expl":"الصواب: تساوي معاملي x² وy² (وبلا حد xy) بنفس المقدار، فتتوزع النقطة بمسافات متساوية حول المركز. سحابة المعاملين ينتج القطع الناقص، وغياب x² ينتج المكافئ من نوع ما. نصيحة: دائرة = \"توازن مربعين\" — إذا كان مربعا x وy متساويين فهي دائرة."},{"q":"رأس القطع المكافئ y = 2x² + 8x + 5 يقع عند:…","a":["x = −2","x = 2","x = 0","x = −8"],"c":0,"d":"hard","hint":"قانون x = −b / 2a","expl":"الصواب: x=−2، لأن −b/2a = −8/(2·2) = −8/4 = −2، وعندها القمة (قانونها قاعدة تحفيظية). بعض الخيارات تخلط مع المعاملات مباشرة. نصيحة: حافظ على \"x رأس = −b/2a\" كأداة دائمة تحل نصف المسألة تلقائياً."},{"q":"خاصية القطع المكافئ الشهيرة في المرايا العاكسة أنه:…","a":["يعكس الأشعة الموازية للمحور نحو البؤرة","يمتص كل الضوء","يوازي الفوتونات","يزيد السرعة"],"c":0,"d":"easy","hint":"التطبيق في الهوائيات النجمية والصحون اللاقطة","expl":"الصواب: يعكس الأشعة المتوازية القادمة نحو البؤرة، وهذا أساس الصحون اللاقطة والأضواء الكاشفة. الخيارات الأخرى خواص غير رياضية للمنحنى. نصيحة: \"صحن دش = قطع مكافئ = تجميع إشارات في بؤرة\" لا تنس الاستدلال الرمزي."},{"q":"المعادلة y² = 8x تمثل قطعاً مكافئاً يفتح نحو:…","a":["اليمين (اتجاه x الموجب)","الأعلى","الأسفل","اليسار"],"c":0,"d":"medium","hint":"مربع y يعني فتحة أفقية وإشارة موجبة تعني اليمين","expl":"الصواب: نحو اليمين لأن المتغير المربع هو y (فتح أفقي) ودلت المعادلة 4a=8 موجبة فأتجه لمحور x الموجب. لو كانت −8 لفتح يساراً، ولو تربع x فتح لأعلى أو لأسفل. نصيحة: \"تربيع y = أفقي، تربيع x = رأسي؛ الموجب = جهة موجبة\"."},{"q":"القطع الناقص x²/16 + y²/4 = 1 نصف محوره الأصغر يساوي:…","a":["2","4","16","8"],"c":0,"d":"easy","hint":"المقام الأصغر يعطي محور أصغر","expl":"الصواب: 2، لأن b²=4 ⇒ b=2 حيث تحت y² وهو الأصغر. في هذا الناقص a=4 (أكبر) وb=2 (أصغر). الخيارات الباقية تخلط بين تغطية الأقطار. نصيحة: نصف المحور الأصغر = الجذر التربيعي للمقام الأصغر، ونصف الأكبر = جذر المقام الأكبر."}]}]},{"title":"الجبر","icon":"🧮","chapters":[{"title":"المعادلات والدوال","read":[{"h":"المعادلة الخطية","t":"أس=1: 2x+3=11 → 2x=8 → x=4. تحل بنقل الحدود وتوازن الطرفين."},{"h":"المعادلة التربيعية","t":"أس=2: ax²+bx+c=0. حلول: تحليل، الجذر التربيعي، القانون: x=[-b±√(b²-4ac)]/(2a). المميز Δ=b²-4ac يحدد عدد الجذور (حقيقية/متكررة/معقدة)."},{"h":"العامة للصفوف","t":"الكسور والجذور: التبسيط، الموحدة، والتطبيقات المتعلقة بزرع السوق والمقادير الفيزيائية والهندسة."},{"h":"الدوال","t":"دالة تربط مدخل بخرج وحيد: (f(x)=2x+1). أنواع: خطية، تربيعية، أسية (خضرية: f(x)=2ˣ)، لوغاريتمية عكسها."},{"h":"الرسم البياني","t":"المستقيم يوصف بميل وتقاطع: y=mx+b. m الميل، b تقاطع الصادي. الميل = تغير y/تغير x."},{"h":"الخلاصة","t":"حل المعادلات (خطية/تربيعية بالقانون)، فهم الدوال وأنواعها، وتمثيل المقاييس بيانياً بالميل والتقاطع."}],"qs":[{"q":"حل المعادلة 2x+3=11:…","a":["x=4","x=8","x=14","x=7"],"c":0,"d":"easy","hint":"قل الناق"},{"q":"المميز في التربيعية:…","a":["b²-4ac","b+4ac","(b/2a)","√-b"],"c":0,"d":"easy","hint":"دلتا"},{"q":"إذا كان Δ>0 فالمعادلة لها:…","a":["جذران حقيقيان مختلفان","جذر واحد","لا جذور","جذور خيالية"],"c":0,"d":"easy","hint":"عدد الجذور"},{"q":"الميل في صيغة y=mx+b يُمثل:…","a":["m","b","x","y"],"c":0,"d":"easy","hint":"معامل x"},{"q":"تقاطع y في المستقيم:…","a":["b","m","الصفر","البداية"],"c":0,"d":"medium","hint":"نقطة على المحور"},{"q":"الدالة العكسية للأسية (خ ˣ):…","a":["اللوغاريتمية","التربيعية","الخطية","المتجهة"],"c":0,"d":"medium","hint":"معكوس"}]},{"title":"الهندسة وحساب المثلثات","read":[{"h":"مساحات ومحيطات","t":"مربع: ضلع²/4×ضلع؛ مستطيل: طول×عرض؛ مثلث: ½ القاعدة×الارتفاع؛ دائرة: πr² محيطها 2πr."},{"h":"نظرية فيثاغورس","t":"في المثلث القائم: مربع الوتر = مجموع مربعي الضلعين. (a²+b²=c²). ملاحظ: يستخدم لحساب مسافات وإقليدية."},{"h":"الدوال المثلثية","t":"جيب الزاوية (sin) = مقابل/وتر؛ جيب التمام (cos) = مجاور/وتر؛ ظل (tan) = مقابل/مجاور. من الزوايا الخاصة 30°,45°,60°."},{"h":"القياسات","t":"قياس الزاوية بالدرجات والراديان (2π = 360°). قوانين حساب المساحات والحجوم للأجسام الصلبة (مكعب، كرة، أسطوانة)."},{"h":"الثانوية","t":"الدائرة: الزاوية المركزية، القوس، القطاع؛ التماثل عن المتحرك والمحوري."},{"h":"الخلاصة","t":"مساحات ومحيطات أساسية، فيثاغورس للمثلث القائم، مثلثات (sin/cos/tan) زوايا خاصة، ودوائر وأجسام صلبة."}],"qs":[{"q":"نظرية فيثاغورس:…","a":["a²+b²=c²","a+b=c","ab=c","a²-b²=c"],"c":0,"d":"easy","hint":"وتر"},{"q":"sin θ = :…","a":["المقابل/الوتر","المجاور/الوتر","المقابل/المجاور","الوتر/المقابل"],"c":0,"d":"easy","hint":"جيب"},{"q":"مساحة الدائرة:…","a":["πr²","2πr","4πr²","r³"],"c":0,"d":"easy","hint":"باي"},{"q":"tan θ = :…","a":["المقابل/المجاور","المجاور/المقابل","الوتر/المجاور","الجبر"],"c":0,"d":"easy","hint":"ظل"},{"q":"قيمة sin 30°:…","a":["½","√3/2","1","0"],"c":0,"d":"medium","hint":"نصف"},{"q":"محيط المربع (ضلعه أ):…","a":["4أ","أ²","2أ","أ³"],"c":0,"d":"easy","hint":"مجموع الأضلاع"}]}]}]},{"id":"geology","name":"الجيولوجيا","icon":"⛰️","color":"#8D6E63","books":[{"title":"الأرض والصخور","icon":"🪨","chapters":[{"title":"طبقات الأرض والمعادن","read":[{"h":"بنية الأرض","t":"للقشرة، الوشاح (الغلاف)، النواة الخارجية السائلة والنواة الداخلية الصلبة. القشرة: محيطية (بازلت) وقارية (جرانيت)."},{"h":"المعادن","t":"المواد الطبيعية الصلبة ذات تركيب كيميائي ثابت؛ خواص: صلادة (موس)، البريق، اللون، المخدش، الانفصام، الوزن النوعي. أمثلة: الكوارتز، الفلسبار، الميكا."},{"h":"الصخور النارية","t":"تتجمد من الصهارة: (جرانيت) تحت الأرض بطيء — (بازلت) عند السطح سريع. تصنيف بالنسيجة والحبيبات."},{"h":"الصخور الرسوبية","t":"تتكون بترسب وتضاغط: جيرية (حجر جيري)، رملية (رمال مضغوطة)، طينية؛ تحوي أحافير لأثر الكائنات."},{"h":"الصخور المتحولة","t":"تتحول بالحرارة والضغط: الرخام من الحجر الجيري، الشيست من الطين/الغنايس من الجرانيت."},{"h":"دورة الصخور","t":"صهارة → نارية ← تجوية وترسب ← رسوبية ← حرارة وضغط ← متحولة ← ذوبان ← صهارة — دورة مستمرة."}],"qs":[{"q":"أنواع الصخور الأساسية:…","a":["نارية ورسوبية ومتحولة","صلبة وسائلة","خشنة","طبقات فقط"],"c":0,"d":"easy","hint":"ثلاثة"},{"q":"البازلت صخر:…","a":["ناري سطحي","رسوبي","متحول","بركاني مرتفع"],"c":0,"d":"easy","hint":"حمم"},{"q":"الرخام صخر متحول من:…","a":["الحجر الجيري","الجرانيت","الرمال","الطوب"],"c":0,"d":"easy","hint":"جير"},{"q":"صلادة المعادن تميز بعسة:…","a":["موس","كلفن","أوم","واط"],"c":0,"d":"easy","hint":"مقياس صلادة"},{"q":"الأحافير توجد غالباً في:…","a":["الرسوبية","النارية","المتحولة","الحمم"],"c":0,"d":"medium","hint":"بقايا كائنات"},{"q":"الغنايس تحول من:…","a":["الجرانيت","الحجر الجيري","الصوان","البازلت"],"c":0,"d":"hard","hint":"ناري حبيبي"}]},{"title":"الزلازل والبراكين والمياه","read":[{"h":"الزلازل","t":"استخراج مفاجئ للطاقة في القشرة (حركة صفائح/صدوع)؛ مركز السطح (epicenter) حيث تشتد التدمير. تقاس بقوة (ريختر) ودرجة العزم (moment)."},{"h":"البراكين","t":"فتحة تنفث الصهارة والرماد والغازات من الوشاح؛ البركان النشط، الخامل، الميت؛ حقول كالبركان تدل على النشاط التكتوني."},{"h":"التكتونية","t":"قشرة الأرض مقسمة صفائح تتحرك: تقارن (زلازل وقوس جبلي)، تباعد (منتصف محيطي)، انزلاق (صدع)."},{"h":"المياه الجوفية","t":"تتسرب أمطار للتخزين في طبقة حاملة للمياه (خزان مائي جوفي)؛ استغلاله عبر آبار؛ مصادر: أمطار، أنهار تمر عبر الحوض."},{"h":"المياه السطحية","t":"أنهار، بحيرات، خزانات؛ توزيع الأنظمة المائية وترشيد استهلاك المياه من أولويات البيئة."},{"h":"الخلاصة","t":"الزلازل والبراكين إفراز طاقة من حركة الصفائح؛ والجيولوجيا المائية تدرس الخزانات الجوفية والمياه السطحية للاستدامة."}],"qs":[{"q":"مقياس قوة الزلازل:…","a":["ريختر","أوم","موس","ديسيبل"],"c":0,"d":"easy","hint":"قوة"},{"q":"مركز الزلزال على السطح:…","a":["Epicenter","فوكس","مركز","محور"],"c":0,"d":"easy","hint":"فوق البؤرة"},{"q":"عند تقارب صفائح تتكون:…","a":["جبال وسلاسل","قيعان","أمواج","محيط"],"c":0,"d":"medium","hint":"الالتقاء"},{"q":"الطبقة الحاملة للمياه الجوفية:…","a":["Aquifer","بازلت","عراق","حجر جيري فجوي"],"c":0,"d":"medium","hint":"مخزن"},{"q":"البركان الميت:…","a":["لا ينتظر ثوران","يندفع","يتراكم","يبخ"],"c":0,"d":"easy","hint":"خامل"},{"q":"الصهارة المنبعثة:…","a":["حمم","جمر","رمال","صخر"],"c":0,"d":"easy","hint":"سائلة حارة"}]}]}]}]},{"id":"azhar_adabi","name":"الأزهرية — الأدبية","icon":"🌙","color":"#2E8B57","grad":"linear-gradient(135deg,#2E8B57,#1D6F42)","desc":"العلوم الشرعية واللغة العربية لطلاب الأزهر الشريف","subjects":[{"id":"aztafsir","name":"التفسير","icon":"📖","color":"#8E24AA","books":[{"title":"علوم القرآن والتفسير","icon":"📖","chapters":[{"title":"التفسير وأهله وقواعده","read":[{"h":"تعريف التفسير وأهميته","t":"التفسير لغة: الكشف والإيضاح والبيان. واصطلاحاً: بيان معاني القرآن الكريم وكشف مراد الله تعالى فيما دلّت عليه ألفاظه، معتمدا على القواعد اللغوية والشرعية. وهو أشرف العلوم لأنه يتعلق بكلام الله تعالى، ولا يُفتى فيه إلا بعد ضبط أصوله."},{"h":"أنواع التفسير","t":"قسم العلماء التفسير إلى نوعين: (1) تفسير بالمأثور: وهو ما نقل عن النبي ﷺ والصحابة والتابعين، كتفسير الطبري وابن كثير. (2) تفسير بالرأي: وهو تفسير الآيات بالاجتهاد المستند إلى قواعد اللغة والشريعة، كتفسير الزمخشري الكشّاف (لغوي) ومفاتيح الغيب للرازي (عقلي). والرأي المذموم هو التفسير بالهوى دون أصل."},{"h":"شروط المفسر","t":"من شروط المفسر وأدواته: معرفة القرآن والحديث وعلوم العربية (نحو وصرف وبلاغة)، ومعرفة أصول الفقه وأسباب النزول والناسخ والمنسوخ والمكي والمدني، إضافة إلى سلامة العقيدة وصدق النية. فمن جهل هذه العلوم فسّر برأيه وأخطأ في كلام الله."},{"h":"المكي والمدني وأسباب النزول","t":"المكي: ما نزل قبل الهجرة وإن نزل في السفر خارج مكة. والمدني: ما نزل بعد الهجرة وإن نزل في مكانه بمكة. والفائدة من هذه المعرفة: تمييز الدعوة من الأحكام، وبيان مراحل التشريع. أما أسباب النزول فهي ما نزلت الآية لأجله أو وردت لتفسيرها، وفائدتها فهم المراد وإزالة الإشكال."},{"h":"الناسخ والمنسوخ والمحكم والمتشابه","t":"الناسخ: رفع حكم شرعي بدليل شرعي متأخر عنه، والمنسوخ: المرفوع حكمه. ويُعرفان بأخبار الشارع أو إجماع أهل العلم، وهذا أول علم يُبادر إليه المفسرون. والمحكم: الواضح الدلالة الذي لا يحتمل إلا معنى واحداً كآيات الأحكام. والمتشابه: ما لم تتضح دلالته أو استأثر الله بعلمه كالحروف المقطعة. والعام اللفظ المستغرق لأفراده، والخاص ما دل على فرد أو أفراد محدودة، وفهم ذلك من فقه الآيات."},{"h":"خلاصة الدرس","t":"اجمع في ذهنك: التفسير كشف لمراد الله، نوعاه المأثور والاجتهادي، وشروط المفسر علوم عربية وشرعية، مع أصول مهمة: المكي والمدني، أسباب النزول، الناسخ والمنسوخ، المحكم والمتشابه، العام والخاص. هذه هي مفاتيح فهم الآيات في امتحانك."}],"qs":[{"q":"التفسير في اصطلاح أهل العلم هو:","a":["بيان معاني القرآن الكريم وكشف مراد الله تعالى وفق القواعد الشرعية واللغوية","مجرد ترجمة ألفاظ القرآن إلى اللغات الأجنبية","استخراج معانٍ ذوقية شخصية من النص دون أصل","نقل القصص الإسرائيلي الوارد في كتب الأولين"],"c":0,"d":"easy","hint":"الغاية منه الفهم الصحيح لكلام الله","expl":"الصواب: بيان معاني القرآن وفق قواعد مقررة، وهذا معنى التفسير اصطلاحاً. الترجمة تغيير للفظ وليست تفسيراً، والمعاني الذاتية بلا أصل تفسير بالهوى المذموم، ونقل الإسرائيليات منه ما يصحّ وما لا يصحّ. نصيحة: افتح سؤال التعريفات بذكر الغاية: كشف مراد الله."},{"q":"من أشهر كتب التفسير التي غلبت فيها الرواية بالمأثور:","a":["تفسير ابن كثير","الكشّاف للزمخشري","مفاتيح الغيب للرازي","الإتقان للسيوطي"],"c":0,"d":"medium","hint":"رواية النبي والصحابة والتابعين","expl":"الصواب: تفسير ابن كثير من كتب التفسير بالمأثور لأنه يعتمد على القرآن والسنة وأقوال السلف. الكشّاف تفسير لغوي بلاغي، ومفاتيح الغيب تفسير عقلي، والإتقان كتاب في علوم القرآن وليس تفسيراً. نصيحة: احفظ لكل كتاب صفته: ابن كثير وابن جرير = مأثور."},{"q":"من أهم أدوات المفسر التي لا يصحّ التفسير بدونها:","a":["العلم بالكتاب والسنة وعلوم العربية والناسخ والمنسوخ","حفظ القرآن دون معرفة معناه","علم الفلسفة القديمة وتحكيمه على النص","معرفة النجوم والأبراج والفلك البحت"],"c":0,"d":"medium","hint":"أصول التفسير تنبني على هذه العلوم","expl":"الصواب: المفسر يحتاج إلى العلوم الشرعية واللغوية كلها حتى يُحسن استنباط المعنى. حفظ القرآن دون فهم لا يكفي، والفلسفة لا تحكم على الوحي، والنجوم لا علاقة لها بالتفسير. نصيحة: أسئلة الشروط = علوم العربية والقرآن والسنة والأصول."},{"q":"المراد باصطلاح (الناسخ والمنسوخ):","a":["رفع حكم شرعي متأخر نزل بعد حكم متقدم قبله","تفسير الآية بمعناها الباطني البعيد","إعمال العام في آية وإهمال الخاص","تقديم المكي على المدني عند كل تعارض"],"c":0,"d":"medium","hint":"رفع حكم بدليل متأخر","expl":"الصواب: الناسخ رفع الحكم السابق بدليل لاحق كنسخ تحويل القبلة من بيت المقدس إلى الكعبة. التأويل الباطني ليس نسخاً، وإعمال العام مع الخاص من فقه الجمع لا النسخ، ومسألة المكي والمدني معرفة زمنية لا رفع حكم. نصيحة: النسخ = تغيير الحكم، والجمع بين النصوص = غير النسخ."},{"q":"الآية المدنية هي الآية التي:","a":["نزلت بعد الهجرة النبوية وإن كان نزولها في مكان بمكة","نزلت في مكة قبل الهجرة كلها","نزلت في أهل مكة فقط ولا تتجاوزهم","نزلت عن الحج والمناسك فقط"],"c":0,"d":"medium","hint":"المعيار الزمني هو الهجرة","expl":"الصواب: المعيار عند الجمهور زمن النزول؛ فما نزل بعد الهجرة مدني وإن نزل بمكة كآيات عام الفتح. الخياران الآخران خلط بين المكان والزمان. نصيحة: واسطة العقل: المدني = بعد الهجرة ولو بمكان مكة."},{"q":"المحكم من آيات القرآن هو:","a":["الواضح الدلالة الذي لا يحتمل إلا معنى واحداً","المتشابه الذي لا يعلمه إلا الله ولا يفهم","المنسوخ بآية متأخرة عنه","الخاص الذي خصص عاماً قبله"],"c":0,"d":"easy","hint":"وضح الدلالة وثبوت المعنى","expl":"الصواب: المحكم ما اتضح معناه واستقر مراده كآيات الأحكام، وهو يعمل به ولا تحريف فيه. المتشابه ما التبس معناه أو استأثر الله بعلمه، والمنسوخ والخاص بابان مختلفان عن معنى الإحكام. نصيحة: تذكّر: المحكم حَكْمٌ بيّن، المتشابه خفيّ الدلالة."},{"q":"العام في أصول تفسير القرآن هو اللفظ:","a":["المستغرق لجميع أفراده بلا حصر","الدال على معنى واحد ظاهر","الفرد الخاص بموضوع واحد","الذي لا يحتمل التأويل أبداً"],"c":0,"d":"easy","hint":"الشمول لجميع الأفراد","expl":"الصواب: العام لفظ يستغرق جميع أفراده كقوله تعالى (أقيموا الصلاة). الخاص يدل على فرد أو أفراد مقيدة، والمحكم لا يلزم منه الاستغراق. نصيحة: العام = كم وكلّة، الخاص = فرد محدد."},{"q":"الفائدة الكبرى من معرفة أسباب النزول:","a":["فهم مراد الله تعالى وبيان الحكمة من التشريع","تصحيح أسانيد الأحاديث فقط","الاستغناء عن بقية علوم القرآن","معرفة بلاغة العرب دون معنى الآية"],"c":0,"d":"easy","hint":"لماذا نزلت هذه الآية؟","expl":"الصواب: سبب النزول يكشف المقصود من الآية ويقيم الحكمة، كمعرفة سبب نزول آية الظهار. لا علاقة له بتصحيح أسانيد الحديث، ولا يغني عن علوم القرآن الأخرى. نصيحة: عند سؤال عن الحكمة اربط بالمقصد التشريعي لا بالأسانيد."}]},{"title":"آيات الأنفس والآفاق","read":[{"h":"معنى الآفاق والأنفس","t":"قال تعالى: (سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق) [فصلت: 53]. والآفاق: عوالم الكون الظاهرة في السماوات والأرض من شمس وقمر ونجوم ورياح وأمطار. والأنفس: ما في داخل الإنسان من عجائب الخلق وتدبير الجسم. والسورة هنا تحشد الأدلة على وحدانية الله وقدرته."},{"h":"آيات خلق السماوات والأرض","t":"أكثر القرآن من التنبيه على خلق السماوات والأرض واختلاف الليل والنهار، فقال: (إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات لأولي الألباب). فهذه الظواهر الثابتة المستقيمة دليل على خالق حكيم يديرها، وكل ما ينبّه إلى التدبير ينبّه إلى الموجد المختار."},{"h":"آيات خلق الإنسان","t":"وصف القرآن مراحل خلق الإنسان من نطفة فعلقة ثم مضغة ثم عظاماً ولحماً، وقال: (ولقد خلقنا الإنسان من سلالة من طين). وبهذا فتح القرآن باب الاعتبار بمراحل تكون الجنين، وهي من أصدق ما عرف حديثاً في علم الأجنة، فتأتي موافقة للحقائق الثابتة لا مناقضة لها."},{"h":"الإعجاز العلمي وأدب التعامل","t":"الإعجاز العلمي: موافقة النص القرآني الثابت للحقائق العلمية المستقرة، كالإشارة إلى الجبال أوتاداً والنوم بالنهار للطلب. لكنه إعجاز دلالة لا يفصّل كل التفاصيل، فلا يصح تكلف إسقاط كل نظريات العلم المتغيّرة على النص، ويقبل العلم الذي ثبت بالتجربة الصحيحة والبرهان القاطع ولا يخالف نصاً قطعياً."},{"h":"الغاية من النظر في الآفاق والأنفس","t":"ليست الغاية مجرد العلم أو الترف المعرفي، وإنما العبرة والاعتبار: أن يتفكر الإنسان في هذه الآيات فيدله وجودها على وجود صانعها، وانتظامها على حكمته، ثم يشهد أن لا إله إلا الله وحده لا شريك له. لذلك قرن القرآن النظر بالتفكر والتبصر والانتقال من المخلوق إلى الخالق."},{"h":"خلاصة الدرس","t":"آيات الأنفس والآفاق أدلة وحدانية تدعو للتفكر: في السماوات والأرض وآيات الليل والنهار، وفي خلق الإنسان عبر مراحله الدقيقة، فالعبرة بالاتعاظ لا بالتعجب، والإعجاز العلمي وفاق لا تعسف، والغاية شهادة الحق وعبادة الله وحده."}],"qs":[{"q":"المراد بلفظ (الآفاق) في قوله تعالى: (سنريهم آياتنا في الآفاق وفي أنفسهم):","a":["عوالم الكون الخارجية في السماوات والأرض","أعضاء جسم الإنسان وأحواله الباطنة","جنود النصر وجيوش الغزوات","أحوال الأمم السابقة وحدها"],"c":0,"d":"easy","hint":"مقابل الأنفس","expl":"الصواب: الآفاق هي عوالم الكون الخارجية، والأنفس هي ما في الإنسان، فجمع بين الشاهدة الخارجية والداخلية. بقية الخيارات تتحدث عن الجنود أو التاريخ أو أحوال الباطن وقد ميزها القرآن بكلمة الأنفس. نصيحة: الآفاق = خارجك، الأنفس = داخلك."},{"q":"من آيات خلق الإنسان في القرآن الكريم:","a":["ولقد خلقنا الإنسان من سلالة من طين","والليل إذا يغشى","ألهاكم التكاثر","والعصر إن الإنسان لفي خسر"],"c":0,"d":"easy","hint":"بداية خلق آدم من العناصر","expl":"الصواب: (ولقد خلقنا الإنسان من سلالة من طين) آية خلق للإنسان صراحة. الآيات الأخرى سور قصار أدبية أو توجيهية لا تتعلق بمراحل الخلق. نصيحة: احفظ مواطن الخلق: طين، نطفة، علقة، مضغة."},{"q":"الهدف الأعظم من ذكر آيات التفكر في الأنفس والآفاق:","a":["الدلالة على عظمة الخالق ووحدانيته","تصوير الحياة الدنيا وبيان زوالها","إبراز قدرة الإنسان واستقلاله","إثارة الجدل العلمي حول الكون"],"c":0,"d":"easy","hint":"العبرة ينقلها من المخلوق إلى الخالق","expl":"الصواب: الغاية توحيد الله والاستدلال بقدرته وحكمته. الوصف الدنيوي له صور أخرى، واستقلال الإنسان أو الجدل العلمي ليس مقصود النص. نصيحة: كل آية كونية اسأل: ما وجه الدلالة على الله؟"},{"q":"قوله تعالى: (وفي أنفسكم أفلا تبصرون) يرشد إلى:","a":["التفكر في خلق الإنسان ليعرف قدرة خالقه","النبذ للنظر في الأعضاء لأنها رخيصة","الاكتفاء بالمشاهدة الطبية البحتة","ترك البحث في سائر آيات الكون"],"c":0,"d":"medium","hint":"الآية دعوة للنظر في داخلك","expl":"الصواب: تدعو الآية إلى البصر والتفكر في بديع خلق الإنسان، وهذه هي الإشارة التي تقود إلى التوحيد. ليست الآية نهياً عن النظر ولا اقتصاراً على الطب ولا نفي لسائر الآيات. نصيحة: (أفلا تبصرون) استفهام تقريري لتحريك العقل."},{"q":"موقف الإعجاز العلمي من الحقائق العلمية الثابتة:","a":["يؤكد وفاق النص الثابت مع العلم القطعي الصحيح","يحوّل النص إلى نظرية تتبدل بتبدل الظنون","يعطل عمل العلماء ويستغني عن التجربة","يجعل النص إشعاراً للخيال الأدبي فقط"],"c":0,"d":"medium","hint":"وفاق لا تناقض ولا تكلّف","expl":"الصواب: الإعجاز مبناه الموافقة بين الخبر اليقيني من الوحي والحقيقة الثابتة بالتجربة، دون تكلف تحميل النص نظريات متغيرة. وبقية الخيارات تصور العلاقة تحويلاً أو تعطيلاً أو أدبية بحتة. نصيحة: احذر من القول بإعجاز النصية لمعلومات غير ثابتة."},{"q":"العبرة في آيات خلق السماوات والأرض تعود إلى:","a":["الإيمان بأن المدبر لها إله واحد حكيم وعليم","عدّ الكواكب والنجوم والإحاطة بها","توقع صراع النجوم في الشهور القمرية","إنكار أن يكون للخلق خالق"],"c":0,"d":"easy","hint":"الانتظام الكامل يدل على المدبر","expl":"الصواب: انتظام هذه المخلوقات على صورة واحدة مستقرة دليل على خالق واحد يدبرها. مجرد العد أو التوقع العلمي لا يحقق مقصود النص، وأما إنكار الخالق فهو ضد الغاية. نصيحة: الارتباط بين النص والغاية هو التوحيد."},{"q":"عرض القرآن لمراحل تطور الجنين بالترتيب هو دليل على:","a":["دقة المعلومات الكونية النظرية وفصاحة الأسلوب في اللفظ","انفصال العلم النظري عن التجربة العملية","أن القرآن كتاب علوم طبية تفصيلي","أن هذه العبارات ليست من الإعجاز"],"c":0,"d":"hard","hint":"وصف مطابق لما وصل إليه علم الأجنة","expl":"الصواب: الترتيب الدقيق في النص (نطفة ثم علقة ثم مضغة...) يطابق ما ثبت في علم الأجنة الحديث، وهذا وجه من وجوه الإعجاز. القرآن ليس موسوعة طبية تفصيلية، والعلم النظري وحده لا ينتج الإعجاز. نصيحة: الإعجاز وفاق لا تداخل: وفاق بلا تفصيل كل شيء."}]},{"title":"آيات الأحكام (العبادات والمعاملات)","read":[{"h":"آيات العبادات","t":"تشتمل آيات الأحكام على آيات الوضوء: (يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق...)، وآيات الصلاة: (وأقيموا الصلاة وآتوا الزكاة)، وآيات الصيام: (كتب عليكم الصيام كما كتب على الذين من قبلكم)، وآيات الحج: (وأتموا الحج والعمرة لله). وقد قرن القرآن في كثير من المواضع بين الصلاة والزكاة لبيان امتنان العلاقة بين العبادة الخفية والظاهرة."},{"h":"آيات المعاملات","t":"عالج القرآن أحكام التعامل: أحل البيع وحرم الربا، فأمر بكتابة الدَّين وشهد عليه، وألزم بالوفاء بالعقود والعقود الجائزة بين الناس إلا ما حرم، وبالبر بالوالدين والإحسان إلى اليتامى، وبالقصاص في القتلى على وجه العدل دون إفراط، وبعدم أكل أموال الناس بالباطل إلا تجارة عن تراضٍ."},{"h":"التدرج في التشريع","t":"من حكمة القرآن في آيات الأحكام التدرج: فتحريم الخمر نزل مرات حتى جاء قوله (فاجتنبوه) حاسماً، وتحريم الربا تدرج من التنبيه إلى القطع في آخر سورة البقرة. والغاية من التدرج مراعاة أحوال المجتمع وقابليته للنقل من عادة إلى تشريع، وهذا نابع من رحمة الله بالعباد."},{"h":"مقاصد أحكام العبادات والمعاملات","t":"مقصد العبادات: صلاح القلب وإقامة ذكر الله وخشيته، فينعكس ذلك على سلوك العبد في معاملاته، فمن لا تنهه صلاته عن الفحشاء والمنكر فصيامه وصومه أداء له. ومقصد المعاملات: قيام العدل وضبط العلاقات بين الناس وحفظ المال من الخداع والربا وأكل أموال الناس بالباطل، حتى يتحقق صلاح دنياهم أهيأً لصلاح آخرتهم."},{"h":"خلاصة الدرس","t":"آيات الأحكام قسمان: عبادات (وضوء، صلاة، زكاة، صيام، حج) ومعاملات (بيع، دين، ربا، قصاص، بر بالوالدين، عدل). تدرج التشريع يبيّن الحكمة والرحمة، ومقاصد كل قسم: العبادة لصلاح القلب، والمعاملة لتحقيق العدل وحفظ المال والأنساب."}],"qs":[{"q":"اقتران ذكر الصلاة بذكر الزكاة في كثير من الآيات يدل على:","a":["عظيم مكانة كلتيهما وأنهما ركنا العبادات الجامعتان للظهر والباطن","أن الزكاة لا تجب إلا بعد أداء الصلاة","أن الزكاة بدل عن الصلاة لمن عجز","أن الصلاة تقع بعد الزكاة في الترتيب الدائم"],"c":0,"d":"medium","hint":"واجبان متلازمان في الذكر","expl":"الصواب: القرن بينهما يبيّن مكانتهما وأن الدين طهارة صلاة ومال، فيشيران للظهر والباطن بأسلوب الترغيب. لا يترتب على الاقتران سقوط أحدهما أو إحلاله محل الآخر. نصيحة: الاقتران في القرآن = التنويه بالشأن لا الترتيب الزمني."},{"q":"آية الصيام في سورة البقرة تبدأ بقوله تعالى:","a":["يا أيها الذين آمنوا كتب عليكم الصيام كما كتب على الذين من قبلكم","وأقيموا الصلاة وآتوا الزكاة","وأتموا الحج والعمرة لله","ولا تقربوا مال اليتيم إلا بالتي هي أحسن"],"c":0,"d":"easy","hint":"أول آية تشرع الصيام","expl":"الصواب: هذه الآية بيّنت فرضية الصيام على الأمة كما كان على من قبلها. بقية العبارات في الزكاة والحج والوصية باليتيم. نصيحة: احفظ أجمل آيات الأحكام مفتاحاً: الصيام = كتب عليكم."},{"q":"قوله تعالى: (إلا أن تكون تجارة عن تراض منكم) يدل على:","a":["أن التجارة المشروعة قائمة على الرضا الصحيح المتبادل","أن أي تجارة بيع مشروعة بلا شروط","أن الربا داخل في معنى التجارة الحلال","أن الرضا وحده كافٍ ولو خالفه الشرع"],"c":0,"d":"medium","hint":"أساس التعامل المشروع الرضا","expl":"الصواب: الآية شرطت في جواز أخذ المال أن يكون عن تجارة رضى بمعايير شرعية لا غرر فيها ولا ربا. أما الربا فلا يكون تجارة حلالاً لنهي النص عنه، وسائر الخيارات إطلاق بلا ضابط. نصيحة: الرضا المشروع = رضا صحيحاً لا ربا فيه ولا غش."},{"q":"تدرج القرآن في تحريم الخمر حتى حسمه بقوله (فاجتنبوه) يدلنا على:","a":["حكمة التشريع ومراعاته لتدرج المجتمع في الإقلاع عن العادة","اضطراب أحكام الشريعة في المسألة الواحدة","جواز شرب الخمر القليل ما دام غير يسكر","أن التحريم وقع دفعة واحدة بلا مراحل"],"c":0,"d":"hard","hint":"التحريم التدريجي عمل فقهي دلالي","expl":"الصواب: التحريم تدرج في النزول مراعاة لأحوال الناس، وهذه حكمة إلهية لا اضطراب. لم يجز النص الخمر قليلاً ولا كثر، والتحريم لم يقع دفعة واحدة. نصيحة: التدرج = رحمة، دفعة واحدة = تعسف، وهذا لن تجده في النص."},{"q":"قوله تعالى: (كتب عليكم القصاص في القتلى) يدل على:","a":["تشريع العدل في العقوبة بمقدار الجناية","جواز الزيادة في العقوبة على المقتول","سقوط العفو وإلغاء الدِّية في القصاص","وجوب القتال عند كل نزاع"],"c":0,"d":"easy","hint":"العدل في الجناية","expl":"الصواب: القصاص يعني المماثلة والعدل في العقوبة، وقد بيّن النص معه جواز العفو عن القاتل بالأولى. بقية الخيارات مخالفة لأصول الشريعة في التخفيف والعدل. نصيحة: القصاص = عدل، العفو = فضل."},{"q":"من آيات البيوع والمعاملات:","a":["وأحل الله البيع وحرم الربا","والذين هم على صلاتهم دائمون","فويل للمصلين الذين هم عن صلاتهم ساهون","تبارك الذي بيده الملك وهو على كل شيء قدير"],"c":0,"d":"easy","hint":"قاعدة التبادل المالي في القرآن","expl":"الصواب: الآية وضعت قاعدة التعامل المالي: إباحة البيع وتحريم الربا. بقية العبارات عن الصلاة والتسبيح لا تتصل بالمعاملات. نصيحة: عند سؤال البيوع ابحث عن كلمة البيع والربا والدَّين."},{"q":"الحكمة الكبرى في تشريع آيات الأحكام:","a":["تحقيق الصلاح والعدل والسعادة للفرد والمجتمع","تحميل الناس المشقة والتضييق عليهم","إهمال الناس ليتصرفوا بلا ضابط","إظهار القوة في التشريع وحدها دون المعنى"],"c":0,"d":"easy","hint":"غاية الشارع رحمة وسلامة","expl":"الصواب: مقاصد الشريعة صلاح الدين والدنيا بتحقيق العدل وحفظ الضروريات (الدين والنفس والعقل والمال والنسل). الشريعة لا تريد المشقة، وتبنّيها ما فيه الخير دائمًا. نصيحة: اجعل مقصد الضرورات الخمسة في ذهنك عند سؤال الحكم."}]}]}]},{"id":"azhadith","name":"الحديث وعلومه","icon":"🕌","color":"#FB8C00","books":[{"title":"قواعد الحديث الشريف","icon":"🕌","chapters":[{"title":"علم الحديث وتقسيم الخبر","read":[{"h":"تعريف الألفاظ: الحديث والسنة والخبر والأثر","t":"الحديث في اصطلاح المحدثين: ما أضيف إلى النبي ﷺ من قول أو فعل أو تقرير أو صفة خُلُقية أو خِلْقية. والسنة قريبة المعنى وتغلب على ما سلكه النبي من المسلك. والخبر: ما روي عن النبي أو غيره، وفي اصطلاح أهل الأصول مرادف للحديث يطلق على ما جاء عن من كان قبله. والأثر: ما نسب إلى الصحابة والتابعين غالباً."},{"h":"أقسام الخبر باعتبار طرق وصوله","t":"ينقسم الخبر باعتبار طرق وصوله إلى قسمين: (1) المتواتر: ما رواه جمع يحيل العقل تواطؤهم على الكذب، وعددهم في كل طبقة كثيف، يفيد العلم اليقيني ويجب الأخذ به كالقراءات والسنن المتواترة. (2) الآحاد: ما لم يجمع شروط المتواتر، وينقسم إلى مشهور وعزيز وغريب، ويفيد الظن غالباً ويُعمل به في الأحكام."},{"h":"الآحاد وأقسامه","t":"الآحاد ثلاثة: المشهور: ما رواه ثلاثة فأكثر في كل طبقة دون التواتر. العزيز: ما رواه راويان في كل طبقة. الغريب: ما تفرد بروايته راوٍ واحد في أي طبقة. وتكاثر الطرق يقوّي الحديث، وخلوّ الحديث عن طرق متعددة لا يسقطه ما دام صحيح الإسناد."},{"h":"السند والمتن","t":"السند: سلسلة الرجال الذين رووا الحديث متصلة إلى النبي ﷺ، والمتن: ما انتهى إليه السند من ألفاظ الحديث. وعلم الحديث إما رواية (ضبط نقل الحديث) وإما دراية (معرفة قواعد يُعرف بها المقبول من المردود). ومعرفة السند تمييّز بين الثقة وغيره، فتصح الرواية إذا رواه الثقة الضابط عن مثله."},{"h":"خلاصة الدرس","t":"الحديث ما أضيف للنبي قولاً أو فعلاً أو تقريراً، والخبر قد يتجاوزه، والأثر عن الصحابة. أقسام الخبر بطريق الوصول: متواتر مفيد للقطع، وآحاد (مشهور وعزيز وغريب) مفيد للظن ويعمل به. الإسناد هو العلامة المميزة لهذه الأمة، وعلم الرواية والدراية معاً لحفظ السنة."}],"qs":[{"q":"الحديث في اصطلاح المحدثين هو:","a":["ما أضيف إلى النبي ﷺ من قول أو فعل أو تقرير أو صفة","كل ما ورد في القرآن الكريم","ما فهمه العلماء من النصوص الشرعية","كلام المجتهدين في الفقه والأصول"],"c":0,"d":"easy","hint":"المرجع إلى النبي ﷺ","expl":"الصواب: الحديث خاص بما أضيف لرسول الله ﷺ من قول أو فعل أو تقرير أو صفة. القرآن وحي منزل غير حديث، وأقوال العلماء اجتهادات لا حديث. نصيحة: الحديث = المنسوب للنبي فقط."},{"q":"الخبر المتواتر هو ما:","a":["رواه جمع تحيل العادة تواطؤهم على الكذب في كل طبقة","رواه راوٍ واحد عن النبي ﷺ","رُوي بلفظ الراوي دون أصله","انقطع سنده في طبقة من الطبقات"],"c":0,"d":"medium","hint":"الكثرة المانعة من التواطؤ","expl":"الصواب: المتواتر ضابطته استحالة تواطؤ جمع كبير في كل الطبقات على الكذب، فيفيد العلم القطعي. الخيارات الباقية من خصائص الآحاد والضعيف. نصيحة: الكلمة (تحيل العادة) مفتاح تعريف المتواتر."},{"q":"الخبر الآحاد هو ما:","a":["لم يجمع شروط المتواتر","روايتين في الطبقة الأولى فقط","متفق على رفضه عند الجمهور","قطع عن روايته للأحكام عند الحنفية"],"c":0,"d":"medium","hint":"المعنى: غير المجمع لشروط التواتر","expl":"الصواب: الآحاد هو ما نقص عن شروط المتواتر بكل أقسامه (مشهور وعزيز وغريب)، وهو يفيد الظن ووجب العمل به عند الجمهور في الأحكام. ليس الكل مردوداً، فالصحيح منه مقبول. نصيحة: التقسيم: متواتر قطعي، آحاد ظني معمول به."},{"q":"التقرير في اصطلاح المحدثين يطلق على:","a":["سكوت النبي ﷺ عن فعل أو قول وقع بحضرته ولم ينكره","نقل الحديث عن النبي بحرفه ولفظه","رفع الحديث إلى النبي بإسناد متصل","الزيادة في الحديث على نسخة أصله"],"c":0,"d":"medium","hint":"سكوت عن المنكر = إقرار","expl":"الصواب: التقرير أن يقع فعل بحضرة النبي ﷺ فيقره، وهذا يدل على إباحة الفعل لأنه لو كان منكراً لأنكر. الخيارات الأخرى خلط بمصطلحات أخرى كالرفع والنقل. نصيحة: التقرير = السكوت والإقرار."},{"q":"الإسناد في الحديث هو:","a":["سلسلة الرجال الذين رووا الحديث إلى النبي ﷺ","اللفظ الدال على معنى الحديث نفسه","شرح غريب الحديث وبيان معانيه","تخريج الحديث في كتب التفسير"],"c":0,"d":"easy","hint":"طريق الرواة","expl":"الصواب: الإسناد طريق الرواة الموصل إلى النبي ﷺ، وهو الجزء الذي يختبر به صدق الرواية. المتن هو اللفظ، والشرح له علم آخر، وتخريج الحديث في كتب أخرى ليس الإسناد. نصيحة: السند طريق، والمتن المقصد."},{"q":"عند تقسيم الخبر إلى متواتر وآحاد فالاعتبار يكون:","a":["بعدد الطرق وكثرة الرواة في كل طبقة","بلغة الرواة وأعرافهم","بطول اللفظ أو قصوره","بموافقة الحديث للقياس"],"c":0,"d":"easy","hint":"أصل التقسيم راهن","expl":"الصواب: التقسيم مبني على عدد الرواة في الطبقات وطرق الحديث، وهذه هي عين الضابطة. لا علاقة للغة، ولا للطول والقصر، ولا لموافقة القياس بهذا التقسيم. نصيحة: المتواتر/الآحاد = سؤال عن العدد والطرق."},{"q":"حكم العمل بالخبر الآحاد الصحيح عند جماهير أهل السنة:","a":["وجوب العمل به في الأحكام والعبادات","إهماله إهمالاً تاماً في كل باب","عدم اعتباره إلا في فضائل الأعمال","تأخيره عن الرأي والقياس عند كل خلاف"],"c":0,"d":"medium","hint":"مفيد للظن لكنه معمول به","expl":"الصواب: الآحاد الصحيح معمول به في الحلال والحرام والاعتقاد عند الجمهور، فإن مثبتوه عصمة العمل. ترك العمل بالآحاد مذهب باطل، وقصره على فضائل الأعمال لا يسلم، ولم يوقف التقديم عن الرأي والقياس. نصيحة: أصل الأمة: الآحاد حجة في الأحكام."}]},{"title":"أقسام الحديث الصحيح والحسن والضعيف","read":[{"h":"الحديث الصحيح لذاته وشروطها","t":"الحديث الصحيح لذاته: ما اتصل سنده بعدول ضابطين من أول السند إلى منتهاه، وسلم من الشذوذ والعلة القادحة. فاشترطوا: اتصال السند، وعدالة الراوي، وضبطه التام، وعدم الشذوخ (عدم مخالفة الثقة لمن هو أوثق منه)، وعدم وجود علة قادحة خفية. فإذا اجتمعت سمي صحيحاً لذاته."},{"h":"الحديث الحسن لذاته","t":"الحديث الحسن لذاته: ما اتصل سنده بنقل العدل الخفيفِ الضبطِ من غير شذوذ ولا علة. فهو كالصحيح في شروطه لكن ضبط راويه أنزل قليلاً؛ أي ضبط قصير لا بلادة، فيؤخذ به ويعمل به، وهو حجة في العمل عند الجمهور، وإن كان دون الصحيح في الرتبة."},{"h":"الحديث الحسن لغيره","t":"الحديث الحسن لغيره: الحديث الضعيف الذي لم يكن ضعفه شديداً وتعددت طرقه واشتدّت بتعددها، فارتقى إلى مرتبة الحسن لغيره. مثال: حديث يرويه راوٍ صدوق فيه لين، فإذا جاء من طريق آخر سالم لم يجعل ما يرويه ضعيفاً، قويت الحجة بجمع الطرق وإن كان كل طريق منفرداً لا يقوم به بنفسه."},{"h":"الحديث الضعيف وأقسام ضعفه","t":"الحديث الضعيف: ما فقد شرطاً من شروط الصحيح أو الحسن، كضعف الراوي أو انقطاع السند أو إرسال أو اختلاط أو تدليس. وليس ضعفه كله بمرتبة واحدة: فمنه منكر وشاذ، ومنه معلول، ومن أكثره ضعفاً الموضوع المختلق على النبي ﷺ. وأشهر أسباب الوضع: الزندقة والطائفية ورواية القصاص والترغيب والترهيب على لسانه ﷺ."},{"h":"حكم رواية الضعيف والعمل به","t":"يجوز رواية الحديث الضعيف في فضائل الأعمال والترغيب والترهيب بشروط: (1) ألا يشتد ضعفه بكون الراوي كذاباً أو متهماً. (2) أن يندرج تحت أصل معمول به. (3) ألا يعتقد ثبوته عند العمل به، ولا يذكر بلفظ الجزم القوي كأنه ثابت. وأما الأحكام والعقائد فلا يعمل بالضعيف فيها، وإنما يحتج بالصحيح والحسن فقط."},{"h":"خلاصة الدرس","t":"الصحيح لذاته: اتصال وعدالة وضبط تام بلا شذوذ ولا علة. الحسن لذاته: راوٍ عدل خفيف الضبط. الحسن لغيره: ضعيف مجبور بتعدد الطرق. الضعيف: فقد شرط أو تخلف ضبط، وأسوأه الموضوع. الرواية في الفضائل بشروط، والحجية في الأحكام والعقائد للصحيح والحسن."}],"qs":[{"q":"شروط الحديث الصحيح لذاته:","a":["اتصال السند وعدالة الضبط بلا شذوذ ولا علة قادحة","عدالة الراوي مع خفّة ضبطه جملة","انقطاع السند مع سلامة المتن من العلل","شهرة الحديث بطرقه وموافقته للقياس"],"c":0,"d":"easy","hint":"أركان القبول كلها","expl":"الصواب: الصحيح لذاته يحتاج إلى اتصال السند وعدالة الضابط وعدم الشذوذ والعلة. خفة الضبط كلمة الحسن لا الصحيح، وانقطاع السند يفتح الطريق للضعف، والموافقة للقياس ليست شرطاً. نصيحة: احفظ خمسة: اتصال، عدالة، ضبط، لا شذوذ، لا علة."},{"q":"الحديث الحسن لذاته هو ما:","a":["اتصل سنده بنقل عدل خفيف الضبط خالٍ من الشذوذ والعلة","اتصل سنده بنقل كذاب مشهور بالوضع","انقطع سنده في أول السند دون آخر","رواه راوٍ اقتصر فيه على الملازمة"],"c":0,"d":"medium","hint":"الراوي عدل لكن ضبطه أقل قليلاً","expl":"الصواب: الحسن لذاته راوبه عدل خفيف الضبط، فقد صدق وأدَّى لكن ضبطه لا يبلغ درجة الصحيح. الخيارات الباقية خصائص الضعيف والموضوع. نصيحة: الفرق بين الصحيح والحسن = درجة الضبط."},{"q":"الحديث الحسن لغيره هو:","a":["الضعيف الذي تعددت طرقه وخلت من الشذوذ والعلة فتقوى للحسن","الحديث الموضوع الذي لا يعمل به","الصحيح الذي خالف فيه راوٍ أوثق منه","المرفوع الذي لم يروه إلا راوٍ واحد"],"c":0,"d":"hard","hint":"ضعف يسير يحبسه طرقه","expl":"الصواب: الحسن لغيره حديث ضعيف من اليسر بحيث لا يكون موضعاً ولا شاذا ولا معلولاً، فإذا انضم إليه طريق أو طرق أخرى قوي ليرتقي إلى الحسن. شذوذ الحديث أو علته أو وضعه يمنع التقوية بالطرق أصلًا. نصيحة: (لغيره) = الترقية بسبب خارجي هو كثرة الطرق."},{"q":"من أهم أسباب ضعف الحديث:","a":["انقطاع السند وعدم ضبط الراوي والتدليس","تواتر طرقه وثقة رواته","متابعة الثقات لضعيف وتقويته","وصول الرواة إلى درجة القبول"],"c":0,"d":"easy","hint":"ما الذي يجعل الحديث مردوداً؟","expl":"الصواب: الانقطاع والجهالة وضعف الضبط والتدليس أسباب مباشرة للضعف. أما تواتر الطرق ومتابعة الثقات فهما من موجبات القبول لا الرد. نصيحة: اعكس الذهنية: قوي ضعيف = يضعف، تكاثر طرق = يقوي."},{"q":"الحديث الذي اشتد ضعفه لكونه باطلاً مختلقاً على النبي ﷺ يسمى:","a":["الموضوع","الحسن لغيره","العزيز","الصحيح الغريب"],"c":0,"d":"medium","hint":"مختلق مفترى","expl":"الصواب: الموضوع هو المفترى المختلق المنسوب إلى النبي ﷺ كذباً، وهو أشد أقسام الضعيف ضعفاً ولا تجوز روايته إلا للبيان. الحسن لغيره ليس موضوعاً، والعزيز والغريب من أقسام الآحاد. نصيحة: الموضوع = مكذوب، لا يحتج به ولا يروى إلا للتحذير."},{"q":"حكم رواية الحديث الضعيف في فضائل الأعمال:","a":["جائزة بشروط: ألا يشتد ضعفه ويدندرج تحت أصل ولا يعتقد ثبوته","جائزة في جميع الأحكام بلا قيد","ممنوعة مطلقاً حتى للبيان","جائزة مع نسبته إلى النبي ﷺ وبيان معناه الثابت"],"c":0,"d":"medium","hint":"ضوابط شرطها العلماء","expl":"الصواب: أجاز العلماء الرواية في فضائل الأعمال والترغيب والترهيب بثلاثة شروط: ألا يشتد الضعف، وأن يندرج تحت أصل، وألا يعتقد ثبوته. الرد على الأحاديث الموضوعة ممنوع، والحمل في الأحكام لا يثبت بالضعيف. نصيحة: الفضائل مقيدة بالشروط الثلاثة في امتحانك."},{"q":"حكم الاحتجاج بالحديث الضعيف في الأحكام والعقائد:","a":["لا يحتج به في شيء من الأحكام ولا العقائد","يقدم على الآحاد في العقائد عند التعارض","يخصص به النص القطعي المتواتر","يقدم على القياس في كل مسألة بلا ضابط"],"c":0,"d":"easy","hint":"الحجية للمقبول","expl":"الصواب: الأحكام والعقائد تثبت بالصحيح والحسن، أما الضعيف فلا حجة فيه ولا يخصص القطعي ولا يقدم على الآحاد. نصيحة: ضعيف = لا حكم ولا عقيدة."},{"q":"العلة القادحة في الحديث هي:","a":["سبب خفي يقدح في صحة الحديث مع أن ظاهره السلامة","متابعة راوٍ ثقة لراوٍ ضعيف في الرواية","بلغ الرواية في السند إلى حد الكمال","اختصار الحديث المشهور المتواتر"],"c":0,"d":"hard","hint":"عيب خفي يبطل لا يظهر للجميع","expl":"الصواب: العلة الزيادة الخفية في الإسناد أو المتن التي يطلع عليها أئمة الحديث بالفحص، وهي قادحة وإن ظهر للحديث ظاهره القبول. والمتابعة تقوية لا علة، والاختصار المتواتر لا يقدح في أصله. نصيحة: العلة خفيه: ابحث عنها بالمقابلة بين الطرق."}]},{"title":"مقدمة كتب الحديث وطبقات الرواة","read":[{"h":"كتب الحديث وأصحها","t":"أصح الكتب بعد كتاب الله تعالى صحيح البخاري ثم صحيح مسلم، وهما يسميان بالصحيحين. بعدهما السنن: سنن أبي داود والترمذي والنسائي وابن ماجه، مع موطأ مالك ومسند أحمد، واتفقت هذه الكتب على شيء من التدقيق والتصنيف. وشرط البخاري في القبول أعلى وأشد من شرط مسلم، لذلك قُدم عليه."},{"h":"شرط البخاري وشرط مسلم","t":"شرط الإمام البخاري: ثبوت سماع الراوي ممن روى عنه مع كونه في طبقة قريبة تضمن الملامسة المباشرة، والعدالة مع تمام الضبط، وقد اشترط في أصحابه ذلك أشد اشتراط. وشرط مسلم أقل في اشتراط العنعنة والمصاحبة، فقبل التحديث بالعنعنة مع المعاصرة. لذلك قال العلماء: شرط البخاري أعلى من شرط مسلم."},{"h":"طبقات الرواة والصحابة والتابعين","t":"يعد علماء الحديث طبقات الرواة مرتبة كي يعرفوا منزلة كل راوٍ واحتمال سماعه. والصحابة كلهم عدول: من لقي النبي ﷺ مؤمناً به ومات على ذلك، فتُقبل روايتهم مطلقاً. التابعون: من لقي الصحابة آمن، وهم مراتب عدة، وأتباع التابعين بعدهم. وأشهر طبقات الصحابة عند الأئمة: السابقون وأهل بدر، ثم من أسلم بعدهم."},{"h":"فوائد علم طبقات الرواة","t":"قد تُدرس الطبقات للعدالة والضبط، وفيها فوائد: تعرف منزلة الراوي وإمكان سماعه ممن فوقه، ومعرفة تفرد الراوي بحديث، والتمييز بين المتقدم والمتأخر في الإسناد، وأن العلم بدرجة كل راوٍ يصون المسلم من النقل بلا تثبت. وقد اشتهر في ذلك كتب مثل \"الطبقات الكبرى\" لابن سعد وتواريخ الرواة."},{"h":"خلاصة الدرس","t":"الصحاح الستة: البخاري ومسلم والسنن الأربعة، وأصحها بعد كتاب الله البخاري فمسلم، وشرط البخاري أعلى من شرط مسلم. طبقات الرواة: الصحابة عدول جميعاً، ثم التابعون وأتباعهم، ودراسة طبقاتهم تفيد صحة الأحكام على السند وتعيين درجة الراوي."}],"qs":[{"q":"أصح الكتب بعد كتاب الله تعالى:","a":["صحيح البخاري ثم صحيح مسلم","الموطأ للإمام مالك","سنن أبي داود والترمذي","مسند أحمد بن حنبل"],"c":0,"d":"easy","hint":"متفق عليه عند الجميع","expl":"الصواب: صحيح البخاري أولا ثم صحيح مسلم، فهما أصح ما صنف في الحديث بعد القرآن. بقية الكتب مصنفات معتمدة لكنها تأتي بعد الصحيحين. نصيحة: اعرف ترتيب: البخاري ثم مسلم ثم بقية الأسماء."},{"q":"من أصحاب كتب السنن:","a":["أبو داود والترمذي والنسائي وابن ماجه","الدارقطني والبيهقي والخطيب","الذهبي وابن حجر والسخاوي","أحمد بن حنبل ومالك وأبو حنيفة"],"c":0,"d":"medium","hint":"السنن الأربع","expl":"الصواب: أصحاب السنن هم أبو داود والترمذي والنسائي وابن ماجه، وهم مع البخاري ومسلم تكوّن الكتب الستة. الخياران الأخيران للمتأخرين من المحدثين. نصيحة: احفظ: الستة = البخاري ومسلم وأربع سنن."},{"q":"شرط الإمام البخاري في صحة الحديث:","a":["أعلى وأشد من شرط مسلم","أدنى من شرط أئمة السنة الأربعة","مساوٍ تماماً لشرط مسلم","أوسع من شرط النسائي في المتابعات"],"c":0,"d":"medium","hint":"التشدد في السماع والعنعنة","expl":"الصواب: البخاري أشد في اشتراط ثبوت اللقاء والسماع، بينما مسلم اكتفى بمعاصرة الراويين. ولذلك قيل شرط البخاري أعلى. نصيحة: البخاري = التشدد بالسماع، مسلم = المعاصرة."},{"q":"التابعون هم الذين:","a":["لقوا الصحابة مؤمنين بالنبي ﷺ","عاصروا أهل البيت فقط","قابلوا الأئمة الأربعة للفقه","تتلمذوا على المحدثين المتأخرين"],"c":0,"d":"easy","hint":"الطبقة بعد الصحابة","expl":"الصواب: التابعون هم من لقوا الصحابة وآمنوا، وهم نواة الطبقة الثانية في الإسناد. عاصرة أهل البيت أو الأئمة الأربعة ليس ضابط التابعية. نصيحة: التابعي = لقاء صحابي."},{"q":"المراد بطبقات الرواة عند المحدثين:","a":["مراتبهم المتدرجة بحفظهم وضبطهم وقرب إسنادهم من النبي ﷺ","أعيادهم والتواريخ الميلادية لولادتهم","عدد مصنفاتهم وكتبهم المؤلفة فقط","مذاهبهم الفقهية وانتسابهم للبلدان"],"c":0,"d":"medium","hint":"المراتب للإسناد والحفظ","expl":"الصواب: الطبقات تنظم درجات الرواة في الإسناد والحفظ والضبط، فيسهل بذلك معرفة منزلة كل راوٍ. بقية الخيارات أمور شخصية لا تشكل علم الطبقات. نصيحة: الطبقات = سلم تنازلي من النبي ﷺ إلى المتأخرين."},{"q":"الصحابة رضي الله عنهم:","a":["كلهم عدول تقبل روايتهم مطلقاً","منهم متهمون لا تقبل روايتهم","لا تقبل روايتهم إلا بتوثيق خاص","فرض فيهم التدقيق كالتابعين"],"c":0,"d":"easy","hint":"عدالة صحابية","expl":"الصواب: الصحابة كلهم عدول بنصوص القرآن والفضائل، لأنهم شهود الوحي والرسالة، فتقبل مروياتهم بلا بحث في العدالة. الخيارات الأخرى تضع الصحابة مع غيرهم في العدالة، وهو خلاف الإجماع. نصيحة: عدالة الصحابة قضية مسلمة."},{"q":"من أهم فوائد معرفة طبقات الرواة:","a":["معرفة إمكانية السماع ومنزلة الراوي وصحة السند","شغل المحدثين عن خدمة السنة","تزيين الكتب بالإسناد الطويل","إهمال دراسة المتن والاهتمام بالإسناد فقط"],"c":0,"d":"easy","hint":"ماذا ينتفع منه الباحث؟","expl":"الصواب: طبقات الرواة تعين على معرفة لقاء الراوي بمن فوقه ومنزلته في الحفظ والضبط، وهذه أساس تصحيح الأسانيد. الإسناد الطويل بلا فائدة أو إهمال المتن يكسر المقصود. نصيحة: علم الطبقات = خدمة أصلية لتحقيق الإسناد والمتن معاً."}]}]}]},{"id":"azfiqh","name":"الفقه","icon":"⚖️","color":"#C62828","books":[{"title":"الفقه الشافعي","icon":"⚖️","chapters":[{"title":"الطهارة والوضوء والصلاة","read":[{"h":"أقسام الطهارة والمياه","t":"الطهارة شرط للعبادات، وتنقسم إلى: طهارة الحدث (رفع الحدث الأصغر بالوضوء وحث الأكبر بالغسل) وطهارة الخبث (إزالة النجاسة من البدن والثوب والمكان). والمياه على أقسام في المذهب: طهور (باقٍ على خلقته الأولى يرفع الحدث ويزيل الخبث، كالماء المطلق)، وطاهر مباح الاستعمال (كالماء المتمم المعار به)، وماء نجس لوقوع نجاسة غلبته."},{"h":"فروض الوضوء عند الشافعية","t":"فروض الوضوء ثمانية: (1) النية بقلبه أول الطهارة، (2) غسل الوجه كاملاً، (3) غسل اليدين إلى المرفقين، (4) مسح شيء من الرأس، (5) غسل الرجلين إلى الكعبين، (6) الترتيب بين الأعضاء، (7) الموالاة المعتبرة عرفاً بين الغسل والمسح، (8) الدلك في الأعضاء. والسنن من تسمية وغسل الكفين والمضمضة والاستنشاق ومسح الأذنين والتثليث وغيرها."},{"h":"نواقض الوضوء","t":"نواقض الوضوء: خروج شيء من السبيلين (قبل أو دبر) وإن لم يصاحب له ريح، والنوم المستغرق الذاهب بالشعور (غير القائم الجالس على شرفه)، واللمس بالبشرة بين الرجل والمرأة الأجنبية المجردة من الحائل، ومس فرج الآدمي بباطن الكف كله، وارتداد المسلم، والجنون والإغماء والسكر. فإذا انتقض الوضوء بطلت الطهارة وقام إليها من جديد."},{"h":"الصلاة: شروط وأركان وسنن ومبطلات","t":"شروط الصلاة: الإسلام والعقل والتمييز والطهارة وستر العورة واستقبال القبلة ودخول الوقت واجتناب النجاسة. أركانها: النية والقيام الفتحة، والصلاة على النبي في الجلسة الأولى والثانية، والتشهدان، والسلام الخروج. ومبطلات الصلاة: الكلام عمداً مع العلم والقدرة، والأكل أو الشرب عمداً، والحدث بالبطلان، وعدم الفتحة أو أحد الأركان عمداً. وسجود السهو سجدتان قبل السلام غالباً يجبر به الخلل القبلي."},{"h":"خلاصة الدرس","t":"الطهارة نوعان: حدث وخبث. فروض الوضوء ثمانية أشهرها النية والغسل والمسح والترتيب والموالاة والدلك. النواقض: الخارج، النوم، اللمس بشرة، المس الفرج، الردة، الجنون. الصلاة شروط وأركان وسنن ومبطلات، وسجود السهو سجدتان قبل السلام غالباً."}],"qs":[{"q":"فروض الوضوء عند الشافعية تشمل:","a":["النية وغسل الوجه واليدين ومسح الرأس وغسل الرجلين مع الترتيب والموالاة والدلك","النية وغسل الوجه فقط","الترتيب وحده دون غسل الأعضاء","تثليث الغسل والمضمضة والاستنشاق"],"c":0,"d":"medium","hint":"ثمانية فروض في المذهب","expl":"الصواب: الفروض الثمانية تجمع النية والغسل للوجه واليدين والرجلين ومسح بعض الرأس والترتيب والموالاة والدلك. المضمضة والاستنشاق والتثليث من السنن لا الفروض عند الجمهور. نصيحة: احفظ: الفرض 8، السنن تزيد على ذلك."},{"q":"من نواقض الوضوء:","a":["خروج شيء من السبيلين والنوم المستغرق واللمس بشرة وأكل امرأة","مس المصحف من غير طهارة","أكل الطعام ولو سُغت منه كثيراً","لبس الخفين على طهارة كاملة"],"c":0,"d":"easy","hint":"ما الذي يبطل الطهارة؟","expl":"الصواب: الخارج من السبيلين والنوم المغشد واللمس بشرة بين الرجل والمرأة ونحوها من النواقض. مس المصحف شرط لمس لا ناقض للوضوء، والأكل والشرب ليسا بناقضين، ولبس الخفين سنة بشرطها. نصيحة: أثبت النواقض كلها: خارج، نوم، لمس، مس فرج، ردة، جنون."},{"q":"الغسل واجب عند:","a":["خروج المني والجماع والحيض والنفاس","الجنون والإغماء والنوم الطويل","لمس الرجل لزوجته من غير إنزال","رؤية الدم في الظفر من غير نضح"],"c":0,"d":"medium","hint":"الجنابة والحيض والنفاس","expl":"الصواب: تجب الطهارة الكبرى من الجنابة (بإنزال المني أو التقاء الختانين ولو بلا إنزال) ومن الحيض والنفاس. اللمس بلا إنزال أو الإغماء أو النوم من غير نازل لن تجب فيه الغسل بل يوجب الوضوء في الظروف المخصوصة. نصيحة: الغسل = ماء يجزئ في الجنابة والحيض والنفاس."},{"q":"عدد تكبيرات صلاة الجنازة عند الشافعية:","a":["أربع تكبيرات","ثلاث تكبيرات","خمس تكبيرات","تسع تكبيرات"],"c":0,"d":"medium","hint":"المشهور في المذهب","expl":"الصواب: المشهور عند الشافعية أربع تكبيرات في صلاة الجنازة: تكبيرة الإحرام ثم الصلاة على النبي ثم الدعاء ثم السلام. الخيارات الأخرى مذاهب أو أوهام لا يوافق عليها المذهب. نصيحة: الجنازة = 4 تكبيرات."},{"q":"من أركان الصلاة عند الشافعية:","a":["قراءة الفاتحة وحدها من القرآن لكل ركعة","الإقامة الحسنة قبل التكبير","الأذان للجماعة في المسجد","رفع اليدين عند التكبير"],"c":0,"d":"easy","hint":"الفاتحة ركن في كل ركعة","expl":"الصواب: قراءة الفاتحة في كل ركعة ركن من أركان الصلاة عند الشافعية، فلا صلاة لمن لم يقرأ بها. الإقامة والأذان ورفع اليدين سنن وليست أركاناً. نصيحة: الفرق: الأركان تبطل بتركها، والسنن تجبر بسجود السهو."},{"q":"من مبطلات الصلاة:","a":["الكلام العمد في صلاته مع الذكر والاستطاعة","أكل شيء يسير سهواً في الصلاة","قول آمين بعد الفاتحة","السجود للسهو في موضعه"],"c":0,"d":"easy","hint":"ما الذي يفسد الصلاة؟","expl":"الصواب: الكلام العمد من جنس كلام الناس يبطل الصلاة، أما السهو فمعفوّ عنه ما لم يفتح باب الفتحة بالنكتة المشتهاة. أكل يسير سهواً غير مبطل على الصحيح، وآمين وسجود السهو من تمام الصلاة. نصيحة: مبطلات الصلاة = كلام، أكل، حدث، ترك ركن."},{"q":"سجود السهو الغالب في المذهب يكون:","a":["سجدتين قبل السلام غالباً يجبر بهما الخلل الذي وقع في الصلاة","سجدة واحدة بعد السلام دائماً","ثلاث سجدات في كل ركعة","سجوداً يجزئ عن قضاء ما سقط من الفرائض"],"c":0,"d":"hard","hint":"الوقت الغالب له قبل الخروج","expl":"الصواب: سجود السهو سجدتان يُسجي فيهما القبلة قبل السلام غالباً، ويجبر بهما الخلل غير المبطل للصلاة. لا يجزئان عن قضاء الفرائض، وعدد السجود لا يقل عن مرتين عند الشارع. نصيحة: تذكّر: السهو = سجدتان قبل السلام."},{"q":"حكم مسح الخفين عند الشافعية بشروطه:","a":["جائز للمسافر ثلاثة أيام بلياليها وللمقيم يومًا وليلة بشرط لبسهما على طهارة","غير جائز في المذهب إطلاقاً","جائز للمقيم ثلاثة أيام والمسافر يومًا","بديل أصلي للغسل في كل الأحوال"],"c":0,"d":"medium","hint":"وقت المسح يتحدد بالسفر والإقامة","expl":"الصواب: المذهب يجيز المسح على الخفين شريطة لبسهما مع الطهارة، والمدة: المقيم يوم وليلة، والمسافر ثلاثة أيام بلياليها. الخيارات الأخرى عكست المدد أو منعت الحكم أصلاً. نصيحة: حافظ: مسافر 3، مقيم 1، والشرط لبس على طهارة."}]},{"title":"الزكاة والصيام","read":[{"h":"شروط وجوب الزكاة","t":"الزكاة ركن من أركان الإسلام وفرض عين على المكلف بشرط: الحرية والإسلام وملك النصاب ملكاً تاماً خالياً من الدين والحاجات الأصلية، ومضي الحول على النصاب في النقدين والمواشي، ويكون المال نامياً. والزكاة إنما تجب على المسلم القادر، ولا تجب على الكافر في الدنيا في مذهبنا وإن أُخذت منه في قول آخر."},{"h":"النصاب والواجب","t":"نصاب الذهب: عشرون مثقالاً (ديناراً) وعليه نصف العشر (2.5%) إن حال عليه الحول. ونصاب الفضة: مائتا درهم. وزكاة الزروع والثمار: العشر كاملًا فيما سقي بلا مؤونة، ونصف العشر فيما سقي بمؤونة، بشرط بلوغ النصاب وهو خمسة أوسق. وزكاة عروض التجارة تُقوَّم بنصاب أحد النقدين."},{"h":"مصارف الزكاة الثمانية","t":"مصارف الزكاة ثمانية ذكرها الله في سورة التوبة: (1) الفقراء، (2) المساكين، (3) العاملون عليها، (4) المؤلفة قلوبهم، (5) في الرقاب، (6) الغارمون، (7) في سبيل الله، (8) ابن السبيل. ولا يجوز صرف الزكاة لهاشمي في المذهب عند الشافعية ولا نقلها من بلد وجبت فيها إبعد إلا لمصلحة."},{"h":"أركان الصيام ومفسداته","t":"الصيام عبادة بدنية فرضها الله بقوله (كتب عليكم الصيام). أركانه: الإمساك عن المفطرات من طلوع الفجر إلى غروب الشمس مع النية (من الليل لكل يوم في الفرض). ومن مفسداته: الأكل والشرب عمداً، والقيء عمداً، والجماع، وإنزال المني عمداً، وكل ما وصل إلى الجوف عمداً من غير عذر. ومن أفطر بعذر يقضي، ومن عجز عجزاً مستمراً ككبر أو مرض مزمن أفطَر وأطعم عن كل يوم مسكيناً (الفدية)."},{"h":"زكاة الفطر","t":"زكاة الفطر صاع من قوت البلد عن كل مسلم وعمن يمونه من المسلمين، وهي واجبة بغروب شمس آخر يوم من رمضان. وقت إخراجها المسنون: قبل صلاة العيد، ولا يحل تأخيرها عن يوم العيد. وحكمتها: طهرة للصائم من اللغو والرفث، وطعمة للمساكين في يوم العيد."},{"h":"خلاصة الدرس","t":"الزكاة تجب بالحرية والإسلام وملك النصاب التام ومرور الحول، نصاب الذهب 20 مثقالاً والفيتين 200 درهم، ومصارفها ثمانية. الصيام ركن بالنية والإمساك، وتفسده المفطرات عمداً، والعاجز عجزاً مستمراً يفدي، وزكاة الفطر صاع عن المسلم عن نفسه وعمن يمونه."}],"qs":[{"q":"نصاب الذهب الذي تجب به الزكاة عند الشافعية:","a":["عشرون مثقالاً (ديناراً)","أربعون مثقالاً","خمسة مثقالات","مائة درهم"],"c":0,"d":"easy","hint":"نصاب الذهب والفضة","expl":"الصواب: نصاب الذهب عشرون مثقالاً، ونصاب الفضة مائتا درهم، وعليهما نصف العشر. بقية الأرقام لا تمثل نصوصاباً معتمدة في المذهب. نصيحة: 20 ذهب = 200 فضة، ولكل نصيب نصف العشر."},{"q":"الواجب في زكاة الزروع المسقية بمؤونة (كالمسقاة بالآلات والمحركات):","a":["نصف العشر أي (5%)","العشر كاملاً (10%)","ربع العشر أي (2.5%)","الثلث من المحصول"],"c":0,"d":"medium","hint":"المؤونة تخفف الواجب","expl":"الصواب: المؤونة على المالك في السقي تجعل الواجب نصف العشر 5%، وقد سقته مياه الأمطار والأنهار بلا مؤونة تجب العشر كاملاً 10%. الخيارات الأخرى لا توافق قواعد الشارع في تقدير النسب. نصيحة: بلا مؤونة = عشر، بمؤونة = نصف عشر."},{"q":"من المصارف الثمانية للزكاة:","a":["الفقراء والمساكين والعاملون عليها والمؤلفة قلوبهم والغارمون وابن السبيل","الأقارب الأغنياء لمجرد القرابة","الجهات الخيرية خارج بلد الزكاة بلا ضابط","المساجد وصيانتها النفقات العامة"],"c":0,"d":"easy","hint":"آية التوبة في المصارف","expl":"الصواب: المصارف ثمانية في آية (إنما الصدقات للفقراء والمساكين...)، فالغني القريب لا يعطى لنفسه، وتحويل الزكاة ونقلها من بلدها مقيد بمصلحة، والمساجد ليست من مصارف الزكاة عند الجمهور. نصيحة: احفظ ثمانية: فقير، مسكين، عامل، مؤلف، رقاب، غارم، سبيل الله، ابن السبيل."},{"q":"حكمة مشروعية زكاة الفطر:","a":["طهرة للصائم من اللغو والرفث وطعمة للمساكين","تعويض عن صيام رمضان لمن أفطر","ضريبة على الأغنياء من التجار فقط","وسيلة لزيادة نصاب الأموال النقدية"],"c":0,"d":"easy","hint":"حكمتها الخاصة بالصائم والمسكين","expl":"الصواب: زكاة الفطر تطهر الصائم من اللغو وتغني المساكين عن السؤال يوم العيد، وهي واجبة على المسلم عن نفسه وعمن يمونه. ليست عوضاً عن الصيام ولا ضريبة، ولا تخص التجار. نصيحة: تذكّر قول*w: طهرة الصائم وطعمة المساكين."},{"q":"حكم صيام رمضان:","a":["فرض عين على كل مكلف قادر خالٍ من الموانع الحقية","سنة مستحبة لا تثبت إلا بالنفل","فرض كفاية إذا فعله بعض سقط عن الباقين","غير واجب على النساء أصلاً"],"c":0,"d":"easy","hint":"آية الفرضية وردت بالكتب","expl":"الصواب: الصيام فرض عين على المكلف القادر، وهو ركن خامس من أركان الإسلام. كفاية أو نفل أو سقوط بحكم الجنس كلها أوهام تخالف الشرع. نصيحة: الفرض العيني = لا يسقط بفعل غيره."},{"q":"من مفطرات الصيام:","a":["الأكل والشرب عمداً والقيء عمداً والجماع وإنزال المني عمداً","التفكير في الطعام من غير أكل","النوم الطويل في نهار رمضان","مس الزوجة من غير جماع"],"c":0,"d":"easy","hint":"ما الذي يفسد الصوم؟","expl":"الصواب: المفطرات الست: الأكل والشرب، والقيء عمداً، والجماع، والإنزال عمداً، والإيما بالمعروف والتطيب، وأما التفكير والنوم واللمس بلا إنزال فغير مفطرة بما لم يصل للجوف. نصيحة: المفسد: ما دخل الجوف عمداً أو خرج منه عمداً."},{"q":"الفدية في الصيام (إطعام مسكين عن كل يوم) مشروعة لمن:","a":["عجز عن الصوم عجزاً مستمراً كالكبير وصاحب المرض المزمن","أفطر يوماً لمرض عارض يرجو برؤه","أفطر لعذر السفر ثم شفا وسافر","عنده صحة تامة وداخل رمضان"],"c":0,"d":"hard","hint":"العجز الدائم المستمر","expl":"الصواب: الفدية لمن لا يستطيع الصيام أبداً بقلب أو كبر شديد أو مرض لا يرجى برؤه، إطعام مسكين عن كل يوم. من مرض عارضاً أو سافر فعليه القضاء لا الفدية، والصحيح يصوم ولا يفدي. نصيحة: عجز دائم = فدية، عارض = قضاء."}]},{"title":"البيوع والمعاملات والقواعد الفقهية","read":[{"h":"شروط صحة البيع","t":"يشترط في البيع: أهلية المتعاقدين (بالغ عاقل رشيد)، ورضا الطرفين، وأن يكون المعقود عليه مالاً متقوماً مباحاً طاهراً منتفعاً به، معلوم النوع والجنس والقدر والقدرة على التسليم، مع خلو العقد عن الغرر والربا والجهالة الفاحشة، وغير ذلك من شروط صحة العقد. ويُسنّ الإشهاد على البيع لقوله تعالى (وأشهدوا إذا تبايعتم)."},{"h":"الغرر وجهالة الصفقة","t":"الغرر: ما تعلق بالمبيع من جهالة تفضي إلى التنازع كبيع السمك في الماء، أو بيع ما لا يمكن تسليمه كبيع الطير في الهواء، أو بيع الموصوف في الذمة دون قدرة، أو بيع الأعيان المجهولة. ونهي النبي ﷺ عن بيع الغرر عام، والقاعدة: كل بيع جهالة فيه غرر مردود، وما جرى مجرى المسيل للأكل والمترفق فهي من بيع التافه الذي لا يمنعه الشارع."},{"h":"الربا وأقسامه","t":"الربا لغة: الزيادة، وهو عند الفقهاء: عقد على عوض مخصوص غير معلوم التماثل في المقدار أو تأخير البدلين في الأموال الربوية. وأقسامه: ربا الفضل (بيع الربوي بجنسه متفاضلاً كبيع ذهب بذهب ناقص) وربا النسيئة (تأخير القبض أو الزيادة بسبب الأجل). وحكمه: حرام، وفيه وعيد شديد، وسبب تحريمه سد ذريعة الظلم وأكل أموال الناس بالباطل."},{"h":"قواعد فقهية كبرى","t":"من القواعد الكبرى في المذهب: (1) الأمور بمقاصدها: فالعبرة بالنية والقصد في العقود والعبادات. (2) المشقة تجلب التيسير: فكل مشقة تجاوز الحد المعتاد تشرع لها الرخصة كالقصر والفطر والمسح والتيمم. (3) لا ضرر ولا ضرار: فلا يضر الإنسان نفسه ولا غيره، والحكومة مأمورة برفع الضرر. (4) اليقين لا يزول بالشك. (5) العادة محكمة في الأعراف المعتبرة. وهذه القواعد قوام ضبط الفقه."},{"h":"خلاصة الدرس","t":"البيع يشترط له الأهلية والرضا والمعلومية والقدرة على التسليم وخلوّ العقد من الغرر والربا، والغرر جهالة مؤدية للنزاع، والربا نوعان: فضل ونسيئة وحرامان، والقواعد الفقهية الكبرى (المقاصد، والتيسير، وعدم الضرر، واليقين، والعادة) أساس الاستنباط الفقهي."}],"qs":[{"q":"من أهم شروط صحة البيع:","a":["الرضا والمعلومية والقدرة على التسليم وخلوّ العقد من الغرر والربا","أن يكون البيع نسيئة بلا أجل محدود","أن يحضر البيع عشرة شهود على الأقل","أن يكون الثمن مقبوضاً قبل العقد"],"c":0,"d":"medium","hint":"شروط التكامل في الصفقة","expl":"الصواب: البيع يتم بتراضٍ على عين معلومة من النوع والقدر، معقود عليه يمكن تسليمه، خالياً من الغرر والربا. عدم تحديد الأجل نسيئة، والاستشهاد مندوب لا شرط صحة بعدد معين، وقبض الثمن قبل العقد ليس شرطاً. نصيحة: شروط الصحة: الرضا + المعلوم + المقتدر + سلامة من الربا."},{"q":"بيع الغرر هو البيع الذي:","a":["تعلق بالجهالة المؤدية إلى النزاع وعدم القدرة على التسليم","تم فيه تحديد كل المواصفات والأثمان بدقة","حصل فيه قبض كامل قبل العملية","استوفى فيه العلم والرضا التام"],"c":0,"d":"easy","hint":"مبني على الخداع والجهل","expl":"الصواب: بيع الغرر ما جهل فيه العوض أو عدم تمكن من التسليم كبيع السمك في الماء، وهو منهي عنه. الخيارات الأخرى تصف بيعاً صحيحاً معلوماً. نصيحة: الغرر = جهل يفتح باب النزاع."},{"q":"الربا عند الفقهاء قسمان هما:","a":["ربا الفضل وربا النسيئة","ربا الجهل وربا الرضا","ربا الرخص وربا السلف","ربا الغائب وربا الحاضر"],"c":0,"d":"easy","hint":"زيادة في الكم أو في الأجل","expl":"الصواب: ربا الفضل زيادة في المقدار مع اتحاد الجنس، وربا النسيئة تأخير حلول الدين أو الزيادة بسبب الأجل، وهما محرمان شرعاً. بقية التقسيمات غير فقهية. نصيحة: الفضل = كم العوض، النسيئة = الأجل."},{"q":"الحكمة من تحريم الربا:","a":["منع استغلال المحتاج وأكل أموال الناس بالباطل وتحقيق عدالة التعامل","تضييق التجارة وتعطيل الاستثمار الحلال","إلغاء الأمانة بين الناس","منع الادخار والاستثمار النافع مطلقاً"],"c":0,"d":"medium","hint":"مقصد الحماية من الظلم","expl":"الصواب: الربا يستغرق الغريم ويأكل ماله دون مقابل، فحرّمه الله حفظاً للنظام الاقتصادي وتحقيقاً للعدل، مع إباحة التجارة الرابحة الحلال. الخيارات الأخرى قلب للمقاصد إذ الإسلام يشجع التجارة والاستثمار الحلال. نصيحة: الحرام لحماية الضعيف، والحلال يأوي الرابح بالقدر.’"},{"q":"القاعدة الفقهية (الأمور بمقاصدها) تعني:","a":["العبرة بالنية والقصد في العقود والعبادات","كل الأعمال حلال بكل نية كانت","لا أثر للنية أصلاً في الأحكام","الالتزام بظاهر اللفظ وحده دون القصد"],"c":0,"d":"easy","hint":"أساس النية في الأفعال","expl":"الصواب: القاعدة مشتقة من حديث (إنما الأعمال بالنيات)، فالعبرة بالنية، والتصرفات تحل وتبطل تبعاً لمقاصده. وليست القاعدة إباحة أو إلغاء للنية. نصيحة: أول قاعدة في الفقه: حسب كل عمل من مقصده."},{"q":"القاعدة (المشقة تجلب التيسير) من ثمراتها:","a":["الرخص: القصر في السفر والفطر والتيمم والمسح","إلغاء الفرائض والتكليف إطلاقاً","جواز ترك العبادات متى شاء العبد","التشديد على المريض والعاجز"],"c":0,"d":"easy","hint":"الرخص تثمر عند المشقة","expl":"الصواب: المشقة فوق المعتاد تجلب الرخصة: قصر الصلاة، الفطر للمريض والمسافر، الجمع، المسح على الخفين، صلاة الخوف، وسقوط ما لا يستطاع. المشقة الميسرة لا تتسع لرفع التكليف، ولا التشديد مقصود. نصيحة: رخصة = مشقة فوق المعتاد."},{"q":"القاعدة (لا ضرر ولا ضرار) تدل على:","a":["منع الإضرار بالنفس والغير ورفع الضرر الحاصل أو المتوقع","جواز الإضرار بالجار إذا كان من جنس الضرر","جواز الضرر لتحقيق الربح التجاري","مسؤولية الإنسان عن كل فعل غيره"],"c":0,"d":"medium","hint":"تحريم الإضرار والأضرار","expl":"الصواب: الحديث (لا ضرر ولا ضرار) يمنع الفعل المضر سواء أوقعه على نفسه أو غيره، والأول للإضرار بنفسه أو غيره وهو أعم. ليس لتحقيق الربح ولا يجبر أحد على ضرر. نصيحة: ضرر = حصول الضرر، ضرار = الإضرار به."}]}]}]},{"id":"azaqida","name":"العقيدة","icon":"✨","color":"#4527A0","books":[{"title":"العقيدة الأشعرية","icon":"✨","chapters":[{"title":"توحيد الألوهية والربوبية","read":[{"h":"أقسام التوحيد","t":"التوحيد إفراد الله تعالى بما يخصه، وينقسم إلى: (1) توحيد الربوبية: إفراد الله بأفعاله من الخلق والرزق والتدبير والملك. (2) توحيد الألوهية: إفراد الله بالعبادة فلا يصرف شيء من العبادة لغير الله كالدعاء والخوف والسجود والذبح والنذر. والشهادتان تجمعانهما: لا إله إلا الله توحيد ألوهية، وأن محمداً رسول الله تصديق الرسالة."},{"h":"توحيد الربوبية","t":"توحيد الربوبية هو الإقرار بأن الله وحده الخالق الرازق المحيي المميت المدبر لشؤون الخلق، لا شريك له في ذلك. وقد كان مشركو العرب يقرون بهذا التوحيد: (ولئن سألتهم من خلق السماوات والأرض ليقولن الله)، ومع ذلك لم يدخلهم في الإسلام لأنهم أخلوا بتوحيد الألوهية واتخذوا الأنداد يعبدونها."},{"h":"توحيد الألوهية حقيقة العبادة","t":"توحيد الألوهية هو توحيد العبادة: إخلاص جميع أنواع الطاعة لله وحده، فالدعاء والخوف والرجاء والذبح والنذر والاستغاثة كل ذلك لا يصرف إلا لله. وهو محور دعوة الأنبياء جميعاً، كما قال تعالى: (ولقد بعثنا في كل أمة رسولاً أن اعبدوا الله واجتنبوا الطاغوت). وسمي في الاصطلاح توحيد العبادة لأنه يعلّم الخلق كيف يطيعون الله ولا يشركون معه."},{"h":"الفرق بين التوحيدين وقيمة الإخلاص","t":"الفرق أن الربوبية معرفة بالألسنة، بينما الألوهية عمل بالقلب والجوارح؛ فمن أقر بالربوبية ولم يعبد الله وحده فهو مشرك. لذلك كانت العبادة ثمرة التوحيد، وحقيقة الإخلاص أن يكون قصد العبد في كل قول وعمل وجه الله وحده لا شريك له، وأن لا يريد بذلك الرياء ولا سمعة، وتلك هي عروة الوثقى لا انفصام لها."},{"h":"خلاصة الدرس","t":"توحيد الربوبية: إفراد الله بأفعاله (خلق ورزق وتدبير)، وتوحيد الألوهية: إفراد الله بالعبادة والدعاء والخوف والذبح، وقبول الربوبية وحده لا يغني دون الألوهية، فذهبت دعوة الرسل كلها إلى توحيد الله وإخلاص العبادة له."}],"qs":[{"q":"توحيد الألوهية هو:","a":["إفراد الله تعالى بالعبادة من دعاء وخوف وبذح ونذر واستغاثة","الإقرار بأن الله خالق رازق مدبر","الإيمان بوجود الله تعالى فقط","الإيمان بالملائكة والكتب والرسل"],"c":0,"d":"easy","hint":"جهة العبادة والطاعة","expl":"الصواب: توحيد الألوهية توحيد العبادة وصرف جميع أنواعها لله وحده. أما خلق الخلق ورزقهم وتدبيرهم فهو توحيد الربوبية، ووجود الله والإيمان بالملائكة من أصول الإيمان لا من هذا التوحيد. نصيحة: الألوهية = الإله المعبود، الربوبية = الرب المدبر."},{"q":"توحيد الربوبية هو:","a":["إفراد الله بالخلق والرزق والتدبير والملك","إفراد الله بالدعاء والاستغاثة","الاعتقاد بعدم وجود إله لغير الله من العبادة","الإيمان باليوم الآخر والبعث والحساب"],"c":0,"d":"easy","hint":"أفعال الله في الكون","expl":"الصواب: الربوبية تتعلق بأفعال الله: الخلق والرزق والملك والتدبير، وهذا يقر به كثير من المشركين. وبقية الخيارات في الألوهية أو أصل الإيمان. نصيحة: رَبّ = ربُّ الكون ومدبره."},{"q":"المراد بالعبادة في مصطلحات علماء التوحيد:","a":["كل ما يحبه الله ويرضاه من الأقوال والأفعال الظاهرة والباطنة","لقول والذكر في الظاهر فقط","الخضوع الفكري للمخلوقين العظماء","فعل العادات المعتادة بلا قصد"],"c":0,"d":"medium","hint":"محبة الله في الأقوال والأفعال","expl":"الصواب: العبادة اسم جامع لكل ما يحبه الله ويرضاه من قول وعمل ظاهر وباطن، وقد عرف بها أئمة العقيدة. لا تقتصر على الذكر اللفظي ولا على الخضوع للمخلوقين ولا على العادات البحتة. نصيحة: العبادة = الحب أو العمل الصالح بقصد التقرب."},{"q":"قوله تعالى: (وما خلقت الجن والإنس إلا ليعبدون) يدل على:","a":["أن غاية خلق الثقلين تحقيق العبادة وحدها لله","ألا يثاب المكلف على أعماله","أن العبادة مقصورة على الملائكة فقط","أن التكليف ينقطع عن العقل تماماً"],"c":0,"d":"medium","hint":"حكمة مستودعة العبادة","expl":"الصواب: الآية بيّنت غاية الخلق وهي العبادة على المعنى الجامع للمعرفة والطاعة. وليست الآية بنفي الثواب ولا بتخصيص العبادة بالملائكة ولا بقطع التكليف، بل هي في مقام الطلب والإخبار عن المقصد. نصيحة: (إلا ليعبدون) = غاية الخلق عبادة الله."},{"q":"مشركو العرب أقاموا على توحيد الربوبية ومع ذلك قاتلهم النبي ﷺ بسبب:","a":["إخلالهم بتوحيد الألوهية واتخاذهم شركاء يعبدونها","إنكارهم أصل وجود الله تعالى","اجتماعهم على إنكار الخالق","تركهم الإيمان ببعث الأموات"],"c":0,"d":"medium","hint":"ما الذي خرجوا به عن التوحيد؟","expl":"الصواب: كانوا مقرين بأن الله الخالق، لكنهم عبدوا الأصنام وصرفوا لها العبادة، فأخلوا بتوحيد الألوهية فاستحقوا القتال. فليس إنكار وجود الله ولا إنكار البعث أصل خلافهم الأكبر. نصيحة: الخلاف الكبير مع المشركين كان في العبادة لا في وجود الخالق."},{"q":"من أنواع العبادة التي لا تصح لغير الله:","a":["الدعاء والذبح والنذر والخوف والاستغاثة","الأكل والشرب وسائر المباحات","شد الرحال لطلب العلم","زيارة الأقارب وبر الوالدين"],"c":0,"d":"easy","hint":"عبادات وأعمال القلوب","expl":"الصواب: الدعاء والذبح والنذر والاستغاثة والخوف ونحوها عبادات لا يجوز صرفها لغير الله، فهي من صميم توحيد الألوهية. أما المباحات وبر الوالدين وصلة الرحم فهي أعمال مباحة أو مستحبة لا تتجه لغير الله. نصيحة: اسأل: هل يجوز تقريب هذا الفعل لغير الله؟"},{"q":"أول ما يفترض على المكلف عند الأشاعرة:","a":["النظر والاستدلال على معرفة الله تعالى ووحدانيته","الشهادة فوراً بلا منهج استدلال","صيام الدهر كله من النفل","الفتوى في النوازل قبل التحصيل"],"c":0,"d":"hard","hint":"الأشاعرة اشترطوا الاستدلال أولاً","expl":"الصواب: عند الأشعرية أول واجب هو النظر المؤدي إلى معرفة الله، لأنه أصل يبنى عليه الإيمان الصحيح، وإن خالفهم فيه بعض أهل الحديث فقد ذهب إليه جمهور الأشاعرة والمعتزلة. ليست المسألة في تعجيل الشهادة بل في منهج الحصول على المعرفة. نصيحة: في الامتحان الأشعري: أول واجب = النظر المعرفي."}]},{"title":"صفات الله تعالى وجميع ما دلت عليه","read":[{"h":"الصفات الثبوتية والسلبية","t":"تنقسم صفات الله الثابتة إلى: (1) ثبوتية: كالحياة والعلم والقدرة والإرادة والسمع والبصر والكلام، وهي إما معانٍ قائمة بذاته. (2) سلبية: تنزيه الله عما لا يليق كالعدم والحدوث والتحيز، وأشهرها (الواحد، الأحد، الصمد). وصفات الله كلها كمال غير محدودة، لا يشبهه شيء في ذاته ولا في صفاته."},{"h":"الصفات الذاتية والفعلية","t":"الصفات الذاتية: ما لا ينفك عنها ولا تتخلف بحال كالحياة والقدرة والعلم. والصفات الفعلية: المتعلقة بأفعاله التي يصدرها بحكمته كالخلق والرزق والإحياء والإماتة والاستواء على العرش على ما يليق. وفي الذاتية لا تتخلف، وفي الفعلية قيدها المشيئة والحكمة، فلا يشبه فعله فعل المخلوقين."},{"h":"المستحيل والواجب والجائز في حق الله","t":"الواجب في حق الله: ما لا يتصور عدمه كالوجود والعلم والقدرة. المستحيل: ما لا يتصور وجوده كالعدم والعجز والجهل والتحيز والتمثيل بالمخلوقين. الجائز: ما لا يتحتم ثبوته ولا نفيه كخلق الخلق أو عدمه، وفعل الرزق في أي زمان. وقاعدة أهل السنة: لا يشبهه شيء لا في الذات ولا في الصفات ولا في الأفعال، فإثبات الشيء من الصفات لا يستلزم مماثلة المخلوقين."},{"h":"الأسماء الحسنى","t":"قال تعالى: (ولله الأسماء الحسنى فادعوه بها). والأسماء الحسنى أعلام لله دالة على معاني صفاته الكاملة، فالعليم دال على العلم، والقدير على القدرة، والرحمن على الرحمة. والإيمان بهذه الأسماء: إثبات دلالتها ومعانيها مع نفي التكييف والتمثيل، وعدم تعطيلها عن معناها، وعدم تحريفها، وعدم تحريف أسماء خصائصها عن المقصود."},{"h":"خلاصة الدرس","t":"صفات الله: ثبوتية (حياة، علم، قدرة، إرادة، سمع، بصر، كلام) وسلبية (نفي العدم والتحيز والتمثيل)، وذاتية لا تنفك لفعلية بحكمة، وكل صفة واجبة أو مستحيلة أو جائزة، والأسماء الحسنى أعلام دالة على المعاني، والإيمان بها إثبات بلا تكييف ولا تعطيل."}],"qs":[{"q":"من الصفات الثبوتية الواجبة لله تعالى:","a":["الوجود والعلم والقدرة والإرادة والحياة والسمع والبصر والكلام","التحيز والانتقال والاتجاه في الأجسام","الجهل والعجز والنوم والنسيان","التمثال بالمخلوقين في صورهم"],"c":0,"d":"easy","hint":"معانٍ كاملة لا تتخلف","expl":"الصواب: الصفات الثبوتية الكمالية ثمانية: حياة، علم، قدرة، إرادة، سمع، بصر، كلام، وجوب الوجود. فالخيارات الباقية تنزه الله عنها تعالى وتعالى. نصيحة: اثبت ثمانية ثبوتية واحفظها جيداً."},{"q":"من صفات المعنى (وهي معانٍ قائمة بذاته لا تشبه صفات المخلوقين):","a":["القدرة والحياة والسمع والبصر","العرش والكرسي والمجسمة","الميل والانحراف والتحيز","الحركة والمنتقل في الجهات"],"c":0,"d":"medium","hint":"المعاني الثابتة التي تدل عليها الأسماء","expl":"الصواب: القدرة والحياة والسمع والبصر معانٍ قائمة بالذات المقدسة دالة على كمال الله، لا تشبه بها المخلوقين ولا تتصف بأدواتهم. فالجهات والتحيز والميل صفات تنافي تنزيه الله. نصيحة: الصفة معنى قائم بالذات لا أداة تتحدد بخظر."},{"q":"الواجب في حق الله تعالى هو:","a":["ما يجب له من الكمال كالوجود والقدرة والعلم","ما يستحيل تحقق وجوده أصلاً","ما يجوز ثبوته أو نفيه بالتساوي","ما يكون من أفعال العباد المرتبطة بمشيئتهم"],"c":0,"d":"easy","hint":"وجوب الوجود والكمال","expl":"الصواب: الواجب كل كمال لازم للذات كالوجود والقدرة والإرادة، فلو افتقر الله شيء من ذلك لزم التركيب والحدوث. بقية الخيارات لا تصف الوجوب. نصيحة: عكس الواجب = المستحيل (العدم والعجز)."},{"q":"من المستحيلات في حق الله تعالى:","a":["العدم والحدوث والتحيز والتمثال بالمخلوقين","الوجود والقدرة والعلم والإرادة","كلامه القديم وسمعه وبصره","رحمة الله وفضله وعنايته"],"c":0,"d":"easy","hint":"ما يتنزه الله عنه","expl":"الصواب: المستحيل ما لا يمكن تصوره في حق الله كالعدم والحدوث (لأنه أزلي) والتحيز والتمثيل. وفي المقابل الوجود والكمال واجبان. نصيحة: المستحيل = نفي الواجب عن الله: عدم، حدوث، تحيز."},{"q":"قاعدة أهل السنة في إثبات الصفات:","a":["إثبات ما دل عليه الدليل مع نفي التكييف والتمثيل والتعطيل","تأويل كل صفة أو تعطيلها جملة","إثبات الصفة تشبيهاً بالخلق","تكييف الصفة بجسمانية أو أداة"],"c":0,"d":"medium","hint":"إثبات بلا تشبيه ولا تعطيل","expl":"الصواب: أهل السنة يثبتون الصفات كما وردت مع الإيمان الكامل بها من غير تكييف ولا تمثيل ولا تحريف ولا تعطيل. فلا تشبيه ولا إنكار، ولا تحريف بالصورة الفاسدة. نصيحة: قاعدة التثبيت: اثبت بلا تمثيل، ونفِ بلا تعطيل."},{"q":"من الصفات السلبية التي ينزه الله عنها:","a":["العدم والحدوث والتحيز وتعدد الآلهة","القدرة والإرادة والعلم والحياة","السمع والبصر والكلام","رحمته ولطفه وبقاؤه"],"c":0,"d":"medium","hint":"ما يصح نفيه عن الله","expl":"الصواب: السلبية تنزه عن النقص: العدم، الحدوث، الحيز، التركيب، التعدد، المعية المادية. وبقية الخيارات صفات ثبوتية أو إيجابية. نصيحة: السلبية = ما يُنفى (ال=لا)، الثبوتية = ما يُثبت."},{"q":"ومن طرق الأسماء الحسنى دلالتها:","a":["كل اسم يدل على صفة ثابتة لله كالعالم دال على العلم","أسماء الله أسماء جماد بلا دلالة","الأسماء الحسنى لا يعمل بمدلولها","أسماء الله لا تتضمن معنى الرحمة في أي حال"],"c":0,"d":"medium","hint":"الاسم علم دال على المعنى","expl":"الصواب: الأسماء أعلام فمعانٍ، فالغفور دال على الغفران، والرحمن على الرحمة، وهذا من جلال التسمية وتضمنه الصفات. الاسم بدون معنى دال أو بالفار للحرمان لا يصح. نصيحة: اربط الاسم بمعناه دائماً: القدير = القدرة."},{"q":"الإيمان بأسماء الله وصفاته يكون بـ:","a":["إثبات دلالتها ومعانيها مع نفي التكييف والتحريف والتمثيل","تقويل معاني أسماء الله وتحريفها عن دلالاتها","الاهتمام بحفظ الأسماء دون معانيها","اعتبار أسماء الله وصفاته صفات خلق قابلة للدخول عليه"],"c":0,"d":"hard","hint":"الإيمان بأسماء الله لا بتعطيلها","expl":"الصواب: الإيمان بالاسم إثبات ما دل عليه من معنى، مع نفي التكييف والتحريف والتعطيل، فالإيمان الخالص هو المراد في سورة الأعراف والبقرة والسجدة وسورة المرسلات. الخيارات الأخرى تعطل أو تحرف أو تمثل. نصيحة: افهم أن الإيمان بالأسماء = الإيمان بمعانيها."}]},{"title":"الإيمان بالغيب والقدر والمعاد","read":[{"h":"الإيمان بالملائكة والكتب والرسل","t":"أركان الإيمان ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره. فالإيمان بالملائكة: التصديق بهم من نور خلقهم، لا يعصون الله ما أمرهم ويفعلون ما يؤمرون، ولا يوصفون بالذكورة والأنوثة ولا بالتوالد، ومنهم جبريل للوحي وميكائيل للمطر وإسرافيل للنفخ في الصور. والإيمان بالكتب: تصديق ما نزل الله على رسله كلها، والقرآن خاتمها والمهيمن عليها. والإيمان بالرسل جميعهم والتسليم بما جاءوا به."},{"h":"القضاء والقدر ومراتبه","t":"القدر: تقدير الله للأشياء في الأزل بعلمه، والقضاء: تنفيذ هذا التقدير في وقته. ومراتبه أربع: (1) العلم السابق بكل شيء، (2) الكتابة في اللوح المحفوظ، (3) المشيئة والمراد الشامل، (4) الخلق: أن الله خالق كل شيء من أفعال العباد وغيرها. وأهل السنة وسط بين الجبرية القائلين بالجبر المحض والقدرية القائلين بأن العبد يخلق فعله، فهم يقولون: لا جبر ولا تفويض بل أمر بين أمرين."},{"h":"اليوم الآخر ونعيمه وجحيمه","t":"الإيمان باليوم الآخر يشمل: البعث من القبور، والحشر، والميزان الذي توزن فيه الأعمال، والصراط الممدود على جهنم، والجنة دار النعيم، والنار دار العذاب، والشفاعة العظمى لرسول الله ﷺ بإذن الله في المقام المحمود. والجنة والنار مخلوقتان قائمتان الآن، لا يفنيتان، والموت يذبح بينهما فلا يموت أهل الجنة ولا يموت أهل النار."},{"h":"الشفاعة والحساب والميزان","t":"الشفاعة الكبرى للنبي ﷺ يوم المحشر أن يبدأ الحساب، ثم شفاعات في إدخال أهل الجنة، وشفاعة في أقوام من أمته، ودخول بعضهم بلا حساب. وللمؤمنين حساب يسير، وتناقش الأعمال، فمن أوتي كتابه بيمينه فحساب يسير، ومن أوتيه بشماله فهلك. والميزان حقيقي توزن فيه الأعمال، والدلائل على ذلك من الكتب والسنة متواترة."},{"h":"خلاصة الدرس","t":"أركان الإيمان ستة، والملائكة من نور لا يعصون، والكتب مصدقة بشهادة القرآن مهيمن، والرسل بلا تفريق بينهم. القدر مراتبه أربع: علم وكتابة ومشيئة وخلق، ونحن بين الجبر والتفويض. واليوم الآخر: بعث وحشر وميزان وصراط، وجنة ونار مخلوقتان دائمتان، وشفاعة بإذن الله."}],"qs":[{"q":"مراتب الإيمان بالقدر أربع هي:","a":["العلم والكتابة والمشيئة والخلق","الاعتقاد المطلق دون علم","الحتم محض الجبر","اللعب والتقدير والسمع"],"c":0,"d":"medium","hint":"أربع مراتب مرتبة","expl":"الصواب: المراتب: العلم السابق، والكتابة في اللوح، والمشيئة الشاملة، وخلق كل شيء. والخيارات الأخرى تصور القدر إهمالاً أو جبراً خالصاً بلا ترتيب. نصيحة: قدر = عِلْمُ، كِتابة، مَشيئة، خَلق."},{"q":"الإيمان بالملائكة يشمل:","a":["تصديق وجودهم وأنهم مخلوقون من نور لا يعصون الله","أنهم يموتون ويتوالدون كبنعمة البشر","أنهم ذكور وإناث مؤاخذون كالإنس","أنهم وسائط يعبدون من دون الله"],"c":0,"d":"easy","hint":"خلقهم من نور وطاعته موصلة","expl":"الصواب: الملائكة خلق من نور لا يوصفون بذكورة ولا أنوثة ولا توالد ولا موت قبل قيام الساعة بوجه عام، ولا يعصون الله. الخيارات الأخرى مخالفة لنصوص الوحي. نصيحة: لا يشبهون بالناس في جنس ولا طبيعة."},{"q":"الإيمان باليوم الآخر يشمل:","a":["البعث والحشر والحساب والميزان والصراط والجنة والنار","الموت نفسه فقط وإهمال ما بعده","رجوع الأرواح في كل فترة دورية","الاعتقاد بأن الجنة والنار منعدمتان بلا خلود"],"c":0,"d":"medium","hint":"الآخرة كل مراحلها","expl":"الصواب: الإيمان باليوم الآخر يتناول كل ما أخبر الله به بعد الموت: بعث وحشر وحساب وميزان وصراط وجنة ونار. فلا يعول على الموت فقط ولا على الأرواح الدورانية. نصيحة: اجمع يوماً كاملاً: قبر، بعث، حشر، حساب، جنة أو نار."},{"q":"الشفاعة الكبرى يوم القيامة تكون:","a":["لرسول الله ﷺ في المقام المحمود بإذن الله","للملائكة بلا إذن عند الجمهور","لكل مخلوق لنفسه مباشرة","منتفية في كل أحوال القيامة"],"c":0,"d":"medium","hint":"المقام المحمود","expl":"الصواب: الشفاعة العظمى للنبي ﷺ في بدء الحساب والنجاة من الهول بإذن الله، ثم له شفاعات أخرى. لا شفاعة باذن الله، والتفويض بلا إذن خلاف النصوص. نصيحة: الشفاعة بإذن الله، والكبرى لرسول الله."},{"q":"الميزان يوم القيامة:","a":["ميزان حقيقي توزن فيه الأعمال","رمز لا حقيقة له","أمر لا يخبر عنه إلا الملائكة","عمل شعب زراعي تاريخي"],"c":0,"d":"easy","hint":"وزن الأعمال","expl":"الصواب: الميزان حقيقي توزن فيه الأعمال كما دلت عليها السنة، ويكون له كفة ولسان بحسب المعلومات الشرعية. وإنكار كونه حقيقة انحراف عن النص. نصيحة: الميزان = حقيقة لا مجاز عند أهل السنة."},{"q":"مذهب أهل السنة في أفعال العباد:","a":["العباد فاعلون حقيقة بمشيئة من الله وقدرة لا جبر ولا تفويض","العباد مجبورون على أفعالهم بلا كسب","الإنسان يخلق أفعاله بنفسه بلا إرادة الله","العبد لا يوصف بفعل ولا كسب البتة"],"c":0,"d":"hard","hint":"قول بين قولين","expl":"الصواب: أهل السنة وسط: فالعبد فاعل بالكسب والاختيار، والله خالق الفعل وأحداثه، فليس جبر محض ولا تفويض كامل. الجبرية قالت بالجبر، والقدرية بالتفويض، وكلاهما خارج عن القصد. نصيحة: لا جبر ولا تفويض بل أمر بين أمرين."},{"q":"من دلائل أن الجنة والنار مخلوقتان دائمتان:","a":["نصوص الوحي المتواترة الدالة على خلقهما وعدم فنائهما","أنهما باطلان بعد قيام الساعة","أن النار تفنى ويلحقها العدم","أن الجنة دار يعمها الموت والفناء"],"c":0,"d":"easy","hint":"الخلود والبقاء","expl":"الصواب: الجنة والنار مخلوقتان الآن على الصحيح، ولا يموت أهلهما ولا يفنيانهما الله، وهذا من أصل المعاد عند أهل السنة. والخيارات الأخرى تنكر الخلود والفناء، وهو قول باطل. نصيحة: الخلود أصل: أهل الجنة خالدون، وأهل النار خالدون."}]}]}]},{"id":"azbalagha","name":"البلاغة العربية","icon":"🎭","color":"#E65100","books":[{"title":"فنون البلاغة","icon":"🎭","chapters":[{"title":"علم البيان (التشبيه والاستعارة والكناية)","read":[{"h":"التشبيه وأركانه","t":"التشبيه: عقد مماثلة بين شيئين في صفة مشتركة. أركانه أربعة: المشبه، والمشبه به، والأداة، ووجه الشبه. وإن حذف وجه الشبه مع الأداة سمي تشبيهاً بليغاً. مثال: (الجندي مثل الأسد في الشجاعة)؛ المشبه الجندي، والمشبه به الأسد، والأداة مثل، ووجه الشبه الشجاعة."},{"h":"أقسام التشبيه","t":"التشبيه بأداة ووجه: (التام أو المفصل) كقولنا: زيد كالأسد في الشجاعة. ذكر الأداة فقط: (مرسل) كقولنا: كأنه قمر. ذكر الوجه فقط: (مؤكد) كقولنا: زيد أسد في الشجاعة. وبلا أداة ولا وجه: (بليغ) كقولنا: زيد أسد. والتشبيه الضمني: لا يظهر فيه المشبه به بل يفهم من الكلام ويُلمح إليه، وجماله في إخفاء وجه المشابهة."},{"h":"الاستعارة","t":"الاستعارة: تشبيه حذف أحد طرفيه. فإذا حذف المشبه وصرح بالمشبه به كانت تصريحية: (رأيت أسداً يقاتل) أي شجاعاً. وإذا حذف المشبه به وصرح بشيء من لوازمه كانت مكنية، كقولهم: (اشتدت الحرب توقد نارها)؛ شبه الحرب بالنار وذكر لازمها التوقد. والفرق بينهما أن في التصريحية يذكر المشبه به وفي المكنية يذكر لازم المشبه به."},{"h":"الكناية","t":"الكناية: لفظ أريد به لازم معناه مع جواز إرادة المعنى الأصلي، جامعاً بين المعنيين. مثال: (هو كثير الرماد) كناية عن الكرم، فالمعنى الحقيقي من الرماد جائز، والمراد لازمه وهو الكرم. وهي أدخل في الابتعاد عن المبالغة وأبلغ في التأكيد. والكناية عن الصفة كتحذير الغضب عن الوصف بالخجل، وعن الموصوف كقولهم (ابن الكرام)."},{"h":"خلاصة الدرس","t":"علم البيان تصل به المعنى دقيقاً: التشبيه أربعة أركان وأقسامه بحسب ذكر الأداة ووجه الشبه (بليغ ومرسل ومؤكد وقاصر). الاستعارة حذف الطرفين، وتكون تصريحية أو مكنية. الكناية لفظ بمعناه اللازوم مع جواز الحقيقة، وأدل على القصد وأبلغ."}],"qs":[{"q":"أركان التشبيه هي:","a":["المشبه والمشبه به والأداة ووجه الشبه","المشبه والمشبه به فقط","المبتدأ والخبر","المفعول والفاعل"],"c":0,"d":"easy","hint":"أربعة أركان كاملة","expl":"الصواب: أركان التشبيه أربعة: المشبه والمشبه به (هما طرفا التشبيه)، والأداة، ووجه الشبه. النقل إلى النحو خلط بين النظمين. نصيحة: اذكر دائماً أربعة أركان في سؤال التعريف."},{"q":"التشبيه الذي يذكر فيه وجه الشبه وأداة التشبيه يسمى:","a":["التشبيه المفصل (التام)","التشبيه البليغ","التشبيه المرسل المؤكد","التشبيه الضمني التمثيلي"],"c":0,"d":"easy","hint":"اجتماع الأداة ووجه الشبه","expl":"الصواب: بذكر الأداة ووجه الشبه معاً يسمى تاماً مفصلاً، كقولك: زيد كالبدر في الجمال. وإن حذف الوجه فمؤكد، وحذف الأداة فبليغ، وحذف الأداة مع الوجه فبليغ أيضاً. نصيحة: كمال الأركان كله = تام أو مفصل."},{"q":"التشبيه البليغ هو التشبيه الذي:","a":["حذف منه وجه الشبه والأداة معاً","حذف منه المشبه والمشبه به","ذكرت فيه جميع الأركان","حذف فيه المشبه وحده"],"c":0,"d":"medium","hint":"أبلغ صور التشبيه","expl":"الصواب: البليغ يحذف وجهه وأداته فيبقى المشبه والمشبه به: زيد أسد، فيزداد الإيهام بالمعنى وبلاغته. الحذف من المشبه والمشبه به يحيل الاستعارة. نصيحة: بلا أداة ولا وجه = بليغ دائماً."},{"q":"الاستعارة التصريحية هي التي:","a":["صرح فيها بالمشبه به وحذف المشبه","صرح فيها بالمشبه وحذف المشبه به","ذكرت فيها الأداة والوجه","ارتبط فيها المعنى الحقيقي واللازم معاً"],"c":0,"d":"medium","hint":"اللفظ المذكور هو المشبه به","expl":"الصواب: التصريحية: يذكر المشبه به صراحة ويحذف المشبه، مثل: رأيت بحراً، أي رجلاً كريماً. وذكر المشبه مع حذف المشبه به هو أساس المكنية والكناية خلاف ذلك. نصيحة: تصريحية = ظهر المشبه به، مكنية = ظهر لازمه."},{"q":"الاستعارة المكنية مثل قوله: (اشتدت الحربُ موقدةَ النيران) تكون عندما:","a":["شبه الحرب بالنار وذكر لازمها وهو التوقد وحذف المشبه به","شبه النار بالحرب وذكر المشبه به صراحة","ذكرت الأداة ووجه الشبه معاً","اجمعت فيها أركان التشبيه كلها"],"c":0,"d":"medium","hint":"لازم المشبه به","expl":"الصواب: في المكنية يحذف المشبه به ويؤتى بلازمه؛ ففي المثال شبهت الحرب بالنار وحذفت النار وأبقت لوازمها وهي التوقد. فإذا صرح بالمشبه به كانت تصريحية. نصيحة: التصريحية اسم ظاهر، المكنية لازم ظاهر."},{"q":"الكناية هي:","a":["لفظ أريد به لازم معناه مع جواز إرادة المعنى الأصلي","لفظ مستعمل في غير معناه مع قرينة مانعة من الحقيقة","لفظ لا يحتمل إلا معنى واحداً","لفظ محذوف أحد طرفيه"],"c":0,"d":"medium","hint":"الجمع بين المعنيين","expl":"الصواب: الكناية تريد باللفظ لازمه وتترك المعنى الأصلي ممكناً، مثل: فلان طويل النجاد كناية عن الطول والجاذبية. وهي غير الاستعارة التي تمنع في معناه قرينة. نصيحة: الكناية = التصريح بالملزوم مع جواز الأصل."},{"q":"قولهم: (هو كثيرُ الرماد) كناية عن:","a":["الكرم والضيافة وتعدد الأضياف","الشجاعة والبأس","العلم والفضل","الغضب والانفعال"],"c":0,"d":"easy","hint":"كثرة الإيقاد للضيفان","expl":"الصواب: كثرة الرماد ناتج من كثرة الإيقاد للضيوف، فصار رمزاً للكرم، ولهذا يكثر الرماد. وهو معنى لازمي حاضر في ذهن الجميع. غلط الباقي في صفة أخرى. نصيحة: احفظ شواهد الكناية: كثير الرماد = كريم."}]},{"title":"علم المعاني (الخبر والإنشاء وأنواعه)","read":[{"h":"الخبر وأغراضه","t":"الخبر: كلام يحتمل الصدق والكذب لذاته، نحو: سافر الركب. وهو إما خبر ابتدائي (للسامع الخالي)، أو طلبي (للمتردد)، أو إنكاري (للمنكر). وأغراضه البلاغية: الفخر، التوبيخ، التحسر، التحذير، التعليم، الحمد، الذم، إظهار الاستعداد، إرادة التصغير. ويخرج الخبر عن معناها الحقيقي إلى هذه الأغراض التي تستثار بها مشاعر المخاطب."},{"h":"الإنشاء الطلبي","t":"الإنشاء الطلبي: ما يطلب به حصول شيء أو تركه: (1) الأمر: (افعل) أو باسمه لاسميته، وللوجوب والندب والإباحة والتسخير والأمر بمعنى التعجيز وغيرها. (2) النهي: (لا تفعل) مع النهي للتحريم أو الكراهة. (3) الاستفهام: بأدواته (هل، الهمزة، ما، من، متى، أين، كيف، كم) للأغراض: الإنكار، التقرير، التعجب، التوبيخ. (4) التمني: (ليت، لعل، هل، لو) (5) النداء: (يا، أيا، هيا...)."},{"h":"الإنشاء غير الطلبي","t":"الإنشاء غير الطلبي: ما لا يطلب به شيء: (1) التعجب (ما أجمله! وأجمل به!) (2) الرجاء (عسى، حرى، اخلولق) (3) القسم (حرف القسم) (4) المدح والذم (نعم، بئس) (5) الإغراء والتحذير (الإخلاصَ الإخلاصَ، إياك والكسل). وهذه كلها لا تستدعي وقوعاً بل تعبر عن إنشاء في النفس."},{"h":"القصر وأقسامه","t":"القصر: تخصيص أمر بأمر، بطريقة مخصوصة، وله طرق: (1) بالعطف: العطف بلا ولا لكن بل. (2) بـ (إنما). (3) بالتقديم: (بإعراب المفعول على المصدر إيامي). (4) بالنفي والاستثناء. وقصر الصفة على الموصوف أو الموصوف على الصفة. مثال: (إنما الأعمال بالنيات) قصر الأعمال على النيات. وتقتضي طريقة القصر تكون المسند إليه المحصور في حكمه."},{"h":"خلاصة الدرس","t":"الخبر يحتمل الصدق والكذب وله أغراض: فخر وتوبيخ وتحسر وتعليم. والإنشاء طلبي (أمر، نهي، استفهام، تمني، نداء) وغير طلبي (تعجب، رجاء، قسم، مدح، إغراء). والقصر تخصيص ويأتي بعطف أو إنما أو تقديم أو نفي واستثناء."}],"qs":[{"q":"الخبر هو الكلام الذي:","a":["يحتمل الصدق والكذب لذاته","لا يحتمل إلا الصدق دائماً","يكون إنشاءً يقصد به طلب","يجب صدقه باعتبار المخبر"],"c":0,"d":"easy","hint":"احتمال الصدق والكذب","expl":"الصواب: الخبر يُقال صدقاً أو كذباً بنفسه، فهو في مقام التقرير لا الطلب. أما الإنشاء فلا يوصف بصدق ولا كذب، والخيارات الأخرى لا تحقق حد الخبر. نصيحة: أول سؤال في علم المعاني: الخبر = احتمال الصدق والكذب."},{"q":"من أغراض الخبر البلاغية:","a":["الفخر والتحسر والتوبيخ والتعليم","طلب الفهم والتصديق","الحكم بالأمر الذي يمكن فعله","تنظيم الكلام بمحسنات لفظية"],"c":0,"d":"medium","hint":"استفزاز مشاعر المخاطب","expl":"الصواب: أغراض الخبر: الفخر، التوبيخ، التحسر، الحمد، الذم، التعليم، إظهار الاستعداد، إرادة التصغير، والتقرير للخلو أو التردد. فطلب الفهم والطلب من شأن الإنشاء. نصيحة: أغراض الخبر = مشاعر نفسية، وأدوات الإنشاء = طلبية نهائية."},{"q":"الإنشاء الطلبي يشمل:","a":["الأمر والنهي والاستفهام والتمني والنداء","الخبر والتقرير والسؤال","الجناس والسجع والتورية","الطباق والمقابلة"],"c":0,"d":"easy","hint":"أنواع الطلب","expl":"الصواب: الطلبي خمسة: أمر ونهي واستفهام وتمني ونداء، فكلها تتضمن طلب حصول أو ترك. والجناس والسجع من البديع، والخبر والتقرير خبر. نصيحة: الطلبي = طلب، البديع = تحسين."},{"q":"صيغة الأمر في وجهها الأصلي هي:","a":["افعلْ","لا تفعلْ","هل تفعل؟","ليتني أفعل"],"c":0,"d":"easy","hint":"أصل الأمر","expl":"الصواب: صيغة الأمر (افعل) للفعل وغالباً للوجوب أو نحوها، بينما النهي (لا تفعل)، والاستفهام (هل تفعل)، والتمني (ليت). نصيحة: الأمر = افعل، النهي = لا تفعل."},{"q":"الاستفهام الذي لا يُراد به طلب العلم بل تقرير معنى أو إنكاره يسمى:","a":["استفهاماً إنكارياً أو تقريرياً بلاغياً","استفهاماً حقيقياً طلبياً","استفهاماً تعجبياً غير مقعد","استفهاماً ابتدائياً في النحو"],"c":0,"d":"medium","hint":"استفهام بلا طلب حقيقي للفهم","expl":"الصواب: الاستفهام البلاغي يخرج عن معناه الأصلي إلى الإنكار والتقرير والتعجب والتوبيخ، مثل (أغير الله أتخذ ولياً) إنكاراً. أما الحقيقي فيطلب الفهم. نصيحة: التقرير = إثبات، الإنكار = نفي، والطلب بلاغة."},{"q":"القصر في البلاغة هو:","a":["تخصيص شيء بشيء بطريق مخصوص كبيان الحصر","إلغاء الحكم رأساً","تعدد التفسيرات في الجملة","الجمع بين اللفظين في التركيب"],"c":0,"d":"easy","hint":"الحصر والتخصيص","expl":"الصواب: القصر هو الحصر والتخصيص، وطرقه العطف وإنما والتقديم والنفي والاستثناء. بينما الإلغاء والتعدد لا علاقة لهما بهذا الفن. نصيحة: القصر = الحصر، وطريقه أربعة."},{"q":"(إنما الأعمال بالنيات) — ما الطريقة التي بها جاء القصر فيها؟","a":["بأداة (إنما) فقصرت الأعمال على النيات","بالتقديم والتأخير في العوامل","بالاستثناء بلا إلا","بالتعجب الصريح بقوله إنما"],"c":0,"d":"medium","hint":"الأداة الحصرية","expl":"الصواب: (إنما) من أدوات القصر وهي تقصر المذكور بعدها على ما يأتي بعدها، فالأعمال مقصورة على النيات. ليست تقديماً ولا استثناء، وإعرابها حرف حصر. نصيحة: إنما = حصر، فاحسم بها عند سؤال طرق القصر."},{"q":"من طرق القصر المعتبرة:","a":["بالاستثناء وبالتقديم وبواسطة النفي والاستثناء وبالعطف و(إنما)","بالإضافة والجر والمجرور","بالنداء والترحيب في الكلام","بأفعال الرجاء والمقاربة"],"c":0,"d":"hard","hint":"أربع طرق","expl":"الصواب: طرق القصر أربعة: بالنفي والاستثناء، وبإنما، وبالتقديم، وبالعطف (لا، بل، لكن). فالنفي والاستثناء من أهمها: ما نجح إلا محمد. وبقية الخيارات ليست من طرق الحصر. نصيحة: القصر بأربعة: نفي، استثناء، إنما، تقديم، عطف."}]},{"title":"علم البديع (المحسنات اللفظية والمعنوية)","read":[{"h":"البديع وأنواعه","t":"علم البديع: علم يبحث في تحسين الكلام بعد مطابقته للغرض (ما يلائم السياق)، وهو قسمان: (1) محسنات لفظية ترجع إلى اللفظ كالجناس والسجع والازدواج. (2) محسنات معنوية ترجع إلى المعنى كالطباق والمقابلة والتورية والتشبيه المجازي. وكلها بهجة الكلام بعد تسديد معناه."},{"h":"الجناس وأقسامه","t":"الجناس: اتفاق اللفظين في النطق أو ما قارب واختلافهما في المعنى. وهو نوعان: (1) تام: ما اتفق في نوع الحروف وعددها وهيئتها وترتيبها، كالقمر في الأعمال بالنيات لفظاً ومعنى تام. (2) ناقص: ما اختلف فيه اللفظان في عدد الحروف أو ترتيبها، نحو: وهم ينهون عنه وينأون عنه، فالأصل ابعدوا فهو جناس ناقص لاختلاف الحروف في المخرج أو الترتيب."},{"h":"السجع والازدواج","t":"السجع: توافق أواخر الفقرات في الحرف الأخير، نحو: (ما بال الذين لا هرولة إلى الصلاة وهم الذين لا إله إلا الله). وهو مرغوب في الأسجاع الأدبية وغير المتكلف في القرآن لأنه إعجازي يجاوز المتكلف. والازدواج: أن تكون الجملة الثانية على وزن الأولى في الإيقاع والتصريع المعتاد بقصد التنبر."},{"h":"المحسنات المعنوية (الطباق والتورية)","t":"الطباق: الجمع بين الشيء وضده في الكلام: (وتحسبهم أيقاظاً وهم رقود)، (يحيي ويميت). وهو طباق إيجاب وسلب. المقابلة: أن يؤتى بمعنيين متوافقين أو أكثر ثم بما يقابلهما على الترتيب (فليضحكوا قليلاً وليبكوا كثيراً). التورية: لفظ له معنيان: قريب ظاهر (يتبادر للذهن) وبعيد وهو المراد دون قرينة مانعة من إرادة المعنى الأصلي، نحو: والنجم إذا هوى، وهي كأنها ضمن المعنى: سقط."},{"h":"خلاصة الدرس","t":"البديع محسنات لفظية: الجناس (تام وناقص) والسجع والازدواج، ومحسنات معنوية: الطباق (الإيجاب والسلب) والمقابلة والتورية وغيرها كمراعاة النظير والاستخدام. والبديع زينة الكلام إذا جاء غير متكلف ولم يشغل عن المعنى."}],"qs":[{"q":"من المحسنات اللفظية:","a":["الجناس والسجع","الطباق والمقابلة","التورية والتشبيه","الاستعارة والكناية"],"c":0,"d":"easy","hint":"يعتمد على اللفظ","expl":"الصواب: المحسنات اللفظية: الجناس، السجع، الازدواج. والطباق والمقابلة معنوية، والاستعارة والكناية من فنون البيان. نصيحة: اللفظية = يسمعها الأذن، المعنوية = يدركها العقل."},{"q":"الجناس التام هو ما:","a":["اتحد فيه اللفظان في نوع الحروف وعددها وهيئتها وترتيبها","اختلف فيه حرف أو مقطع","تقدم أحدهما وارتفع الآخر في الوزن","اختلف فيه اللفظان في كل شيء"],"c":0,"d":"easy","hint":"الحروف كلها متطابقة","expl":"الصواب: التام اتحاد التام في النوع والعدد والهيئة والترتيب. أما الاختلاف في حرف واحد أو ترتيبه فيكون ناقصاً، ولو اختلفا كلية انعدم الجناس. نصيحة: تام = حروف واحدة، ناقص = حرف مختلف."},{"q":"مثال الجناس الناقص في قوله تعالى: (وهم ينهون عنه وينأون عنه):","a":["اتفاق (ينهون) و(ينأون) في التاء والهاء واختلاف في حرف الباء في الأخير","اتحاد اللفظين في كل حروفهما","تشابه الوزن والقافية","توافق أواخر الآيات"],"c":0,"d":"hard","hint":"سبب النقص اختلاف المخرج","expl":"الصواب: في المثال تنهم (ينهون) و(ينأون) مشتركتان في الوزن العام لكن تختلفان في حرف (الهاء والهمزة) فصار جناساً ناقصاً. ولو تشابهت في كل حرف لكان تاماً. نصيحة: جناسٌ ناقص = تغيير في حرف أو ترتيب."},{"q":"من المحسنات المعنوية:","a":["الطباق والمقابلة","الجناس والسجع","الازدواج والترصيع","التكرار والإرداف"],"c":0,"d":"medium","hint":"حسنها راجع للمعنى","expl":"الصواب: الطباق والمقابلة والتورية وغيرها من المعنوية لأنها تقوم على المعنى والعلاقة بين اللفظ ومدلوله. الجناس والسجع والازدواج عائدة للفظ. نصيحة: الطباق = الجمع بين الضدين، وهذا معنى."},{"q":"الطباق هو:","a":["الجمع بين الشيء وضده في الكلام (يحيي ويميت)","الجمع بين اللفظين المتشابهين","إيراد الكلام بفواصل متساوية","التعطف في الأسماء المتقابلة"],"c":0,"d":"easy","hint":"الضد في الضد","expl":"الصواب: الطباق جمع بين معنيين متضادين في الجملة، كقوله تعالى (وتحسبهم أيقاظاً وهم رقود)، (يحيي ويميت). وهو إيجاب وسلب. أما الجناس فلفظي، والتساوي الإيقاعي سجع. نصيحة: احفظ: الطباق = ضد مقابل ضد."},{"q":"التورية هي:","a":["لفظ له معنيان: قريب ظاهر والمراد البعيد دون قرينة مانعة","لفظ يظهر فيه المعنى الواحد","استعارة تصريحية بأداة","لفظ مؤكد بالتوكيد السمعي"],"c":0,"d":"medium","hint":"مخفية المعنى البعيد","expl":"الصواب: التورية لفظ ذو معنيين، يتبادر القريب وتُراد البعيد بلا قرينة تصلمفه، فيظهر الكلام بمظهر الإبهام. والاستعارة لها قرينة مانعة، والحقيقة معنى واحد. نصيحة: التورية = دلالة بلا قرينة على البعيد."},{"q":"المقابلة في البديع هي:","a":["الإتيان بمعنيين متوافقين أو أكثر ثم بما يقابلهما على الترتيب","الجمع بين الضدين فقط","المبالغة في الوصف","الخروج عن أصل الكلام إلى مجازه"],"c":0,"d":"medium","hint":"الأزواج المتقابلة المتناظرة","expl":"الصواب: المقابلة إيراد معنيين ثم مقابليهما على الترتيب، كقوله تعالى: (فليضحكوا قليلاً وليبكوا كثيراً)، وفرقها عن الطباق اشتمالها على أكثر من طرفين مقابلين كل مقابل لما يقابله. الخيارات الباقية تصف الطباق أو المبالغة أو المجاز. نصيحة: مقابلة = أزواج متقابلة على الترتيب، والطباق = ضد واحد للضد."}]}]}]},{"id":"aznahw","name":"النحو والصرف","icon":"✒️","color":"#00695C","books":[{"title":"النحو المتقدم لأزهر الثالث","icon":"✒️","chapters":[{"title":"الاشتغال والتنازع والتعجب","read":[{"h":"الاشتغال","t":"الاشتغال: أن يتقدم اسم على عامل ويشتغل العامل بضميره أو بملابسه، نحو: (زيداً ضربته) و(زيدٌ ضربته) و(البابَ فتحتُه). فالاسم المتقدم يسمى المشغول عنه، والعامل بعدُ اشتغل عن العمل فيه بنصب الضمير أو يأتي بملابسه. وحكمه: يجوز نصبه (علل الفعل العاملة بنيت) أو رفعه الحال على الابتداء، والنصب أرجح عند البصريين ذا المفعولية."},{"h":"حكم الاشتغال","t":"الراجح عند البصريين النصب على المفعولية، وعند الكوفيين الرفع بالابتداء. وجاء الخلاف فيها حقيقة، وكلاهما جائز، لكن يتعين: النصب إذا لم يبق الابتداء معنى تاماً كما لو تقدم اللفظ على عامل. والاختلاف تغلب فيه المعاني على الصناعة. وقد يأتي الاشتغال على أنه إما مفعول به أو مفعول مطلق مقدر."},{"h":"التنازع","t":"التنازع: أن يتقدم عاملان ويتأخر معمول يعمل فيه أحدهما، نحو: (درستُ وحفظتُ الدرسَ)، و(أعطيتُ وأكرمتُ زيداً). وحكمه أنه يجوز إعمال الأول أو الثاني أو إعمال الاثنين معاً بنية الأول. والأحسن إعمال الثاني ورفع الأول بالابتداء أو الفاعل لكونه أقرب وعلى المشهور من قاعدة: إذا أعملت الثاني فالأول يرفع ولا ينتظر في النية."},{"h":"التعجب","t":"التعجب: استعظام أمر في صفاته، وصيغتاه القياسيتان: (ما أفعله!) و(أفعِل به!)، نحو: ما أجمل السماء! وأجمل بالسماء! ويجوز فيه غير ذلك من الصور غير القياسية كقولك: كم أخَذَ في الدهر وأكثر. ويأتي التعجب بشروط من الفعل: ثلاثية تامة متصرفة غير منفية ولا مبنيّة للمجهول ولا متعجباً منها عند النحاة في غير الموارد الخاصة."},{"h":"خلاصة الدرس","t":"الاشتغال: اسم تقدم واشتغل العامل بضميره، والراجح نصبه مفعولاً والخلاف مع الكوفيين، وكلاهما جائز بحسب السياق. التنازع: عاملان ومفعول واحد، والأحسن إعمال الثاني ورفع الأول. التعجب: صيغتان قياسيتان (ما أفعله، أفعل به)، وشروط الفعل: ثلاثي تام متصرف غير منفي ولا مبني للمجهول."}],"qs":[{"q":"الاشتغال في النحو هو:","a":["أن يتقدم اسم ويشتغل العامل بضميره، نحو زيداً ضربته","أن يتقدم الفعل على اسم ويشتغل به","أن يتنازع الفعلان معمولاً واحداً","أن يعمل عاملان في اسمين"],"c":0,"d":"medium","hint":"المشاغلة بالضمير","expl":"الصواب: الاشتغال: تقديم الاسم ثم مجيء عامل مشغول بضمير ذلك الاسم، فالعامل عند البصريين ناصب السابق مفعولاً به بالنصب. الخيارات الأخرى تصف التنازع أو غيره. نصيحة: (اشتغل) = اشتغل بالضمير عن الوصل المباشر."},{"q":"مثالٌ صحيح على الاشتغال:","a":["قرأتُ وكتابُ فلانٍ نصبَ","ضربتُ زيداً ضرباً شديداً","زيداً ضربتُه","إنما الأعمال بالنيات"],"c":0,"d":"medium","hint":"الاسم قبل عامل مشغول بضميره","expl":"الصواب: (زيداً ضربتُه) الاسم زيد تقدم واشتغل الفعل عنه بالهاء العائدة عليه، فيصح نصبه أو رفعه. (ضربتُ زيداً) اشتغال بلا تقدم اسم، والمصدر المؤكد يخص المفعول المطلق. نصيحة: لاحظ الضمير العائد (ه) فهم مفتاح الاشتغال."},{"q":"الصيغتان القياسيتان للتعجب:","a":["ما أفعله! وأفعل به!","هل فعله وأفعل منه","إن فعلتُ والإختيار","فعَّل وأُفعِّل"],"c":0,"d":"easy","hint":"صيغتان سمعهما العرب","expl":"الصواب: التعجب القياسي صيغتان: (ما أفعله) و(أفعل به)، نحو: ما أجملَ السماء، وأجملْ بالسماءِ. والبقية لا تعمل هذا العمل. نصيحة: احفظ الصيغتين بنطق طويل: ما أَفعله! وأَفعِل به!"},{"q":"من شروط الفعل في التعجب القياسي:","a":["أن يكون ثلاثياً تاماً متصرفاً غير منفي وغير مبني للمجهول","أن يكون رباعياً ولو مبنيَّ للمجهول","أن يكون خماسياً مجرداً من التصرف","أن يكون منفياً أو مرادفاً للصفة"],"c":0,"d":"medium","hint":"الأصل في صيغ التعجب","expl":"الصواب: يشترط في الفعل المتعجب منه أن يكون ثلاثياً تاماً متصرفاً غير منفي وغير مبني للمجهول ولا مما لا يتصرف. فالرباعي لا يدخل في هذه الصيغ القياسية. نصيحة: ثالاثي تام متصرف مثبت معلوم = صحة التعجب."},{"q":"التنازع هو:","a":["أن يتقدم عاملان ويتأخر معمول يصلح لأحدهما","أن يتقدم العامل على معمولين","أن يشترك الفاعل والمفعول في عامل","أن يشتغل الفعل بضمير الاسم المتقدم"],"c":0,"d":"medium","hint":"عاملان ومعمول واحد","expl":"الصواب: التنازع: عاملان يطلبان معمولاً واحداً متأخراً، نحو: أعطيتُ وأكرمتُ زيداً، فيعمل الثاني على الأنسب أو الأول. والاشتغال غير التنازع. نصيحة: تنازع = عاملان يختصمان على معمول."},{"q":"الأحسن عند النحاة في التنازع:","a":["إعمال الثاني ورفع الأول بالابتداء أو الفاعلية","إعمال الأول ورفع الثاني دائماً","إعمال الاثنين معاً بلا ترجيح","إلغاء العاملين والاكتفاء بالمعنى"],"c":0,"d":"hard","hint":"القرب يرجِّح الثاني","expl":"الصواب: المشهور أن إعمال الثاني أولى لقربه من المعمول، فيرفع الأول ويسمى مرموقاً لا يعمل به لفظاً، ويجوز إعمال الأول مع المتابعة من الثاني. لا إلغاء للعاملين. نصيحة: القاعدة: أعمل الأقرب (الثاني)، وميّز الأول بالرفع."},{"q":"خلاف البصريين والكوفيين في الاشتغال:","a":["البصريون رجحوا النصب والكوفيون رجحوا الرفع في المفعول به المشغول عنه","فريقان قالا بالمنع عن التركيب أصلاً","البصريون قالوا بالرفع فقط والكوفيون بالنصب","فريقا قالا بالجر في الاسم المتقدم دائماً"],"c":0,"d":"hard","hint":"خلاف في أرجح المصنوع","expl":"الصواب: البصريون جعلوا العامل ناصباً للسابق أي مفعولاً به إلا أن يكون مرفوعاً على الابتداء عند مقتضاه، والكوفيون صرفوه إلى الابتداء المرفوع. والخلاف صناعة يعود في الجواز، فردّاً النحاة يبقى كلاهما جائزاً. نصيحة: البصرة = نصب، الكوفة = رفع على الابتداء."}]},{"title":"أنواع الخبر وأساليب التوكيد","read":[{"h":"أنواع الخبر","t":"الخبر ثلاثة أنواع: (1) مفرد: غير جملة ولا شبه جملة: زيدٌ قائمٌ، (2) جملة: إما اسمية (الكتابُ محتواهُ مفيد) أو فعلية (المعلمُ يشرحُ الدرس)، و(3) شبه جملة: ظرف (الطيرُ فوقَ الشجرة) أو جار ومجرور (بشرط أن يحتفظ بمعناه)، كقولك: الكتابُ في البيت. ويشترط في خبر الجملة أن يكون مع المبتدأ ما يربطه به: ضمير أو إشارة أو عموم."},{"h":"أحكام خبر الجملة","t":"إذا كان الخبر جملة اسمية أو فعلية فلا بد من رابط يربطه بالمبتدأ: (1) ضمير مطابق، (2) الإشارة: الكتابُ ذلكَ نفعُه عظيم، (3) إعادة اللفظ: الحاقة ما الحاقة، (4) العموم: زيدٌ خيرُ الناسِ أُخوهُ علِيمٌ. وفي خبر الجملة الفعلية يجب أن يكون فعلها ماضياً أو مضارعاً دالاً على الحال في الأصل، ولا يجوز ابتداء الخبر بإنشاء."},{"h":"التوكيد اللفظي والمعنوي","t":"التوكيد أسلوب يقرر المعنى في ذهن المستمع، ويكون: (1) لفظياً: بتكرار اللفظ بعينه: جاء زيدٌ زيدٌ، نجح الطلابُ الطلابُ، بكرر الاسم والفعل والحرف، ويرفع بعضهما. (2) معنوياً: بألفاظ تدل على الشمول: النفس، العين، كل، جميع، كلا، كلتا، أجمع، جمعاء، جمع. نحو: جاء الطلابُ كلُّهم، ونجح القومُ أجمعون، وقرأ القومُ جميعاً. والتوكيد المعنوي يتبع المؤكد في الإعراب."},{"h":"أقسام التوكيد المعنوي","t":"التوكيد المعنوي نوعان: (1) توكيد باالنفس والعين: يفيد الذات المعينة وحدها: قام محمد نفسه. (2) توكيد بالكل والجميع وأجمع وجمعاء: يفيد الشمول والعموم. وله في المعنى زيادة الفائدة: النفس والعين للتعيين، وكل وجميع للشمول، وأجمع وجمعاء لتأكيد الشمول. ويجوز تعدد المؤكدات وتتابعها."},{"h":"خلاصة الدرس","t":"أنواع الخبر ثلاثة: مفرد وجملة وشبه جملة، وشبه الجملة ظرف أو جار ومجرور، وخبر الجملة يحتاج رابطة (ضمير، إشارة، إعادة لفظ، عموم). التوكيد نوعان: لفظي بتكرار اللفظ، ومعنوي بألفاظ (نفس، عين، كل، جميع، أجمع...)."}],"qs":[{"q":"الخبر في جملة (الكتابُ محتواهُ مفيدٌ) هو:","a":["جملة اسمية","جملة فعلية","مفرد","شبه جملة"],"c":0,"d":"medium","hint":"خبر ابتداء بجملة اسمية","expl":"الصواب: (محتواه مفيد) جملة من مبتدأ وخبر، والرابط الضمير (ه) في محتواه، فهي خبر جملة اسمية. لو كانت (يشرح) لفعلية ولو كانت (فوقه) لشبه جملة. نصيحة: حدد نوع الخبر: جملة اسمية أم فعلية أم شبه جملة أم مفرد."},{"q":"خبر جملة فعلية في قولنا:","a":["المعلمُ يشرحُ الدرسَ","الكتابُ جديدٌ","العصفورُ فوقَ الشجرةِ","محمدٌ أخوكَ"],"c":0,"d":"easy","hint":"فعل ماض أو مضارع","expl":"الصواب: (يشرح) جملة فعلية خبر المبتدأ المعلم، والرابط الضمير المستتر في الفعل. (جديد) مفرد، (فوق الشجرة) شبه جملة، (أخوك) مفرد. نصيحة: انظر لبداية الخبر: فعل = فعلية."},{"q":"خبر شبه الجملة في قولنا:","a":["العصفورُ فوقَ الشجرةِ","العلمُ نورٌ","زيدٌ قائمٌ","الفريقُ يفوزُ"],"c":0,"d":"medium","hint":"ظرف أو جار ومجرور","expl":"الصواب: (فوق الشجرة) ظرف متعلق بمحذوف خبر، فهو شبه جملة، وكذلك جار ومجرور (في البيت) تجيء بهذا النوع. (نور) مفرد، (قائم) مفرد، (يفوز) جملة فعلية. نصيحة: شبه الجملة = ظرف أو جار ومجرور."},{"q":"مثال يكون فيه كل من المبتدأ والخبر معرفتين:","a":["محمدٌ قائدُ الجيشِ","العلمُ نورٌ","زيدٌ قائمٌ","سافرَ المسافرونَ"],"c":0,"d":"easy","hint":"تعريف الطرفين معاً","expl":"الصواب: (محمد قائد الجيش) المبتدأ معرفة والخبر معرفة مضاف معرفة فصار مثالك المطلوب. (العلم نور) الخبر نكرة، (زيد قائم) الخبر نكرة، الأخير جملة فعلية. نصيحة: المعرفة بالمعرفة = خبر مضاف."},{"q":"التوكيد اللفظي هو:","a":["تكرار اللفظ الأول بعينه للتقرير: جاء زيدٌ زيدٌ","التأكيد بألفاظ: النفس والعين","التأكيد بالكل والجميع","تكثير المترادفات في الجملة"],"c":0,"d":"easy","hint":"تكرير اللفظ","expl":"الصواب: اللفظي بتكرار اللفظة نفسها (اسم أو فعل أو حرف) كقولك: نجح محمدٌ محمدٌ. أما النفس والعين فمعنوية، والكل والجميع شمولية أيضاً. نصيحة: لفظي = اللفظ نفسه مكرر، معنوي = أدوات الشمول."},{"q":"التوكيد المعنوي يقع بألفاظ:","a":["النفس والعين وكلا وكلتا وكل وجميع وجمع وأجمع","إنما وما الحجازية","قد والسوف وحرفي التنفيس","كأن وليت ولعل"],"c":0,"d":"easy","hint":"أدوات المتوكلين","expl":"الصواب: أدوات التوكيد المعنوي: النفس، العين، كلا، كلتا، كل، جميع، أجمع، جمعاء، جمع. وهذه تتبع المؤكد في الإعراب. (إنما) حرف حصر، و(قد) للتحقيق، وليت للتمني، لا من أدوات التوكيد. نصيحة: احفظ ألفاظ التوكيد المعنوي جملة واحدة."},{"q":"في جملة (جاء الطلابُ كلُّهم) كلمة (كل):","a":["توكيد معنوي للشمول","مبتدأ مرفوع","خبر الجملة","مفعول مطلق"],"c":0,"d":"medium","hint":"تتضمن الشمول","expl":"الصواب: (كل) توكيد معنوي يفيد الشمول، وهو متبوع لكلمة الطلاب، وتتعين جميعها وحدها أو مع (أجمع) مؤكدين. ليست مبتدأ ولا خبراً، فالتوكيد تابع. نصيحة: كلهم وكلتا وأجمعون = توكيد معنوي."},{"q":"خبر المبتدأ لا يجوز أن يكون جملة:","a":["إنشائية كالأمر والنهي والاستفهام في الأصل","اسمية ذات ضمير يعود على المبتدأ","فعلية ماضية أو مضارعة الحالية","شبه جملة ظرفية مرتبطة"],"c":0,"d":"hard","hint":"الخبر يفيد تقريراً لا طلباً","expl":"الصواب: الخبر تقريري، فإذا كان الجملة إنشائية كالأمر أو النهي أو الاستفهام لم يصلح خبراً لأنها لا تحتمل الصدق والكذب، وإنما يصح الخبر الجمل الاسمية والفعلية الخبرية. الخيارات الباقية صحيحة للخبر. نصيحة: الخبر = تقرير، الإنشاء = طلب، يتنافيان."}]},{"title":"المصادر والمشتقات وأوزان الصرف الرئيسية","read":[{"h":"المصادر وقياسها","t":"المصدر: اسم يدل على حدث مجرد من الزمن، وتقاس مصادر الرباعي وما فوقه. فأوزان المصادر: الثلاثي سماعي يؤخذ من كتب اللغة، والرباعي: على (فَعْلَلة) من الرباعي، (إفعال) من أفعل، (تفعيل) من فعَّل، (مفاعلة وفِعال) من فاعل. والخماسي: (تَفعُّل) من تفعَّل، (تفاعل) من تفاعل، و(افتعال) من افتعل. والسداسي: (استفعال) من استفعل، و(افعلال) من افعلّ، و(افعنلال) من اقعنلّل."},{"h":"اسم الفاعل واسم المفعول","t":"اسم الفاعل من الثلاثي على (فاعل): كاتب، ومن غير الثلاثي على الحرف الحتمي بالاعتماد على المضارع مع إبدال حرف المضارعة ميم مضمومة وكسر ما قبل الأخير: مُكرِم، مُستفهِم. واسم المفعول من الثلاثي على (مفعول): مكتوب، ومن غير الثلاثي على المضارع مع ضم الحرف إبدال الميم مضمومة وفتح ما قبل الآخر: مُكرَم، مُستخرَج. والفاعل يرفع المرفوع، والمفعول ينصبه."},{"h":"صفة المشبهة وأمثلة المبالغة","t":"صفة المشبهة: اسم مشتق من لازم يدل على ثبوت معنى، قياسية من الثلاثي اللازم: فعول، فعيل، فعل، فعلان، أفعل. أشهرها: حسن، طويل، غضبان، عطشان. وأمثلة المبالغة: فعّال (ضرّاب)، مفعال (مضراب)، فعول (غفور)، فعيل (سميع)، فعل (حذر). وهي تدل على كثرة وقوع الحدث."},{"h":"الميزان الصرفي والأوزان","t":"الميزان الصرفي: قالب يوزن به الكلمة العربية على أحرف (ف، ع، ل): فاعل وزنه (فاعل)، كتّاب (فَعّال)، المستقبل (مُفتعِل). وللتاء زيادة أو بدل يوضع ما يقابلها في الموضع يميناً أو يساراً: يجري الميزان. ويعرف بالوزن زيادة الحروف والقلب والإعلال والإبدال. وأوزان الأسماء الرئيسية في الصرف العربي: فَعَل، فَعِل، فَعُل، فعالة... تستعمل للتمييز بين الأبواب."},{"h":"خلاصة الدرس","t":"المصادر الثلاثية سماعية والرباعية فصاعداً قياسية بالأوزان المعروفة، واسم الفاعل فاعل في الثلاثي والمفعول مفعول، والمشتقات كصفة المشبهة وأمثلة المبالغة، والميزان الصرفي (فعل، فعِل، فعَل، فعُل...) أداة لضبط الصيغ والتعرف على الزوائد والأوزان."}],"qs":[{"q":"المصدر من الفعل الثلاثي يكون:","a":["سماعياً يؤخذ من كتب اللغة والقاموس وليس له قاعدة","مقيساً على وزن فَعْلَلة","مقيساً على وزن إفعال","مقيساً على وزن مفاعلة"],"c":0,"d":"medium","hint":"الثلاثي والميزان","expl":"الصواب: مصادر الثلاثي سماعية لا قاعدة قياسية لها، فتؤخذ من المعاجم: كتب كتابةً، ضرب ضرباً. والأوزان المذكورة قياسية لما فوق الثلاثي. نصيحة: تذكّر: الثلاثي سماعي، وما فوق الثلاثي قياسي."},{"q":"مصدر الفعل (فعَّل) الرباعي المضعف قياسه:","a":["تفعيلاً","إفعالاً","مفاعلة وفِعالاً","فعولة"],"c":0,"d":"medium","hint":"وزن فعّل","expl":"الصواب: قياس فعلَّ على تفعيل: كرَّم تكريماً، علَّم تعليماً. وأما إفعال لفعل الثلاثي (أكرم إكراماً)، ومفاعلة لفاعل (قاتل قتالاً)، وسطوع قياس لأفعال معينة. نصيحة: فعّل = تفعيل، أفعل = إفعال، فاعل = مفاعلة."},{"q":"مصدر الفعل (فاعَل) قياسه:","a":["مفاعلة وفِعالاً","إفعالاً","تفعيلاً","افتعالاً"],"c":0,"d":"medium","hint":"وزن فاعل","expl":"الصواب: فاعل قياس مصدره مفاعلة وفِعال: قاتله مقاتلة وقتالاً، جاهد مجاهدة وجهاداً. الخيارات الأخرى أوزان أفعال أخرى. نصيحة: فاعل = مفاعلة أو فعال، اسأل عن العلاقات الودية."},{"q":"الميزان الصرفي هو:","a":["قالب يوزن به الكلمة العربية على أحرف (ف، ع، ل) لضبط الصيغ","ميزان يعرف به أحكام الإعراب","ميزان الشواهد الشعرية","ميزان الجمع والمفرد في التصريف"],"c":0,"d":"easy","hint":"ف ع ل","expl":"الصواب: الميزان الصرفي يستعمل أحرف ثلاثة (ف ع ل) لبيان وزن الكلمة وزوائدها: كاتب = فاعل، استفعال = استفعال. ليس ذا علاقة بالإعراب ولا بالشعر. نصيحة: كل حرف في الميزان يقابل حرفاً من (ف ع ل)."},{"q":"اسم الفاعل من الفعل الثلاثي يكون على وزن:","a":["فاعل","مفعول","فعيل","فعلان"],"c":0,"d":"easy","hint":"الفاعل الثلاثي","expl":"الصواب: اسم الفاعل من الثلاثي على وزن فاعل: كتب كاتب، شرب شارب. المفعول من الثلاثي مفعول، والفعيل والفعيل من صفات المشبهة. نصيحة: كاتب = الفاعل، مكتوب = المفعول."},{"q":"اسم المفعول من الفعل غير الثلاثي، مثال: (أكرم) يكون:","a":["مُكرَم على وزن مُفعَل","مُكرِم على وزن مفعِل","أكرمُ على وزن أفعل","مُتكرَمَ على وزن متفعَّل"],"c":0,"d":"medium","hint":"المفعول غير الثلاثي","expl":"الصواب: من غير الثلاثي يبنى اسم المفعول على المضارع مع ضم ما قبل الآخر: أكرم → يُكرم (مُفعِل) لكن المفعول من الفعل الرباعي على (مُفعَل): مُكرَم، استخرج → مستخرَج (مُستفعَل). والمتعاهد الخطأ: مُكرِم فاعل، مُكرَم مفعول. نصيحة: فاعل = فتح ما قبل الآخر، مفعول = ضم الميم مع فتح ما قبل الآخر."},{"q":"من أوزان صيغ المبالغة الشائعة:","a":["فعّال وفعول ومِفعال وفعيل وفُعَل","فاعل ومفعول","مفعول وفعلان","مفاعلة وفِعال"],"c":0,"d":"easy","hint":"أوزان المبالغة الخمسة","expl":"الصواب: أمثلة المبالغة: فعّال (ضرّاب)، فعول (غفور)، مفعال (مضراب)، فعيل (سميع)، فعل (حذر). والفاعل والمفعول أسماء مفعول عاديتان. نصيحة: احفظ الخمسة: فعّال، فعول، مفعال، فعيل، فعل."}]}]}]},{"id":"azen","name":"لغة أجنبية (إنجليزية)","icon":"🇬🇧","color":"#0277BD","books":[{"title":"English Azhar 3","icon":"🇬🇧","chapters":[{"title":"Grammar Review (Tenses + Conditional)","read":[{"h":"Tenses: Present and Past","t":"The present simple is used for general truths and habits: She goes to Cairo every Friday. The present continuous is for actions happening now or around now, and the past continuous describes an action in progress at a past moment: I was doing my homework when my friend called me. Remember the signal words: every day, always, usually (simple), now, at the moment (continuous)."},{"h":"Tenses: Perfect and Future","t":"The present perfect shows a link between past and present: I have lived here for ten years. It combines with since (point of time) and for (duration): since 2010 / for ten years. The past perfect shows an event before another past event: When I arrived, the meeting had already started. The future perfect shows completion before a future time: By next year, he will have worked here for ten years."},{"h":"Conditionals","t":"Zero conditional (general truth): If you heat water, it boils. First conditional (likely future): If it rains, we will stay home. Second conditional (unreal present): If I were rich, I would travel around the world (note the subjunctive \"were\"). Third conditional (unreal past): If he had studied hard, he would have passed the exam. Remember the sequence of tenses carefully."}],"qs":[{"q":"She ______ to Cairo every Friday.","a":["goes","go","going","gone"],"c":0,"d":"easy","hint":"habit with literal week; subject she → -s","expl":"The subject \"she\" requires the third person singular -s with the present simple used for habits: She goes. \"Go\" and \"going\" do not conjugate correctly, and \"gone\" needs a helping verb. Exam tip: check the subject and the signal word (every Friday)."},{"q":"I ______ my homework when my friend called me.","a":["was doing","do","did was","am doing"],"c":0,"d":"medium","hint":"past action in progress interrupted","expl":"The past continuous (was doing) shows a long action interrupted by a short past action (called). Present tenses do not fit the past context \"called me\". Exam tip: past continuous + past simple is a classic pattern pair."},{"q":"By next year, he ______ here for ten years.","a":["will have worked","works","has worked","worked"],"c":0,"d":"medium","hint":"completion before a future moment: future perfect","expl":"\"By next year\" points to a completed action before a future time, so we need the future perfect (will have worked). \"Has worked\" is present perfect and \"worked\" is past simple, both not for the future. Exam tip: \"by + future time\" always signals future perfect."},{"q":"If I ______ rich, I would travel around the world.","a":["were","am","was be","have been"],"c":0,"d":"medium","hint":"second conditional: unreal present","expl":"The second conditional uses the subjunctive \"were\" for unreal present situations: If I were rich. \"Am\" and \"have been\" do not fit the structure, and \"was be\" is not a form. Exam tip: \"would + infinitive\" means second conditional → subjunctive \"were\"."},{"q":"If he had studied hard, he ______ the exam.","a":["would have passed","will pass","passes","would pass"],"c":0,"d":"hard","hint":"third conditional: unreal past","expl":"The past perfect clause (had studied) requires the third conditional result \"would have passed\". \"Will pass\" and \"passes\" belong to first conditional, and \"would pass\" to the second. Exam tip: past perfect in the if-clause → would have + past participle."},{"q":"She has been living in Alexandria ______ 2010.","a":["since","for","ago","from"],"c":0,"d":"easy","hint":"point of time in the past with present perfect continuous","expl":"\"2010\" is a point of time, so we use \"since\" with the present perfect continuous. \"For\" needs a duration (for ten years), \"ago\" is used with past simple, and \"from\" does not work here. Exam tip: since + point, for + duration."},{"q":"When I arrived, the meeting ______ already ______.","a":["had, started","has, started","was, start","did, started"],"c":0,"d":"hard","hint":"past event before another past event","expl":"The past perfect \"had started\" shows the meeting began before my arrival. \"Has started\" is present perfect, \"was start\" is ungrammatical, and \"did started\" repeats a past marker. Exam tip: two past actions → the earlier one gets the past perfect."}]},{"title":"Vocabulary of the Azhar curriculum","read":[{"h":"Education and Science Words","t":"Words related to studying and exams are common in the Azhar curriculum: achieve (نجح في / أنجز), improve (يحسّن), appoint (يعيّن في منصب), benefit (فائدة), research (بحث), knowledge (معرفة). Learn their opposites as well: ancient opposite modern, brave opposite cowardly, success opposite failure."},{"h":"Everyday Words and Phrasal Verbs","t":"Everyday vocabulary helps in reading: urgent (عاجل ملحّ), courage (شجاعة), furniture (أثاث), generous (كريم), polite (مهذب), journey (رحلة). Two-useful patterns: word building (act → action → active → activity) and common suffixes such as -ment, -ness, -tion, -ful."},{"h":"Revision Tips","t":"اتبع طريقة المراجعة للمفردات: اكتب الكلمة ومعناها في دفتر خاص، وضعها في جملة من إنشائك، ثم اربطها بمرادفها وضدها. تدرب على قراءة القطع القصيرة واستخراج معنى الكلمة من السياق، فهذه المهارة هي الأكثر تكراراً في امتحانات الأزهر الشريف."}],"qs":[{"q":"To \"achieve\" means to:","a":["succeed in doing or reaching something","avoid something completely","make something fail","postpone something forever"],"c":0,"d":"easy","hint":"فعل النجاح والإنجاز","expl":"The correct meaning of \"achieve\" is to succeed in reaching a goal or completing something. The other options express avoiding, failing, or delaying, which are opposite ideas. Exam tip: understand meaning through context; \"achieve a goal\" is a common collocation."},{"q":"The opposite of \"ancient\" is:","a":["modern","old","historic","antique"],"c":0,"d":"easy","hint":"قديم وعتيق يقابله حديث","expl":"\"Ancient\" means very old, so its opposite is \"modern\" (حديث). \"Old\", \"historic\" and \"antique\" are close in meaning to ancient, not opposites. Exam tip: when a question asks for the opposite, eliminate the synonyms first."},{"q":"The word \"appoint\" means:","a":["choose someone for a job or position","cancel a meeting","refuse an offer","delay an event"],"c":0,"d":"medium","hint":"التعيين في منصب","expl":"\"Appoint\" means officially choose someone to do a job (يعيّن). The other options are about cancelling, refusing, or delaying, which are unrelated actions. Exam tip: connect \"appoint\" with \"manager\" or \"position\" in exam texts."},{"q":"A synonym of \"brave\" is:","a":["courageous","afraid","cowardly","weak"],"c":0,"d":"medium","hint":"شجاع","expl":"\"Brave\" means showing courage, and \"courageous\" is its exact synonym. Afraid, cowardly and weak are all opposite meanings. Exam tip: most vocabulary questions give one correct synonym and three distractors of opposite meaning."},{"q":"The word \"urgent\" means:","a":["needing immediate attention","delayed forever","optional and easy","relaxing and calm"],"c":0,"d":"medium","hint":"ملحّ وعاجل","expl":"\"Urgent\" describes something that must be dealt with very soon (عاجل ملحّ). The other options express postponing, ease, or calmness, which contradict urgency. Exam tip: remember \"urgent\" collocates with \"need\" and \"matter\"."},{"q":"To \"improve\" means to:","a":["make something better","make something worse","destroy something","ignore something"],"c":0,"d":"easy","hint":"يحسّن ويطوّر","expl":"\"Improve\" means to make something better or advance it. Making worse, destroying, or ignoring are all opposite or unrelated meanings. Exam tip: think of \"improvement\" as a noun for betterment; it is a frequent exam word."}]}]}]}]},{"id":"azharu","name":"الأزهرية — العلمية","icon":"🕌","color":"#2E7D32","grad":"linear-gradient(135deg,#2E7D32,#A5D6A7)","desc":"العلوم الشرعية، اللغة العربية، والرياضيات — لمنهج الأزهر الشريف العلمي","subjects":[{"id":"sharia","name":"العلوم الشرعية","icon":"📿","color":"#795548","books":[{"title":"التفسير","icon":"📖","chapters":[{"title":"آيات الخلق","read":[{"h":"الكون مخلوق بقدرة الله","t":"تناولت آيات الخلق في القرآن كيفية إنشاء الله للكون والسماء والأرض والحياة، قال تعالى: \"أَفَلَمْ يَنظُرُوا إِلَى السَّمَاءِ فَوْقَهُمْ كَيْفَ بَنَيْنَاهَا وَزَيَّنَّاهَا وَمَا لَهَا مِن فُرُوجٍ\". وتؤكد الآيات أن الخلق ليس عبثاً بل بحكمة وبقدر وترتيب، ويدعو القرآن إلى النظر والتفكر في الخلق ليكون عبرة للعلم والإيمان معاً."},{"h":"خلق الإنسان وتكريمه","t":"ذكر القرآن مراحل خلق الإنسان: من تراب ثم نطفة ثم علقة ثم مضغة ثم عظاماً ثم كسا العظام لحماً، قال تعالى: \"وَلَقَدْ خَلَقْنَا الْإِنسَانَ مِن سُلَالَةٍ مِّن طِينٍ * ثُمَّ جَعَلْنَاهُ نُطْفَةً فِي قَرَارٍ مَّكِينٍ\". وكرم الله الإنسان بالعقل والاختيار وخلافة الأرض، فكان الخلق دفعةً، وله غاية سامية هي عبادة الله وعمارة الكون."},{"h":"الإعجاز والموافقة العلمية","t":"امتاز القرآن الكريم بلزوم الإعجاز العلمي في آيات الخلق؛ فالآية تصف ما وصل إليه العصر من دقة في خلق السماوات والأرض والمراحل الجنينية، دون تعارض مع الحقائق العلمية الثابتة. هذا دليل النبوة والدعوة إلى البحث العلمي الموظف لخدمة الإنسانية."},{"h":"الغاية من التفكر","t":"ينبهنا القرآن بأن الغرض من خلق الكائنات الحية وذكرها عبرة: \"كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ\". فالكون = كتاب مفتوح يقرأ صفحاته العلماء، والقرآن = الدليل الهادي لهذه القراءة. هكذا يجمع النص بين التوحيد والتوجيه العلمي."},{"h":"خلاصة الدرس","t":"آيات الخلق تثبت قدرة الله في إنشاء الكون والإنسان، وتدعو لتدبر ملكوته، وتشتمل إعجازاً علمياً متوافقاً مع دقائق المعرفة، وغايتها العبادة والعمارة والتفكر."}],"qs":[{"q":"تبدأ آيات القرآن في بيان خلق الإنسان من:…","a":["التراب أو الطين مرحلة أولى","النور مباشرة","الماء فقط بلا مراحل","النار دائماً"],"c":0,"d":"easy","hint":"أول مراحل ذكر الخلق في النصوص","expl":"الصواب: تبدأ من التراب/الطين، قال تعالى \"من سلالة من طين\"، ثم تتنقل لمراحل النطفة والعلقة والمضغة. لا نبدأ بالنور ولا نقتصر على الماء فقط ولا بالنار. نصيحة: احفظ مراحل الخلق بالترتيب: تراب ← نطفة ← علقة ← مضغة ← عظام ← لحم، ثم تسهل كل أسئلة الخلق."},{"q":"خلق السماوات سبعاً طباقاً ورد في القرآن في سياق:…","a":["إثبات قدرة الله وتفرده بالخلق","بيان فائدة الرعد","أحكام الميراث","قصص الأنبياء فقط"],"c":0,"d":"medium","hint":"الغرض من ذكر خلق الكون في القرآن","expl":"الصواب: إثبات قدرة الله وتفرده بالخلق وإحكامه؛ فذكر السماوات مصروف لدلالة الوحدانية والحكمة، لا لأحكام ولا لقصة خاصة وحدها. نصيحة: كل خلق للكون في القرآن يأتي إما للدلالة على وحدانية الله أو للتفكر والعبرة."},{"q":"الغرض الرئيسي من دعوة القرآن الكريم إلى التفكر في مخلوقات الله:…","a":["الوصول إلى الإيمان والعبرة","تجميع المعلومات فقط","الفخر بذلك","الترفيه"],"c":0,"d":"easy","hint":"لماذا تُقرأ آيات الكون؟","expl":"الصواب: الوصول إلى الإيمان واليقين والعبرة؛ فالتفكر في الخلق طريق معرفة الخالق. المعلومات وحدها بلا عبرة ليست هي الغاية، والفخر والترفيه لا يليقان بمقام النص. نصيحة: \"عبادة التفكير\": كونٌ متدبر + قرآن متلو = إيمان راسخ."},{"q":"قال تعالى \"ثُمَّ جَعَلْنَاهُ نُطْفَةً فِي قَرَارٍ مَّكِينٍ\". المقصود بالقرار المكين:…","a":["الرحم الذي يستقر فيه الجنين","جوف الأرض","البحر العميق","الصحراء"],"c":0,"d":"medium","hint":"مكان آمن ثابت في جسد الأنثى","expl":"الصواب: الرحم، فهو المستقر الآمن الحافظ للنطفة طوال مرحلة التكوين، وهو ما أشار إليه المفسرون. بقية الخيارات لا تتوافق مع سياق خلق الإنسان في الأرحام. نصيحة: تذكّر: قرار مكين = رحم حصين، وهذا يعينك في أسئلة مراحل الخلق."},{"q":"أحد الأدلة النقلية على إحكام خلق الله في قوله تعالى:…","a":["\"صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ\"","\"وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ\"","\"إِنَّ فِي ذَلِكَ لَعِبْرَةً\"","كل الآيات المذكورة"],"c":0,"d":"hard","hint":"صيغة الدقة والإحكام المباشرة","expl":"الصواب: جميع الآيات الثلاث تدل على المراد؛ الآية الأولى تصرح بالإتقان، والثانية تنفي اللعب والعبث، والثالثة تدعو للعبرة، فهي تكاملية وليست خياراً واحداً حصراً. نصيحة: في أسئلة اختيار متعدد، انتبه لخيار \"كل ما سبق\" عندما تكون الآيات الثلاث دلالات للغرض نفسه."},{"q":"القرآن الكريم يصف مرحلة تكون العظام قبل كسوة اللحم وهذا يتفق مع:…","a":["ترتيب الخلق الجنيني المذكور في النص","رأي فلاسفة القدماء فقط","الحياة في القرون الوسطى","لا علاقة له بشيء"],"c":0,"d":"medium","hint":"مراحل التخلق وتأييد النص الوصفي","expl":"الصواب: يصف النص ترتيباً له دلالته في تخلق الجنين: عظام ثم كسوة لحم؛ وهذا التعبير القرآني حمال للشرح العلمي الحديث دون تناقض. لا يخص فلسفة قديمة أو الحياة الوسيطة بالذات. نصيحة: آن لنا أن نتبين أن \"موافقة النص العلم الثابت\" من دلائل الإعجاز، لا تكلف الخطأ."}]},{"title":"آيات الأحكام","read":[{"h":"مصدر الأحكام الشرعية","t":"آيات الأحكام مجموعة النصوص القرآنية التي تتضمن تكاليف وأحكاماً يفعل الناس بعملها، مثل: الصلاة، الزكاة، الصيام، الحج، المعاملات، الحدود. فهي الأساس الأول للتشريع ثم السنة الإيضاحية. القرآن \"قاعدة التشريع\" والسنة \"الشارحة والمفصلة\"، وهذا أصالة التشريع في آيات الأحكام."},{"h":"آيات العبادات","t":"فرض الله العبادات ببيان وجوبها ومواقيتها وأركانها: الصلاة \"وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ\"، والصيام \"كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ\"، والحج \"وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا\". هذا وسقط حكم مخصوص كالقصر والفدية في آيات عديدة."},{"h":"آيات المعاملات والحلال والحرام","t":"ضبط القرآن المعاملات المالية: إباحة البيع وتحريم الربا \"وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا\"، والعدل في الكيل والميزان، وأداء الأمانات والعهود. وفي الأطعمة أحل الطيبات وحرم المحرمات \"حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ\". الأحكام أتت تفصيلاً أو جملة تحتاج السنة لتفصيلها."},{"h":"الناسخ والمنسوخ ومنهج الفهم","t":"من آيات الأحكام ما زال عاملاً وبعضها نسخ حكمه كتحريم الخمر تدريجياً بعد التدرج في التنزيل، ففهم آيات الأحكام يتطلب مراعاة: السياق، وأسباب النزول، والناسخ والمنسوخ، وتفسير الصحابة والتابعين، وقواعد اللغة العربية. لذلك الفقيه المجتهد لا يستغني عن النصوص الشرعية كلها."},{"h":"التطور التدريجي للتشريع","t":"من الحكم العظيمة في الأحكام أن الله شَرعها بالتدرج، خاصة في المجتمع الأول؛ فتحريم الخمر جاء على مراحل؛ ليقلع القوم عن العادات الجاهلية قولاً بعيداً عن الصدمة العنيفة، فكانت رحمة بالامة ولطفاً بها، وهو درس في فقه الواقع وأسس التيسير."},{"h":"خلاصة الدرس","t":"آيات الأحكام أساس التشريع: عبادات (صلاة، زكاة، صيام، حج) ومعاملات (بيع، ربا، أطعمة، أمانات). فهمها يحتاج مراعاة أسباب النزول والناسخ والمنسوخ والسياق، وقد شرعت فيها الأحكام بالتدرج الحكيم لسهولة التطبيق على المجتمع."}],"qs":[{"q":"أساس التشريع الأول في الإسلام هو:…","a":["القرآن الكريم","الإجماع فقط","القياس وحده","رأي الحاكم"],"c":0,"d":"easy","hint":"الوحي المتلو أول المصادر","expl":"الصواب: القرآن الكريم، فهو الأصل الأول للتشريع ثم السنة تفسر الشيء جملته. الإجماع والقياس مصادر لاحقة مبناها على الكتاب والسنة، ورأي الحاكم تبع لها لا أصل. نصيحة: رتب المصادر: قرآن ← سنة ← إجماع ← قياس، فهو جدول أخلاقي محفوظ."},{"q":"قوله تعالى \"وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا\" يدل على:…","a":["إباحة البيع وتحريم الربا","تحريم البيع","إباحة الربا","التحريم عن كل البيع"],"c":0,"d":"easy","hint":"أصل المعاملات بالحكمين معاً","expl":"الصواب: إباحة البيع وتحريم الربا؛ فالجملة جاءت مقابلة تجعل الحلال والحرام ظاهرين. لا تحريم للبيع بذاته ولا إباحة للربا، فالمنع جزئي محدد. نصيحة: هذه الآية \"ميزان المعاملات\": بيع مباح، ربا محظور — استظهار قاعدة الرسول في اقتصاداتك."},{"q":"من آيات الأحكام ما ورد مجملاً يحتاج إلى تفصيل السنة، مثال آية:…","a":["آية الزكاة التي تفصلها السنة في الأنصبة والقدر","آية التوحيد","آية الوعد والوعيد","آيات القصص"],"c":0,"d":"hard","hint":"فروض فرضت جملة وجاءت السنة بتفصيلها","expl":"الصواب: الزكاة فرضها القرآن مجملاً (آتوا الزكاة) وحّدت السنة أنصابها ومواقيتها وأهلها، وهذا نموذج بيان السنة للقرآن. التوحيد والوعد لا يحتاجان تفصيل عمل؛ والقصص عظة لا أحكام. نصيحة: كل \"أقيموا/آتوا\" مجمل العبادة، والسنة هي المفصلة؛ مثل صلاة، زكاة، حج."},{"q":"تدريج تشريع تحريم الخمر يدل على مراعاة الشارع لمبدأ:…","a":["التدرج في التشريع والرفق بالمكلفين","التشديد الفوري في كل شيء","الغش في الترتيب","تجاهل الواقع"],"c":0,"d":"easy","hint":"خطوة بخطوة حتى القطع النهائي","expl":"الصواب: التدرج في التشريع والرفق بالمكلفين والمجتمع؛ فالتدرج عالج عادة راسخة برفق حتى كامل التحريم. التشديد الفوري يناقض ظاهر النصوص، والغش والتجاهل لا يليقان بالشارع. نصيحة: \"شريعة التدرج\": طعم الرحمة في تشريع الله، كتحريم الخمر بعد نزول آيات النهي المتدرج."},{"q":"حدود التكليف في عبادة الحج قرنها الله في القرآن بقوله:…","a":["من استطاع إليه سبيلاً","على كل الناس دون شرط","على الأغنياء فقط","على المقيمين في مكة"],"c":0,"d":"easy","hint":"شرط القدرة في آية الحج","expl":"الصواب: بالاستطاعة (من استطاع إليه سبيلاً)، فالواجب مربوط بالقدرة المادية والبدنية والأمن. وجوبه على كل مسلم مستطيع: رجل وامرأة، وليس حصراً على فئة. نصيحة: \"الاستطاعة إمام التكليف\": الحج يقيد بالاستطاعة، والصوم بالطاقة لنفسه، وغير ذلك."},{"q":"سبب اهتمام المفسرين بمعرفة أسباب النزول في آيات الأحكام:…","a":["لفهم الحكم بدلالته وظرفه وتطبيقه الصحيح","لزيادة عدد الآيات","لإبطال الأحكام","لتزيين الكلام"],"c":0,"d":"medium","hint":"وعي السياق يضبط الاستنباط","expl":"الصواب: فهم الحكم وظرفه المرتبط بسببه ثم تطبيقه الصحيح، فالنزول يفسر العلاقة بين النص وواقعه. ليس لأغراض زيادة العدد ولا لإبطال الأحكام ولا تجميل النص. نصيحة: وأسباب النزول \"قبة السياق\": إذا عرفته أحسنت الفهم، وإذا جهلته أخطأت التطبيق."}]}]},{"title":"الحديث والعقيدة","icon":"🕌","chapters":[{"title":"أركان الإيمان","read":[{"h":"حديث جبريل وأركان الإيمان","t":"سأل جبريل النبي صلى الله عليه وسلم عن الإيمان فقال: \"أن تؤمن بالله وملائكته وكتبه ورسله واليوم الآخر وتؤمن بالقدر خيره وشره\". هذا الحديث مدار أصول العقيدة، وتعريف الإيمان عند أهل السنة: قول باللسان، واعتقاد بالقلب، وعمل بالجوارح، يزيد بالطاعة وينقص بالمعصية."},{"h":"الإيمان بالله","t":"أصل الأركان ومنبعها، وهو الإقرار بوحدانية الله في ربوبيته (الخالق المدبر)، وألوهيته (المستحق للعبادة)، وأسمائه وصفاته (كما وصف نفسه بلا تكييف ولا تعطيل ولا تمثيل). يتضمن محبة الله وتعظيمه والخوف والرجاء والتوكل عليه. توحيد الله قطب الإيمان الأول والوجوب العلوي في الشرع."},{"h":"الملائكة والكتب والرسل","t":"الإيمان بالملائكة: خلق نورانيون لا يعصون الله، مثل جبريل (الوحي)، ميكائيل (الأرزاق)، إسرافيل (النفخ في الصور)، ملك الموت. الإيمان بالكتب: التوراة والإنجيل والزبور والقرآن المهيمن ناسخ لما قبله. الإيمان بالرسل: وجوب الإيمان بجميعهم، وأشهرهم أولو العزم، محمد صلى الله عليه وسلم خاتمهم، ونؤمن بأن رسالتهم واحدة في التوحيد والأصل."},{"h":"اليوم الآخر والقدر","t":"الإيمان باليوم الآخر: الموت والبعث والحشر والميزان والصراط والجنة والنار، وهو يقود للعمل والاستعداد. القدر: أن الله علم كل شيء وقدّره وكتبه في اللوح المحفوظ وشاءه، ومنه خيره وشره. لا يعني القدر تخلياً عن الأسباب؛ بل يجمع المؤمن بين توكل وسببية كما في سؤال النبي عن التوكل واعتقاد أهل السنة."},{"h":"أثر الإيمان في السلوك","t":"الأركان ليست معلومات تلقى، بل منظومة تربي: الإيمان بالله يملأ القلب بالطمأنينة، والملائكة تجعل المراقبة حية، واليوم الآخر يغذي المسؤولية، والقدر يورث الرضا والاتزان النفسي، فيكون المؤمن آمن النفس منشرح الصدر منضبط السلوك. هذه ثمرة العقيدة العملية."},{"h":"خلاصة الدرس","t":"أركان الإيمان ستة: الله، الملائكة، الكتب، الرسل، اليوم الآخر، القدر خيره وشره. الإيمان قول وعمل واعتقاد يزيد وينقص. أثره: طمأنينة ومسؤولية وانضباط ورضا، وهذه منظومة تصنع النفس المسلمة."}],"qs":[{"q":"عدد أركان الإيمان كما في حديث جبريل عليه السلام:…","a":["ستة","خمسة","أربعة","سبعة"],"c":0,"d":"easy","hint":"عد معك: الله، ملائكته، كتبه، رسله، اليوم الآخر، القدر","expl":"الصواب: ستة، وهي المذكورة في حديث جبريل، بينما أركان الإسلام خمسة. الخيارات الأخرى تخلط بين الإسلام والإيمان. نصيحة: فرّق: \"الإيمان ستة، والإسلام خمسة\" رابط أبدي في عقول طلاب الأزهر."},{"q":"من أصناف الملائكة:…","a":["جبريل المكلف بالوحي","إبليس المكلف بالوحي","شخص النبي","الجن في السماوات"],"c":0,"d":"medium","hint":"الملك الموصوف بتنزيل الوحي","expl":"الصواب: جبريل ملك الوحي الذي ينزل به على الأنبياء. إبليس من الجن وليس من الملائكة في العقيدة السليمة، ونبي الله خلق بشري مختلف عن الملائكة، والجن نقل لنوع آخر. نصيحة: احذر الخلط الشهير: إبليس من الجن، وجبريل من الملائكة."},{"q":"تعريف الإيمان عند أهل السنة يشمل:…","a":["القول والاعتقاد والعمل","الاعتقاد بالقلب فقط","فعل اللسان فقط","العمل فقط بلا قلب"],"c":0,"d":"easy","hint":"مدرسة الصحابة في فهم الإيمان","expl":"الصواب: قول باللسان، واعتقاد بالقلب، وعمل بالجوارح، يزيد بالطاعة وينقص بالمعصية. الاقتصار على جانب واحد مذهب مرجئة أو جبرية، لا يوافق كلام السلف. نصيحة: الإيمان \"كالثالوث عملي وقول واعتقاد\"؛ لا تجعل العمل زائداً خارج حقيقته."},{"q":"الإيمان بالقضاء والقدر لا يسقط عن المؤمن:…","a":["الأخذ بالأسباب والاتكاء على الله","القعود عن العمل","إنكار السنن","ترك الدعاء"],"c":0,"d":"medium","hint":"أمر به النبي حين سأله الصحابي عن الوضوء","expl":"الصواب: لا يسقط الأخذ بالأسباب، فالنبى رابط بين الأسباب والتوكل: \"اعقلها وتوكل\". القدر لا يجيز ترك العمل والدعاء والسنن والأسباب؛ هذه حجة الطاعنين والمغفلين. نصيحة: اقبض على الضابط: قدر حق، وأسباب مطلوبة، واتكال عليه يمزج بينهما."},{"q":"الإيمان بالكتب السماوية يتضمن الإيمان بأن:…","a":["القرآن مهيمن عليها منسوخ لها","كل الكتب محرّفة بالضرورة","التورية والإنجيل أصبحا ناسخين","لا نؤمن بشيء منها"],"c":0,"d":"hard","hint":"أفضل تشريع الشريعة الخاتمة","expl":"الصواب: نؤمن بكون الكتب كلها من عند الله، وبأن القرآن مهيمن مصدق لها ناسخ لما قبله من أحكام. القول بأنها كلها محرفة أو منسوخة كلها أو لا نؤمن بها باطل، بل التحريف وقع في الألفاظ والمعاني لبعضها والناسخ المتبع لنا هو القرآن. نصيحة: قاعدة: \"نشهد على الأصول، ونتبع الناسخ الخاتم، ونكذّب ما خالف القرآن\"."},{"q":"الإيمان باليوم الآخر يقود المؤمن إلى:…","a":["الاستعداد بالأعمال الصالحة","الأنس مع البعد عن الواجب","الخوف من الناس فقط","الانشغال بالحسابات الدنيوية فقط"],"c":0,"d":"easy","hint":"ثمرة الإيمان بالحساب","expl":"الصواب: الاستعداد بالأعمال الصالحة والوقوف عند حدود الله؛ فالخوف من يوم الحساب يورث المسؤولية. الباقي من آفات غافلة الإيمان. نصيحة: \"اليقين بالجزاء = رقيب داخلي\": جعل العالم يحرص على الطاعة من داخله لا بمراقب خارجي فقط."}]},{"title":"فقه السنة","read":[{"h":"قيمة السنة ومكانتها","t":"السنة الشريفة الأصل الثاني من أصول التشريع؛ وهي كل ما صدر عن النبي ﷺ من قول وفعل وتقرير وصفة خِلقية أو خُلقية. ومكانتها: تفسير مجمل القرآن وتفصيله وتخصيص عامه وتقييد مطلقه، كما بينت كيفيات العبادات: \"صَلُّوا كما رأيتموني أصلي\". لا يفهم الإسلام كاملاً إلا بجمع الكتاب والسنة."},{"h":"منهج تلقي السنة وتصنيفاتها","t":"تُقبل الأحاديث على حسب أصول الجرح والتعديل: الصحيح (ثقة رواة متصل سنده بلا شذوذ ولا علة)، الحسن، الضعيف الذي لا يُعمل به في العقائد والأحكام إلا بشروط عند بعض. كتب أهل السنة: الصحيحان (البخاري ومسلم) ثم السنن (أبو داود والنسائي والترمذي وابن ماجة) والمسانيد كمسند أحمد."},{"h":"أحاديث العبادات في السنة","t":"وردت السنة بكثير من أحاديث العبادات: \"إنما الأعمال بالنيات\"، \"بني الإسلام على خمس\" بيان لأركانه، \"لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ\"، وأدعية وأذكار وأوراد على مدار اليوم. هذه الأحاديث مرآة تطبيق عملي للنص النبوي في الطهارة والصلاة والصيام والزكاة والحج."},{"h":"حديث بني الإسلام على خمس","t":"الحديث جامع: \"بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت من استطاع إليه سبيلاً\". هو مفتاح الفقه ذكر الأركان، وتفصيل كيفيتها وتحديد شروطها ومواقيتها في السنة النبوية العملية."},{"h":"أهمية العمل بسنة النبي في العبادة","t":"العبادات توقيفية؛ فما يشرع فيها يُقبل به من الكتاب والسنة، والمصدر بيان كيفية عبادة الله في هذه السنة العملية: مواقيت الصلاة، عدد ركعاتها، هيئة الطهارة والوضوء، وبقية التفاصيل. ومن هنا كان \"فقه السنة\" حفظاً للفهم النبوي ومدارسةً لفعل النبي ﷺ النقل."},{"h":"خلاصة الدرس","t":"السنة أصل ثانٍ تفسر القرآن وتفصل مجمله. تقسم آحاديثها: صحيح وحسن وضعيف. كتابا عمدتها: البخاري ومسلم. ولها أحاديث جامعة كالعمل بالنيات وبني الإسلام على خمس، ولابد من السنة العملية في كيفيات العبادات."}],"qs":[{"q":"الركن الثاني من أصول التشريع بعد القرآن الكريم هو:…","a":["السنة النبوية","الإجماع","القياس","عرف الناس"],"c":0,"d":"easy","hint":"الوحي غير المتلو","expl":"الصواب: السنة النبوية، فهي البيان والتفصيل لما جاء في القرآن، ثم يأتي بعدها الإجماع والقياس معتمدَيْن عليها. نصيحة: مصدران وحذف: قرآن + سنة، ثم الآراء الفقهية المبنية عليهما."},{"q":"قول النبي ﷺ \"إنما الأعمال بالنيات\" يدل على أن القبول بمرتبط بـ:…","a":["نية العمل الصالحة","كثرة العمل","سرعة الإنجاز","حسن المكان"],"c":0,"d":"easy","hint":"ميزان القبول عند الله","expl":"الصواب: النية الصالحة؛ فالعمل لا يقبل ولا يُجازى عليه إلا بحسنه. كثرة العمل وحده أو سرعته أو مكانه لا قيمة له بلا إخلاص. نصيحة: \"النية علة القبول\": ميزان الأعمال عند المولى في النيات لا في الصور."},{"q":"أحد الكتب المعتمدة في جمع السنة بعد الصحيحين هو:…","a":["سنن أبي داود","نهج البلاغة","فصوص الحكم","مقامات الحريري"],"c":0,"d":"medium","hint":"من كتب السنن الأربعة","expl":"الصواب: سنن أبي داود، وهي من السنة المعتمدة عند أهل السنة. باقي الخيارات كتب أدبية أو فلسفية ليست من دواوين الحديث. نصيحة: احفظ الستة: بخاري، مسلم، ترمذي، نسائي، أبو داود، ابن ماجة — فتجيب سريعاً عن كل أسئلة \"الدواوين\"."},{"q":"توجيه قوله ﷺ \"صلّوا كما رأيتموني أصلي\" إلى:…","a":["وجوب اتباع السنة في هيئة الصلاة","جواز الاجتهاد في كل صلاة","ترك الصلاة","الصلاة بلا وضوء"],"c":0,"d":"medium","hint":"رسم بيان عملي للصلاة","expl":"الصواب: وجوب اتباع السنة في كيفيات الصلاة، فرسول الله علم عملياً والحديث يعمم الحكم، وهو سند أصولية \"مخالفة السنة في العبادة بلا دليل مبطل\". الخيارات الأخرى تفريع خاطئ. نصيحة: \"الفقه العملي\" في أحاديث الصلاة: اعمل كما كان يعمل، شاهد ما شاهد."},{"q":"عبارة \"بني الإسلام على خمس\" تستخدم في الأحاديث بياناً لـ:…","a":["أركان الإسلام الخمسة","أركان الإيمان","شروط النية","سنن الوضوء"],"c":0,"d":"easy","hint":"بنى أركان الدين الخمسة","expl":"الصواب: أركان الإسلام الخمسة (شهادتان، صلاة، زكاة، صوم، حج). أركان الإيمان ستة وثمة قضية مختلفة، فلا يخلط بين البابين. نصيحة: \"الإسلام أبنيته خمسة\" و\"الإيمان أركانه ستة\"، جملتان تُعرفان نوعي الأسئلة."},{"q":"الحديث الصحيح يعرّف بأنه:…","a":["ما اتصل سنده بنقل العدل الضابط عن مثله بلا شذوذ ولا علة","ما ضعف رواته","ما ورد عن التابعين فقط","ما اشتهر عند الناس"],"c":0,"d":"medium","hint":"شروط القبول الأربعة","expl":"الصواب: ما اتصل سنده بالعدول الضابطين مع نفي الشذوذ والعلة، والتقسيم شرطه فيضاف العدالة والضبط والاتصال. الضعف ما يستبعد، والتابعون فقط لا يكفي للصحة، والاشتهار ليس دليلاً لدى النقاد. نصيحة: احفظ \"عدل ضابط متصل لا شذوذ ولا علة\" = صحيح؛ عند نقص شرط تنزل المرتبة."}]}]},{"title":"الفقه المقارن","icon":"⚖️","chapters":[{"title":"العبادات (فقه مقارن)","read":[{"h":"مفهوم الفقه المقارن","t":"الفقه المقارن بحث المسائل الفقهية في مذاهب أهل العلم (الشافعي، الحنفي، المالكي، الحنبلي وغيرها) وعرض أدلة كل مذهب وأوجه الترجيح والموازنة بينها؛ للوصول إلى الراجح دون تعصب. قيمته فهم المسائل فهماً عميقاً وقدرة عرض الأدلة والترجيح بما يوافق مصلحة المكلف وأصول الشرع."},{"h":"الطهارة والمياه","t":"أصل أركان الطهارة في العبادة: رفع الحدث عن البدن والثوب والمكان، بالماء الطاهر المطهر أو ما يقوم مقامه. يبحث الفقهاء: أقسام المياه (طهور، طاهر، نجس)، والوضوء والغسل والتيمم، وإزالة النجاسات. اختلفوا في بعض فروعها (كالماء المستعمل أو تغير طعم بعضه)، ودلل كل مذهبه، والمناسب مراعاة الحرج والتنظيف."},{"h":"الصلاة: شروطها وأركانها","t":"أركان الصلاة وواجباتها وسننها محل نظر مقارن؛ كفوات التكبير، قراءة الفاتحة (فرض عند الجمهور عند كل ركعة)، التشهد عند الشافعية والحنابلة مقابل الصلاة خلفها، التسليمة الأخيرة وسلام الإنصراف. فقه مقارن بضبط كل ركن مرتبط بالنص النبوي وكيفيات الأئمة، مع مراعاة قضاء الفائتة."},{"h":"الصيام والزكاة والحج في المذاهب","t":"يختلف الفقهاء في وجوه فرعية: قضاء رمضان عبر الأيام المتفرقة، كفارة الإفطار، زكاة الأنعام والنقدين وشروط النصاب والحول، ومواقيت الإحرام للحج والعمرة شوطه، ونقض نفس المؤمنين في تلبية العمل المأمور به. عرض الأدلة والنظر في أصل المصلحة هو جوهر البحث."},{"h":"أهلية العبادة وضوابطها","t":"العبادات ملتزم بها على أهلية التكليف: عقل وبلوغ، ومن سقط شرط لقدرة الاكتساب، كالمريض يفطر ويقضي، والمسافر يقصر، والمستطيع فقط يحج. من مبادئها يسّر المنهج: \"لا يكلف الله نفساً إلا وسعها\"، فكان الشرع من التيسير لا التطويع. ويقدم الفقه المقارن حلول المسائل المستجدة بضوابط الأصول."},{"h":"خلاصة الدرس","t":"الفقه المقارن يعرض مذاهب الأئمة وأدلتها للوصول إلى الراجح. في العبادات محل بحث: الطهارة والمياه، شروط الصلاة وأركانها، فروع الصيام والزكاة والحج، وأهلية التكليف. غايته التيسير على المكلف والضبط بأدلة الشرع."}],"qs":[{"q":"الفقه المقارن مبني على:…","a":["عرض مذاهب الأئمة وأدلتها والموازنة للوصول إلى الراجح","التمذهب لرأي محدد واحد فقط","رفض الحجج كلها","عدم معرفة أدلة الأئمة"],"c":0,"d":"medium","hint":"ما قيمة الدراسة المقارنة؟","expl":"الصواب: عرض المذاهب وأدلتها والموازنة بينها للوصول للراجح، فهذا التجمع يُخرج العقل من التعصب ويشرح المسائل. لو كان التمذهب فقط واحداً لانعدم المقارنة، ورفض الحجج ينافي طلب العلم. نصيحة: \"مقارنة = ميزان\": كل مذهب دليل، ودورك تقييم الأدلة لا الهجوم على المذاهب."},{"q":"من المياه التي يصح بها رفع الحدث الطهارة عند جمهور الفقهاء:…","a":["الماء الطهور الطاهر المطلق","الماء المتغير الطعم","ماء البحر والملح الشديد","مياه الصرف الصحي"],"c":0,"d":"easy","hint":"نوعية الماء النجس يرفع به","expl":"الصواب: الطهور الطاهر المطلق، الذي لم يتغير بشيء نجس، فبه يتحقق التطهير. تغير النجس يخرج الماء من الطهورية، وماء البحر والرطوبة المالحة مقبول إذا بقي على اطلاقه بشرط التغير غير المكتسب بطبيعته، والصرف نجس لا يرفع الحدث. نصيحة: معادلة الطهورية: \"ماء مطلق لم تُغيّره نجاسة = طهور\"."},{"q":"قراءة الفاتحة في كل ركعة:…","a":["ركن عند الجمهور (الشافعية والحنابلة) مذهبه يتطلبها في الصلاة","سنة مستحبة عند الجميع","محظورة عند جميع المذاهب","بدعة مقامة"],"c":0,"d":"hard","hint":"الخلاف المعروف في الفقه","expl":"الصواب: ركن عند الجمهور (الشافعية والحنابلة) في كل ركعة، لدليل \"لا صلاة لمن لم يقرأ بفاتحة الكتاب\"، بينما عند الحنفية والحنابلة في غيرها من مواضع معينة سنية للقراءة كالمأموم. فلا سنة محظورة ولا بدعة، بل نص عن الصلاة نفسها. نصيحة: الخلاف قولان مشهوران: فريضة عند الشافعية، ووجوب عند الحنفية في بعض الوجوه. اذكر كلا."},{"q":"حكم من سافر سفرًا مباحاً في رمضان واتفق الإمساك القصر:…","a":["يرخص له الفطر ويقضي الأيام بدل الفائتة","لا يُفطر أبداً","يصوم ولا يقضي","يفطر بلا قضاء إطلاقاً"],"c":0,"d":"medium","hint":"رخصة التيسير في السفر","expl":"الصواب: يرخص له الفطر لأن الله شرع للعذر؛ \"فمن كان مريضاً أو على سفر فعدة من أيام أخر\"، ويقضي إذا زال العذر عدد الأيام التي أفطرها. لا يلزم الصيام في العذر ولا الفطر بلا قضاء. نصيحة: قاعدة ظريفة: \"عذراً فأفطر، وقدرة فاقض\"؛ السفر والمريض مفتاح الرخصة."},{"q":"النصاب هو مقدار المال الذي إذا بلغه المزكي:…","a":["وجبت فيه الزكاة","حرم إخراج الزكاة","جازت للزكاة دون وجوب","سقطت الزكاة أبداً"],"c":0,"d":"easy","hint":"حد الوجوب المالي","expl":"الصواب: إذا بلغه أو تجاوزه وجبت الزكاة بشرط حول الحول، وهذا هو النصاب. دون ذلك لا زكاة، وهو شرط الوجوب لا تحريم وغيره. نصيحة: اربط \"النصاب\" بحد الوجوب، ثم أعد سؤال \"تعديته\" تلوح الوجوب."},{"q":"الاعتماد على مبدأ التيسير في الفقه يقصد به:…","a":["رفع الحرج ومراعاة الظروف مع عدم إلغاء النصوص","الهاوية في هدم الأحكام","فعل المحرمات بلا خوف","رفض النصوص كلها"],"c":0,"d":"easy","hint":"التيسير لا يعني التلاعب بالأحكام","expl":"الصواب: رفع الحرج ومراعاة عذر المكلف مع حفظ نصوص الشرع، فالتيسير فيزيل العذر، لا في الأحكام الثابتة. الهاوية والتساهل المحرم وتحليل ما حرم الله ليس من التيسير الشرعي. نصيحة: \"تيسير مع صور\": الرخصة تسع العذر، والحرمة تبقى حيث لا عذر."}]},{"title":"المعاملات (فقه مقارن)","read":[{"h":"المعاملات المالية وأصولها","t":"فقه المعاملات ينظم علاقات الناس في البيع والشراء والإجارة والشركة والضمان والأمانات. مبناها على: الإذن الشرعي، والتراضي، وخالية من الربا والغرر والجهالة الفادحة والميسر وما لا يملك منه. كل معاملة خلت عن محظور فالأصل فيها الإباحة، وكل ما كان جباية بالباطل أو حراماً في عينه مردود."},{"h":"البيع: أركانه وشروطه","t":"البيع عقد يعتمد على: عاقدين (بائع ومشتر) أهل للتصرف، وصيغة (إيجاب وقبول)، ومعقود عليه (ثمن ومثمن). شروط العقد المقارنة كالملكية والقدرة على التسليم وكون السلعة معلومة ومنفعة مباحة، وخلوها من الغرر المحرم والربا. يبحث الفقهاء في مجازه كبيع السلم والتقسيط ووجوه جديدة خلافاً لبعضها."},{"h":"الربا والغرر والمحرمات","t":"حرم الشرع الربا: ربا القرض (زيادة قدرها مشروطة في القرض) وربا الفضل (تفاضل في الأشياء الربوية)، لقول الحديث \"فما زاد فهو ربا\". وحرم الغرر (جهالة في العقد)، والميسر (القمار)، وبيع المحرمات كالخمر. ويرى الفقهاء تحريم صور التمويل الربوية وبهذا حاجة في تأسيس البدائل المباحة كالمرابحة المشروعة بضوابط."},{"h":"عقود الإجارة والشركة والوكالة","t":"الإجارة بيع منفعة معلومة بمعلوم قدرها مقابل عوض، كاستئجار أرض أو خدمات. الشركة عقد تعاون بين اثنين أو أكثر في مال أو عمل؛ قسمها فقهاء: شركة الأموال (مضاربة)، والأعمال (الأبدان)، والوجوه، بضوابط كون الربح والخسارة بحصة المال أو العمل المتفق عليه. الوكالة إنابة تدبير بقبول موكل."},{"h":"فقه المعاملات المستجدة","t":"المسائل المعاصرة كالبيع الآجل والتقسيط، والعملات الرقمية، والتأمين التعاوني مقابل التجاري، والتداول بالأسهم، يخرج فيها الفقهاء أحكامهم بالقياس على أصول المذاهب مع نظر المقاصد. القواعد الحاكمة: قاعدة \"الدرر يزال\"، و\"الأصل الإباحة في المعاملات\"، و\"لا ضرر ولا ضرار\" إذا ثبت الواجب به."},{"h":"خلاصة الدرس","t":"المعاملات مبناها التراضي والشروع خالية من ربا وغرر وجهالة وميسر. البيع أركان وعاقد وصيغة، والإجارة والشركة والوكالة عقود منظمة. المستجدات تقاس على الأصول بنظر المقاصد وقاعدة الرفع: إباحة الأصل، ورفع الضرر."}],"qs":[{"q":"الأصل في المعاملات المالية عند الشريعة الإسلامية:…","a":["الإباحة ما لم يرد دليل تحريم","التحريم حتى يجوز الدليل","الحظر التام دائماً","الإهمال الكامل"],"c":0,"d":"easy","hint":"القاعدة الأصولية في أبواب العقود","expl":"الصواب: الإباحة ما لم يوجد دليل على تحريم، فهكذا شرع المعاملات: الأصل الحل إلا لنص. عكس ذلك يخالف نصوص إباحة البيع وغيرها. نصيحة: استظهر: \"المعاملات حلال الأساس، والرقبة محرمة بالأدلة\"، ولا تعكس قواعد العبادة."},{"q":"أركان عقد البيع عند جمهور الفقهاء:…","a":["عاقدان وصيغة ومعقود عليه","البائع فقط","المشتري فقط","المكان فقط"],"c":0,"d":"medium","hint":"أركان أي عقد تبادلي","expl":"الصواب: عاقدان (بائع ومشتر)، صيغة (إيجاب وقبول)، معقود عليه (ثمن ومثمن)، فهذه الكل المطلوب لإتمام البيع بوجودها. اقتصار العقد على طرف واحد أو مكان وحده لا يكون بيعاً. نصيحة: \"عاقدان + صيغة + عين\" اجعلها ثلاث كلمات فقط لبناء أي عقد."},{"q":"ربا الفضل يتعلق بـ:…","a":["تفاضل في عوض صنف ربوي واحد عند اتحاده بالجنس","زيادة مؤجلة في القرض","ربح بيع السلم","أجور الإجارة"],"c":0,"d":"medium","hint":"بيع متماثلات بالأصناف الربوية","expl":"الصواب: التفاضل في بيع صنف محدد ربوي (كذهب بذهب، بر ببر) مع اشتراط التقابض في المجلس، فلا يُزاد فيه شيء. هذا تعريف ربا الفضل عند المذاهب، بينما الزيادة المؤجلة في القرض ربا النسيئة/القرض. نصيحة: \"ربا الفضل = زيادة في الكمية، وربا النسيئة = تأجيل زائد\"، أدّ المربطين في الذاكرة."},{"q":"الغرر المحرم في البيوع هو:…","a":["الجهالة الفاحشة في العوض أو العين التي تفضي للنزاع","جهالة يسيرة تعفو بها التعامل","الحذر في السوق","البيع وقت الصلاة"],"c":0,"d":"medium","hint":"جهالة تؤدي إلى الخصومة","expl":"الصواب: الجهالة الفاحشة في الثمن أو المبيع التي تورث النزاع، كبيع ما لا يملكه البائع أو بيع الغائب المجهول. الجهالة اليسيرة التي يعفو عنها العرف ليست محرمة، والحذر ليس غرراً. نصيحة: \"غرر = غفلة نازعة\": إذا كانت الجهالة تؤول للشجار القائم، اعتبره محرماً، وإلا فيفتقر للعرف."},{"q":"يُعرف عقد الإجارة في الفقه بأنه:…","a":["بيع منفعة معلومة بعوض معلوم لمدة معينة","بيع العين نفسها","قرض بلا عوض","هبة مطلقة"],"c":0,"d":"easy","hint":"استئجار الخدمات أو الأصول","expl":"الصواب: بيع منفعة معلومة بعوض معلوم مدة معلومة، كاستئجار بيت أو سيارة أو عامل. بيع العين يخص البيع، والقرض عقد آخر، والهبة تبرع. نصيحة: \"إجارة = إيداع المنفعة\": العين نفسها تبقى ملكاً والمستأجر يملكها الانتفاع."},{"q":"التأمين الذي يجيزه جمهور الفقهاء الحديثون بضوابط هو:…","a":["التعاوني الذي يقوم على المشاركة والبر بعيداً عن التعامل الربوي","التجاري الربحي على كل حال","القهري من المال العام فقط","التأمين لا يصح والجميع محرم"],"c":0,"d":"hard","hint":"التحقق من الصورة المباحة","expl":"الصواب: التأمين التعاوني القائم على التعاون والمواساة بآلية تدفع الخطر دون عقد ربوي ولا مقامرة، وهو الذي يتجه تجويزه ضمن ضوابط فتاوى هيئات معاصرة، بينما التجاري الذي يُمثل مقامرة وربحاً مضاربة في أبواب أكثر المضاربة ممنوع عند أغلب اللجان. نصيحة: أي سؤال مستجدد: ابحث عن صورة \"تعاوني نقي بلا ربا ولا غرر\" تتناسب مع الأصول، ولا تحكم على عامة."}]}]}]},{"id":"arabic_azhar","name":"اللغة العربية الأزهرية","icon":"📝","color":"#FF9800","books":[{"title":"النحو والصرف المتقدم","icon":"✒️","chapters":[{"title":"المرفوعات","read":[{"h":"المبتدأ والخبر","t":"المبتدأ اسم مرفوع صريح في أول الجملة للابتداء، والخبر هو المتمم الذي ينهي فائدته: الجملة الاسمية = مبتدأ + خبر. مبتدأ مثل: \"العلمُ نورٌ\". الخبر أنواع: مفرد (نورٌ)، جملة اسمية (أخلاقُهُ حسنةٌ، يوجد رابط)، جملة فعلية (زيدٌ قام أبوه)، شبه جملة (الكتابُ في الحقيبة). علامات الإعراب: ضمة ظاهرة أو مقدرة."},{"h":"الفاعل ونائبه","t":"الفاعل اسم مرفوع يأتي بعد فعل مبني للمعلوم للدلالة على من قام بالفعل أو اتصف به: \"نجحَ الطالبُ\"، وقد يكون ضميراً مستتراً أو بارزاً، مؤولاً بالمصدر: \"يَسُرُّني أن تجتهد\". نائب الفاعل: اسم مرفوع يحل محل الفاعل المحذوف عند البناء للمجهول، وكان قبله مفعول به: \"كُتبَ الدرسُ\"."},{"h":"النواسخ: كان وأخواتها وإنّ وأخواتها","t":"كان وأخواتها: تفيد الحدوث والثبوت (كان، صار، أصبح، أضحى، ظل، بات، ليس، ما زال، ما دام...). ترفع المبتدأ اسمها، وينصب الخبر. إنّ وأخواتها: (إنّ، أنّ، كأن، لكن، ليت، لعلّ) تنصب الاسم وترفع الخبر. مثال: (كان الجوُّ جميلاً) قياساً: (إنّ الجوَّ جميلٌ)."},{"h":"أدوات المرفوعات والخبر والتابع","t":"والمرفوعات تشمل: الفاعل، نائب الفاعل، المبتدأ، خبر المبتدأ، اسم كان، خبرها مفعولاً منصوباً في الظاهر، اسم \"ما\" الحجازية وخبرها. التابع المرفوع: النعت والبدل والعطف والتوكيد. علامة الرفع: الضمة وما ناب عنها (الواو في جمع المذكر السالم، والألف في المثنى، والثبوت في الفعل المضارع المعتل الآخر نقدمه)."},{"h":"أمثلة تحليلية","t":"{\"المؤمنونَ أبناءُ بعضهم لبعض\": المبتدأ مرفوع بالواو لِجمع المذكر السالم، والخبر مرفوع بالضمة. في {\"العاملُ نجحَ\"}: فاعل مرفوع ضمّة. وأما {\"إنّ العلمَ نور\": اسم إن منصوب بالفتحة، وخبرها مرفوع. كل مثال يحل نفسه بدقة تسمح بالمرور على كل النظريات."},{"h":"خلاصة الدرس","t":"المرفوعات: مبتدأ وخبر وفاعل ونائبه واسم النواسخ والخبر بعدها، والتابع المرفوع. علاماتها: الضمة والواو والألف. النواسخ: كان ترفع الاسم وتنصب الخبر، وإن تنصب الاسم وترفع الخبر. اعرف هذه القواعد ترسم الإعراب بلا تردد."}],"qs":[{"q":"الجملة (العلمُ نورٌ) إعراب (نورٌ):…","a":["خبر مرفوع بالضمة","مبتدأ مرفوع","فاعل مرفوع","مفعول به منصوب"],"c":0,"d":"easy","hint":"المتمم للجملة الاسمية","expl":"الصواب: خبر مرفوع بالضمة الظاهرة، لأن الجملة اسمية مبتدأها العلمُ وخبرها نورٌ. \"مبتدأ\" إنكار بعد \"العلمُ\" أول الجملة، والفاعل فعل جملة، والمفعول منصوب. نصيحة: تحقق أولاً من بداية الجملة فهي تملي عليك نوعها وركنيها."},{"q":"في جملة (إنّ المعلمَ مخلصٌ) إعراب (المعلمَ):…","a":["اسم إنّ منصوب بالفتحة","خبر إنّ مرفوع","مبتدأ مرفوع","فاعل منصوب"],"c":0,"d":"medium","hint":"إنّ وأخواتها تنصب الاسم","expl":"الصواب: اسم إنّ منصوب بالفتحة، لأن \"إنَّ\" من النواسخ الناصبة للاسم. أما الخبر مرفوع (مخلصٌ)، فهذا الاسم سلوكه مختلف عن قواعد المبتدأ. نصيحة: \"إنّ نصبت والاسم ورفعت الخبر\": احفظ الاتجاهين في سطر واحد، ويكفيك الحسم."},{"q":"عند بناء جملة (كتبَ خالدٌ الدرسَ) للمجهول تصبح:…","a":["كُتبَ الدرسُ (نائب فاعل مرفوع)","كُتب الدرسُ","كتب خالد الدرسُ","كُتب خالدٌ"],"c":0,"d":"medium","hint":"المفعول به يحل محل الفاعل المحذوف","expl":"الصواب: كُتبَ الدرسُ، فيحذف الفاعل (خالد) ويصبح المفعول به (الدرس) نائب فاعل مرفوعاً بالضمة. الخيارات التي تبقى صيغ المعلوم أو تجعل خالد نائباً خاطئة. نصيحة: القاعدة: \"حذف الفاعل، فاقبل المفعول به مكانه مرفوعاً\"، ولا نعتمد سوى هذا الترتيب."},{"q":"المثال الذي يحتوي فاعلاً ضميراً مستتراً هو:…","a":["اجتهدْ في دراستك","عملُ الولدِ الصالحُ","الكتابُ مفيدٌ","مررتُ بمحمدٍ"],"c":0,"d":"hard","hint":"فاعل مخفي تقديره أنت","expl":"الصواب: \"اجتهدْ\" فعل أمر فاعله مستتر تقديره أنت، فلا يظهر في اللفظ. بقية الخيارات فيها اسم ظاهر أو جملة لا فعل فيها، ولا فاعل مستتر بذلك. نصيحة: الأفعال والأوامر لا فاعل ظاهر لها في كثير من الأحوال، فتسأل: من الفاعل؟ فيستتر تقدير."},{"q":"علامة رفع جمع المذكر السالم هي:…","a":["الواو","الضمة","الفتحة","الكسر"],"c":0,"d":"easy","hint":"علامة فرعية تدل على الرفع","expl":"الصواب: الواو (مثل المؤمنونَ)، فجمع المذكر السالم يرفع بالواو نيابة عن الضمة. الضمة للمفرد، والفتحة نصب، والكسرة جر. نصيحة: \"الجمع المذكر السالم مرفوع بالواو\" ثلاثياً محفوظاً: عروج المذكر بواو."},{"q":"من النواسخ التي ترفع المبتدأ وتنصب الخبر كلمة:…","a":["صار","إنّ","ليت","كأنّ"],"c":0,"d":"medium","hint":"أخوات \"كان\" رافعات للاسم","expl":"الصواب: \"صار\" من أخوات كان فترفع المبتدأ وتنصب الخبر (صار الجوُّ جميلاً). أما إنّ وليت وكأنّ فمن النواسخ الناصبة للاسم. نصيحة: قسّم نواسخ النصب: \"كانية ترفع الاسم، وأنّية تنصبه\"؛ لذلك تفرّق بسرعة."}]},{"title":"المنصوبات","read":[{"h":"المنصوبات في الجملة","t":"من الأسماء المنصوبة: المفعول به، المفعول المطلق، المفعول لأجله، المفعول فيه (الظرف)، المفعول معه، الحال، التمييز، المستثنى، المنادى، وخبر كان، واسم إن مقعراً: فهي دائرة واسعة تدور حول فعل الجملة وتوابعها."},{"h":"المفعول به والمطلق","t":"المفعول به ما وقع عليه الفعل: \"قرأَ الطالبُ الكتابَ\". المفعول المطلق مصدر من لفظ الفعل يؤكد معناه أو يبين نوعه أو عدده: \"ضربت ضرباً شديداً\"، أو \"ضربت ثلاث ضربات\". لا يتعلق بحرف جر، وناصبه هو المصدر المذكور أو مؤول فحسب."},{"h":"المفعول لأجله والمفعول معه","t":"المفعول لأجله: مصدر قلبي يبين سبب الفعل: \"وقفتُ احتراماً لمعلمي\". شرطه أن يكون مصدراً (ليس عيناً)، ذا سبب للفعل (تعليل)، مع مشاركة الفعل في الزمنية. المفعول معه: اسم منصوب بعد واو بمعنى \"مع\" تدل على المصاحبة: \"جاءَ عليٌّ والكتابَ\"، أي مع الكتاب، ويشترط ألا تسبقه جملة للفعل نفسه."},{"h":"الحال والتمييز","t":"الحال: اسم نكرة منصوب يبين هيئة صاحبه حال وقوع الفعل، جواباً لكيف: \"جاءَ اللاعبُ مسرعاً\"، وصاحبه غالباً معرفة. التمييز: اسم نكرة منصوب يزيل إبهام ما قبله من كمية أو مساحة: \"اشتريتُ كيلوًّا تفاحاً\"، أو نسبة: \"للرجلِ عندي دَينٌ قرشاً\". الحال تعدد مقدمات إعرابية مختلفة، لكن يميز بينهما بجواب السؤال."},{"h":"الظروف والمستثنى والمنادى","t":"المفعول فيه (الظرف): اسم منصوب يبين مكان وقوع الفعل (فوق، تحت، أمام) أو زمانه (صباحاً، ليلاً). المستثنى يخضع لأحكام الاستثناء: النصب عند تمام الكلام موجب (جاء القوم إلا زيداً)، والبدل أو النصب على الاستثناء عند القلة. المنادى: اسم منصوب بعد حرف النداء (يا، أي، أيا) مثل: يا طالبَ العلمِ اقبل."},{"h":"خلاصة الدرس","t":"المنصوبات: مفعول به (وقع عليه الفعل)، مفعول مطلق (مصدر مؤكد)، مفعول لأجله (سبب قلبي)، مفعول معه (وابو مع)، مفعول فيه (ظرف مكان/زمان)، حال (هيئة)، تمييز (إزالة إبهام)، مستثنى، منادى. تعرفها بأسئلة: أين؟ كيف؟ متى؟ ونوع المصدر. هذه خارطة الأبواب."}],"qs":[{"q":"في جملة (قرأَ الطالبُ الكتابَ) كلمة (الكتابَ):…","a":["مفعول به منصوب","فاعل مرفوع","حال منصوب","تمييز منصوب"],"c":0,"d":"easy","hint":"الذي وقع عليه أثر الفعل","expl":"الصواب: مفعول به منصوب، لأنه الشيء الذي وقع عليه فعل القراءة. الفاعل هو الطالب، والحال والتمييز لا تمثيل لهما هنا. نصيحة: اسأل \"ماذا قرأ؟\" فتحصل على المفعول به فوراً."},{"q":"المفعول المطلق في (أجتهدتُ اجتهاداً) يعد:…","a":["مؤكداً لمعنى الفعل","بياناً لنوعه","بياناً لعدده","جاراً لمعناه"],"c":0,"d":"medium","hint":"نفس لفظ الفعل بلا قيد","expl":"الصواب: يؤكد معنى الفعل لأنه مصدر من لفظه دون إضافة وصف أو عدد. لو قلت \"اجتهاداً شديداً\" فبنوعه، و\"اجتهدتُ اجتهادين\" فبعدده. نصيحة: فحص سريع: مصدر تليد بلا وصف ولا عدد = تأكيد؛ النوع فيه وصف، والعدد رقم يتلو الكلمة."},{"q":"(وقفتُ احتراماً لمعلمي) كلمة (احتراماً) تعرب:…","a":["مفعولاً لأجله","مفعولاً معه","حالاً","تمييزاً"],"c":0,"d":"medium","hint":"مصدر قلبي يعلل سبب الفعل","expl":"الصواب: مفعول لأجله، لأنه مصدر (احترام) ورد لبيان سبب الفعل (لماذا وقفت؟ احتراماً). ليس مفعولاً معه لعدم الواو، ولا حالاً ولا تمييزاً بحكم دلالته. نصيحة: \"لماذا وقفت؟\" يعطيك المفعول لأجله: مصدر قلبي معللاً للفعل."},{"q":"جاء الجنديُّ منتصراً. كلمة (منتصراً) هي:…","a":["حال من صاحبها وتبين هيئته","تمييز","مفعول مطلق","نعت منصوب"],"c":0,"d":"medium","hint":"جواب سؤال \"كيف جاء؟\"","expl":"الصواب: حال منصوب يبين هيئة الجندي وقت مجيئه (منتصراً)، ويسأل عنه بكيف. التمييز لا يجيب عن كيف هنا، والمفعول المطلق من لفظ الفعل. نصيحة: (كيف جاء؟) = حال؛ (ماذا؟) = مفعول به؛ (كم/ما قيمة؟) = تمييز."},{"q":"المفعول فيه (الظرف) في جملة (سافرتُ صباحاً) يدل على:…","a":["الزمان الذي وقع فيه الفعل","المكان المتسع","السبب","التوكيد"],"c":0,"d":"easy","hint":"ظرف الزمان","expl":"الصواب: الزمان، فإن \"صباحاً\" ظرف زمان منصوب يحدد وقت وقوع السفر. لو قيل (سافرت أمام المسجد) لكان مكاناً. نصيحة: الظروف قسمان: زمان (سؤال متى) ومكان (سؤال أين)؛ اسأل نفسه واحدة تميزها."},{"q":"في (اشتريتُ كيلوًّا تفاحاً) كلمة (تفاحاً) تعرب:…","a":["تمييزاً منصوباً","مفعولاً به","نعتاً","عطفاً بيانياً"],"c":0,"d":"hard","hint":"يزيل إبهام الكيلو وكثرة مفردة","expl":"الصواب: تمييز منصوب؛ يوضح جنس الكمية المبهمة (كيلو) فتقول \"من ماذا؟ تفاحاً؟\" والصلاح في هذه الحالة من إبهام الصفة. لا مفعول به لأن الكيلو هو المفعول، ولا نعت ولا عطف. نصيحة: \"كمية غامضة بعدها مبين\" = تمييز: قم بطرح سؤال \"من ماذا\" لتراه يطفو."}]},{"title":"المجرورات والتوابع","read":[{"h":"المجرورات: بحرف الجر والمضاف إليه","t":"ينقسم الاسم المجرور إلى نوعين: مجرور بحرف جر (من، إلى، عن، على، في، الباء، اللام، الكاف، حتى، مذ، منذ)، ومضاف إليه كلمة تجر ما بعده: \"كتابُ الطالبِ\"، يجوز بمضاف إليه كإضافة ملكية أو بيانية، وقس بحسب موجود في المضاف إليه أو اختياري، ويكون إعرابه الجر بالكسرة أو الياء."},{"h":"إعراب الجر وعلاماته","t":"العلامات: الكسرة الظاهرة للاسم المفرد وجمع التكسير، والياء في المثنى وجمع المذكر السالم، والفتحة نيابة عن الكسرة في الاسم الممنوع من الصرف، باستثناء أن المضاف إليه لا تسقط الفتحة بل الجر بالفتحة. مثال: \"سجنتُ في دورٍ كبيرة\": الكسرة في \"دور\" لأنها جمع تكسير."},{"h":"التوابع: النعت","t":"النعت (الصفة) يتبع منعوته في: الرفع والنصب والجر، والتعريف والتنكير، والإفراد والتثنية والجمع، والتذكير والتأنيث: \"جاء الطالبُ المجتهدُ\". وقد يكون النعت جملة أو شبه جملة: \"مررتُ برجلٍ حسنٍ خلقه\" (جملة اسمية في محل جر). وظيفته تخصيص الموصوف أو توضيحه أو مدحه أو ذمه."},{"h":"التوابع: العطف والبدل والتوكيد","t":"العطف: تابع يفصل بينه وبين متبوعه حرف عطف (الواو، الفاء، ثم، أو، أم...): \"جاءَ عليٌّ وزيدٌ\" ويتبع في الحالة الإعرابية. البدل: يسمّى مبدلا ومبدلا منه وغالباً بدل كل من كل أو بدل اشتمال أو بدل بعض من كل: \"جاءَ أخوكَ سعيدٌ\". التوكيد لفظي (بتكرار اللفظ) ومعنوي (نفس، عين، كل، كلا، كلتا، أجمع): \"جاء الرجلُ نفسُهُ\"."},{"h":"أمثلة على جميع التوابع","t":"{\"الناجحُ الناجحُ فاز\": تكرار لفظي=توكيد. \"أعجبني الطالبُ المجتهدُ\": النعت. \"جاء زيدٌ وعمرو\": عطف. \"فهمتُ القاعدةَ نصفَها\": بدل بعض من كل. كل تابع يتبع متبوعه في الحكم، فهذا هو التعريف الجامع للتوابع: التابع الحكم الإعرابي التالي صاحبه بلا واسطة."},{"h":"خلاصة الدرس","t":"المجرور: بحرف جر وبالإضافة، وعلاماته كسرة أو ياء بإدارة المثنى والجمع، وفتحة للممنوع من الصرف. التوابع خمسة: نعت وعطف وتوكيد وبدل، وكلها تتبع متبوعها في الإعراب. تفهمها بسؤال: \"هل يتبع الحكم ما قبله؟\"."}],"qs":[{"q":"في (كتابُ الطالبِ) كلمة (الطالبِ) مجرورة بـ:…","a":["الإضافة (مضاف إليه)","حرف الجر","الظرف","العطف"],"c":0,"d":"easy","hint":"تأتي بعد اسم آخر وتكسبه تعريفاً أو تخصيصاً","expl":"الصواب: مضاف إليه مجرور بالإضافة؛ إذ أضيفت كتاب إلى الطالب. حرف الجر يتقدم الاسم بـ\"من/في/الباء\"، والظرف والعطف لا يجران. نصيحة: إذا رأيت اسمين متتاليين ثانيهما مكسور غالباً فالأول مضاف والثاني مضاف إليه؛ بهذه يصبح الجر بلا سؤال."},{"q":"علامة جر جمع المذكر السالم هي:…","a":["الياء","الكسرة","الفتحة","الضمة"],"c":0,"d":"easy","hint":"علامة فرعية في مواضع النصب والجر","expl":"الصواب: الياء نيابة عن الكسرة في حالتي الجر والنصب: (مررتُ بالمهندسينَ). الضمة للرفع والكسرة للمفرد. نصيحة: خريطة جمع المذكر السالم: واو رفعاً، ياء جراً ونصباً؛ من هذه نقطة الاختراق اسعفك زمن."},{"q":"أي الجمل الآتية فيها نعت صريح:…","a":["جاءَ الطالبُ المجتهدُ","جاءَ الطالبُ وشكرَ","إنّ الطالبَ نجحَ","جاءَ الطالبُ نفسُهُ"],"c":0,"d":"medium","hint":"الصفة التابعة للموصوف","expl":"الصواب: \"المجتهدُ\" نعت صريح يصف الطالب ويتبعه في الرفع. \"نفسه\" توكيد معنوي، والواو والشكر عطف مستقل. نصيحة: النعت \"وصف واضح\" وفي شك يسأل نفسه: هل هذه صفة؟ فإذا نعم فتأكيد للوصف وأخسرها في التابع."},{"q":"في (فهمتُ الدرسَ نصفَهُ) كلمة (نصفَهُ):…","a":["بدل بعض من كل منصوب","نعت منصوب","عطف بيان","مفعول مطلق"],"c":0,"d":"hard","hint":"جزء يتبع الكل ويوضحه","expl":"الصواب: بدل بعض من كل؛ فالدرس كلٌّ والنصف بعض يشتمل عليه، وحكم التبعية يمنع النعت (لا وصفاً) والعطف (لا عاطفة) والمفعول المطلق (لا مصدراً). نصيحة: \"بعض كل = بدل\": بدائل شائعة: الصفة والموصوف. فإذا كان ثانيه جزءاً من الأول فهو بدل بعض من كل."},{"q":"التوكيد في (جاءَ المؤمنونَ كلُّهم) هو:…","a":["توكيد معنوي (كلّ + ضمير)","توكيد لفظي","نعت","بدل"],"c":0,"d":"medium","hint":"ألفاظ: نفس، عين، كل، جميع","expl":"الصواب: توكيد معنوي بـ\"كلّهم\" التي تشمل الأفراد وتقرر شمول الحكم، بينما التوكيد اللفظي بتكرار الكلمة. لا نعت ولا بدل هنا لأنها من أدوات التوكيد المجردة. نصيحة: احفظ ألفاظ التوكيد المعنوي الستة: نفس، عين، كل، جميع، كلا، كلتا؛ إذا رأيتها مع متبوعها فالتوكيد المعنوي."},{"q":"كلمة مجرورة بالفتحة نيابة عن الكسرة تظهر في:…","a":["الاسم الممنوع من الصرف غير المضاف ولا المنون","الاسم المفرد العادي","جمع المذكر السالم","المضاف إليه النكرة"],"c":0,"d":"hard","hint":"اسم لا يقبل التنوين ويجر بالفتحة","expl":"الصواب: الممنوع من الصرف يُجر بالفتحة نيابة عن الكسرة ما لم يضف أو تعريف بأل: (مررتُ بإبراهيمَ)، أما الأسماء الباقية عواملها الأصلية. نصيحة: شروط الجر بالفتحة: \"ممنوع من الصرف وغير مضاف وغير المعرف بأل\" — ثلاثية التحكم تُقال بضغط واحد."}]},{"title":"الصرف: الاشتقاق والميزان","read":[{"h":"الميزان الصرفي","t":"الميزان الصرفي نظام لتقويم الكلمات يبنى على الجذر الثلاثي: فـَـعـَـل، تقاس به الكلمات لأنواع الزيادة. الحروف الثلاثة الأصلية تقابل (ف، ع، ل) وتنطق الحروف الزائدة بإضافتها بحرف من أحرف الزيادة (سألتمونيها أو نحوها). مثال: كلمة (كِتَاب): عينها الميزان فِعال، و(مكتبة) مفعلة، وهكذا يعرف الميزان أصلي الكلمة من زائدها."},{"h":"أحرف الزيادة","t":"أحرف الزيادة مجموعة في جملة: \"سألتمونيها\" أو (س أ ل ت م و ن ي ه)؛ فكل حرف فيها يجوز زيادته في كلمات، وما سواه أصل. إذا جمعها صاحب العلم علم بمقدور كل صيغة، فبالميزان تميز الأصيل من الزائد ووظيفته الصيغية."},{"h":"الاشتقاق أوزانه","t":"الاشتقاق نوعان: صغير وهو أخذ فرع من أصل (فعل، فاعل، مفعول، فعيل، فُعولة...) ككتب وكاتب ومكتوب وكتابة، وكبير بنقل الحروف المغايرة. من أشهر الصيغ: اسم الفاعل (فاعل/مفعل)، واسم المفعول (مفعول)، والصفة المشبهة (فعيل/فعول)، واسم التفضيل (أفعل)، واسما الزمان والمكان (مفعل/مفعلة)، واسم الآلة (مفعال/مفعلة/فعالة)."},{"h":"التصغير والنسب والجمع","t":"المصغَّر: اسم يدل على التصغير بضم أوله وفتح ثانيه وإضافة ياء ساكنة بعد ثانيه: (كتب → كُتَيب). النسبة: يلحق آخر الكلمة ياء مشددة تكسر ما قبلها: (مصر → مصريّ). الجمع: جمع تكسير يغيّر بناء مفرده: (كتاب → كتب)، وجمع المذكر السالم بالواو أو الياء، والمؤنث السالم بالألف والتاء. ضبط كل نوع بقواعد ميزانه."},{"h":"المجرد والمزيد والعلم بالطرق","t":"الفعل المجرد الثلاثي والرباعي دون حروف زائدة، والمزيد ما زيد فيه حرف أو حرفان أو ثلاثة بأوزان معروفة: فَعَّل، فاعلَ، أفعَل، تفعَّل، تفاعل، افترعل، استفعل، افتعل وانفعل... كل منها له دلالة صوتية: التضعيف للتكثير، وأفعل للجعل، واستفعل للطلب، وتفاعل للاشتراك، فهذه الدلالات تفتح معنى الكلمة الجديدة."},{"h":"خلاصة الدرس","t":"الميزان الصرفي \"فعل\" أساس النقد: أعرف أصلي الكلمة من زائدها. أحرف الزيادة (سألتمونيها). الاشتقاق: فاعل، مفعول، فعيل، أفعل، مفعلة... التصغير والنسب والجمع أوزان لها. المجرد والمزيد بأوزان ودلالات (تكثير، جعل، طلب، اشتراك). الميزون تعلمه فتقبل أبواب الصرف كلها."}],"qs":[{"q":"ميزان كلمة (مَكاتِب) على الترتيب:…","a":["مفاعل","مفعل","فعال","فاعول"],"c":0,"d":"medium","hint":"أصلها \"كتب\" بحذف التاء الزائدة والكسر","expl":"الصواب: مفاعل، فالكلمة تحكمها (مَكاتِب): ميم زائدة، والكاف فاء، والتاء عين، والباء لام. الأصول الثلاثة (ك ت ب) بأوزانها الكتابة الميزانية. لو كانت \"مكتوب\" فمفعل. نصيحة: أخرج الجذر أولاً (ك ت ب) ثم راقب السوابق واللواحق: فتجد الميزان بسهولة."},{"q":"حروف الزيادة مجموعة في جملة…:","a":["سألتمونيها","فعلٌ بلا زوائد","الضاد والظاء","الباء والتاء فقط"],"c":0,"d":"easy","hint":"جملة تلاميذ من كنوز الصرف","expl":"الصواب: \"سألتمونيها\" مجموعة أحرف الزيادة (سا-أل-تمو-ني-ها)، وكلها تحتمل الزيادة في الكلم، وما عداها أصل. \"فعل بلا زوائد\" ليس جملة الأحرف، والبقية خاطئة. نصيحة: احفظ \"سألتمونيها\" كأنما تسأل الحروف أن تدخل الكلمة فتزيدها."},{"q":"اسم الفاعل من الفعل الثلاثي (كتب) هو:…","a":["كاتب","مكتوب","كتاب","كتبة"],"c":0,"d":"easy","hint":"وزنه فاعل","expl":"الصواب: كاتب، فقد أخذ وزن فاعل الدال على من قام بالفعل. مكتوب اسم مفعول، وكتاب مصدر واسم، وكبتة جمع. نصيحة: صيغة \"فاعل\" = فاعل بمعنى قام بالفعل، مثل: كاتب، قائل، عامل. احفظها تخرج أي اسم فاعل."},{"q":"المصغّر من كلمة (قلم) هو:…","a":["قُلَيم","قلاّم","قلميّ","أقلام"],"c":0,"d":"easy","hint":"تصغير: ضم الأول، فتح الثاني، ياء ساكنة بعد الثاني","expl":"الصواب: قلَيم؛ الصيغة: ضم القاف، فتح اللام، ياء ساكنة بعد الثاني (قُلَيم)، وهذا التصغير. قلام (اسم آلة)، وأقلام جمع، وقُلَيْمي نسبة. نصيحة: \"قُ لَ يْ م\" هي قاعدة التصغير: انظر ترتيب (ضُم، افتح، أَدخل ياء) وهكذا."},{"q":"وزن (استفعل) يدل على:…","a":["الطلب (استغفر: طلب الغفران)","الاشتراك بين اثنين","التحول الذاتي","التكثير المستبد"],"c":0,"d":"hard","hint":"مفهوم \"طلب الفعل\"","expl":"الصواب: الطلب؛ فاستفعل تفيد طلب حصول الفعل: استغفر=طلب الغفران، واستنصر=طلب النصر. الاشتراك لت و\"تفاعل\"، والتحول لانفعل أحياناً، والتكثير لفعّل. نصيحة: \"استفتني أيها الصرفي: استفع = طلب\"؛ مغزل الذاكرة: صاحب \"است\" يطلب الشيء دائماً."},{"q":"اسم المكان على وزن (مفعَل) مثل كلمة:…","a":["مكتب","مفكرة","مِفتاح","استقبال"],"c":0,"d":"medium","hint":"مكان الحدث بضم الميم","expl":"الصواب: مكتب، مكان الكتابة على وزن مَفعَل، وكذلك مفرش ومطلع. مِفكرة وزن (مفعلة) اسم مكان أيضاً لكن بالكسر، ومفتاح اسم آلة، واستقبال مصدر مزيد. نصيحة: \"مَفعَل مكان\" و\"مِفعال آلة\": مفتاح التمييز يكون غالباً بفتحة الميم أو السكنة للمكان والآلة."}]}]},{"title":"البلاغة العربية","icon":"🌸","chapters":[{"title":"علم المعاني: الخبر والإنشاء","read":[{"h":"مدخل علم المعاني","t":"علم المعاني دراسة الأحوال التي يلائمها الكلام لحال المخاطب والغرض من إبلاغه، فتراعي البلاغة مطابقة الكلام لمقتضى الحال. من مسائله: الإسناد، الخبر والإنشاء، الفصاحة، والقصر والوصف وإطالة الأحكام والتقديم والتأخير. المقال يُقاس بميزانه البلاغي: مناسبة القائل والمقام والمتلقي."},{"h":"الخبر وأغراضه","t":"الخبر كلام يحتمل الصدق والكذب لذاته، ويقصد منه إفادة المخاطب فائدة جديدة (فائدة الخبر)، أو تنزيله منزلة من لا يعلم (لازم الفائدة). أغراضه البلاغية متنوعة: التقرير والقبول، الثناء والمدح، الاسترحام، إظهار الضعف، التحسر، الفخر، الإنكار، التوبيخ. جاز حمل الكلام في صيغة الخبر ويقتضي العناية بحال المخاطب."},{"h":"الإنشاء وأقسامه","t":"الإنشاء كلام لا يحتمل تصديقاً ولا تكذيباً، وهو نوعان: إنشاء طلبي (طلب غير المستحيل وقوعه) بأدواته: أمر (افعلْ)، نهي (لا تفعل)، استفهام (هل/أ/ما؟)، التمني (ليت/هل؟)، النداء (يا/أيها)، النداء المتعدي (لعلّ في الترجي واستفهام في التعجب)؛ وإنشاء غير طلبي كالتعجب والمدح والذم والقسم وصيغ العقود."},{"h":"الأمر والنهي والاستفهام","t":"الأمر له أعني بلاغي غرض: التعجيز والإباحة والدعاء والإرشاد والإهانة والتوبيخ، ولفظه \"افعل\" ويدل بضعفه على الوجوب عند الإطلاق. النهي (لا تفعل) أغراضه: النصح والدعاء والقنوط. الاستفهام بأدواته (هل للتصديق، الهمزة للتقرير والإنكار والتعظيم) يحمل أغراضاً: التقرير، الإنكار، التعجب، التمني، التشويق، التهكم."},{"h":"تطبيقات على المطابقة","t":"عند تحليل نص، اسأل: هل الكلام خبر أم إنشاء؟ والخبر: هل فائدته إفادة أم لازم الفائدة؟ والأمر: هل الغرض الوجوب أم غرض بلاغي (الالتماس، الدعاء، التهديد)؟ والمطابقة = اختيار الصيغة المناسبة للمقام؛ فإن بالغت في الاستفهام إنكاراً مثلاً كان موافقاً لمقتضى الحال. البلاغة سرّ المطابقة، والنصوص المقدسة أعلى نماذجها."},{"h":"خلاصة الدرس","t":"الخبر يحتمل الصدق والكذب وله أغراض بيانية (فائدة الخبر، لازم الفائدة، الثناء، التوبيخ...). الإنشاء لا يحتمل التصديق، طلبي (أمر، نهي، استفهام، تمني، نداء، ترج) وغير طلبي. لكل أداة أغراضها. المطابقة بين الصيغة والمقام جوهر علم المعاني."}],"qs":[{"q":"الخبر في اللغة هو:…","a":["ما يحتمل الصدق والكذب لذاته","ما لا يحتمل الصدق والكذب","طلب المستحيل","تعجب فقط"],"c":0,"d":"easy","hint":"الجملة التقريرية الناقلة للمعلومات","expl":"الصواب: ما يحتمل الصدق والكذب لذاته؛ لأنه نسبة خبرية تتصف بالواقع أو فلا واقع لها. الإنشاء لا يحتمل التصديق، والاستفهام طلب، والتعجب إنشاء. نصيحة: \"القول خبر يُصدَّق أو يُكذَّب\": هذه أفضل تعريف للخبر البلاغي."},{"q":"جملة (ما أجملَ السماءَ!) تعتبر في علم المعاني:…","a":["إنشاءً غير طلبي (تعجب)","خبراً","إنشاءً طلبياً","قصراً"],"c":0,"d":"medium","hint":"صيغة تعجب سماعية","expl":"الصواب: إنشاء غير طلبي، لأن التعجب لا يُطلب به شيء پس لا تحتمله تصديقاً ولا تكذيباً. أما الطلبي فيطلب أمراً، والخبر يمكن صده، والقصر باب آخر في علم المعاني. نصيحة: ابحث عن الأدوات القياسية: ما/أفعل للتعجب = إنشاء غير طلبي، ولا تستدل به في شأن الخبر."},{"q":"استخدام الأمر للدعاء كما في (رَبَّنا آتِنا) يفيد:…","a":["طلباً من الأعلى بلا إلزام","وجوباً مؤكداً","تهديداً","تبكيتاً"],"c":0,"d":"medium","hint":"مقام الدعاء يخرج الأمر عن الوجوب","expl":"الصواب: طلباً من الله بإلحاح بلا قصد وجوب على الفاعل؛ فصيغة الأمر إذا وردت في مقام الدعاء سقط معنى الوجوب إلى الالتماس والتذلل. ما عدا ذلك مجالات أخرى خارجة عن مقصد النص. نصيحة: \"افعل\" لها معانٍ: وجوب، إباحة، دعاء، تهديد، إهانة — انظر المقام قبل أن تحسم."},{"q":"أداة الاستفهام التي يغلب استخدامها للتصديق (نسبة الخبر) هي:…","a":["هل","الهمزة","أين","متى"],"c":0,"d":"easy","hint":"استفهام تصديقي بسيط","expl":"الصواب: هل، والتي يطلب بها التصديق دون تفصيل. الهمزة تصادق أو تصور (تقرير/إنكار)، وأين ومتى لطلب المكان والزمان (طلب تصور). نصيحة: \"هل للتصديق، والهمزة للتصور والتقرير\": ميزان أدوات الاستفهام بلا تعب."},{"q":"خروج الخبر عن مقتضى الظاهر إلى اللازم للفائدة يكون لغرض:…","a":["تنزيل المخاطب منزلة الجاهل","تأكيد معلوم لديه","التعجب فقط","طلب الفعل"],"c":0,"d":"hard","hint":"المخاطب لا يعرف القضية","expl":"الصواب: تنزيل المخاطب منزلة من لا يعلم، فتُفاد الفائدة الجديدة التي لا يدركها، وهذا هو (لازم الفائدة). أما ما عرفه الملك فتنزيلٌ منزلة من لم يعلم يدفعنا إلى المعنى الآخر: \"فائدة الخبر\". نصيحة: \"فائدة الخبر = لنقل الجديد، ولازم الفائدة = لمن لا يعلم أيضاً\"، ربط معلومات المستقبل بالحال."},{"q":"من أغراض الاستفهام البلاغية ممثلاً بـ(أَأَنتَ فَعَلْتَ بِآلِهَتِنَا يَا إِبْرَاهِيمُ):…","a":["التقرير وإنكار الفعل","طلب معرفة جديدة","التمني","أمر حقيقي"],"c":0,"d":"medium","hint":"استفهام مقصود به التثبيت واللوم","expl":"الصواب: التقرير وإنكار الفعل؛ فالاستفهام هنا جحودي مقرر للفعل ومفضوح لفعله، لا بحث عن جواب مجهول. الباقي تفاسير خارجة عن مقصد النص. نصيحة: الاستفهام التقريري \"يقفل الباب بلا جواب\"؛ واستشعر نبرة الإنكار لتتعرف عليه."}]},{"title":"علم البيان: التشبيه والاستعارة والمجاز","read":[{"h":"علم البيان وأركانه","t":"علم البيان دراسة الأساليب التي تؤدي المعنى الواحد بطرائق مختلفة لزيادة الوضوح والقوة، وأركانه: التشبيه، الاستعارة، المجاز المرسل، والكناية. غايته التصوير وإظهار المعنى في صورة حسية يقوى بها في الذهن، ويصدر عن مقام وخيال البليغ. تصنيفه شرطي بتمام المعنى مع المجاز."},{"h":"التشبيه وأركانه","t":"التشبيه عقد مماثلة بين شيئين اشتركا في صفة واحدة. أركانه الأربعة: المشبه، المشبه به، وجه الشبه، أداته (الكاف، كأن، مثل...). أنواعه: مفصل (بوجه شبه وأداة)، مجمل (بلا وجه شبه)، مؤكد (بلا أداة)، بليغ (بلا أداة ولا وجه شبه) وهو أرقى الأنواع: \"عليّ أسد\". أغراضه: إيضاح وإقناع وتزيين وتفخيم، مباشرة برؤية الحال."},{"h":"الاستعارة","t":"الاستعارة تشبيه حذف أحد طرفيه (المشبه أو المشبه به). إن حذف المشبه به وبقي المشبه فهي تصريحية: (بطل ألد الأبطال) والمراد أسد... وإن حذف المشبه وبقي المشبه به فهي مكنية: (على الأسدِ المهابةُ) الحذف بالتصريح. الاستعارة أبلغ من التشبيه لأنها تدّعي اتحاداً بين الطرفين بجرأة، وتثير الخيال أكثر. أمثلة قرآنية: \"رَأَيْتُهُمْ لِي سَاجِدِينَ\" ككناية استعارة مكنية."},{"h":"المجاز والكناية","t":"المجاز: لفظ مستعمل في غير ما وضع له لعلاقة مع قرينة مانعة من إرادة الحقيقة، وعلاقاته: السببية والمسببية والجزئية والكلية (المجاز المرسل): \"واسألِ القريةَ\" علاقته إطلاق المحل وإرادة أهله. الكناية: لفظ أريد به لازم معناه مع جواز إرادة المعنى الأصلي؛ فهي أسلوب يصور بالتلويح لا بالتصريح، مثل: \"هو كثيرُ الرمادِ\" (كرم) و\"صاحبُه طيبُ الثرى\" (كرم/نجابة) — مصداق الخيال السامي."},{"h":"أمثلة تحليلية بلاغية","t":"تحليل النصوص البيانية: في قول الشاعر \"وكأنّ النجومَ بين دجاها صوارمُ مشرعةً بلا ذود\" = تشبيه مفصل؟ قل: مشبه (النجوم) ومشبه به (صوارم) وأداة (كأن) ووجه شبه (اللمعان). وفي \"الدهرُ يومانِ\" استعارة مكنية (أنسن الحال). اعرف أنواع الاستعارة يفرقك عند تمييز المجاز المرسل في \"نشرَ الجوربُ الأنباء\"."},{"h":"خلاصة الدرس","t":"التشبيه: مشبه + مشبه به (وكأن/مثل) + وجه شبه غالباً. الاستعارة: حذف طرف = تصريحية (فحذف المشبه به) ومكنية (فحذف المشبه). المجاز المرسل: علاقة غير المشابهة (جزئية، كلية، سببية...). الكناية: دلالة على لازم المعنى مع الإمكان. فصل البيان يكشف جمال النصوص من الداخل."}],"qs":[{"q":"أركان التشبيه في (عليٌّ كالأسدِ في الشجاعة):…","a":["مشبه ومشبه به وأداة ووجه شبه","مشبه فقط","مشبه به فقط","مبتدأ وخبر"],"c":0,"d":"easy","hint":"جملة تشابه كاملة","expl":"الصواب: المشبه (علي) والمشبه به (الأسد) والأداة (الكاف) ووجه الشبه (الشجاعة)، فبتمام الأركان يكون التفصيل. غياب بعضها يجعله مجملاً أو مؤكداً أو بليغاً. نصيحة: عدّ الأركان: من؟ بمن؟ بذات (أداة)؟ وبماذا يشبه؟ إذا توافر الأربعة فالتشبيه مفصل."},{"q":"(محمدٌ أسدٌ) تشبيه نوعه:…","a":["بليغ","مفصل","مؤكد","مجمل"],"c":0,"d":"medium","hint":"لا أداة ولا وجه شبه","expl":"الصواب: بليغ، لأنه إثبات المشبه صحة المشبه به دون أداة ووجه شبه، يليق بأعلى مراتب التفصيل حيث ادعى الاتحاد. المفصل يحتاجهما، والمؤكد يحذف الأداة فقط، والمجمل يحذف وجه الشبه فقط. نصيحة: \"بليغ = قفزة الأركان\": حذفت الأداة ووجه الشبه، فصار كاتحاد لا تشبيه — أبلغ تشبيه."},{"q":"في الاستعارة التصريحية يُحذف:…","a":["المشبه به ويبقى المشبه","المشبه ويبقى المشبه به","الأداة فقط","وجه الشبه"],"c":0,"d":"hard","hint":"المستعار بالتصريح بالشبيه به","expl":"الصواب: يُحذف المشبه به ويبقى المشبه مصرحاً به، كقولنا: (رأيتُ أسداً يحمي البلاد) والمراد رجلاً شجاعاً؛ فتصريح بالمشبه به المصرح. أما إبقاء المشبه به وحذف المشبه فهو مكنية. نصيحة: لتحديد الاستعارة: أنظر أيهما مذكور؛ \"تصريحية = يصرح بالمشبه به (المعنى المستعار) ويحذف الأصل\"."},{"q":"بأداة التشبيه في (صرخَ الحقلُ والعصافيرُ فوق الصفافير) أي مثال؟…","a":["استعارة مكنية (أسند الفعل البشري للمكان)","تشبيه مجمل","مجاز لغوي","كناية"],"c":0,"d":"hard","hint":"حذف المشبه (السطور البشرية) وأبقى المشبه به (الحقل)","expl":"الصواب: استعارة مكنية؛ إذ سرى صرخة البشر إلى الحقل في مجاز أنسي قائم على حذف المشبه، مع إشارة الشطر الرمزية لبقاء المشبه به. وهي بخلاف التصريحية التي تحذف المشبه به. نصيحة: \"مجاز العناق\": إذا نسب فعل البشر إلى جماد فاستعارة مكنية؛ هبه لحظة تدريب تحافظ على العلامة."},{"q":"المجاز المرسل في (نزلَ المطرُ بالمكان) علاقته:…","a":["المحلية (الكلية) بدلالة المكان وإرادة أهله","المشابهة","السببية","التناسب"],"c":0,"d":"medium","hint":"علاقة تحمل الكل وتريد الجزء","expl":"الصواب: المحلية أو الكلية؛ إذ نسمي المكان (الوادي) ونريد أهله، على نحو \"واسأل القريةَ\". لو كانت المشابهة لكان استعارة، والسببية/التناسب علاقات مجازية أخرى. نصيحة: مجاز مرسل = علاقة غير المشابهة، فإذا وجدت العلاقة (جزء/كل/سبب/محل/Eل) فقل مَرَّسل."},{"q":"الجملة (فلانٌ طيبُ السريرة) من حيث العلاقة تكون:…","a":["كناية عن نقاء النفس","تشبيهاً بليغاً","استعارة مكنية","مجازاً مرسلاً بعلاقة سبب"],"c":0,"d":"medium","hint":"ذكر لازم المعنى دون تصريح","expl":"الصواب: كناية عن نقاء النفس، إذ نعبر عن حال روحانية بلازمها الوصفي دون تصريح المعنى الحقيقي، ويبقى إمكان إرادة الحقيقة. بخلاف التشبيه المجرد أو الاستعارة أو المجاز المرسل الذي قد يخرج المعنى من مجاله. نصيحة: \"الكناية تلمح ولا تصرح\": عبارة تدل على الخلق الحميد، واحرص على تلخيصها باللازم."}]},{"title":"علم البديع: اللفظي والمعنوي","read":[{"h":"علم البديع وتعريفه","t":"علم البديع يبحث في تحسين الكلام بعد رعاية المعنى والبيان، وينقسم إلى: بديع لفظي (يتعلق بنظم اللفظ: الجناس، السجع، التصريع) وبديع معنوي (يتعلق بالمعنى: الطباق، المقابلة، التورية، مراعاة النظير، المبالغة، حسن الاستهلال). وظيفته: تجميل اللفظ وتوافق أجزاء الكلام بلا تكلف."},{"h":"المحسنات اللفظية","t":"الجناس: اتفاق الكلمتين في اللفظ مع اختلاف المعنى، له نوعان: تام (اتفاق في عدد الحروف وهيئتها: \"وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ\") وناقص (اختلاف في بعض الحروف أو الهيئة: قرآن/قرين). السجع: توافق الفاصلتين في الحرف الأخير: \"اللهم اغفر لي خطيئتي وجهلي وإسرافي في أمري\". التصريع: توافق شطري البيت الأول."},{"h":"المحسنات المعنوية: الطباق والمقابلة","t":"الطباق: الجمع بين معنيين متضادين في جملة: \"وتحسبهم أيقاظاً وهم رقود\" (نوع معنا) وله تقسيمات: إيجابي (بلا نفي) وسلبي (بإيجاب وسلب: \"لا تقل ما تفعل\"). المقابلة: الجمع بين معنيين أو أكثر وما يضادها على التوالي: \"العطاء يُزيد المودة والبخل يُذلُّ\". الفرق: الطباق معنيان فقط، والمقابلة معنيان فصاعداً."},{"h":"التورية ومراعاة النظير","t":"التورية: لفظ له معنيان: قريب (المذكور أولاً) وبعيد (المراد)، تعمى التورية بغرض الإبهام واللطف: \"الحمد لله الذي... الحسنُ مني خُلُقٌ نحمدُه\" (الحسن قريب=القبول، بعيد=التحسين). مراعاة النظير (الإيهام): ذكر الشيء وما يناسبه في محل نظير كالشراب مع السكر، أو معية الأسماء في المعنى. مراعاة النظير تعطي الكلام ترابطاً وتناسقاً."},{"h":"المبالغة وحسن التوطئة","t":"المبالغة: ادعاء قوة تقرب إلى حد الاستحالة؛ بدرجاتها الثلاث: التبليغ (مبينها في مقدور العادة)، الإغراق (يزيد)، والغلو (يتجاوز مقدور العادة). ومنها المبالغة في المدح والذم. حسن التخلص: خروج الحديث من غرض لآخر برشاقة. حسن الابتداء/الاستهلال: افتتاح الكلام بما يلفت (قول نبوي \"لا يبلغ العبد أعظم الدرجات...\"). كلها تخضع لإيداع الكلام في مستويات الدقة."},{"h":"خلاصة الدرس","t":"البديع لفظي: جناس (تام/ناقص) وسجع وتصريع. ومعنوي: طباق (ضدان) ومقابلة (معنيان وما يضادها)، وتورية (قريب وبعيد)، ومراعاة نظير (تناسب)، ومبالغة (تبليغ/إغراق/غلو). ما دامت المحسنات موجودة بلا تكلف فهي تُحسن الكلام؛ وإذا تكلفت أفسدت المعنى."}],"qs":[{"q":"مثال السجع هو:…","a":["(المسلمُ مَن سَلِمَ المسلمون من لسانه ويده)","(عليّ أسد)","(واسأل القريةَ)","(ما أجمل السماء)"],"c":0,"d":"medium","hint":"توافق فواصل الجمل بالحرف الأخير","expl":"الصواب: السجع في طرف الكلام يتوافز مع الكلمة \"لسانه ويده\"، أي فاصلتان \"لسانه\" و\"يده\" اتحدت أحرفهما الأخيرة. عليّ أسد تشبيه، وقرض مجرد استعارة مجاز، وما أجمل تعجب إنشاء. نصيحة: تلمس آخر حرف من كل جملة: إذا تشابه فالسجع بلا تردد."},{"q":"(والليل إذا يغشى والنهار إذا تجلى) فيه:…","a":["طباق بين الليل والنهار","مقابلة","تور","جناس تام"],"c":0,"d":"easy","hint":"معنيان متضادان في الجملة","expl":"الصواب: طباق بين الليل والنهار، لأنه اجتماع نقيضين في نص واحد. لم توجد مقابلة (معنيان وما يتقابلهما؟ والواحد لم يذكر مقابل عددين)، ولا تور ولا جناس. نصيحة: طباق = زوج متضاد (ليل/نهار، حياة/موت، نافع/ضار)."},{"q":"التورية تدل على لفظ له معنيان أحدهما:…","a":["قريب غير مراد وبعيد مراد","بعيد غير مراد وقريب مراد","كلاهما مراد معاً","لا معنيين إطلاقاً"],"c":0,"d":"medium","hint":"الغموض الذكي بالمراد البعيد","expl":"الصواب: له معنيان: قريب يتبادر للذهن (غير مراد) وبعيد هو المقصود، وهذا مكيال الأسلوب. إن كان المراد القريب فقط فلم تدفع إلى التورية، وبات الانسداد ذكاءً. نصيحة: \"القريب درع، والبعيد الكنز\": تأكد أن المعنى المطلوب حقاً هو البعيد الذي قصده المتكلم."},{"q":"الجناس الناقص موجود في:…","a":["(الهمزةُ لوكه والهمزةُ لوكا)","(علمٌ وعالم)","(ورداً ورداً)","(قرأ وكتب)"],"c":0,"d":"hard","hint":"اختلاف يسير في الحروف","expl":"الصواب: (همزة الوكه/الوكا) تتشابه في معظم الحروف وتختلف في حرف (الهاء والألف)، فهي جناس ناقص. وعالم مع علم يختلف حرفاً ويكون ناقصاً هو أيضاً. أما (ورد/ورد) فجناس تام، وقرأ وكتب لا جناس فيه. نصيحة: جناس ناقص = اختفاء حرف أو تغييره: انظر الحروف المتفقة واعرف مكان النقص."},{"q":"يُعد (حرص البخيل على المال) ضداً مع (كرم الكريم) نوعاً من:…","a":["المقابلة","الطباق","التورية","المبالغة"],"c":0,"d":"medium","hint":"كثر المعاني المتضادة على التوالي","expl":"الصواب: المقابلة، لأنها تجمع معنيين متقابلين فصاعداً على التوالي (البخل لك، والكرم لفلان) بترتيب؛ فالمقابلة أوسع من الطباق. وليس طباقاً (فالطباق معنيين فقط)، ولا توراً ولا مبالغة. نصيحة: عدّ الأزوا: زوجان = مقابلة، وزوج واحد = طباق. هذه \"سُلَّم التضاد\" الأسهل."},{"q":"من أنواع المحسنات اللفظية أيضاً:…","a":["التصريع (توافق شطري البيت الأول)","الطباق","التورية","مراعاة النظير"],"c":0,"d":"easy","hint":"تحسين وجملة لفظية خاصة بالشّعر","expl":"الصواب: التصريع، وهو موافقة الشطرين في القافية أول البيت، فهو لفظي. الطباق والتورية ومراعاة النظير محسنات معنوية. نصيحة: قسّم البليغ: \"اللفظي = لفظ كالسجع والجناس والتصريع، والمعنوي = المعنى كالطباق والنظير\"."}]},{"title":"الإعجاز البلاغي والأدب","read":[{"h":"الإعجاز البلاغي للقرآن","t":"الإعجاز البلاغي بروز أثر القرآن في فصل خطابه وأسلوبه؛ فهو معجز ببلاغته وأساليبه التي تحدى بها العرب وهم فرسان البيان، فلا يستطيعون محاكاته. آياته تجمع بين فصاحة الألفاظ وإحكام المعاني وروعة الصور وعمق الدلالة في نسق لا تكافئه محاولات الخلق."},{"h":"التحدي في النصوص","t":"التحدي آية في الإعجاز: (قُل لَّئِنِ اجْتَمَعَتِ الْإِنسُ وَالْجِنُّ عَلَىٰ أَن يَأْتُوا بِمِثْلِ هَـٰذَا الْقُرْآنِ لَا يَأْتُونَ بِمِثْلِهِ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا)، ثم تنازل التحدي إلى عشر سور، ثم سورة واحدة \"فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ\" (فسورة؟ سورة واحدة). سعة التحدي دليل قوة الحجة، وعدم إجابة العرب له دليل العجز الإعجازي."},{"h":"مصادر الأدب العربي ونصوصها","t":"الأدب العربي مستمد من عصوره: الجاهلي (معلقات ووصف وحماسة)، وصدر الإسلام (قرآن وحديث وشعر إسلامي)، والأموي (غزل ونقائض)، والعباسي (مولد وتجديد ومجون وزهد)، ومما بعد ذلك في العصور الحديثة. دراسة الشواهد القديمة تعرض لسلوك البلاغة في نبض العصور، فكل عصر عالم من الملامح الفنية."},{"h":"أسلوب كتابة وأدباء كبار","t":"خصومات الأسلوب: الجاحظ (أسلوب قصصي حي ومذهب الأدب)، ابن المقفع (براعة في الرسائل والمقامات)، ابن خلدون (مقدمات تاريخية مؤصلة)، المتنبي (حكمة وفخر)، أبو العلاء (فلسفة الشك)، حافظ إبراهيم (شعر الخطابة) وطه حسين (أدب حديث). لكل منهم خصائص تعرف لمقولاتهم في النصوص."},{"h":"فنون النثر والشعر","t":"النثر أنواع: الخطابة (الرسائل والمقامات والوصايا والمحاضرات)، والقصة والرواية والمسرحية في العصر الحديث. الشعر أنواعه: العمودي (وحدة البيت والقافية) والحر (تغيّر القافية والتفعيلة). دراسة هذه الفنون تطبق عليها مصطلحات البلاغة لتقرأ النص قراءة جمالية ناقدة بميزان العرب الأدبي."},{"h":"خلاصة الدرس","t":"الإعجاز البلاغي: تفوق النص القرآني في البيان والفصاحة مع تحدي العرب بأقصر سورة. الأدب عصور تعدد: جاهلي، إسلامي، أموي، عباسي، حديث؛ ولكل فنون نثر (خطابة، مقالة، قصص) وشعر (عمودي، حر). أعلام كبار لكل عصر."}],"qs":[{"q":"يتميز الإعجاز البلاغي للقرآن الكريم بأنه:…","a":["تحدَّى العرب ببلاغته وفصاحته فعجزوا عن محاكاته","قتصر على نبأ التاريخ","لا يهتم بالبيان","محاكاة الحواشي"],"c":0,"d":"easy","hint":"رسالة تحدٍّ أبلغ من قوة البيان","expl":"الصواب: تحدَّى العرب وهم أئمة البيان بمثل أقصر سورة، فعجزوا عن الإتيان بمثله، وهذا من أغلب الإعجاز. لا يقتصر على التاريخ ولا يهمل البيان ولا يحاكي أحداً فقد انفرد في سباقه. نصيحة: \"تحدٍّ وعجز\": ثنائية الإعجاز عند العرب أصحاب الفصاحة المطلقة."},{"q":"أقصر آية تحدٍّ قرآني طلب من العرب:…","a":["الإتيان بسورة من مثله","عشرين آية","خمسين آية","صحيفة كاملة"],"c":0,"d":"medium","hint":"الدرجة الأخيرة من التحدي","expl":"الصواب: طلب الإتيان بسورة واحدة \"فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ\"، وعلى الرغم من قصر المطلب فقد عجزوا؛ وهذا أعلى البرهان. طلبه سورة واحدة حذف المشكلة وكشف العجز. نصيحة: اذكر درجات التحدي: قرآن كامل ← عشر سور ← سورة واحدة، فالطلب يتراجع والبرهان يرتفع."},{"q":"المعلقات من الشعر:…","a":["الجاهلي","الإسلامي","الأموي","الحديث"],"c":0,"d":"easy","hint":"قصائد جاهلية مطولة معلقة","expl":"الصواب: الجاهلي؛ فالمعلقات عشرات/سبع أشهر قصائد جاهلية، كانت العرب تعليقها على الكعبة. الشعر الإسلامي له موقف من الدين، والأموي والحديث بعيدان عن عصرها الأفقي. نصيحة: \"المعلقات = جاهلية البيت\": أنسبها لا تعرف إلا في عفصها الأول."},{"q":"من أشهر أدباء الأسلوب في العصر العباسي:…","a":["الجاحظ","أمرؤ القيس","الخرّاز","طرفة"],"c":0,"d":"medium","hint":"كاتب الرسائل والأمثلة الشهير","expl":"الصواب: الجاحظ، إمام النثر العباسي صاحب البيان والتبيين والحيوان؛ صاحب الأسلوب الممتع. أمرؤ القيس وطرفة شاعران جاهليان. نصيحة: مصر صاحب \"الرسائل\" الجاحظ وأنواع الخصومات والطرائف والنفائس؛ صلة العصر عباسي."},{"q":"شعر العصر الحديث الذي يلتزم به وحدة الوزن والقافية:…","a":["العمودي","الحر","المقطوع","الأنشودة"],"c":0,"d":"easy","hint":"شعر البيت التقليدي","expl":"الصواب: العمودي المحافظ على وحدة البيت والقافية والوزن الخليلي. الحر له تفعيلة متكررة بلا قافية موحدة، والمقطوع والأنشودة تجاوزان العمود التقليدي عند كثيرين. نصيحة: \"عمودي عمود في البيت والقافية\": استرجع \"روسيا حقها\" بكلمة عمودي"}]}]},{"title":"الأدب العربي","icon":"📜","chapters":[{"title":"الشعر الجاهلي والمعلقات","read":[{"h":"مفهوم الأدب الجاهلي","t":"الأدب الجاهلي ما أنتجته العرب قبل الإسلام: شعر (فخر ومدح وهجاء وغزل ورثاء ووصف وحكمة) ونثر (خطابة وأمثال وقصص). كان الشعر ديوان العرب يسجل أيامهم ومفاخرهم وأنسابهم، ويتحدى به الأعداء."},{"h":"المعلقات","t":"المعلقات قصائد جاهلية طوال اختيرت من عيون الشعر، فكتبت بماء الذهب وعلقت على الكعبة، ومنها سبع أو عشر. أصحابها: امرؤ القيس وطرفة وعنترة وزهير ولبيد وعمرو بن كلثوم والحارث بن حلزة. تتصف بوحدة الموضوع وصدق العاطفة وجزالة اللغة."},{"h":"امرؤ القيس","t":"امرؤ القيس أشهر شعراء الجاهلية، لقب بالملك الضليل وذو القروح، صاحب المعلقة الشهيرة التي مطلعها (قفا نبك من ذكرى حبيب ومنزل). عرف بالإبداع في الوصف والغزل، وتنوع أغراضه بلا تقيد."},{"h":"الأغراض الشعرية الجاهلية","t":"أهم الأغراض: الفخر والحماسة، والمدح، والهجاء، والغزل والنسيب، والوصف، والرثاء، والحكمة، والاعتذار. يبتدئ الشاعر غالباً بالوقوف على الأطلال ثم يتدرج إلى غرضه الرئيس."},{"h":"دواوين العرب ونثرهم","t":"النثر الجاهلي: الخطابة في المفاخر والمنافرات، والأمثال السائرة، والقصص والأساطير. من أشهر الخطباء: قس بن ساعدة وقصي بن كلاب. الأمثال مصدر غني يعكس عقل العرب وتجاربهم."},{"h":"خلاصة الدرس","t":"الأدب الجاهلي: شعر بأغراضه تسعة وأشهر رجاله المعلقون، ونثر بالخطابة والأمثال. هو اللبنة الأولى في صرح الأدب العربي، ومرآة حياة العرب قبل الإسلام."}],"qs":[{"q":"المعلقات سميت بهذا الاسم لأنها:…","a":["كتبت في أنواط وعلقت على الكعبة","لأنها معلقة على صدور أصحابها","تتعلق بالرواية","نسبة إلى بيت المعلقات"],"c":0,"d":"easy","hint":"سبب التسمية مادي مرتبط بالمكان","expl":"الصواب: كتبت بماء الذهب وعلقت على أستار الكعبة لتعليها وفخامتها. نصيحة: علِّق على الكعبة، هذا أصل التسمية."},{"q":"لقب الشاعر امرئ القيس:…","a":["الملك الضليل","النابغة","شاعر النيل","الأخطل"],"c":0,"d":"easy","hint":"اللقب مرتبط بمحنه وضياع ملكه","expl":"الصواب: عرف بالملك الضليل، لطول محنه في طلب ثأر أبيه. نصيحة: ملك ضل ملكه، فسمى الملك الضليل."},{"q":"مطلع معلقة امرئ القيس:…","a":["قفا نبك من ذكرى حبيب ومنزل","بَانَتْ سُعاد","أمن أم أوفى","خليلي مرا بي"],"c":0,"d":"medium","hint":"أشهر مطلع في المعلقات","expl":"الصواب: (قفا نبك من ذكرى حبيب ومنزل). نصيحة: اربط امرأ القيس بهذين الشطرين دائماً."},{"q":"من شعراء المعلقات السبعة:…","a":["أمرؤ القيس وطرفة وعنترة","أبو نواس والمتنبي","شوقي وحافظ","المعري وابن الرومي"],"c":0,"d":"easy","hint":"كلهم من الجاهلية","expl":"الصواب: أمرؤ القيس وطرفة وعنترة وزهير ولبيد وغيرهم جاهليون معلقون. نصيحة: اعزل شعراء الجاهلية عن العصور اللاحقة."},{"q":"أشهر أغراض الشعر الجاهلي افتتاحاً للقصيدة:…","a":["الوقوف على الأطلال والغزل","الهجاء","الرثاء","الوصف فقط"],"c":0,"d":"medium","hint":"طقس تقليدي يفتتح به الجاهلي","expl":"الصواب: البدء بالوقوف على الأطلال والبكاء وتذكر المحبوبة، ثم الانتقال لغرضه. نصيحة: الجاهلي يقف على الأطلال ثم ينسج غزلاً قبل الوصول لقصد القصيدة."},{"q":"من أعلام الخطابة في الجاهلية:…","a":["قس بن ساعدة","المتنبي","بشار","الرافعي"],"c":0,"d":"hard","hint":"خطيب أسواق عكاظ","expl":"الصواب: قس بن ساعدة الإيادي خطيب العرب الأول في الجاهلية. نصيحة: في الأسواق اشتهرت الخطب المفاخرة، وقدمَ قس فسُبق."},{"q":"يغلب على شعر زهير بن أبي سلمى:…","a":["الحكمة والمدح","الغزل الفاحش","الهجاء اللاذع","الرثاء فقط"],"c":0,"d":"medium","hint":"شاعر الحلم والموعظة","expl":"الصواب: شعر زهير حكمة وموعظة واحتكام للعقل، مقل في الغزل. نصيحة: في الحكمة ذكر زهير ببيت الشعر الحكيم."}]},{"title":"الشعر في صدر الإسلام والعصر الأموي","read":[{"h":"أثر الإسلام في الشعر","t":"بفضل القرآن أخذ الشعر مضموناً دينياً: الدفاع عن الإسلام (حسان بن ثابت)، والمدائح النبوية، والغزل العفيف، والزهد، والحكمة المستمدة من التعاليم. تغيرت القيم وساد الهدى والجهاد."},{"h":"حسان بن ثابت","t":"حسان بن ثابت شاعر الرسول ﷺ، وقف في الدفاع عن الإسلام مع أصحاب بادوا المسلمين، وبإذن النبي كان هجاؤه أشد على المشركين من رمي النبال. قيل إنه عمر طويلاً واشتهر بمدحه النبي."},{"h":"الأمويون والشعر السياسي","t":"في العصر الأموي أصبح الشعر أداة صراع سياسي: مدح الخلفاء والهجاء السياسي من شيعة وخوارج. ظهرت مدارس: شعر المدح المتحضره، وشعر الحزبية والصراع بين جرير والفرزدق والأخطل."},{"h":"الغزل العذري والحضري","t":"الغزل العذري (الحجازي): عشق طاهر عاش بعيداً عن الفحش، من رجاله جميل بثينة وكثير عزة ومجنون ليلى. والغزل الحضري: فاحش في مدن الشام والحجاز كمكة، من رجاله عمر بن أبي ربيعة."},{"h":"العرصات والمدارس الشعرية","t":"مناظرات النقائض بين جرير والفرزدق أشهر ظاهرة أموية، وهي معارك هجائية تتبع الوزن والقافية. هذه المناظرات حفظت لنا حياة المجتمع بصورها المتحركة."},{"h":"خلاصة الدرس","t":"الإسلام غير مضمون الشعر، وانبثق شعر إسلامي (حسان) وأموي سياسي (جرير والفرزدق)، وتنوع الغزل بين عذري وحضري، واحتدمت النقائض."}],"qs":[{"q":"شاعر الرسول ﷺ:…","a":["حسان بن ثابت","امرؤ القيس","الفرزدق","المتنبي"],"c":0,"d":"easy","hint":"روي أن الرسول قال له: اهجهم","expl":"الصواب: حسان بن ثابت شاعر النبي، دافع عن الإسلام بشعره. نصيحة: حسان + الرسول = شاعر النبي."},{"q":"الغزل العذري يتميز بأنه:…","a":["عاطفة طاهرة بعيدة عن الفحش","غزل حسّي فاحش","غير موجود","مدح للذات"],"c":0,"d":"easy","hint":"طهر القلوب في الحجاز","expl":"الصواب: عشق طاهر روحي بعيد، من مدارس الحجاز. نصيحة: العذرة عفة في الحب، فتمس العاطفة الشعراء."},{"q":"من شعراء الغزل الحضري:…","a":["عمر بن أبي ربيعة","جميل بن معمر","كثير عزة","قيس بن الملوح"],"c":0,"d":"medium","hint":"شاعر مكة الفاحش","expl":"الصواب: عمر بن أبي ربيعة من غزل مكة الحضري. نصيحة: أفرده عن العذريين في التمييز."},{"q":"النقائض معارك شعرية اشتهرت بين:…","a":["جرير والفرزدق والأخطل","حسان ولبيد","بشار وأبو نواس","شوقي ومطران"],"c":0,"d":"easy","hint":"ثالوث الأمويين","expl":"الصواب: جرير والفرزدق والأخطل تناقضوا بازدواج الأشعار. نصيحة: الثالوث الأموي حاضر في كل نص عن النقائض."},{"q":"الغرض الجديد الذي أدخله الإسلام على الشعر:…","a":["الدفاع عن الدين والتوحيد","الخمر","الفساد","الرثاء فقط"],"c":0,"d":"easy","hint":"مضمون عقائدي جديد","expl":"الصواب: الدفاع عن الإسلام والمدائح النبوية والموعظة. نصيحة: الدين أضفى على الشعر أغراض الهداية."},{"q":"مدرسة الغزل العذري عبدت الحب بصورته:…","a":["الروحية الطاهرة","الحسية المجردة","السياسية","الهجائية"],"c":0,"d":"medium","hint":"طهر العاطفة","expl":"الصواب: الروحية الطاهرة البعيدة عن اللذة الجسدية. نصيحة: العذري يطير بعاطفته بعيداً عن الدنيا."},{"q":"أشتهر العصر الأموي بالشعر:…","a":["السياسي والهجاء (النقائض)","الغزلي المجرد","الزهد في كل شيء","السرد القصصي"],"c":0,"d":"easy","hint":"صراع الأحزاب والأسر","expl":"الصواب: برز الشعر السياسي والنقائض والمدح. نصيحة: أموي = سيادة وسياسة وهجاء."}]},{"title":"الشعر في العصر العباسي","read":[{"h":"المولدون والمجددون","t":"في العصر العباسي اختلطت الأجناس (عربي وفارسي ورومي) وازدهرت الحضارة، فنشأ شعراء مولدون جددوا في المعاني والصياغة: بشار بن برد، وأبو نواس، وأبو العتاهية، ومسلم بن الوليد."},{"h":"أبو نواس","t":"أبو نواس شاعر الخمر والمجون، تفوق في وصف الطبيعة والمداعبة والنزعة الوجودية، ثم تاب وقلب في شعر زهد. له نظرة ثاقبة في النصوص والمعاني."},{"h":"المتنبي","t":"أحمد بن الحسين المتنبي أعظم شعراء العربية، فلسفي الحكمة والمدح والفخر، جمع بين جزالة اللفظ ودقة المعنى وعمق الفكرة. له أبيات خالدة في الحكمة والاعتزاز بالنفس."},{"h":"أبو العتاهية","t":"شاعر الزهد والحكمة في العصر العباسي، ترك الغزل إلى المواعظ البسيطة الصادقة، وخاطب العامة بلغة سهلة، وانفرد بمعاني التأمل في الموت والحياة."},{"h":"تجديد الأغراض","t":"تجددت الصياغة: طول القصيدة والوحدة الفنية، والوصف الطبيعي الدقيق، والمدح برؤى فلسفية، والغزل بمذاهب الحب، والهجاء السياسي المحتدم."},{"h":"خلاصة الدرس","t":"العباسي عصر التجديد: بشار وأبو نواس مولدان مجددان، والمتنبي سيد الحكمة والفخر، وأبو العتاهية الزاهد، مع توسع المعاني وفسح الشعر للإفكار."}],"qs":[{"q":"شاعر الخمر والمجون في العصر العباسي:…","a":["أبو نواس","بشار بن برد","المتنبي","أبو تمام"],"c":0,"d":"easy","hint":"صاحب زهد متأخر","expl":"الصواب: أبو نواس، تفوق في الخمر والمجون والطبيعة ثم زهد. نصيحة: أبو نواس = خمر وفتوة وتوبة."},{"q":"أعظم شعراء العربية وأكثرهم حكمة وفخراً:…","a":["المتنبي","أبو نواس","بشار","الراضي"],"c":0,"d":"easy","hint":"مدح سيف الدولة","expl":"الصواب: المتنبي، ببلاغته وأبواب الحكمة والفخر. نصيحة: المتنبي = حكمة وفخر ومدح."},{"q":"من شعراء الزهد في العصر العباسي:…","a":["أبو العتاهية","أبو تمام","الحماسي","شوقي"],"c":0,"d":"medium","hint":"المواعظ والعبر","expl":"الصواب: أبو العتاهية فارس الزهد والحكمة. نصيحة: أبو العتاهية = عظات وتقوى."},{"q":"المولدون في العصر العباسي يعني:…","a":["عربٌ وفدوا واختلطت أجناسهم","الأعراب البدو","شعراء الأندلس فقط","أصحاب الموشحات"],"c":0,"d":"hard","hint":"نشأوا في بيئة مدينية متحضرة","expl":"الصواب: هم الذين وُلدوا في الإسلام بعد فتوح المدن واختلطوا بأجناس أخرى. نصيحة: مولد = وُلد في مدن الحضارة العباسية."},{"q":"من فنون التجديد في الشعر العباسي:…","a":["الوصف والمدح برؤى فلسفية","التقيد بالمعلقات","الجهل بكل جديد","الهجاء البدوي فقط"],"c":0,"d":"medium","hint":"أغراض تتجدد بتحول الحضارة","expl":"الصواب: توسعت الأغراض، وتفنن الوصف، وطالت القصائد. نصيحة: الحضارة جددت الشعر بمواضيع العيش المتحضر."},{"q":"بشار بن برد عرف بأنه:…","a":["من المولَدين المجددين","شيخ العذريين","أموي محافظ","جاهلي متضلع"],"c":0,"d":"easy","hint":"أحد رواد التجديد","expl":"الصواب: بشار من المولدين، رائد التجديد في العصر العباسي. نصيحة: بشار = تجديد ورقة حضرية."},{"q":"اشتهر المتنبي بمدح:…","a":["سيف الدولة الحمداني","الخلفاء العباسيين","ملوك الأندلس","الفرعون"],"c":0,"d":"hard","hint":"بلاط حلب وأبيات الخيل","expl":"الصواب: مدح سيف الدولة أمير حلب وبلاط ابن كعب. نصيحة: المتنبي وسيف الدولة توأم الشهرة."}]},{"title":"النثر: الرسائل والمقامات","read":[{"h":"فن النثر العربي","t":"النثر فن الكلام غير الموزون: الرسائل والخطب والمقامات والوصايا. تطور بعد الإسلام بالقرآن الذي رفع أسلوبه، ونضج في العصر العباسي مع الكتاب."},{"h":"الرسائل","t":"الرسائل نوعان: ديوانية (رسمية باسم السلطان) وإخوانية (مودة بين الأصدقاء). تطورت بيد كتاب الدواوين: عبد الحميد الكاتب أول من رتب رسائل الدولة."},{"h":"الجاحظ وأسلوبه","t":"عمرو بن بحر الجاحظ إمام النثر العربي، صاحب (البيان والتبيين) والبخلاء والحيوان. امتاز بالسخرية وروح الدعابة والأسلوب الطلي يستريح للمقامة."},{"h":"ابن المقفع","t":"عبد الله بن المقفع كاتب وعالم، عرف بترجمة (كليلة ودمنة) وأدبه الكبير. اعتنى بتحسين اللفظ وتزكية المعنى وعمق الحكمة."},{"h":"المقامات","t":"المقامات قصص نثرية وهمية تدور حول بطل (أبو زيد السروجي وأبو الفتح الإسكندري)، اجتمع فيها السجع وفن البلاغة، من أشهرها مقامات بديع الزمان الهمذاني والحريري."},{"h":"خلاصة الدرس","t":"النثر العربي: رسائل (ديوانية وإخوانية) وكتاب كالجاحظ وابن المقفع، ومقامات بسجعها وبديعها، ومستمد من القرآن والتجربة المدنية."}],"qs":[{"q":"صاحب كتاب البيان والتبيين:…","a":["الجاحظ","ابن المقفع","الهمذاني","ابن خلدون"],"c":0,"d":"easy","hint":"إمام النثر بالسخرية","expl":"الصواب: الجاحظ، موسوعته النقدية البيان والتبيين. نصيحة: الجاحظ = بأسلوب السخرية والرسائل."},{"q":"كليلة ودمنة من ترجمة:…","a":["ابن المقفع","الجاحظ","البديع","الحريري"],"c":0,"d":"easy","hint":"الكتاب المترجم من الفهلوية","expl":"الصواب: ابن المقفع ترجمه ورتبه. نصيحة: ابن المقفع = الحكمة المترجمة وكليلة ودمنة."},{"q":"المقامات اشتهرت بأنها:…","a":["قصص نثرية مبني على السجع","شعر عمودي","خطب سياسية","أمثال شعبية"],"c":0,"d":"medium","hint":"فن نثري بديعي","expl":"الصواب: قصص وضعية يعرفها بطل واحد بأسلوب مسجوع. نصيحة: المقامة = قصة + بلاغة + سجع."},{"q":"من أقطاب المقامات:…","a":["الهمذاني والحريري","الجاحظ فقط","أبو نواس","بشار"],"c":0,"d":"easy","hint":"بديع الزمان وصاحب جار","expl":"الصواب: بديع الزمان الهمذاني ثم القاسم الحريري. نصيحة: الهمذاني والحريري فرسا المقامات."},{"q":"أول من أرسى قواعد الرسائل الديوانية:…","a":["عبد الحميد الكاتب","قس بن ساعدة","الحجاج","ابن المقفع"],"c":0,"d":"hard","hint":"كاتب دواوين بني أمية","expl":"الصواب: عبد الحميد الكاتب رتب رسائل الدولة. نصيحة: اسمه يشرح نفسه: كاتب الدواوين."},{"q":"الرسائل الإخوانية تعني:…","a":["رسائل المودة بين الأصدقاء","رسائل الدولة الرسمية","الرسائل القرانية","العقود التجارية"],"c":0,"d":"medium","hint":"التقارب والود","expl":"الصواب: رسائل الود والتهاني بين الأخلاء. نصيحة: إخوانية = بين المودة والإخاء."},{"q":"يختص الجاحظ من بين الكتاب النثريين بـ:…","a":["روح الدعابة والسخرية في الأسلوب","الجفاف اللغوي","الجلالة الصارمة","الالتزام بالخطب فقط"],"c":0,"d":"easy","hint":"أسلوب ساخر طريف","expl":"الصواب: امتاز بالنكتة والسخرية والأسلوب الطلي. نصيحة: اقرأ للبخلاء تستشعر روح الجاحظ."}]},{"title":"الشعر والنثر في العصر الحديث","read":[{"h":"مدارس الشعر الحديث","t":"بعد النهضة الحديثة تنوعت المدارس: مدرسة الإحياء (البارودي وشوقي وحافظ) تبعث القديم، ومدرسة الديوان (العقاد وشكري) تلتزم الوحدة الفنية، ومدرسة أبولو الرومانسية."},{"h":"شوقي أمير الشعراء","t":"أحمد شوقي أمير الشعراء، جمع بين الموروث الأصيل والتجديد، فأبدع في المدح والوصف القصصي (الشوقيات)، وكتب المسرح الشعري (مجنون ليلى، مصرع كليوباترا)."},{"h":"حافظ إبراهيم","t":"شاعر النيل، بساطة لغة ومباشرة في العبارة، وشعر تم مقدم عن وطنه، عرف بأجوبته (الأوضاع) والحوار في شعره عن الشعر."},{"h":"طه حسين والأدب النثر","t":"طه حسين عميد الأدب العربي، تجدد في المقال والقصة (الأيام، دعاء الكروان)، وطالب بإلحاح العقل والمنهج العلمي في النقد."},{"h":"نجيب محفوظ والرواية","t":"نجيب محفوظ أديب نوبل، رائد الرواية الواقعية، كتب ثلاثيته الشهيرة (بين القصرين وقصر الشوق والسكرية)، وحظي بشهرة عالمية."},{"h":"خلاصة الدرس","t":"الشعر الحديث: إحياء وديوان وأبولو. النثر الحديث: مقال (طه حسين) ورواية (نجيب محفوظ) وقصة. توهجت الثقافة العربية بالجنسين معاً."}],"qs":[{"q":"أمير الشعراء في العصر الحديث:…","a":["أحمد شوقي","حافظ إبراهيم","المتنبي","البارودي"],"c":0,"d":"easy","hint":"لقب خاص بشوقي","expl":"الصواب: أحمد شوقي لقب بأمير الشعراء. نصيحة: شوقي = أمير الشعراء."},{"q":"شاعر النيل هو:…","a":["حافظ إبراهيم","شوقي","العقاد","المازني"],"c":0,"d":"easy","hint":"شعراء مصريون لاحقون","expl":"الصواب: حافظ إبراهيم شاعر النيل. نصيحة: حافظ = النيل."},{"q":"مدرسة الديوان تحرص على:…","a":["الوحدة العضوية للقصيدة","التقليد المحض","المحافظة على المعلقات","الزهد"],"c":0,"d":"medium","hint":"وحدة البناء الفني","expl":"الصواب: المدرسة ترى القصيدة كاتصال عضو كالـوحدة العضوية. نصيحة: ديوان = وحدة وبناء وأصالة."},{"q":"مدرسة أبولو في الشعر تنتمي إلى:…","a":["الرومانسية والذاتية","الواقعية الحادة","الرمزي","استعراض البلاغة"],"c":0,"d":"hard","hint":"عواطف الذات ورؤاها","expl":"الصواب: رومانسية تعبر عن طيف الذات ومناجاة الطبيعة. نصيحة: أبولو = رومانسية "},{"q":"عميد الأدب العربي:…","a":["طه حسين","نجيب محفوظ","العقاد","سيد قطب"],"c":0,"d":"easy","hint":"الأيام والقصر الثقافي","expl":"الصواب: طه حسين عميد الأدب العربي. نصيحة: طه حسين = عميد ومجدد."},{"q":"أديب نوبل ورب الرواية العربية:…","a":["نجيب محفوظ","إحسان عبد القدوس","توفيق الحكيم","يوسف إدريس"],"c":0,"d":"medium","hint":"ثلاثيته الإسكندرية","expl":"الصواب: نجيب محفوظ حائز نوبل. نصيحة: محفوظ = نوبل وثلاثية."},{"q":"من أعلام مدرسة الإحياء في الشعر:…","a":["البارودي وشوقي وحافظ","أبو نواس","المتنبي","الهادئ"],"c":0,"d":"easy","hint":"رجال النهضة الحديثة","expl":"الصواب: البارودي وشوقي وحافظ رموز الإحياء. نصيحة: الإحياء = عودة للقديم بطراز جديد."}]},{"title":"المسرحية والفنون الأدبية","read":[{"h":"الأدب القصصي الحديث","t":"القصة القصيرة والرواية والمسرحية فنون جديدة دخلت الأدب العربي بعد الاحتكاك بالغرب. تستهدف تصوير الواقع، والكشف عن النفس الإنسانية."},{"h":"المسرحية العربية","t":"المسرحية توفيق الحكيم رأس النهضة، كتب (أهل الكهف وعودة الروح)، جمع بين الفلسفة والمسرح الواقعي، واستمرت المسرحية الشعرية مع شوقي."},{"h":"القصة القصيرة","t":"يوسف إدريس ومحمود تيمور من أعلام القصة القصيرة، تستجمعحادثة محددة برموز بسيطة تعبر عن الواقع اليومي بصدق."},{"h":"التطور التاريخي للفنون","t":"تدرج الأدب: من (الحكاية الشعبية) في القديم، إلى (الرسائل والمقامات)، ثم القصة الحديثة والرواية والمسرح بمراجعة شاملة للتجارب الواقعية."},{"h":"الفنون النثرية المعاصرة","t":"المقال والعمود الصحفي، والترجمة، والنقد الأدبي، والسيرة الذاتية: كلها فروع للفن النثري المعاصر، زادت رزانتها المدارس الأجنبية."},{"h":"خلاصة الدرس","t":"الفنون الحديثة: قصة قصيرة (إدريس وتيمور)، ورواية (محفوظ)، ومسرحية (توفيق الحكيم)، ومقال (طه حسين). تفتحت أعمالها على الواقع والنفس."}],"qs":[{"q":"رائد المسرحية العربية:…","a":["توفيق الحكيم","شوقي","نجيب محفوظ","الرافعي"],"c":0,"d":"easy","hint":"أهل الكهف وسر الذات","expl":"الصواب: توفيق الحكيم رأس النهضة المسرحية. نصيحة: حكيم = مسرح وفلسفة."},{"q":"أهل الكهف من أعمال:…","a":["توفيق الحكيم","يوسف إدريس","محمود تيمور","العقاد"],"c":0,"d":"medium","hint":"مسرحية فلسفية","expl":"الصواب: مسرحية توفيق الحكيم الشهيرة. نصيحة: أهل الكهف = حكيم."},{"q":"من أعلام القصة القصيرة في مصر:…","a":["يوسف إدريس ومحمود تيمور","شوقي وحافظ","المتنبي","البارودي"],"c":0,"d":"easy","hint":"كتاب القصص الحديث","expl":"الصواب: يوسف إدريس ومحمود تيمور روادها. نصيحة: إدريس وتيمور = قصة قصيرة."},{"q":"المسرحية الشعرية كتبها في العصر الحديث:…","a":["شوقي (مصرع كليوباترا)","توفيق الحكيم","نجيب محفوظ","الرافعي"],"c":0,"d":"hard","hint":"جمع أمير الشعراء المسرح والشعر","expl":"الصواب: شوقي كتب مسرحياته شعراً. نصيحة: شوقي - الشعر + المسرح = شعرية المسرح."},{"q":"الرواية من الفنون:…","a":["النثرية الحديثة","الشعرية القديمة","التعبيرية البدوية","التشكيلية"],"c":0,"d":"easy","hint":"تتطلب سرداً موسعاً","expl":"الصواب: فن نثري حديث يستوعب قصصاً طويلة. نصيحة: الرواية = نثر + أحداث + شخصيات."},{"q":"السيرة الذاتية ككتاب (الأيام) لطه حسين تمثل:…","a":["تجربة ذاتية وحدثاً نثرياً أدبياً","شعراً","بحثاً علمياً","خطبة"],"c":0,"d":"medium","hint":"حكاية حياة صاحبها","expl":"الصواب: السيرة الذاتية أدب نثري يحفظ حياة كاتبها. نصيحة: الأيام = سيرة طه حسين الذاتية."},{"q":"القصة القصيرة تتميز بـ:…","a":["حدث مركزي موجز ورموز بسيطة","امتداد تاريخي طويل","شعرية مطلقة","عدم الحكاية"],"c":0,"d":"medium","hint":"بحث المرونة والوحدوية","expl":"الصواب: انتهاء الحدث سريعاً مع رموز تعبر عن العالم. نصيحة: القصة القصيرة = جرعة الوجيزة الفنية."}]}]}]},{"id":"math_azhar","name":"الرياضيات الأزهرية","icon":"📐","color":"#5E35B1","books":[{"title":"أساسيات التفاضل والتكامل","icon":"∑","chapters":[{"title":"نسبة التغير والمعدل اللحظي","read":[{"h":"مقدمة في التغير","t":"إذا غيّرنا متغيراً مستقلاً x تغيراً صغيراً، يتغير المتغير التابع y وفق الدالة. النسبة بين التغيرين تسمى نسبة التغير، وهي مقياس لسرعة تغير الدالة."},{"h":"نسبة التغير المتوسطة","t":"الفرق في y مقسوماً على الفرق في x يعطي نسبة التغير المتوسطة. بين النقطتين (x₁,y₁) و(x₂,y₂) هي (y₂−y₁)/(x₂−x₁)، وهي ميل الوتر للدالة linear تقريباً."},{"h":"المعدل اللحظي","t":"عندما يصغر فرق x إلى ما لا نهاية (الاقتراب من الصفر) نحصل على المعدل اللحظي، ويرمز له dy/dx. مثال: للدالة y=x² عند النقطة x=1 يكون المعدل اللحظي 2."},{"h":"الاشتقاق بالمتباينات","t":"هناك إشارات للاشتقاق: الحد العام للقاعدة الأساسية: إذا كان y=xⁿ فإن dy/dx = n·xⁿ⁻¹. إذا كان y=ثابت فالمشتقة صفر، وإذا ضربنا أي دالة في ثابت بقي الثابت مضروباً في مشتقتها."},{"h":"أمثلة تطبيقية","t":"سرعة السيارة المتغيرة تتطلب معدلاً لحظياً في كل لحظة، وليس معدلاً متوسطاً طوال الرحلة. النمو البيولوجي والتغير في درجة الحرارة أمثلة حية على المعدل اللحظي."},{"h":"خلاصة الدرس","t":"نسبة التغير = فرق الدالة ÷ فرق المتغير. المعدل اللحظي = نهاية نسبة التغير (المشتقة). قاعدة الأس: dy/dx(xⁿ)=n·xⁿ⁻¹. استعمل الاشتقاق لدراسة أي تغير لحظي."}],"qs":[{"q":"نسبة التغير المتوسطة في الدالة الخطية y=3x بين x=1 و x=3:…","a":["3","6","9","12"],"c":0,"d":"easy","hint":"أوجد ميل المستقيم","expl":"الصواب: النسبة المتوسطة هي ميل المستقيم الثابت 3 دائماً. نصيحة: في الدالة الخطية نسبة التغير = الميل دائماً."},{"q":"مشتقة الدالة y=x³ تساوي:…","a":["3x²","x²","3x","2x"],"c":0,"d":"easy","hint":"القاعدة الأساسية للأسس","expl":"الصواب: مشتقة xⁿ = n·xⁿ⁻¹، إذن 3x². نصيحة: انزل الأس للمقدار ثم انقص واحداً من الأس."},{"q":"مشتقة الثابت 7:…","a":["0","7","1","−7"],"c":0,"d":"easy","hint":"ثابت لا يتغير","expl":"الصواب: مشتقة أي ثابت صفر لأن الثابت لا يتغير مهما تغير x. نصيحة: تذكر أن معدل تغير الثابت صفر."},{"q":"التعبير عن المعدل اللحظي رياضياً:…","a":["dy/dx","Δy/Δx","x/y","y/x"],"c":0,"d":"medium","hint":"نهاية النسبة عندما يقترب المقام من الصفر","expl":"الصواب: dy/dx يدل على المعدل اللحظي، بينما Δy/Δx يدل على المعدل المتوسط. نصيحة: d الرقيقة تعني الحد الحظي، وΔ المكبرة تعني الفرقة الحسابية."},{"q":"قيمة المشتقة عند x=2 للدالة y=2x²:…","a":["8","4","16","2"],"c":0,"d":"medium","hint":"احسب المشتقة أولاً ثم عوض","expl":"الصواب: المشتقة 4x، وعند x=2 تكون 4×2=8. نصيحة: اشتق ثم عوض، لا تعوض في الدالة الأصلية."},{"q":"ماذا تقيس المشتقة في نقطة معينة؟:…","a":["ميل المماس للمنحنى فيها","طول المنحنى","مساحة المنحنى","إحداثي النقطة"],"c":0,"d":"easy","hint":"هندسياً: المماس يلامس المنحنى","expl":"الصواب: المشتقة عند نقطة = ميل المماس للمنحنى عند تلك النقطة. نصيحة: تخيل خطاً يلامس المنحنى في نقطة: ميَله هو المشتقة."}]},{"title":"التطبيقات على الدوال","read":[{"h":"التزايد والتناقص","t":"إذا كانت المشتقة موجبة في فترة تكون الدالة متزايدة، وإذا كانت سالبة تكون متناقصة، وإذا كانت صفراً تكون النقطة حرجة قد تكون عظمى أو صغرى أو نقطة انعطاف."},{"h":"إيجاد النقاط الحرجة","t":"نضع المشتقة الأولى = صفر ونجد القيم التي تحققها، وهي النقاط التي يتغير عندها سلوك الدالة، ثم نحدد نوع التغير بدراسة إشارة المشتقة حولها."},{"h":"القيم العظمى والصغرى","t":"إذا تغيرت إشارة المشتقة من موجب إلى سالب فالنقطة عظمى محلية، ومن سالب إلى موجب فالنقطة صغرى محلية. وإذا لم تتغير الإشارة فلا نقطة قصوى."},{"h":"رسم منحنيات بسيطة","t":"نستخدم المشتقة لمعرفة أين ترتفع الدالة وأين تهبط، فنرسم المنحنى بدقة: نحدد النقاط الحرجة، ثم نميل المماس، ثم نقارنة مع محور الصادات في الأصل."},{"h":"أمثلة تطبيقية","t":"الربح الأكبر لشركة عند المشتقة = صفر، وأسرع نمو في الفطريات عند التزايد الأقصى، والمشكلة العظمى والصغرى في التحسين الاقتصادي تُحل بالمشتقة الأولى."},{"h":"خلاصة الدرس","t":"المشتقة الموجبة = تزايد، والسالبة = تناقص. النقطة الحرجة عند تساوي المشتقة صفراً. عظمى محلية إذا انتقلت من + إلى −، وصغرى إذا من − إلى +."}],"qs":[{"q":"عندما تكون المشتقة سالبة في فترة، فإن الدالة فيها:…","a":["متناقصة","متزايدة","ثابتة","غير معرفة"],"c":0,"d":"easy","hint":"إشارة المشتقة","expl":"الصواب: المشتقة السالبة تعني تناقص الدالة في تلك الفترة. نصيحة: سالب يعني هبوط، موجب يعني صعود."},{"q":"النقط الحرجة للدالة y=x²−4x+3 نجدها بوضع:…","a":["2x−4=0","x²−4x=0","(x−1)=0","4x=0"],"c":0,"d":"medium","hint":"المشتقة الأولى تساوي صفراً","expl":"الصواب: المشتقة = 2x−4، ونضعها صفراً فنجد x=2. نصيحة: اشتق ثم اجعل الناتج صفراً."},{"q":"النقطة x=2 للدالة السابقة هل هي عظمى أم صغرى؟:…","a":["صغرى","عظمى","انعطاف","ليست حرجة"],"c":0,"d":"hard","hint":"إشارة المشتقة حول x=2","expl":"الصواب: عند x=2 تتغير المشتقة من سالب إلى موجب، إذن النقطة صغرى محلية للدالة المحدبة. نصيحة: لو تخيلت شكل الحرف ∪ فيكون القاع صغرى."},{"q":"الدالة الثابتة y=5:…","a":["لا تملك نقاطاً حرجة لأن مشتقتها صفر دائماً","لها عظمى لا نهائية","متناقصة تماماً","لها نقطة تعويم"],"c":0,"d":"medium","hint":"ما هي مشتقة الثابت؟","expl":"الصواب: المشتقة صفر دائماً ولا تتغير الإشارة، فلا توجد نقاط حرجة، والدالة خط مستقيم أفقي ثابت. نصيحة: الثابت خط أفقي، لا قمة ولا قاع."},{"q":"القيمة العظمى المحلية تحدث عندما تتغير المشتقة من:…","a":["موجب إلى سالب","سالب إلى موجب","موجب إلى موجب","سالب إلى سالب"],"c":0,"d":"easy","hint":"القمة تشبه الجبل","expl":"الصواب: في القمة العظمى الصعود يتوقف فتصبح المشتقة صفراً ثم يبدأ الهبوط، أي من + إلى −. نصيحة: فكّر في شكل الجبل: قمة ثم هبوط."},{"q":"لدراسة سلوك الدالة في فترة نحلل:…","a":["إشارة المشتقة فيها","قيمة الدالة فقط","أصل الدالة","التكامل"],"c":0,"d":"easy","hint":"الإشارة تحدد الاتجاه","expl":"الصواب: نحلل إشارة المشتقة: موجبة تزايد، سالبة تناقص، صفر نقطة حرجة. نصيحة: أشرطة الإشارات سلاحك لتحديد السلوك."}]},{"title":"التكامل","read":[{"h":"التكامل معكوس الاشتقاق","t":"التكامل هو العملية العكسية للاشتقاق: إذا اشتقنا دالة وحصلنا على نتيجة، فإن تكامل النتيجة يعيد الدالة الأصلية. لذلك يسمى التكامل أيضاً الاشتقاق العكسي."},{"h":"التكامل غير المحدد","t":"نتكامل الدالة بإضافة واحد للأس وقسمة على الأس الجديد: ∫xⁿ dx = xⁿ⁺¹/(n+1) + C، حيث C ثابت التكامل لأن أي ثابت مشتقته صفر، فلا نستطيع تحديده من المشتقة وحدها."},{"h":"التكامل المحدد","t":"التكامل المحدد بين حدين a و b يحسب المساحة تحت المنحنى: نوجد الدالة الأصلية ثم نطرح قيمتها عند الحد الأدنى من قيمتها عند الحد الأعلى F(b)−F(a)."},{"h":"خصائص التكامل","t":"تكامل جمع = جمع تكاملات، ويمكن إخراج الثوابت من التكامل. سيساعدنا هذا كثيراً في تحليل الدوال الأكثر تعقيداً إلى أجزاء أبسط قبل التكامل."},{"h":"أمثلة تطبيقية","t":"المسافة المقطوعة = تكامل السرعة، والمساحة تحت المنحنى تُحسب بالتكامل المحدد، والمعدلات المتراكمة كالمياه المتجمعة والدخل الكلي تحسب بالتكامل."},{"h":"خلاصة الدرس","t":"التكامل = معكوس الاشتقاق. غير المحدد: +C. المحدد F(b)−F(a)=المساحة. خصائصه تجعل التكامل أسهل عند التحليل."}],"qs":[{"q":"ناتج تكامل ∫ 3x² dx:…","a":["x³ + C","x² + C","3x³ + C","6x + C"],"c":0,"d":"medium","hint":"استخدم قاعدة الأس العكسية","expl":"الصواب: نزيد الأس 1 ليصبح 3 ونقسم على 3 فنحصل x³+C. نصيحة: التكامل يرفع الأس واحداً ويقسم."},{"q":"المساحة تحت المنحنى y=x بين x=0 و x=2:…","a":["2","4","1","0.5"],"c":0,"d":"hard","hint":"التكامل المحدد لـ x","expl":"الصواب: التكامل x²/2 من 0 إلى 2 = (4/2)−0 = 2. وهو مساحة مثلث قائم بذروة 2. نصيحة: ارسم مثلثاً: المساحة = نصف القاعدة في الارتفاع."},{"q":"لماذا نضيف ثابت التكامل C؟:…","a":["لأن مشتقة أي ثابت صفر فلا يمكن تحديده","لأنه عدد لازم للرسم","لأن الدالة دائماً موجبة","لا نضيفه أبداً"],"c":0,"d":"easy","hint":"الاشتقاق يمحي الثوابت","expl":"الصواب: عند الاشتقاق تختفي الثوابت، فعند التكامل لا نعرف قيمتها فنرموز لها بالثابت C. نصيحة: أي دالة تختلف بثابت لها نفس المشتقة."},{"q":"التكامل المحدد ∫₁³ 2x dx يساوي:…","a":["8","4","6","2"],"c":0,"d":"hard","hint":"احسب F(3)−F(1)","expl":"الصواب: التكامل x² من 1 إلى 3 = 9−1=8. نصيحة: لا تنسَ طرح قيمة الدالة عند الحد الأدنى."},{"q":"العلاقة بين الاشتقاق والتكامل:…","a":["كل منهما معكوس الآخر","مستقلان تماماً","التكامل أحد حالات الاشتقاق","يكره بعضهما"],"c":0,"d":"easy","hint":"النظرية الأساسية للتفاضل","expl":"الصواب: الاشتقاق والتكامل عكسيتان تماماً، وهذا ما تسميه النظرية الأساسية في التفاضل والتكامل. نصيحة: كل عملية تلغي الأخرى."},{"q":"تكامل ثابت 5 بالنسبة لـ x:…","a":["5x + C","5 + C","x + 5C","0"],"c":0,"d":"easy","hint":"الثابت يتكامل كضرب في المتغير","expl":"الصواب: الثابت الموجود في التكامل يبقى مضروباً في x، لأن مشتقة 5x هي 5. نصيحة: التكامل يسترجع ما كان قبل الاشتقاق."}]}]},{"title":"الهندسة والمتجهات","icon":"📐","chapters":[{"title":"المتجهات في المستوى","read":[{"h":"المتجه تعريفه","t":"المتجه كمية لها مقدار واتجاه، يمثل بسهم له نقطة بداية ونهاية. على عكس الكمية القياسية التي تحدد بمقدارها فقط كالطول ودرجة الحرارة."},{"h":"تمثيل المتجه في المستوى","t":"يكتب المتجه في صورة زوج مرتب (x,y)، حيث x المركبة الأفقية وy المركبة الرأسية. ويمثل بيانياً بسهم من نقطة البداية إلى النهاية."},{"h":"جمع وطرح المتجهات","t":"لجمع متجهين نجمع مركباتهما: (a,b)+(c,d)=(a+c,b+d)، وللطرح نطرح المركبات. جمع المتجهات عملية تبديلية وتجميعية."},{"h":"الضرب في كمية قياسية","t":"عند ضرب متجه في عدد k نضرب كل مركبة في k: k(x,y)=(kx,ky). إذا كان k موجباً يبقى الاتجاه، وإذا كان سالباً ينعكس الاتجاه."},{"h":"طول المتجه","t":"طول المتجه (x,y) يحسب بنظرية فيثاغورس: |v|=√(x²+y²). مثال: (3,4) طوله √(9+16)=5. المتجه الواحد طوله يساوي المقدار فقط."},{"h":"خلاصة الدرس","t":"المتجه (x,y) له مقدار واتجاه. الجمع والطرح بالمركبات، والضرب في كمية يضاعف المركبات. الطول √(x²+y²). هذه أساسيات العمل بالمتجهات."}],"qs":[{"q":"طول المتجه (3,4):…","a":["5","7","12","25"],"c":0,"d":"easy","hint":"استخدم فيثاغورس","expl":"الصواب: √(3²+4²)=√(9+16)=√25=5. نصيحة: 3-4-5 ثالوث فيثاغورس مشهور جداً."},{"q":"ناتج (2,3)+(1,4):…","a":["(3,7)","(3,1)","(1,7)","(2,4)"],"c":0,"d":"easy","hint":"اجمع مركبة مع مركبة","expl":"الصواب: (2+1, 3+4)=(3,7). نصيحة: اجمع الأفقي مع الأفقي، والرأسي مع الرأسي."},{"q":"ناتج 2(1,-3):…","a":["(2,-6)","(2,3)","(1,-6)","(2,6)"],"c":0,"d":"easy","hint":"اضرب كل مركبة في 2","expl":"الصواب: (2×1, 2×−3)=(2,−6). نصيحة: الإشارة السالبة تبقى عند الضرب بعدد موجب."},{"q":"المتجه الصفري:…","a":["له مقدار صفر واتجاه غير محدد","له مقدار 1","اتجاهه شمالاً دائماً","يساوي الأعداد القياسية"],"c":0,"d":"easy","hint":"المتجه الذي لا يحرك شيئاً","expl":"الصواب: المتجه (0,0) مقداره صفر واتجاهه غير محدد لأنه لا يحرك النقطة. نصيحة: نقطة إلى نفسها لا تعطي اتجاهاً."},{"q":"الضرب في كمية سالبة يجعل المتجه:…","a":["ينعكس اتجاهه ويأخذ مقداراً مضاعفاً","يتناقص مقداره فقط","يبقى كما هو","يصبح صفرياً"],"c":0,"d":"medium","hint":"إشارة السالب تعكس","expl":"الصواب: الضرب في −1 يعكس الاتجاه تماماً، وفي k سالبة يعكس الاتجاه ويضاعف المقدار بالقيمة المطلقة. نصيحة: السالب يقلب السهم."},{"q":"متجهان متساويان يعني:…","a":["تساوي مركبيهما ومقدارهما واتجاههما","تساوي طولهما فقط","التوازي فقط","كلاهما سالب"],"c":0,"d":"easy","hint":"التساوي الكامل","expl":"الصواب: المتجهان يتساويان إذا تساوت مركباتهما الأحادية والرأسية، أي نفس المقدار ونفس الاتجاه. نصيحة: متوازيان لا يعني متساويين."}]},{"title":"المخروطيات","read":[{"h":"أنواع المخروطيات","t":"المخروطيات منحنيات تنشأ من تقاطع مستوى مع مخروط: الدائرة، القطع الناقص، القطع المكافئ، القطع الزائد. أشكالها تصف مدارات الكواكب وعكس الضوء."},{"h":"الدائرة","t":"الدائرة مجموعة النقاط التي تبعد بعداً ثابتاً (نصف القطر r) عن نقطة ثابتة (المركز). معادلتها العادية: (x−h)²+(y−k)²=r² حيث (h,k) المركز."},{"h":"القطع الناقص","t":"القطع الناقص تجمع النقاط التي مجموع بعديها عن بؤرتين ثابت. معادلته القياسية: (x−h)²/a² + (y−k)²/b² = 1. الأكبر بين a وb هو المحور الأكبر."},{"h":"القطع المكافئ","t":"القطع المكافئ تجمع النقاط المتساوية البعد عن نقطة (بؤرة) وخط (دليل). له معادلات شهيرة مثل y=ax² وتكون رأس قمة أو قاع حسب إشارة a."},{"h":"القطع الزائد","t":"القطع الزائد تجمع النقاط التي فرق بعديها عن بؤرتين ثابت. معادلته (x−h)²/a² − (y−k)²/b² = 1، ويتكون من فرعين منفصلين."},{"h":"خلاصة الدرس","t":"المخروطيات: دائرة (بعد ثابت)، ناقص (مجموع ثابت)، مكافئ (تساوي البعد)، زائد (فرق ثابت). معادلاتها القياسية تعرف من شكلها."}],"qs":[{"q":"معادلة الدائرة التي مركزها البداية ونصف قطرها 3:…","a":["x²+y²=9","x²+y²=3","x²+y²=6","x²−y²=9"],"c":0,"d":"easy","hint":"المركز (0,0)","expl":"الصواب: الصيغة x²+y²=r² أي x²+y²=9. نصيحة: مربع نصف القطر في الطرف الأيمن."},{"q":"معادلة الدائرة مركز (2,3) ونصف قطر 1:…","a":["(x−2)²+(y−3)²=1","(x+2)²+(y+3)²=1","(x−2)²+(y−3)²=3","x²+y²=1"],"c":0,"d":"medium","hint":"الصيغة القياسية","expl":"الصواب: (x−h)²+(y−k)²=r² فبالتعويض (x−2)²+(y−3)²=1. نصيحة: عبر عن المركز بإشارات سالبة."},{"q":"القطع المكافئ y=x² له رأس عند:…","a":["(0,0)","(1,1)","(0,1)","(2,2)"],"c":0,"d":"easy","hint":"أصغر صورة","expl":"الصواب: عند x=0 يكون y=0، فالرأس في الأصل، وهو أدنى نقطة هنا لأنها تفتح لأعلى. نصيحة: الرأس هو نقطة القمة أو القاع."},{"q":"المعادلة التي تمثل قطعاً ناقصاً:…","a":["(x²/4)+(y²/9)=1","x²+y²=4","y=x²","y=0.5x+3"],"c":0,"d":"medium","hint":"مجموع نسب مربعة = 1","expl":"الصواب: الناقص صيغته مجموع كسرين مربعين يساوي 1. نصيحة: وجود (+) بين الكسرين مع مساواة 1 = ناقص."},{"q":"أي مما يأتي ليس من المخروطيات:…","a":["الخط المستقيم","الدائرة","القطع الناقص","القطع المكافئ"],"c":0,"d":"easy","hint":"بالكلمة: ما يقصه مخروط","expl":"الصواب: الخط المستقيم لا ينشأ من قطع مخروط مقص؛ أما الدائرة والناقص والمكافئ فمن مخروطيات. نصيحة: استبعد الأشكال المنحنية وغير المستقيم."},{"q":"عدد بؤرتي القطع الناقص:…","a":["بؤرتان","بؤرة واحدة","ثلاث بؤر","لا بؤر"],"c":0,"d":"easy","hint":"تعريف البعدين","expl":"الصواب: القطع الناقص له بؤرتان مجموع البعدين عنهما ثابت. نصيحة: لا تخلط بينه وبين المكافئ ذي البؤرة الواحدة."}]}]}]}]}];